CREATE TABLE content_item_versions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            content_item_id INTEGER,
            project_id INTEGER NOT NULL,
            operation TEXT NOT NULL DEFAULT 'upsert',
            status TEXT NOT NULL DEFAULT 'pending',
            snapshot_json TEXT NOT NULL,
            submitted_by TEXT NOT NULL DEFAULT '',
            submitted_at TEXT NOT NULL,
            reviewed_by TEXT NOT NULL DEFAULT '',
            reviewed_at TEXT NOT NULL DEFAULT '',
            review_note TEXT NOT NULL DEFAULT '',
            changes TEXT NOT NULL DEFAULT ''
        );
CREATE TABLE content_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER NOT NULL,
            page_id INTEGER,
            code TEXT NOT NULL,
            module_key TEXT NOT NULL,
            content_type TEXT NOT NULL DEFAULT 'article',
            title TEXT NOT NULL,
            subtitle TEXT NOT NULL DEFAULT '',
            summary TEXT NOT NULL DEFAULT '',
            body_json TEXT NOT NULL,
            meta_json TEXT NOT NULL,
            cover_asset_id INTEGER,
            sort_order INTEGER NOT NULL DEFAULT 0,
            featured INTEGER NOT NULL DEFAULT 0,
            enabled INTEGER NOT NULL DEFAULT 1,
            review_status TEXT NOT NULL DEFAULT 'approved',
            pending_version_id INTEGER,
            submitted_by TEXT NOT NULL DEFAULT 'admin',
            reviewed_by TEXT NOT NULL DEFAULT 'admin',
            review_note TEXT NOT NULL DEFAULT '',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(project_id, code)
        );
INSERT INTO "content_items" VALUES(3,32,95,'finance-commerce-overview','overview','article','专题概况','','系部简介：财政经济系','[{"type": "paragraph", "text": "系部简介：财政经济系"}, {"type": "paragraph", "text": "财政经济系于2008年组建，紧扣现代职业教育发展方向，锚定区域产业升级与乡村振兴需求，以“德商融合、数商兴农、赛商砺能、服商赋能”为核心路径，深耕商科人才培养与社会服务，开设大数据与会计、现代物流管理、电子商务三大专业，年均在校生约1600人。2022 年起与贵州工程应用技术学院联合培养财务管理本科班。"}, {"type": "paragraph", "text": "专业建设成果丰硕：电子商务专业为毕节市人民政府授牌 \"毕节电子商务学院\"，专业群获评贵州省职业教育特色骨干专业群（优秀等次）；大数据与会计专业为省级骨干专业。加入全国直播电商职业教育集团等 5 个国家级产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体（成员单位120余家）。"}, {"type": "paragraph", "text": "系部拥有贵州省农业电商产业扶贫协同创新中心、高水平乡村电商产教融合实训基地等省级项目 11 项，获批市级数商兴农人才团队、省级教学创新人才团队。先后荣获省级五好基层党组织、市级样板院系、全国五四红旗团支部、全国活力团支部等荣誉。"}, {"type": "paragraph", "text": "育人成效显著：学生专升本上线率 93%、录取率89%。2025年荣获贵州省教学成果特等奖；技能大赛斩获国家级铜奖5项、省级一等奖12项，各级各类奖项累计400余项，为区域经济社会发展作出积极贡献。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,0,1,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(4,32,96,'finance-commerce-majors','majors','article','专业群布局','','财经商贸电子商务专业群（省级特色骨干专业群 特色打造）','[{"type": "paragraph", "text": "财经商贸电子商务专业群（省级特色骨干专业群 特色打造）"}, {"type": "paragraph", "text": "以电子商务专业群（省级专业群验收优秀等次）为核心，整合大数据与会计（省级质量提升工程骨干专业）、现代物流管理（两年内完成数字化升级为智能物流技术专业），构建“电商引流+物流支撑+会计赋能”三位一体乡村振兴服务体系，精准对接贵州省数字经济、现代服务业及毕节市新型综合能源、山地特色农业、资源精深加工产业集群需求。"}, {"type": "paragraph", "text": "专业群深耕区域特色打造差异化优势：大数据与会计聚焦能源财税、农产加工成本核算，嵌入 RPA 税务机器人等前沿工具；电子商务主攻乡村电商、民族文创电商、跨境电商，助力“黔货出山”；智能物流技术专业聚焦农村共配、服务毕节“1区8中心”快递物流体系建设，同步推进与京东深度合作，升级改造现有物流实训室为生产性智能物流配送中心，新建1-2个京东订单班，为专业数字化升级筑牢基础。"}, {"type": "paragraph", "text": "进一步深化产教融合，推进订单培养模式，整合现有省级实训基地，开发活页式教材。构建“岗课赛证”融通课程体系，培养兼具“传统财经技能+数字技术应用+本土产业认知”的复合型人才，专业群将打造毕节中小企业财经服务、乡村振兴电商赋能、区域物流体系优化核心平台，为西部陆海新通道建设和毕节区域经济高质量发展提供坚实人才支撑。"}, {"type": "paragraph", "text": "电子商务专业"}, {"type": "paragraph", "text": "培养目标：本专业培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向互联网和相关服务、批发业、零售业的运营主管、全渠道营销主管、O2O 销售主管、智能客服主管、视觉营销设计师等岗位（群），能够从事数据化运营、网店运营、社群运营、行业运营、营销活动策划与执行、销售方案执行与优化、客户服务管理、视觉设计工作的高技能人才。"}, {"type": "paragraph", "text": "核心课程：网店运营、数据化运营、社群运营、互联网销售、视觉营销设计、网络营销、零售门店O2O运营、农产品电商运营、跨境电子商务运营、短视频拍摄与直播运营。"}, {"type": "paragraph", "text": "就业方向：本专业毕业生主要面向面向电子商务师、互联网营销师、营销员、市场营销专业人员、商务策划专业人员、品牌开发与运营专业人员、客户服务管理员等职业，运营主管、全渠道营销主管、O2O销售主管、智能客服主管、视觉营销设计师、互联网产品开发主管等岗位（群）就业和自主创业，从事相关工作。"}, {"type": "paragraph", "text": "培养特色：竞赛成果：学生获全国职业院校技能大赛、挑战杯、“互联网+ ”双创赛奖项5 项、省赛 100 余项；对口就业：与京东、贵州卡妈等 15 家企业开展订单培养 350余人，就业率提升至98%以上；考证培训：面向退伍军人、新农人及返乡创业就业人员，开展乡村电商技能培训和职业体验2000 人次，开展互联网营销师等职业技能鉴定，考证通过率94%以上；获教育部产教融合校企合作典型案例；牵头成立东西部协作乡村电商行业产教融合共同体；教师打造了《黔西北农业职业经理人》省级优质课，培养高级农业经理人7人。"}, {"type": "paragraph", "text": "培养目标：培养践行社会主义核心价值观，具备良好人文素养、数字素养与职业道德，掌握现代物流管理核心知识与技术技能的高技能人才。学生需熟练运用仓储管理系统、数据分析工具及智能物流技术，具备智慧仓配运营、物流运输调度、供应链协同管理等能力，能从事物流项目运营、数据分析、国际货运代理等工作，兼具可持续发展能力与创新创业意识。"}, {"type": "paragraph", "text": "核心课程：构建“基础+核心+拓展”三层课程体系，核心课程包括智慧仓配运营、智慧运输运营、物流成本与绩效管理、采购与供应管理、物流营销与客户关系、国际货运代理实务、物流项目运营、物流系统规划与设计。课程融入大数据、人工智能等新技术，结合农产品电商运营仿真实训、物流数据采集与分析等实践内容，对接物流管理、供应链运营等职业技能等级证书考核要求。"}, {"type": "paragraph", "text": "办学特色：产教融合深厚：与10余家企业共建校外实习基地，引入真实物流项目开展生产性实训，“数商兴农”人才团队助力区域产业发展。"}, {"type": "paragraph", "text": "赛教融合突出：承办贵州省第二届职业技能大赛“物流与货运代理”赛项并获省赛金奖1项，学生在世界职业院校技能大赛全国决赛物流与供应链赛道中获铜奖1项、并先后获省赛一等奖2项，2025第八届一带一路暨金砖国家技能发展与技术创新大赛供应链管理赛项全国总决赛中获一等奖1项，专业教师先后累计指导学生获技能大赛奖项50余项。"}, {"type": "paragraph", "text": "师资力量雄厚：拥有“双师型”教师占比91%的教学团队，含全国商贸服务业青年专家1人、市级高技能骨干人才1人、商贸物流专家3人及企业行业导师，主持立项30余项省级、市厅级教研科研课题。"}, {"type": "paragraph", "text": "证书体系完善：推行职业技能等级证书制度，学生可考取贵州省人力资源与社会保障厅认可的三级物流服务师（高级）、供应链管理师等证书。"}, {"type": "paragraph", "text": "部分骨干教师"}, {"type": "paragraph", "text": "就业方向：毕业生主要面向智慧仓配运营、智慧运输运营、生产物流管理等领域，可从事物流项目运营主管、物流数据分析员、国际货运主管、供应链管理师等岗位。就业单位涵盖京东、顺丰速运等知名企业及区域重点物流企业，可通过岗位实习实现就业衔接，也可自主创业开展物流相关服务业务。"}, {"type": "paragraph", "text": "培养目标：大数据与会计专业紧跟会计行业数字化、智能化转型要求，立足毕节、服务贵州经济和社会发展为目标，培养德、智、体、美、劳全面发展，践行社会主义核心价值观，具备一定文化水平、良好职业道德和人文素养，掌握本专业知识和技术技能，具备职业综合素质和行动能力，主要面向中小型企业及会计师事务所等中介服务机构，能够胜任出纳、会计核算、税务管理、成本管理、财务数据分析等工作，既精通传统财务功底，又能驾驭财务大数据分析工具，具有创新精神的高素质技术技能型人才。"}, {"type": "paragraph", "text": "核心课程：企业财务会计、智能化成本核算与管理、智能化税费申报与管理、会计信息系统应用、管理会计实务、财务大数据分析、Python开发与财务应用、企业内部控制。"}, {"type": "paragraph", "text": "就业方向：毕业生可选择专升本或到行政事业单位、各类中小微企业、会计师事务所等单位，从事出纳、会计核算、纳税申报、成本管理、财务管理、大数据分析、财务机器应用与开发等岗位相关工作。"}, {"type": "paragraph", "text": "办学特色：大数据与会计专业（原名会计电算化）专业于2008年开始招生，2014年被学校评为重点专业，2017年被贵州省教育厅评为省级骨干专业，2024年大数据与会计专业人才培养方案被贵州省教育厅评为省级示范性人才培养方案。经过10年积淀，办学成果显著。学生参加国家级、省级技能大赛获奖44个，其中获国家三等奖 4个， 获省级一等奖 12 个，二等奖4个，三等奖24个；教师参加金砖国家职业技能竞赛获二等奖2个，三等奖2 个，教师参加贵州省教学成果奖申报获一等奖1个，主持省级、校级科研项目16项，发表科研论文30多篇，开展财税知识培训1000多人次，专业实力雄厚，办学成果显著。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,1,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(5,32,97,'finance-commerce-training','training','scene','实训场景','','贵州省兴黔富民行动计划项目——高水平乡村电商产教融合实训基地','[{"type": "paragraph", "text": "贵州省兴黔富民行动计划项目——高水平乡村电商产教融合实训基地"}, {"type": "paragraph", "text": "围绕毕节建设贯彻新发展理念示范区历史使命，聚焦乡村振兴和人力资源开发，学院瞄准区域农业全产业链数字化转型新机遇，围绕新经济、新商业、新电商，融入人工智能、物联网、大数据、虚拟现实等新技术，构筑线上线下有机融合的“毕货网行”双轨系统，拟建“高水平乡村电商产教融合实训基地”(以下简称基地)，按照“深化产教融合新模式、对接产业发展新定位、融合“云物大智”新技术、共创协同发展新标杆”的总体建设思路，建立“1 基地+4 内容+6 功能+X 中心”的产教融合服务体系，构建一个集教学科研、职业培训、技能竞赛和社会服务为一体的人才培养、技术创新、实务对接、精准扶贫与创新服务高水平专业化产教融合实训基地。探索建立发展股份制、混合所有制产权制度，形成产教深度融合的校企命运共同体。服务我校电子商务省级特色骨干专业群，重点是培养“懂财会、会技术、明市场、精电商、能运营、善管理、可创业”的复合型本土化高素质“新农商”人才。"}, {"type": "paragraph", "text": "本项目建成六中心一平台，其中 1+X 考培中心辐射全校所有 1+X 证书制度试点（15 个），同时兼顾校内外培训，目前在中心已开展社会培训 500 人次，考证合计 300 人次，针对四类人员培训（退伍军人、农民工、下岗职工、普通高中毕业生）500 人次；京东校园实训中心目前组织开展真实订单业务，截止目前已完成订单 3582752 单，2022 年产生社会效益 42.6 万元，2023 年至今产生社会效益 26.6 万元；乡村电商网络营销与直播实训中心连续开展四届网络直播大赛（2020 年——2023 年），主要直播品类为家乡农特产品及其他类目引流品，用实际行动服务乡村振兴，产生总经济效益 36481 元；与重庆诺维奇进出口贸易有限公司开展真实外贸业务，产生订单国家10余个，产生外贸订单销售额2679.65美金；职教扶贫农村电商，助力乡村振兴，辐射带动区域产"}, {"type": "paragraph", "text": "业高质量发展。"}, {"type": "paragraph", "text": "贵州省技能贵州建设项目——乡村电商物流生产性产教融合实训基地"}, {"type": "paragraph", "text": "基地立足服务贵州省“乡村振兴、大数据、大生态”三大战略目标，围绕“四新”主攻“四化”，以服务区域现代农业全产业链“种植、养殖、加工、检测、销售、物流、客服”中农产品上行及工业品下乡为出发点，持续引入京东、顺丰等头部电商物流企业真实工作任务和生产性实训业务，打造创新型教师团队、推进“岗课赛证”综合育人，建立产学研用技术创新高地，助力毕节乡村电商及配套物流体系的发展完善，将基地打造成为“五大标杆”。"}, {"type": "paragraph", "text": "打通农产品上行与工业品下乡流通链路，降低物流成本，带动涉农主体增收。依托“岗课赛证”定向培育电商物流技能人才，同步开展社会化培训，培育本土创业带头人。打造双师团队，开发特色实训课程，产出课题、论文、软著等科研成果。建成全链条生产性实训平台，实现多功能融合，为乡村涉农主体提供技术服务。"}, {"type": "paragraph", "text": "乡村电商物流生产性产教融合实训基地"}, {"type": "paragraph", "text": "电子商务课程培训"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,2,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(6,32,98,'finance-commerce-cooperation','cooperation','activity','产教协同','','数商兴农：产教协同，构建特色发展格局','[{"type": "paragraph", "text": "数商兴农：产教协同，构建特色发展格局"}, {"type": "paragraph", "text": "紧扣“数商兴农”战略与“黔货出山”需求，系部深化专业建设与产教融合，走出特色发展之路。优化专业布局，暂停同质化专业，打造电子商务特色骨干专业群，建成贵州省农业电商扶贫协同创新中心、高水平乡村电商产教融合实训基地等 11 项省级项目，组建毕节市数商兴农人才团队、贵州省电子商务教师教学创新团队。搭建高能级产教平台，受邀加入5个全国性产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟等协作载体，与京东实现 “课堂即岗位” 深度合作，与顺丰联合推进直播助农项目，将数字商务技能培养与乡村振兴需求精准对接，相关成果荣获贵州省教学成果特等奖。"}, {"type": "paragraph", "text": "服商赋能：扎根地方，扛起区域发展责任"}, {"type": "paragraph", "text": "立足毕节区域发展需求，系部以“服商赋能”为导向，全面强化社会服务能力。10名教师入选毕节市商贸流通领域专家库（全市共 29人），4 人入选市文化旅游培训师资库，拥有科技特派员、毕节市拔尖人才、高级农业职业经理人等一批行业骨干。聚焦商贸流通、乡村电商等领域，开展技能培训与技术服务，助力地方产业升级；组建学生助农团队两年来，帮助毕节农特产品实现销售转化 30 余万元，成功破解织金县竹荪电商运营技术难点，获织金县商务局感谢函；协助推广毕节市航空航天展，获主办单位四川商会致谢，相关事迹被毕节日报等多家媒体大版面报道。通过东西部协作、校地联动，将商科人才培养、技术服务与区域电子商务、现代物流产业发展深度绑定，在数商兴农、商贸人才培育等领域持续贡献力量，赢得广泛社会赞誉。"}, {"type": "paragraph", "text": "对接产业"}, {"type": "paragraph", "text": "系部深度锚定贵州省及毕节市现代商贸、数字经济、现代物流、财税服务、农特产品产销等重点产业链，精准对接产业岗位需求，深化校企协同育人，构建全链条、全覆盖的产业对接体系，实现专业与产业、教学与岗位、育人与就业精准适配。"}, {"type": "paragraph", "text": "（一）核心对接产业领域"}, {"type": "paragraph", "text": "重点对接数字电商产业、现代供应链物流产业、智能财税服务产业、乡村农特产品商贸产业、进出口贸易产业、智慧供应链科技产业六大核心产业，贴合数字经济发展浪潮与粤黔东西部协作发展布局，聚焦地方数商兴农、乡村振兴、商贸流通升级核心需求。"}, {"type": "paragraph", "text": "（二）重点合作企业单位"}, {"type": "paragraph", "text": "深耕行业龙头企业与地方重点国企、优质本土企业合作，合作单位涵盖全国头部电商物流企业、行业科技龙头、地方国资商贸企业、农业龙头企业及专业财税服务机构，核心合作主体包括：京东集团、阿里巴巴（中国）教育科技、贵州顺丰速运、江苏京东信息技术、贵州京邦达供应链、珍岛信息技术、广州大洋教育、中联集团教育科技、重庆诺维奇进出口贸易；毕节市商贸物流发展集团、毕节农投实业、毕节十八农产品物流园、贵州电子商务云、贵州卡妈农特产品开发、毕节珍好农特产品开发、毕节家乡美农业综合开发、毕节山宝农业、毕节绿色畜牧科技；贵州嘉禾华政税务师事务所、毕节水务、厦门网中网软件、贵州誉佳朗商贸等，全方位保障实习实训、岗位就业、项目研发、师资共建等产教融合落地。"}, {"type": "paragraph", "text": "平台建设层级高、数量多，累计建成贵州省电子商务协同创新中心、物流生产性产教融合实训基地等省级平台项目11项；获批毕节市数商兴农人才团队、省级教学创新人才团队。行业影响力持续攀升，2024年成功加入全国直播电商、现代物流与供应链、财税服务等5个国家级行业产教融合共同体；牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体，共同体汇聚120余家成员单位，由全国电商教指委、毕节市教育局、商务局、粤黔协作工作组权威指导，成为区域产教融合标杆平台。"}, {"type": "paragraph", "text": "京东订单班"}, {"type": "paragraph", "text": "为深化校企合作，充分发挥学校和企业双方的优势，推进电子商务专业建设和教学改革，完善实践实验教学体系，使学生在顶岗实训中内化专业知识，发挥高校为社会服务的功能，为企业培养更多高素质、高技能的应用型人才，同时学生在实训过程中能够获取一定的经济收入，院校与京东充分沟通，《客服实战跟岗实训》由学校教师和京东教师联合授课，把京东企业真实客服业务引入课堂，充分利用京东校企合作实训室建设基础设施和学院师资和教学资源，与企业行业共同培养客户服务相关人才。"}, {"type": "paragraph", "text": "顺丰订单班"}, {"type": "paragraph", "text": "为深化校企协同育人机制，提升电商专业学生实践应用能力与岗位适配素养，毕节职业技术学院财经经济系联合顺丰企业打造顺丰班赋能电商专业体系。通过明确实践方向、优化团队架构、强化资源保障，为系列实践项目规范化推进奠定坚实基础。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,3,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(7,32,99,'finance-commerce-masters','masters','person','名师名匠','','张进华，男，41岁，汉族，中共党员，副教授。先后担任财政经济系团总支书记、副主任、系主任等职务，现任毕节职业技术学院教务处长，贵州省高等职业学校办学能力评价专家、贵州省职教学会职业教育教学专家、市管专家、市拔尖人才、毕节市“数商兴农”人才团队负责人、贵州省电子商务教师教学创新团队负责人、贵州省电子商务特色骨干专业群负责人（优秀等次）、贵州省农业电商产业扶贫协同创新中心负责人;获全国商贸服务业青年专家、中国商业会计学会慧心育人奖、贵州省“甲秀之光”访问学者、毕节市商贸服务重点领域专家库专家等荣誉称号;担任“畅享杯”全国财经商贸类专业教师数字技术技能大赛-直播营销竞赛裁判、贵州省职业院校技能大赛教学能力比赛裁判、广东省等省级职业院校技能大赛（世界职业院校技能大赛选拔赛）裁判。','[{"type": "paragraph", "text": "张进华，男，41岁，汉族，中共党员，副教授。先后担任财政经济系团总支书记、副主任、系主任等职务，现任毕节职业技术学院教务处长，贵州省高等职业学校办学能力评价专家、贵州省职教学会职业教育教学专家、市管专家、市拔尖人才、毕节市“数商兴农”人才团队负责人、贵州省电子商务教师教学创新团队负责人、贵州省电子商务特色骨干专业群负责人（优秀等次）、贵州省农业电商产业扶贫协同创新中心负责人;获全国商贸服务业青年专家、中国商业会计学会慧心育人奖、贵州省“甲秀之光”访问学者、毕节市商贸服务重点领域专家库专家等荣誉称号;担任“畅享杯”全国财经商贸类专业教师数字技术技能大赛-直播营销竞赛裁判、贵州省职业院校技能大赛教学能力比赛裁判、广东省等省级职业院校技能大赛（世界职业院校技能大赛选拔赛）裁判。"}, {"type": "paragraph", "text": "主持成果荣获2024年贵州省职业教育教学成果奖特等奖;主持成果《育训并举 多方协同 平台赋能：西部山区乡村振兴人才培养模式创新实践》荣获2025年教育赋能乡村振兴典型案例、《乡村振兴背景下本土化复合型乡村电商人才培养研究与创新实践》荣获2025年贵州省职业教育典型案例；荣获省级以上奖项10项；主持市厅级以上科研项目5项；发表论文8篇。"}, {"type": "paragraph", "text": "李洁，女，33岁，汉族，硕士研究生，毕节职业技术学院财政经济系电子商务专业专任教师，主攻短视频剪辑与直播运营方向。"}, {"type": "paragraph", "text": "2025年参加贵州省第二届职业技能大赛直播带岗特色赛项，获得金牌，被授予“贵州省技术能手”称号；2024年在毕节市第三届职业技能大赛中斩获电子商务师一等奖；多次担任市级直播电商大赛裁判；深耕创新创业人才培养，指导学生参与全国职业院校技能大赛选拔赛、“挑战杯”等赛事，斩获多项省、市级奖项，多次获评优秀指导教师。坚持以赛促教、教研相融，积极投身地方电商人才培养与乡村电商服务工作。"}, {"type": "paragraph", "text": "先后主编教材《农产品短视频拍摄与直播运营》《电子商务法律法规》，参编《短视频拍摄与直播运营》《消费者行为分析》等多部校级教材"}, {"type": "paragraph", "text": "社会服务方面，立足毕节本地乡村振兴需求，持续开展电商助农与技能培训工作。助力大屯彝族乡三观村打通柑橘线上销售渠道；赴赫章县企业开展直播技能培训；面向七星关区多个社区普及直播电商知识；配合毕节市人社局面向应届毕业生、失业青年开展创新创业课程培训，持续为地方培育电商人才，以专业能力服务地方产业发展。"}, {"type": "paragraph", "text": "何园园，女，39岁，汉族，中共党员，副教授、物流专业带头人、一级物流师（高级技师），毕节市高技能骨干人才、毕节市商贸服务重点领域专家库专家。深耕物流教学与技能竞赛领域，担任第三届全国职业技能大赛、省级技能大赛等多项赛事裁判与技术专家，先后荣获贵州省职业院校教学能力大赛三等奖、“智慧物流”教师赛省赛二等奖，“京津冀沪”交通职业教育集团联盟教师赛一等奖，指导学生获各级各类赛事奖项20余项，囊括一带一路金砖供应链管理赛项全国总决赛一等奖、全国物流仿真设计大赛一等奖、贵州省第二届职业技能大赛物流与货运代理赛项省赛金奖等多项荣誉；曾荣获校级“优秀教师”“优秀辅导员”“优秀党务工作者”、毕节市“师德标兵”等荣誉。"}, {"type": "paragraph", "text": "主持省级技能贵州项目乡村电商物流生产性产教融合实训基地、贵州省教育厅教育科学规划课题、贵州省教育厅职业教育课题、市委重大课题、市社科课题等10余项市厅级科研项目，聚焦毕节农产品物流、电商物流本土产业发展方向，发表论文10余篇。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,4,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(8,32,100,'finance-commerce-alumni','alumni','person','优秀校友','','基础信息栏（基层奉献类校友）','[{"type": "paragraph", "text": "基础信息栏（基层奉献类校友）"}, {"type": "paragraph", "text": "姓名：穆桥林"}, {"type": "paragraph", "text": "入学：2021年9月"}, {"type": "paragraph", "text": "毕业年份：2024年6月"}, {"type": "paragraph", "text": "专业：大数据与会计"}, {"type": "paragraph", "text": "荣誉标签"}, {"type": "paragraph", "text": "优秀学生干部、国家奖学金获得者、基层工作者"}, {"type": "paragraph", "text": "个人简介"}, {"type": "paragraph", "text": "穆桥林，贵州金沙人，2024 届大数据与会计专业毕业生，中共预备党员。求学期间身兼多项学生工作，平衡学业与服务工作，屡获国家奖学金、省优秀毕业生等荣誉。毕业后投身西部计划，在纳雍县乡镇综合治理中心开展矛盾调解、信访接待、禁毒宣传等工作，坚守基层一线，以青春力量守护地方平安稳定。"}, {"type": "paragraph", "text": "四、校友寄语"}, {"type": "paragraph", "text": "青年当向基层而行，把所学付诸乡土。愿学弟学妹坚守理想、脚踏实地，勇担时代使命，在祖国需要的地方扎根生长，书写属于青年的青春答卷。"}, {"type": "paragraph", "text": "基础信息栏"}, {"type": "paragraph", "text": "李会，2018年9月---2021年7月 财务管理专业。"}, {"type": "paragraph", "text": "荣誉标签"}, {"type": "paragraph", "text": "曾获：“国家励志奖学金”、省级“优秀毕业生”、“优秀学生干部”、“三好学生”、“优秀共青团干部”、“青春思辩-最佳辩手”、第六届中国“互联网+”大学生创新创业大赛职教赛道银奖等荣誉。"}, {"type": "paragraph", "text": "个人简介"}, {"type": "paragraph", "text": "李会，女，汉族，中共党员。于2018年9月入学毕节职院，2021年7月毕业。同年9月升学至凯里学院读本科，本科在校期间曾获：“优秀毕业生”、“三好学生”、一等奖学金等荣誉；"}, {"type": "paragraph", "text": "2023年7月毕业后考入银行系统工作，2024年9月选择从银行裸辞返乡投身基层工作。从村主任助理逐步成长为村副主任，一直坚守乡村基层治理一线，党建引领扎实开展民生服务、平安建设、群众宣传等工作；扎根田间地头，奔走农户家中，坚持把一件件群众小事做实，累计服务两千余人。将财经专业素养融入乡村发展，扎根乡土奉献青春，用实际行动诠释新时代财经学子的责任与担当。"}, {"type": "paragraph", "text": "校友寄语"}, {"type": "paragraph", "text": "在困苦磨砺中练就不屈不挠的眼神，从头再来的魄力；在心中深耕成长的踏实、力量和智慧。愿各位校友永葆热忱初心，一如既往，乘风破浪。"}, {"type": "paragraph", "text": "基础信息栏"}, {"type": "paragraph", "text": "曹静 2018-2021 财务管理"}, {"type": "paragraph", "text": "荣誉标签"}, {"type": "paragraph", "text": "2018-2019年获学院优秀干部"}, {"type": "paragraph", "text": "2018-2019年获国家励志奖学金"}, {"type": "paragraph", "text": "2019-2020年获学院优秀会长"}, {"type": "paragraph", "text": "个人简介"}, {"type": "paragraph", "text": "2018级财务管理1班学生，曾担任班级资助委员，院社会实践部部长、ERP商战协会会长。本人性格热情开朗，对待工作积极主动，认真负责。在校期间积极参与学校组织的各项活动，积极进取不断提升自己。"}, {"type": "paragraph", "text": "校友寄语"}, {"type": "paragraph", "text": "大学是充满无限可能的 “成长副本”， 只管努力珍惜、勇敢向前。我们不去想是否会成功。既然选择了，便只顾风雨兼程，我们不必强求，但不可不求。"}, {"type": "paragraph", "text": "基础信息栏（基层奉献类校友）"}, {"type": "paragraph", "text": "刘娇，2017年9月入学，2020年6月毕业，会计专业"}, {"type": "paragraph", "text": "荣誉标签"}, {"type": "paragraph", "text": "“文明礼仪”征文比赛一等奖、"}, {"type": "paragraph", "text": "三等奖学金、"}, {"type": "paragraph", "text": "优秀学生干部、"}, {"type": "paragraph", "text": "国家励志奖学金获得者"}, {"type": "paragraph", "text": "优秀毕业生。"}, {"type": "paragraph", "text": "个人简介"}, {"type": "paragraph", "text": "本人在校期间，与同学友好相处，尊师敬长，同时担任班内团支部书记一职，做好“纽带”工作，期间也大大提升了自身综合素质、多方面学习及发展的能力，不怕苦肯吃苦，在校积蓄成长力量，参加工作便自带较强的环境适应能力、抗压能力，工作顺利。"}, {"type": "paragraph", "text": "校友寄语"}, {"type": "paragraph", "text": "不管走了多远，提起母校名字，还是会心头一暖，这里是梦开始的地方，也是永远的家。"}, {"type": "paragraph", "text": "祝愿母校枝繁叶茂，桃李芬芳；"}, {"type": "paragraph", "text": "祝各位师长身体健康，工作顺利；"}, {"type": "paragraph", "text": "祝各位校友前程似锦，万事顺意；"}, {"type": "paragraph", "text": "祝学弟学妹们学业有成，不负韶华！"}, {"type": "paragraph", "text": "基础信息栏（行业精英类校友）"}, {"type": "paragraph", "text": "付绍翔｜2018年9月入学/2021年6月毕业｜会计"}, {"type": "paragraph", "text": "荣誉标签"}, {"type": "paragraph", "text": "国家奖学金获得者、贵州省“三好学生”、2021届贵州省“优秀毕业生”、2019年全省大中专学生志愿者暑期“三下乡”社会实践活动先进个人、优秀学生干部。"}, {"type": "paragraph", "text": "个人简介"}, {"type": "paragraph", "text": "付绍翔，中共党员，在校期间曾担任财政经济系团总支副书记、学生会主席、毕节职院ERP商战协会副会长。2023年在佛山市禅城区发展和改革局工作，2024年担任佛山市企业征信建设促进会办公室主任。"}, {"type": "paragraph", "text": "校友寄语"}, {"type": "paragraph", "text": "情系毕职院，根在财经系。感恩母校悉心培育，祝愿母校宏图永续，财经系薪火绵延、广育英才。"}, {"type": "paragraph", "text": "基础信息（基层奉献类）"}, {"type": "paragraph", "text": "郎廷，2018年9月入学，2021年7月毕业，财政经济系财务管理专业"}, {"type": "paragraph", "text": "荣誉标签"}, {"type": "paragraph", "text": "优秀学生干部、国家励志奖学金获得者、基层工作者"}, {"type": "paragraph", "text": "三、个人简历"}, {"type": "paragraph", "text": "求学期间勤奋笃学，曾多次荣获奖学金、国家励志奖学金，履职学生干部，积极参与校园服务与实践。毕业之后响应号召参军入伍，两年军旅生涯磨砺意志、锤炼作风。退伍后返乡扎根基层岗位，踏实履职尽责，以实干践行青年使命，在基层沃土锤炼成长。"}, {"type": "paragraph", "text": "四、校友寄语"}, {"type": "paragraph", "text": "昔日校园相伴，今朝各自扬帆。祝愿全体校友眼里有光，心中有梦，不负韶华，前路坦荡，期待他日再聚，共叙当年！"}, {"type": "paragraph", "text": "一、基本信息"}, {"type": "paragraph", "text": "秦大红，财政经济系2023级大数据与财务管理专业，曾担任财政经济系学生会班级联络部部长，班级副班长兼任生活委员，校级排球协会会长。曾获国家励志奖学金、校级优秀共青团员、校级优秀学生干部，毕节职业技术学院第二届职业规划大赛优秀奖。"}, {"type": "paragraph", "text": "二、荣誉标签"}, {"type": "paragraph", "text": "国家励志奖学金、优秀学生干部、优秀共青团员，行业骨干。"}, {"type": "paragraph", "text": "三、个人简介"}, {"type": "paragraph", "text": "在校期间深耕专业学习，专业排名前10%，连续两年获得国家励志奖学金。积极参与社会实践，多次获评校级荣誉。扎实掌握专业理论知识，积极参与学科竞赛与校园实践。主动参与班级、社团工作，责任心强，善于协作交流。持续提升综合能力，保持求知进取的态度，为步入社会夯实基础。"}, {"type": "paragraph", "text": "四、校友寄语"}, {"type": "paragraph", "text": "日复一日，那些看似冷漠的日子会像你展示坚持的意义，没有一朵花从一开始就是花，世界盛大灿烂 欢迎出发。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,5,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(9,32,101,'finance-commerce-students','students','person','优秀学生','','座右铭：不负韶华砥砺前行 心怀热爱奔赴万里','[{"type": "paragraph", "text": "座右铭：不负韶华砥砺前行 心怀热爱奔赴万里"}, {"type": "paragraph", "text": "白金妹，毕节职业技术学院财政经济系现代物流管理专业2024级高职学生，布依族，共青团员。曾获国家奖学金，荣获2025年度毕节职业技术学院“优秀学生干部”称号、2025年度毕节职业技术学院“三好学生”称号，始终秉持勤学笃行、技能成才的理念，深耕专业学识，锤炼职业技能，全面提升综合素养，学业成绩优异，荣获国家奖学金；认真履行学生工作职责，服务师生、务实担当，先锋模范作用突出。深耕物流专业技能领域，潜心备战各级高水平专业赛事，勇于拼搏、精益求精，在各类职业技能竞赛中屡获佳绩：荣获2025年世界职业院校技能大赛总决赛争夺赛物流与供应链赛道铜奖、2025年贵州省职业院校技能大赛智慧物流（高职组）一等奖、2024年“百蝶杯”第十届全国大学生物流仿真设计大赛（高职组）物流系统规划设计赛道二等奖。立足高职学子初心，以实干践行使命，以奋进诠释担当，充分展现新时代技术技能人才勤学上进、技能过硬、昂扬向上的精神风貌，用实际行动彰显新时代高职学子的责任与担当。"}, {"type": "paragraph", "text": "座右铭：道理在书上，践行在心中，知行合一，可为君子"}, {"type": "paragraph", "text": "卢義，毕节职业技术学院财政经济系现代物流管理专业 2023 级高职学生，穿青人，共青团员。曾获国家奖学金；2025 年度毕节职业技术学院 “优秀学生干部” 称号；第十九届 “挑战杯” 贵州省大学生课外学术科技作品竞赛三等奖、2025 年世界职业院校技能大赛总决赛争夺赛物流与供应链赛道铜奖。作为2023级现代物流管理一班学习委员，他深刻认识专业知识的重要性，在校期间获得过专业第一的成绩。赛场之上，他多次担任竞赛队长，统筹协调、凝心聚力，带领队员并肩钻研、互帮共进，充分彰显出色的组织能力与团队担当；课余之余，他热爱体育锻炼，入选系部篮球队，在竞技拼搏中深刻感悟团结协作、凝心聚力的意义。身为班级学习委员，深刻认识专业知识的重要性，在校期间获得过专业第一的成绩。他立足专业、奋勇争先，以扎实的学识功底、过硬的职业技能践行新时代职业教育使命，充分展现新时代高职青年朝气蓬勃、奋发向上的良好精神风貌。"}, {"type": "paragraph", "text": "座右铭：以赛促学，以行践知"}, {"type": "paragraph", "text": "游盈盈，女，汉族，共青团员，毕节职业技术学院财政经济系 2023 级电子商务专业高职生，现任校学生会主席、班级学习委员兼副团支部书记。"}, {"type": "paragraph", "text": "学业成绩稳居班级第一，综合考评、第二课堂均位列专业第一，25门必修课平均分93分。曾荣获国家奖学金、校级三好学生称号。专业技能扎实，先后斩获贵州省职业院校技能大赛电子商务赛项一等奖、毕节市电商直播大赛一等奖、贵州省乡村旅游创客大赛创意设计组一等奖、贵州省高校团支部“微团课”竞赛二等奖等多项省市级荣誉。"}, {"type": "paragraph", "text": "牵头策划校园电商文化节，搭建班级学习互助平台，统筹学生会与团务工作，服务同学、实绩突出，是全面发展、品学兼优的优秀学生代表。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,6,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(10,32,102,'finance-commerce-achievements','achievements','achievement','专题成果','','教学改革成果：','[{"type": "paragraph", "text": "教学改革成果："}, {"type": "paragraph", "text": "财政经济系教学改革成效显著，2025年斩获贵州省教学成果特等奖，登顶省级教学改革最高荣誉。贵州地处我国西南腹地，曾是全国脱贫攻坚的主战场，毕节贫困人口最多、贫困面最广、贫困程度最深，是贵州脱贫攻坚的主阵地。攻坚克难，关键在人才。毕节职业技术学院是毕节市唯一的综合性高职院校，肩负为西部山区发展培养高素质技术技能人才的使命，从2015年开始，针对西部山区技能人才培养中存在的思政教育价值引领不够、实践教学资源供给不足、专业交叉融合培养不实等问题，以毕节市人民政府为学校授牌毕节电子商务学院、贵州省农业电商产业扶贫协同创新中心建设为契机，依托“毕节试验区职业教育助推农村电商融合发展的探索与实践”等课题研究，联合东部对口帮扶院校、行业企业与联建村，系统调研、分析、研判、设计、试点、总结，于2018年制定《毕节职业技术学院数字新农人培养行动方案》并付诸实施。学校先后培养了近万名本土技术技能人才，学生获全国职业院校技能大赛（世界职业院校技能大赛总决赛争夺赛）等奖项30余项，毕业生陈燕创办农产品电商企业带动51户农民致富并当选纳雍县人大代表，育人成效入选2025年教育赋能乡村振兴典型案例、教育厅职业教育典型案例，全国人大常委会副委员长、民革中央主席郑建邦对学校学生培养成效给予高度评价；建成省级乡村电商特色骨干专业群、生产性产教融合实训基地、电子商务教师教学创新团队等省部级项目8项，牵头开发的《农业经理人职业技能标准》被菲律宾采用为国家标准；获全国五四红旗团支部、贵州省脱贫攻坚先进集体等荣誉称号；开展各类非遗、新农人培训超3500人次，推动毕节农产品销售800多万元，助力卡妈集团等15家本土企业营收增长超3.5亿元；成果获50多所院校借鉴、中央电视台新闻联播等30余家媒体报道；成果荣获2024年贵州省职业教育教学成果奖特等奖。"}, {"type": "paragraph", "text": "大数据与会计创新构建了 “课岗证赛融通、三步实训、三个一体化”的人才培养模式，形成了课、证、岗、赛深度融合的课程体系，打造了一支业务强、技能精的专兼职教师队伍，科研与社会服务能力逐步提高。"}, {"type": "paragraph", "text": "兴黔富民行动计划建设项目——《基础会计》精品在线开放课程"}, {"type": "paragraph", "text": "《基础会计》是省级“兴黔富民行动计划”立项建设的精品在线开放课程，目前已经验收完成并投入使用，作为会计、财务管理专业的核心基础课，同时也是省级电子商务专业群共享平台课程，为后续专业学习筑牢理论与技能根基，助力培养高素质财会技能型人才。"}, {"type": "paragraph", "text": "课程紧扣职业教育改革要求与行业发展需求，以“任务引领、资源核心、学用融合、思政铸魂”为建设理念，构建了多元化教学资源体系。现已建成50个微课视频、12个技能点动画、473道习题及491道考核试题，配套教学PPT、108页活页式电子教材和虚拟仿真实训平台，通过“筑梦财经 APP ”、学习通等实现资源共享，支持碎片化学习与沉浸式实训。真正实现 “教学相长、产教融合、服务地方”的建设目标，是财会入门学习者与行业从业者的优质学习资源。"}, {"type": "paragraph", "text": "贵州省技能贵州建设项目——《农业职业经理人经营管理实务》省级优质课"}, {"type": "paragraph", "text": "该课程是电子商务省级特色骨干专业群平台共享课。课程立足贵州乡村振兴，搭建一门基于“岗课赛证+数字赋能”模块化的课程资源建设平台，以“课程教学团队、课程资源、实践条件、课程实施、课程评价、数字应用”为课程开发建设抓手，始终坚持立德树人，推进“三教改革”的课堂革命改革，力争建设一门对接贵州山地乡村振兴省内一流《农业职业经理人经营管理实务》特色品牌课程，发挥示范带动作用，促进人才质量培养的提高，提升服务乡村振兴人才培养培训能力水平。"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,7,1,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(11,32,103,'finance-commerce-competitions','competitions','activity','技能大赛','','技能大赛补充资料','[{"type": "paragraph", "text": "技能大赛补充资料"}, {"type": "paragraph", "text": "——赛商砺能：以赛促学，彰显育人实效"}, {"type": "paragraph", "text": "坚持“以赛促学、以赛砺能”，将技能竞赛作为提升人才实战能力的重要抓手。组建会计协会、直播运营协会等6个专业型技能社团，完善内训机制，强化实战训练。近五年来，学子在各类赛事中捷报频传，斩获国家级职业院校技能大赛奖项3项、国家级行业赛20余项，省级技能大赛一等奖13项（含6项代表贵州省参赛项目）及其他省级奖项百余项；教师在教学能力大赛、青教赛等赛事中收获校级一等奖5次、省级奖项8次。系部多次圆满承办省级重要赛事，包括3次贵州省职业院校技能大赛-市场营销赛项、4项贵州省第二届职业技能大赛赛项，4名教师获评该赛事“表现突出场地经理”，1人获评“表现突出工作人员”，输出菲律宾《农业经理人》职业技能标准等标志性成果。"}, {"type": "paragraph", "text": "毕节市第四届电商直播大赛"}, {"type": "paragraph", "text": "2025年贵州省职业院校师生技能大赛"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,8,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(12,32,104,'finance-commerce-honors','honors','honor','荣誉资质','','1.毕节市数商兴农人才团队','[{"type": "paragraph", "text": "1.毕节市数商兴农人才团队"}, {"type": "paragraph", "text": "毕节市数商兴农人才团队"}, {"type": "paragraph", "text": "2.东西部协作乡村电商行业产教融合共同体、全国智慧物流与供应链行业产教融合共同体副理事长单位、贵州数智财税行业产教融合共同体副理事长单位"}, {"type": "paragraph", "text": "视频资料（专业特色，可于所在区域屏幕循环播放）"}, {"type": "paragraph", "text": "通过网盘分享的文件：毕节职院成果奖成品8.mp4"}, {"type": "paragraph", "text": "链接: https://pan.baidu.com/s/1DItiFZTOyGxOXj73rISivw 提取码: 9fk7"}, {"type": "paragraph", "text": "--来自百度网盘超级会员v1的分享"}]','{"sourceDoc": "创新育人-财经商贸2026.8.4更新.docx", "updatedAt": "2026-08-04"}',NULL,9,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:42.352562+00:00','2026-08-04T09:41:42.352562+00:00');
INSERT INTO "content_items" VALUES(13,37,105,'modern-agriculture-overview','overview','article','专题概况','','系部简介：农业工程系','[{"type": "paragraph", "text": "系部简介：农业工程系"}, {"type": "paragraph", "text": "农业工程系办学历史可追溯到1956年贵州省毕节农业学校，近年来先后获批贵州省第一批、第二批高水平专业群，全省先进基层党组织。现有专业教师50人，其中，教授3人，副教授17人，讲师15人；博士研究生1人、硕士研究生27人；“双师型”教师38人，中华优秀茶教师1人，省级职教名师2人，贵州省五一劳动奖章1人，贵州省技术能手5人，毕节市管专家3人。省级技能大师工作室1个、省级劳模和创新工作室1个、省级名匠工作室1个和毕节市数字育训人才团队1个。"}, {"type": "paragraph", "text": "目前开设畜牧兽医、中草药栽培与加工技术、农产品加工与质量检测、茶叶生产与加工技术和园林技术等5个高职专业，畜牧兽医1个中技专业，其中畜牧兽医专业为省级特色骨干专业。在校生1750人，学生平均就业率为98.2％，累计培养学生20000余人。近三年师生参加全国、省、市技能大赛获奖100余项。"}, {"type": "paragraph", "text": "牵头成立毕节生态食品产业市域产教联合体，加入中国智慧养猪业产教融合共同体、贵州省药学行业产教融合共同体、贵药大健康行业产教融合共同体。现有贵州省山地特色农业数字化人才产教融合实训平台等实训教学设备价值达3000余万元。"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,0,1,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(14,37,106,'modern-agriculture-majors','majors','article','专业群布局','','专业群介绍','[{"type": "paragraph", "text": "专业群介绍"}, {"type": "paragraph", "text": "农产品加工与质量检测专业群是省级“高水平”专业群，由畜牧兽医、中草药栽培与加工技术、农产品加工与质量检测、茶叶生产与加工技术和电子商务等5个高职专业组成，专业群紧紧围绕毕节要打造农产品加工产业集群和绿色生态食品加工基地等产业布局，贯穿毕节生态食品产业种养、加工、检测、销售全产业链，精准对接生态食品产业规范化、绿色化、数字化对高技能人才培养的要求，做到坚持需求导向、产教融合、质量为本、标准引领，全面落实立德树人根本任务，加快推进产教一体化、教学数智化、办学国际化，系统推进金专业、金课、金师、金教材、金基地等“五金”关键办学能力建设，努力成为毕节生态食品产业的关键技术集成引领者、技术标准输出者，培养适应生态食品产业链从原料生产到终端消费全产业链环节和新质生产力岗位急需的“懂工艺、会管理、善协作、能创新”“知农爱农”人才。"}, {"type": "paragraph", "text": "茶叶生产与加工技术专业"}, {"type": "paragraph", "text": "培养目标：茶叶生产与加工技术专业是省级重点专业群建设专业之一。坚持培养学生理想信念坚定，德、智、体、美、劳全面发展，具有一定的科学文化水平，良好的人文素养、职业道德和创新意识，精益求精的工匠精神，较强的就业能力和可持续发展的能力；掌握本专业知识和技术技能，针对区域经济发展、为巩固拓展脱贫攻坚和乡村振兴有效衔接，培养懂技术、会管理、善经营的具有“三农”情怀的新茶人，面向茶叶生产管理、茶叶加工、茶产品营销、茶叶生产技术服务等岗位（群）的高素质技术技能人才。"}, {"type": "paragraph", "text": "核心课程：茶叶加工技术、茶树栽培技术、茶树病虫害防治技术、茶的综合利用、茶叶市场营销、茶叶审评与检验技术、茶艺。"}, {"type": "paragraph", "text": "职业面向：本专业毕业生主要面向茶行业、茶企事业单位，主要从事茶叶生产管理、茶叶加工、茶产品营销、茶叶生产技术服务等岗位（群）工作。"}, {"type": "paragraph", "text": "专业特色：茶叶生产与加工技术专业致力于培养懂种植、会加工、能品评、善营销的复合型高素质技术技能人才，服务于茶产业全链条，推动传统茶业向现代茶业转型升级。"}, {"type": "paragraph", "text": "我校茶叶生产与加工技术专业拥有校内教学茶园、标准化审评室、多种类加工实训车间，每年春茶茶季还与贵州乌蒙利民农业开发有限公司、贵州乌撒烤茶茶业有限公司开展现代学徒制教学。学生实训贯穿种植、采摘、加工、审评、销售全流程，实现“从茶园到茶杯”的全产业链实践教学。"}, {"type": "paragraph", "text": "茶叶生产与加工技术专业课程对接评茶员、茶艺师等职业资格证书；组织学生参与省级茶叶加工、茶艺、评茶技能大赛；课程内容直接对应茶园管理、生产品控、技术服务等岗位需求，实现“岗课赛证”综合育人。"}, {"type": "paragraph", "text": "学生到贵州乌蒙利民农业开发有限公司茶园开展“学徒制”实践教学"}, {"type": "paragraph", "text": "办学成效：经多年发展，茶叶生产与加工技术专业取得的办学成果如下。"}, {"type": "paragraph", "text": "1.建成茶叶加工实验室1个和茶叶审评室1个；"}, {"type": "paragraph", "text": "2.建成茶叶生产与加工技术教师创新团队1个；培养“甲秀之光”访问学者1名；贵州省“黔茶工匠”1名；2022年12月获得《贵州省技能大师工作室》建设。"}, {"type": "paragraph", "text": "3.承担重大科研项目：毕节市联合基金项目《毕节市茶叶加工实验平台建设》，在研；与广东农科院茶叶研究所联合申报2022年毕节市“揭榜挂帅”项目《毕节市夏秋茶提质加工与品控技术及示范》，获批立项，经费100万元。"}, {"type": "paragraph", "text": "4.技能大赛取得丰硕成果。近三年，师生学生参加市级、省级制茶大赛获得省级“一等奖”5个，“二等奖”5个，“三等奖”6个；市级“一等奖”3个，“二等奖”2个，“三等奖”4个，省市“优秀奖”若干。"}, {"type": "paragraph", "text": "杨留勇荣获贵州省制茶大师称号"}, {"type": "paragraph", "text": "畜牧兽医专业"}, {"type": "paragraph", "text": "培养目标：畜牧兽医专业是省级重点专业群建设专业之一。本专业培养能够践行社会主义核心价值观，传承技能技艺，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向牲畜饲养、家禽饲养、畜牧专业及辅助性活动行业的畜禽种苗繁育人员、畜禽饲养人员及其他畜牧业生产人员等职业，能够从事畜禽繁育、畜禽饲养管理、畜禽疾病防控、畜牧场废弃物资源化利用、畜牧场设备使用与维护工作的高技能人才。"}, {"type": "paragraph", "text": "核心课程：养猪与猪病防治技术、养禽与禽病防治技术、养牛与牛病防治技术、养羊与羊病防治技术、兽医临床诊疗技术、畜牧场设备使用与维护、畜牧场经营与管理。"}, {"type": "paragraph", "text": "就业方向：本专业毕业生主要面向养殖企业、饲料加工与销售企业、兽药生产与营销企业、动物卫生监督与疫病监测机构、动物医院、基层畜牧兽医服务机构等；可在县、乡级兽医行政部门、动物防检站、动物屠宰企业、动物疾控中心、动物/宠物医院、规模养殖企业、饲料企业和兽药企业等企事业部门或单位，从事动物疫病防治、动物检疫检验、兽医化验、执业（助理）兽医、兽药饲料营销、动物饲养管理、牧场经营管理等工作或自主创业。"}, {"type": "paragraph", "text": "办学特色：畜牧兽医专业为省级特色骨干专业，紧扣毕节山地畜牧业需求。创新“五阶递进、四创融合”等育人模式，推行现代学徒制与订单班，深化“校政企行”产教融合，建有“国家高技能人才培训基地”，培养适配区域产业的高素质技术技能人才。"}, {"type": "paragraph", "text": "畜牧兽医专业进行猪的防疫实训"}, {"type": "paragraph", "text": "农产品加工与质量检测专业"}, {"type": "paragraph", "text": "培养目标：农产品加工与质量检测是省级重点专业群建设专业之一。本专业培养具有良好的职业素质和职业素养，掌握农产品加工与质量检测专业必要的文化基础知识、专业知识和职业技能，具备从事农产品生产加工、产品开发、品质控制、质量检测、产品营销管理等方面的基本理论知识、专业操作技能和综合应用素质，适应农产品加工与质量检测相关行业生产、建设、管理、服务等一线需要的德智体美劳全面发展的高素质复合型技术技能人才"}, {"type": "paragraph", "text": "专业开设的课程：本专业开设的核心课程：生态特色农产品加工技术、果蔬加工技术、畜产品加工、特色生态食品加工、仪器分析、农产品安全与质量安全控制、农产品食品检验技术、食品微生物。专业基础课程：食品生物化学；中西式面点制作、饮料生产技术、农产品贮藏技术、农产品食品标准与法规、食品添加剂、无极与分析化学、食品化学等。"}, {"type": "paragraph", "text": "专业特色：作为省级“双高计划”专业群核心专业，农产品加工与质量检测专业人才培养按照“五阶递进、五育贯通”的“双五模式，身份“学生一学徒一准员工一员工一创业者”五阶递进，并进行“岗、课、赛、证”四创融合综合育人培养模式。"}, {"type": "paragraph", "text": "学生校内实训教学"}, {"type": "paragraph", "text": "学生校外实习实训"}, {"type": "paragraph", "text": "学生技能比赛教师社会服务"}, {"type": "paragraph", "text": "老师社会服务"}, {"type": "paragraph", "text": "学生实训作品"}, {"type": "paragraph", "text": "专业教师走访企业"}, {"type": "paragraph", "text": "邀请企业技术能手到校上课"}, {"type": "paragraph", "text": "制作黔西黄粑"}, {"type": "paragraph", "text": "中草药栽培技术与加工技术专业"}, {"type": "paragraph", "text": "培养目标：中草药栽培与加工技术专业是省级重点专业群建设专业之一。该专业坚持培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向农业的中草药良种繁育、中草药栽培管理、中草药采收与产地初加工、中草药质量检测、中草药销售等岗位（群），能够从事中草药良种繁育、中草药栽培管理、中草药采收与产地初加工、中草药质量检测、中草药销售等工作的高技能人才。"}, {"type": "paragraph", "text": "核心课程：结合区域内中药材支柱产业发展需要，针对直接培养学生的中草药栽培、加工、检测分析能力，训练学生完成工作任务，获得岗位能力，设置《中草药栽培技术》《中草药病虫害防治技术》《中草药鉴别技术》《中草药繁育技术》《中草药质量检测技术》《中草药采收与产地初加工》《中草药营销》7门专业（技能）核心课程。"}, {"type": "paragraph", "text": "就业方向：毕业生主要面向以满足各县（区）中药材生产种植企业、加工企业、购销企业、制药企业以及医院药房等就业和自主创业，从事中草药栽培、生产管理、加工、鉴别检测及营销等工作。适应的岗位群是：①中草药良种繁育岗位群；②中草药栽培管理岗位群；③中草药采收与产地初加工岗位群；④中草药质量检测岗位群；⑤中药材销售岗位群。"}, {"type": "paragraph", "text": "专业特色：在贵州省委、省政府重点打造中药产业发展战略下，中药现代化科技产业（毕节）基地建设不断推进。中药材经营主体逐渐壮大，中草药栽培技术专业立足于服务地方中药材产业发展，培养能进行中草药栽培技术、中药炮制加工、中药材鉴别与质量检测及中药销售产业的高素质技术技能人才。"}, {"type": "paragraph", "text": "中药专业实训室-中药炮制实训室"}, {"type": "paragraph", "text": "中药专业实训室-中药调剂实训室"}, {"type": "paragraph", "text": "中药调剂实训室"}, {"type": "paragraph", "text": "中药炮制实训室"}, {"type": "paragraph", "text": "中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观"}, {"type": "paragraph", "text": "中草药栽培与加工技术专业学生到国药集团贵州同济堂中药饮片有限公司的中药智能煎配中心，开展岗位实习试岗活动"}, {"type": "paragraph", "text": "中草药栽培与加工技术专业学生创立黔草菁英社2024年、2025年连续两年为军训新生提供中药茶饮服务"}, {"type": "paragraph", "text": "园林技术"}, {"type": "paragraph", "text": "智慧大棚"}, {"type": "paragraph", "text": "教师带领学生识别植物"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,1,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(15,37,107,'modern-agriculture-training','training','scene','实训场景','','依托贵州省职业教育“兴黔富民”“技能贵州”行动计划，夯实实训硬件根基，累计投入3000余万元建成贵州省职业教育山地特色农业数字化人才产教融合实训平台，配套智慧植物工厂、现代农业实训基地、农产品质量检测中心等实训场地，建成6个校内协同创新中心，实训设备总值雄厚，实现数字化、智能化、实景化实训全覆盖，彻底打破传统农业教学“重理论、轻实操”的壁垒。','[{"type": "paragraph", "text": "依托贵州省职业教育“兴黔富民”“技能贵州”行动计划，夯实实训硬件根基，累计投入3000余万元建成贵州省职业教育山地特色农业数字化人才产教融合实训平台，配套智慧植物工厂、现代农业实训基地、农产品质量检测中心等实训场地，建成6个校内协同创新中心，实训设备总值雄厚，实现数字化、智能化、实景化实训全覆盖，彻底打破传统农业教学“重理论、轻实操”的壁垒。"}, {"type": "paragraph", "text": "畜牧兽医专业高技能人才培养基地"}, {"type": "paragraph", "text": "畜牧兽医专业高技能人才培养基地是国家级培训基地，聚焦山地特色畜牧业发展需求。基地配备自动微生物鉴定与药敏分析系统、离心机、VR远程牧场实训系统等先进设备，建有动物健康服务中心、宠物护理实训室等8间功能实训室，涵盖疫病检测、畜禽繁育、宠物养护等120余个实训项目。基地以“岗课赛证”融通为核心，承担“认知-跟岗-岗位实习”阶梯式实践教学，支撑《黔西北牛羊生产》等核心课程理实一体化教学。同时开展动物疫病防治员、养猪工等职业技能培训与鉴定，累计培训超800人次，职业技能大赛登记认定通过率95%以上。作为区域畜牧技术服务枢纽，基地组建科技特派员团队，为养殖户提供技术咨询、疫病防控等服务，助力乡村振兴；与正大集团等企业共建学徒制，推动产学研深度融合，为毕节山地特色畜牧业输送高素质技术技能人才。"}, {"type": "paragraph", "text": "中药专业实训室-中药炮制实训室"}, {"type": "paragraph", "text": "中药专业实训室-中药调剂实训室"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,2,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(16,37,108,'modern-agriculture-cooperation','cooperation','activity','产教协同','','农业工程系深耕乌蒙山区职业农业教育，紧扣毕节乡村振兴战略与山地特色农业产业布局，立足“1+3+5+N”毕节现代农业产业，坚守“以农立系、以技兴农、服务地方、赋能振兴”办学定位，深耕职教育人、产教融合、科技助农、社会服务四大核心领域，形成了专业精准对接产业、实训赋能实战、师资深耕乡土、育人贴合需求、服务扎根地方的办学特色，办学质量、育人成效、社会影响力持续提升。','[{"type": "paragraph", "text": "农业工程系深耕乌蒙山区职业农业教育，紧扣毕节乡村振兴战略与山地特色农业产业布局，立足“1+3+5+N”毕节现代农业产业，坚守“以农立系、以技兴农、服务地方、赋能振兴”办学定位，深耕职教育人、产教融合、科技助农、社会服务四大核心领域，形成了专业精准对接产业、实训赋能实战、师资深耕乡土、育人贴合需求、服务扎根地方的办学特色，办学质量、育人成效、社会影响力持续提升。"}, {"type": "paragraph", "text": "在产教融合方面，构建“校内实训基地+校外产业基地+科普教育基地”三位一体实训体系，校内建成中草药“百草园”实训基地，校外打造2400余亩枇杷产业科普实训基地、织金生态茶叶实训基地等一批产业实景教学点。深化校企、校地协同育人，与地方农业龙头企业、专业合作社深度合作，推行“课堂搬进田间、实训对接产业”的实景教学模式，实现教学过程与生产过程无缝衔接，让学生在真实产业场景中练技能、长本领，切实提升人才培养实操性与岗位适配度。"}, {"type": "paragraph", "text": "对接产业"}, {"type": "paragraph", "text": "校企合作订单班/产业学院"}, {"type": "paragraph", "text": "中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观"}, {"type": "paragraph", "text": "中草药栽培与加工技术专业学生到国药集团贵州同济堂中药饮片有限公司的中药智能煎配中心，开展岗位实习试岗活动览会"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,3,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(17,37,109,'modern-agriculture-masters','masters','person','名师名匠','','杨留勇 中共党员 副教授','[{"type": "paragraph", "text": "杨留勇 中共党员 副教授"}, {"type": "paragraph", "text": "茶叶生产与加工技术专业带头人，长期从事茶叶生产加工及教学科研研究工作，国家一级评茶技师、一级制茶师，管理期内市管专家，贵州省技能大师工作室、贵州省名师名匠工作室及贵州省劳模和工匠人才创新工作室等领办人，毕节市高山生态茶加工技术创新中心主任"}, {"type": "paragraph", "text": "2021年以来，主持教科研项目11项，其中省级4项，市“揭榜挂帅”重大专项1项，市技术创新中心1项；完成团体标准13项（其中3项排名第一，2项排名第二），完成企业标准8项（其中1项排名第一，4项排名第二）；发表研究论文10余篇（其中2篇被中文核心期刊收录）；参编《中国茶全书·贵州毕节分卷》《贵州太极古茶》等茶专著2部；开展技术培训30余期，培训茶叶技能人才2000余人，完成“师带徒”186人，为企业创收约1.5亿元；指导学徒在省市级技能大赛获奖百余项（其中省级金牌（一等奖）8名，铜牌（二等奖）12名等）；培养省级技术能手4名，黔茶工匠3名。2023年荣获贵州省五一劳动奖章，贵州省技术能手和贵州省茶文化传播优秀工作者等荣誉称号。2024年荣获全国第三届“茶人榜样”中华优秀茶教师荣誉称号，2024年入选贵州省第八批高层次创新型“千”层次人才称号。2025年荣获“贵州十佳红茶制茶能手”荣誉称号。"}, {"type": "paragraph", "text": "汪青筑 中共党员、副教授"}, {"type": "paragraph", "text": "中草药栽培与加工技术专业带头人"}, {"type": "paragraph", "text": "2011年7月毕业于贵州大学农学院中草药栽培与鉴定专业，同年8月进入毕节职业技术学院农业工程系担任专业教师；教学中参编的《药用植物栽培技术》（第3版）获评高等职业教育农业部“十二五”规划教材，在《中医教育》《光明中医》等期刊发表论文10篇，2019年以来荣获各级各类奖项15项，围绕中药产品开发指导学生斩获创新创业大赛奖项4项；科研层面主持毕节市科技局《毕节牡丹生长适应性调查及药材质量评价研究》、贵州省教育厅兴黔富民行动计划精品课程《中草药栽培》等7个项目，全部完成验收，同时作为主要完成人参与《三种石斛在毕节市种植适应性研究》《半夏鲜药材去皮技术及质量控制研究》等12项各级各类科研项目；社会服务方面担任贵州省科技特派员与毕节市科普专家，运用专业技术服务地方中药材产业发展、科技提升与区域经济建设。"}, {"type": "paragraph", "text": "李兰芝 农业工程系专任教师"}, {"type": "paragraph", "text": "2018年在中文核心期刊《动物医学进展》上以第一作者发表文章1篇，2019年以第一作者在SCI（International Journal of Molecular Sciences）期刊发表论文1篇，具有较强的科研能力。2021年至2022年，在贵州省教育厅主办的贵州省职业院校师生技能大赛中分别荣获教师组“一等奖”和“二等奖”，指导学生荣获“三等奖”。2022年在全省大中专学生志愿者暑期文化科技卫生“三下乡”社会实践活动中，所指导的团队荣获省级“优秀团队”称号。同年入选贵州省第十二届“最美劳动者”。作为主要参与人员，参与了贵州省兴黔富民项目——“畜牧兽医”特色骨干专业的建设，是校级教师教学创新团队-畜牧兽医团队成员，作为农产品加工与质量检测专业群核心专业课的教师，参与了农产品加工与质量检测省级高水平专业群建设。"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,4,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(18,37,110,'modern-agriculture-students','students','person','优秀学生','','苏兴梦','[{"type": "paragraph", "text": "苏兴梦"}, {"type": "paragraph", "text": "苏兴梦，女，毕节职业技术学院畜牧兽医专业毕业生，中共党员。2021年通过专升本考试进入安顺学院农学专业学习；2022年考取青海大学畜牧专业硕士研究生；2026年硕士毕业之际，已完成博士研究生入学考试，目前正在等待录取结果。"}, {"type": "paragraph", "text": "杨荣"}, {"type": "paragraph", "text": "毕节职业技术学院农业工程系2020届茶叶专业优秀毕业生，现任贵州春山已知茶文化传播有限责任公司法人，国家二级茶艺技师、高级评茶员、高级制茶师。是学校依托职业教育培育成才、深耕贵州茶产业、助力乡村振兴的优秀校友。在校期间依托学校系统化专业教学与校内外实训资源夯实茶学功底，走出校园后深耕茶产业，凭借扎实专业素养从应届毕业生成长为行业骨干、创业先锋，用实干印证职业教育赋能出彩人生。"}, {"type": "paragraph", "text": "从踏入校园的那一刻起，杨荣就与茶结下了不解之缘。通过不断的努力与坚持，杨荣在茶艺领域取得了一些成绩，也找到了属于自己的职业方向。"}, {"type": "paragraph", "text": "缪慢"}, {"type": "paragraph", "text": "缪慢，2017级园林工程技术专业学生，从专科起点，历经专升本、考研读研，再成功申博、即将入读博士，以步步深耕、持之以恒的求学之路，书写了职院学子逆袭成长的励志答卷，生动诠释“人生没有白走的路，每一步付出皆有回响”。"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,5,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(19,37,111,'modern-agriculture-achievements','achievements','achievement','专题成果','','教科研成果、课题项目...','[{"type": "paragraph", "text": "教科研成果、课题项目..."}, {"type": "paragraph", "text": "序号 / 项目名称 / 数量 / 备注 1 / 毕节特色中药材产业实训基地 / 1 / 2020年贵州省中药材产业实训基地（培育） 2 / 省精品在线开放课程 / 1 / 2020年兴黔富民行动计划《中草药栽培》 3 / 院级精品课程 / 4 / 分别于2022、2024年 4 / 道地中药材检测服务中心 / 1 / 产教融合技术技能创新平台 5 / 参编《药用用植物栽培技术》第三版 / 1 / 2020年高等职业教育农业部“十二五”规划教材高等职业教育“十四五”规划教材 6 / 院级教材 / 2 / 2024年 7 / 校外实训基地 / 6 / 威宁天露、大方九龙、贵州乌蒙腾等 8 / 中药炮制技能大师工作室 / 1 / 董志颖（上海中医药大学）、黎代余等 9 / “中草药栽培与加工技术教师教学创新团队” / 1 / 张士齐等 10 / 学生参与各类比赛获奖 / 20 / 省级 11 / 团队教师主持参与项目 / 20 / 省级、市级 12 / 贵州省科技特派员 / 2 / 2022年 13 / 毕节市科技特派员 / 3 / 2024年 14 / 毕节市科普专家 / 4 / 2022年"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,6,1,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
INSERT INTO "content_items" VALUES(20,37,112,'modern-agriculture-honors','honors','honor','荣誉资质','','技能大赛获奖证书','[{"type": "paragraph", "text": "技能大赛获奖证书"}, {"type": "paragraph", "text": "学生技能大赛获奖证书"}, {"type": "paragraph", "text": "2025年教师获奖"}, {"type": "paragraph", "text": "2024年中药专业教师指导学生智慧农业种植大赛获奖"}, {"type": "paragraph", "text": "2025年中药专业教师指导学生中药传统技能大赛获奖"}, {"type": "paragraph", "text": "2025年中药专业教师指导学生中药传统技能大赛获奖"}, {"type": "paragraph", "text": "2025年中药专业教师指导学生创新创业大赛获奖"}, {"type": "paragraph", "text": "视频资料（专业特色，可于所在区域屏幕循环播放）"}]','{"sourceDoc": "创新育人-现代农业(1).docx", "updatedAt": "2026-08-04"}',NULL,7,0,1,'approved',NULL,'admin','admin','','2026-08-04T09:41:45.959916+00:00','2026-08-04T09:41:45.959916+00:00');
