CREATE TABLE lowcode_record_assets (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            record_id INTEGER NOT NULL,
            asset_id INTEGER,
            role TEXT NOT NULL DEFAULT 'gallery',
            title TEXT NOT NULL DEFAULT '',
            caption TEXT NOT NULL DEFAULT '',
            url TEXT NOT NULL DEFAULT '',
            sort_order INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        );
CREATE TABLE lowcode_records (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            form_id INTEGER NOT NULL,
            form_version_id INTEGER NOT NULL,
            project_id INTEGER NOT NULL,
            content_item_id INTEGER,
            status TEXT NOT NULL DEFAULT 'pending',
            data_json TEXT NOT NULL,
            submitted_by TEXT NOT NULL DEFAULT '',
            submitted_at TEXT NOT NULL,
            reviewed_by TEXT NOT NULL DEFAULT '',
            reviewed_at TEXT NOT NULL DEFAULT '',
            review_note TEXT NOT NULL DEFAULT '',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE page_versions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            page_id INTEGER,
            project_id INTEGER NOT NULL,
            code TEXT NOT NULL,
            operation TEXT NOT NULL DEFAULT 'upsert',
            status TEXT NOT NULL DEFAULT 'pending',
            snapshot TEXT NOT NULL,
            submitted_by TEXT NOT NULL DEFAULT '',
            submitted_at TEXT NOT NULL,
            reviewed_by TEXT NOT NULL DEFAULT '',
            reviewed_at TEXT NOT NULL DEFAULT '',
            review_note TEXT NOT NULL DEFAULT '',
            changes TEXT NOT NULL DEFAULT ''
        );
INSERT INTO "page_versions" VALUES(1,5,15,'BJ-SERVICE','upsert','approved','{"code": "BJ-SERVICE", "category": "社会服务成果", "source": "毕节职业技术学院", "publishedAt": "", "title": "社会服务成果", "subtitle": "聚焦技能培训、职业认定与乡村振兴服务，测试指标卡、图文组合与引用块。", "body": "<div class=\"lead-card\"><span>SOCIAL SERVICE</span><strong>服务地方产业与技能人才培养</strong><p>学校围绕毕节新发展理念示范区建设，聚焦现代能源、生态食品、先进装备制造、轻纺及健康医药等产业，持续开展职业技能培训、等级认定和乡村振兴服务。</p></div>\n<div class=\"stat-grid\"><div class=\"stat\"><strong>45000+</strong><span>培训人次</span><p>联合政校企完成多类型技术技能培训。</p></div><div class=\"stat\"><strong>15000+</strong><span>认定人次</span><p>面向学生和社会人员开展职业技能等级认定。</p></div><div class=\"stat\"><strong>八大产业</strong><span>服务方向</span><p>对接地方工业产业和特色农业发展需求。</p></div></div>\n<h2>重点服务方向</h2><ul><li>高技能人才、基层服务、煤矿安全技术、退役军人就业创业培训。</li><li>乡村振兴技能人才培养和非物质文化遗产传承人群研修研习。</li><li>职业技能等级认定与专项职业能力认定平台建设。</li></ul>\n<div class=\"photo-strip\"><figure><img src=\"/uploads/bijie-samples/image1.jpeg\" alt=\"培训现场\"><figcaption>毕节市财政财务基础业务培训班</figcaption></figure><figure><img src=\"/uploads/bijie-samples/image16.jpeg\" alt=\"稻米示范推广培训\"><figcaption>优质稻米示范推广培训进入田间地头</figcaption></figure></div>\n<blockquote>以学校技术资源和师资优势服务地方产业发展，助力毕节市人力资源开发和乡村全面振兴。</blockquote>", "imageUrl": "/uploads/bijie-samples/image16.jpeg", "accent": "#49c5b6", "enabled": true}','admin','2026-07-16T02:42:30.580908+00:00','admin','2026-07-16T02:42:30.580908+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(2,6,15,'BJ-INTL','upsert','approved','{"code": "BJ-INTL", "category": "国际交流合作", "source": "毕节职业技术学院", "publishedAt": "", "title": "国际交流合作成果", "subtitle": "从海外研学到职业标准输出，测试时间线、列表、图片和分隔线。", "body": "<div class=\"lead-card\"><span>GLOBAL COOPERATION</span><strong>从“引进来”到“走出去”的国际合作</strong><p>学校主动服务“一带一路”倡议和中国-东盟、中非教育合作，在海外交流、标准输出、多边合作、技能竞赛、人文往来等方面形成阶段性成果。</p></div>\n<div class=\"timeline\"><div><span>2024</span><p>组织师生赴泰国格乐大学开展短期研学，拓宽学生国际视野，增进中泰人文交流。</p></div><div><span>2025</span><p>牵头制定菲律宾《农业经理人》国家职业技能标准，并参与中国-东盟数字资源共建共享合作。</p></div><div><span>近三年</span><p>累计接待国（境）外来访团组 4 个，举办国际文化交流活动 4 场，签订校际合作备忘录 2 份。</p></div></div>\n<h2>成果看点</h2><ul><li>获批埃塞俄比亚国家职业标准开发项目认证。</li><li>课程资源被俄罗斯喀山联邦大学、埃塞俄比亚 Dire Dawa University 采用。</li><li>师生在金砖国家技能发展与技术创新大赛等国际赛事中获得多项奖项。</li></ul>\n<div class=\"photo-strip\"><figure><img src=\"/uploads/bijie-samples/image23.jpeg\" alt=\"泰国研学合影\"><figcaption>师生赴泰国格乐大学开展短期研学</figcaption></figure><figure><img src=\"/uploads/bijie-samples/image31.jpeg\" alt=\"国际人文交流活动\"><figcaption>“桥见”贵州毕节职院人文交流活动</figcaption></figure></div>\n<hr><p>这一页用于测试时间线、图文组合、列表与分隔线在大屏详情页中的可读性。</p>", "imageUrl": "/uploads/bijie-samples/image23.jpeg", "accent": "#f8c35a", "enabled": true}','admin','2026-07-16T02:42:30.580908+00:00','admin','2026-07-16T02:42:30.580908+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(3,7,15,'BJ-GRAD','upsert','approved','{"code": "BJ-GRAD", "category": "育人成果", "source": "教育科学系", "publishedAt": "", "title": "优秀毕业生张娅婷", "subtitle": "以人物卡片、荣誉标签和分段叙事展示优秀毕业生成长故事。", "body": "<div class=\"profile-card\"><img src=\"/uploads/bijie-samples/image38.jpeg\" alt=\"张娅婷事迹照片\"><div><span>优秀毕业生</span><h3>张娅婷</h3><p>贵州省 2024 届优秀毕业生，学前教育专业。她在校园学习、学生工作、志愿服务和西部计划实践中持续成长。</p></div></div>\n<div class=\"badge-list\"><span>中共党员</span><span>教育科学系</span><span>学前教育</span><span>国家奖学金</span><span>省级优秀毕业生</span></div>\n<h2>一路追光，筑梦前行</h2><p>在校期间，她担任系学生会团总支副书记、学生会主席、班级团支部书记与班长，荣获全国乡村振兴“笃行计划优秀实践个人”、励志奖学金、省三好学生等荣誉。</p>\n<h3>敢担当</h3><p>2021 年至 2023 年，她承担学生组织工作，并于 2023 年赴马来西亚英迪国际大学短期访学，按期高质量完成学业。</p>\n<h3>能吃苦</h3><p>连续两年参加“三下乡”社会实践，组织关爱留守儿童、服务空巢老人和民族文化传承活动，在实践中锤炼专业能力和社会责任。</p>\n<h3>有理想</h3><p>2024 年 8 月，她投身贵州省毕节市七星关区碧阳街道办事处西部计划志愿服务，参与档案整理、热线回应和志愿服务等工作。</p>\n<div class=\"template-note\"><strong>教师评语</strong><p>希望你用行动去诠释教育的真谛，展现青春的力量。</p></div>", "imageUrl": "/uploads/bijie-samples/image37.png", "accent": "#ff8f5a", "enabled": true}','admin','2026-07-16T02:42:30.580908+00:00','admin','2026-07-16T02:42:30.580908+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(4,8,15,'BJ-TEACHER','upsert','approved','{"code": "BJ-TEACHER", "category": "名师名匠", "source": "旅游管理系", "publishedAt": "", "title": "校内名师谭佳", "subtitle": "用人物介绍、数据卡和成果列表展示名师名匠内容模板。", "body": "<div class=\"profile-card\"><img src=\"/uploads/bijie-samples/image39.jpeg\" alt=\"谭佳 portrait\"><div><span>校内名师</span><h3>谭佳</h3><p>旅游管理系副教授，聚焦旅游技能人才培养、数智赋能课程建设等教学教改方向。</p></div></div>\n<div class=\"stat-grid\"><div class=\"stat\"><strong>10+</strong><span>省部级、市厅级项目</span><p>主持并推进多项教学教改与社会服务项目。</p></div><div class=\"stat\"><strong>10000+</strong><span>课程覆盖人次</span><p>开发《乡村旅游导览实务》等培训课程。</p></div><div class=\"stat\"><strong>30+</strong><span>团队课题</span><p>围绕生态旅游、红色讲解、研学旅游开发等方向开展研究。</p></div></div>\n<h2>教学与产业服务成果</h2><ul><li>获全国教师教学能力大赛三等奖、省赛一等奖。</li><li>实践成果入选文旅部优秀成果并在全国推广。</li><li>教学案例入选文旅部旅游职业教育“五金”数智化建设典型案例。</li></ul>\n<div class=\"photo-strip\"><figure><img src=\"/uploads/bijie-samples/image32.jpeg\" alt=\"论坛发言\"><figcaption>在论坛活动中进行主旨发言</figcaption></figure><figure><img src=\"/uploads/bijie-samples/image30.jpeg\" alt=\"校园成果展示\"><figcaption>职业教育成果面向行业与社会展示</figcaption></figure></div>\n<blockquote>通过老带新、师带徒，优化人才结构，赋能贵州文旅产业高质量发展。</blockquote>", "imageUrl": "/uploads/bijie-samples/image32.jpeg", "accent": "#8bd17c", "enabled": true}','admin','2026-07-16T02:42:30.580908+00:00','admin','2026-07-16T02:42:30.580908+00:00','','legacy import');
