INSERT INTO "page_versions" VALUES(8,9,15,'DEMO-10100043','delete','approved','{"code": "DEMO-10100043", "category": "校园新闻", "source": "学校展示", "publishedAt": "", "title": "欢迎来到成果展示", "subtitle": "深圳先进技术研究院展会互动展示", "body": "这里可以放项目介绍、展品亮点、团队说明和现场引导文案。后台可以随时替换这些文字和图片。", "imageUrl": "/static/sample.svg", "accent": "#0f766e", "enabled": false}','admin','2026-07-16T03:52:14.627497+00:00','admin','2026-07-16T03:52:14.627497+00:00','','');
INSERT INTO "page_versions" VALUES(9,22,25,'BP-DEPT-MINING_CONSTRUCTION-OVERVIEW','upsert','approved','{"code": "BP-DEPT-MINING_CONSTRUCTION-OVERVIEW", "category": "基本情况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "智慧矿山、智能制造与现代建造", "body": "<figure><img src=\"/uploads/blueprint/departments/mining-construction/images/img01.webp\" alt=\"\"></figure>\n<p>系部简介：</p>\n<p>工矿建筑系2008年成立，开设建筑工程技术、煤矿智能开采技术、智能机电技术、安全技术与管理、测绘工程技术、应用化工技术、新能源汽车检测与维修技术、资源综合利用技术、无人机应用技术等9个高职专业和煤矿开采中技专业，与贵州工程应用技术学院联合培养土木工程、工程管理、采矿工程3个本科专业学生。建筑工程技术、煤矿智能开采技术专业群为贵州省高水平专业群。</p>\n<p>现有教职工82人，博士、教授、副教授等高层次人才齐备。建有国家、省、市三级高技能人才培训基地，打造模拟矿井、智能综采中心、建筑模型等30余间实训室，实训总投入近1.4 亿元。</p>\n<p>依托统战资源对接广州港、广汽、奇瑞等东部龙头企业，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>\n<p>累计培养学生2万余名，斩获国家级教学成果二等奖1项、省级一等奖2项，近三年学生竞赛获奖120余项，获评贵州省脱贫攻坚先进集体；教师承担省市级科研项目50余项，年度横向经费到账80余万元，成果丰硕。</p>", "imageUrl": "/uploads/blueprint/departments/mining-construction/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(10,23,26,'BP-DEPT-FINANCE-OVERVIEW','upsert','approved','{"code": "BP-DEPT-FINANCE-OVERVIEW", "category": "基本情况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "数字商贸、智慧物流与财务实践", "body": "<p>改：财政经济系于 2008 年组建，开设大数据与会计、现代物流管理、电子商务三大专业，年均在校生约 1600 人。2022 年起与贵州工程应用技术学院联合培养财务管理本科班。</p>\n<p>电子商务专业为毕节市人民政府授牌 \"毕节电子商务学院\"，专业群获评贵州省职业教育特色骨干专业群（优秀等次）；大数据与会计专业为省级骨干专业。加入全国直播电商职业教育集团等 5 个国家级产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体（成员单位 120 余家）。拥有贵州省农业电商产业扶贫协同创新中心、高水平乡村电商产教融合实训基地等省级项目 11 项，获批市级数商兴农人才团队、省级教学创新人才团队。先后荣获省级五好基层党组织、市级样板院系、全国五四红旗团支部、全国活力团支部等荣誉。</p>\n<p>学生专升本上线率 93%、录取率 89%。2025年荣获贵州省教学成果特等奖；技能大赛斩获国家级铜奖5项、省级一等奖12项，各级各类奖项累计400余项，为区域经济社会发展作出积极贡献。</p>\n<figure><img src=\"/uploads/blueprint/departments/finance/images/img01.webp\" alt=\"\"></figure>\n<p>京东实战班618校内真岗实战</p>\n<figure><img src=\"/uploads/blueprint/departments/finance/images/img02.webp\" alt=\"京东实战班618校内真岗实战\"><figcaption>京东实战班618校内真岗实战</figcaption></figure>\n<p>物流专业教师开展校内专业教学</p>\n<figure><img src=\"/uploads/blueprint/departments/finance/images/img03.webp\" alt=\"物流专业教师开展校内专业教学\"><figcaption>物流专业教师开展校内专业教学</figcaption></figure>\n<p>学生到昆山亚洲一号物流园开展实践教学</p>", "imageUrl": "/uploads/blueprint/departments/finance/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(11,24,27,'BP-DEPT-INFORMATION-OVERVIEW','upsert','approved','{"code": "BP-DEPT-INFORMATION-OVERVIEW", "category": "基本情况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "人工智能、网络安全与数字技术", "body": "<p>电子信息工程系系部介绍</p>\n<p>毕节职业技术学院电子信息工程系溯源于1996年成立的毕节农业学校计算机教研室，2008年正式建系，至今已有30年办学积淀。现有教职工40余人，其中副高以上职称占比32.3%，“双师型”教师达83.3%。</p>\n<p>现开设计算机应用技术（省级重点特色专业）、人工智能技术应用（省级现场工程师培训基地）、计算机网络技术三个专业，在校生1500人。学生职业证书获取率达92%，毕业生就业去向落实率长期保持在90%以上。近三年获省级以上比赛奖项46项（国家级三等奖1项、省级一等奖6项、省级二等奖10项、省级三等奖14项）；创新创业类比赛获国家级银奖1项、省级银奖2项、省级铜奖16项；“挑战杯”比赛获省级二等奖1项、省级三等奖5项、省级优秀奖1项。</p>\n<p>系部建有国家级计算机应用技术高技能人才培养基地1个、国家级小米AIoT工程师能力培训中心1个、省级重点（特色）专业1个、省级人工智能现场工程师培训基地1个。入选全国新一代信息技术、全国大数据、全国人工智能、全国信息安全行业产教融合共同体理事单位。与小米、360、H3C等头部企业深度合作，共建人工智能产业学院、360数智安全产业学院、H3C网络学院，实现课堂与岗位无缝对接。</p>\n<p>1.师生在2025年省第二届网络安全实战赛获奖</p>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img01.webp\" alt=\"1.师生在2025年省第二届网络安全实战赛获奖\"><figcaption>1.师生在2025年省第二届网络安全实战赛获奖</figcaption></figure>\n<p>2.系部学生王恩利利用数字化技术服务乡村被中央电视台报道</p>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img02.webp\" alt=\"2.系部学生王恩利利用数字化技术服务乡村被中央电视台报道\"><figcaption>2.系部学生王恩利利用数字化技术服务乡村被中央电视台报道</figcaption></figure>\n<p>3.系部学生参加2024全国职业院校技能大赛获奖</p>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img03.webp\" alt=\"3.系部学生参加2024全国职业院校技能大赛获奖\"><figcaption>3.系部学生参加2024全国职业院校技能大赛获奖</figcaption></figure>\n<p>4.荣获小米优秀合作院校表彰</p>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img04.webp\" alt=\"4.荣获小米优秀合作院校表彰\"><figcaption>4.荣获小米优秀合作院校表彰</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/information/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(12,25,28,'BP-DEPT-MEDICAL_NURSING-OVERVIEW','upsert','approved','{"code": "BP-DEPT-MEDICAL_NURSING-OVERVIEW", "category": "基本情况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "临床护理、康养服务与急救教育", "body": "<p>系部简介：医学护理系</p>\n<p>医学护理系始建于2011年，是毕节市内首批开设卫生健康类专业的高职院校，作为区域内医疗卫生与大健康服务领域高素质技术技能人才重点培养基地。</p>\n<p>紧扣大健康产业发展需求设置专业，现开设护理、老年保健与管理、智慧健康养老服务与管理三大专业，精准对接临床护理、健康养老、基层社会服务核心岗位。师资队伍结构优良，双师型教师占比超95%。</p>\n<p>现拥有国家级高技能人才培训基地（康养家政护理）、全国学校急救教育试点学校两大国家级平台；美国心脏协会心血管急救培训中心、贵州省红十字会救护员取证培训试点等省级平台。系部为全国智慧健康养老行业产教融合共同体第一届理事单位、铜仁市健康养老行业产教融合共同体副理事单位，联动省内外20余家优质单位共建校外实训基地，构建岗课训赛一体化育人体系。</p>\n<p>校内建有标准化模拟医院、AHA急救培训中心等35个实训场地。办学至今累计培养优秀技能人才6000余人，学生护士执业资格考试通过率稳定在95%、专升本上线率达94%，师生累计斩获国家级、省级奖项180余项，乡村义诊服务群众超7万人次，人才质量获行业高度认可。</p>\n<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img01.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img02.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img03.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img04.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/departments/medical-nursing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(13,26,29,'BP-DEPT-TOURISM-OVERVIEW','upsert','approved','{"code": "BP-DEPT-TOURISM-OVERVIEW", "category": "基本情况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "数字文旅、酒店运营与烹饪技艺", "body": "<p>旅游管理系简介：</p>\n<p>旅游管理系2010年成立，开设旅游管理、酒店管理与数字化运营、烹饪工艺与营养3个高职专业，饭店（酒店）服务、烹饪（中式烹调）2个中技专业，旅游管理专业为省级重点特色专业。</p>\n<p>共计专兼职教师35人，双师型教师比例达95%以上。其中，文旅部“万名旅游英才”2名，农业农村部“名课名师”1名，贵州省技术能手3名，毕节工匠3名。</p>\n<p>先后建成贵州乡村旅游虚拟仿真实训基地、毕节数字文旅开放型产教融合实践中心2个省级产教融合基地，烹饪工艺与营养黔匠工坊1个省级工坊，洞天花海产业学院、大方九驿街道乡村旅游学院2个产业学院。</p>\n<p>依托东西部协作、统一战线帮扶、聚焦地方产业发展，开设广州地铁集团、广州岭南集团越秀集团、广州酒家等优质订单班，与牵头成立“全国乡村生态旅游行业产教融合共同体”“毕节市乡村生态旅游市域产教联合体”。</p>\n<p>近五年，立项省级“校旅结合”示范校、省级虚拟仿真实训基地、省级黔匠工坊等18个省级建设项目。育人模式获贵州职业教育教学成果二等奖、贵州省第五届教育科学研究优秀成果三等奖；团队获全国职业院校教师教学能力大赛三等奖、贵州省职业院校教师教学能力一等奖。师生先后获省级一等奖22人次、二等奖30人次、三等奖若干。办学特色鲜明、成果显著！</p>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img01.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img02.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img03.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img04.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/departments/tourism/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(14,27,30,'BP-TOPIC-SMART_ENERGY-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>系部简介：工矿建筑系</p>\n<p>工矿建筑系2008年成立，下设矿业、机电、建筑三个教研室，设建筑工程技术、煤矿智能开采技术、智能机电技术、安全技术与管理、测绘工程技术、应用化工技术、新能源汽车检测与维修技术、资源综合利用技术等8个高职专业和煤矿开采中技专业，与贵州工程应用技术学院开展联合培养土木工程、工程管理、采矿工程3个本科专业。建筑工程技术、煤矿智能开采技术获批两个省级高水平专业群。</p>\n<p>办学基础好。系部现有教职工82人，博士、教授、副教授等高层次人才齐备，双师型教师49人。先后获批国家高技能人才培训基地、毕节市智能矿山产教融合实训基地、贵州省开放性实训基地等多个项目支持，建成模拟矿井、智能综采实训中心、智能综掘进实训中心、建筑等比例模型、智能机电实训中心、应用化工专业实训室等30余个实训室，总投入资金近1.4亿元。</p>\n<p>产教融合实。依托统一战线帮扶，与东部广州港集团、广汽集团、奇瑞控股集团等龙头企业开展深度合作，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>\n<p>办学质量高。累计培养学生2万余名。获国家教学成果二等奖1项、省级教学成果一等奖2项。近三年学生在各类大赛中获奖120余项。系部获“贵州省脱贫攻坚先进集体”等优秀称号。</p>\n<p>科研能力强。教师主持省市级科研项目 50 余项，一年来开展横向课题经费到账80余万元。</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(15,28,30,'BP-TOPIC-SMART_ENERGY-MAJORS','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "专业设置", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>绿色智慧能源专业群（省级高水平专业群）</p>\n<p>绿色智慧能源专业群立足省级高水平建设定位，以煤矿智能开采技术为核心，整合安全技术与管理、应用化工技术、资源综合利用技术、测绘工程技术五大专业，聚焦煤炭绿色开发、磷煤化工、资源循环利用、智慧测绘等领域，服务贵州省基础能源、毕节市精细磷煤化工及资源综合利用产业集群。</p>\n<p>专业群对接智能矿山建设、煤炭安全高效生产、化工工艺管控、固废资源化利用、矿山测绘与地理信息等关键环节，面向智能采掘工程师、安全监测监控师、化工工艺技术员、资源综合利用工程师、测绘与地理信息技术员等岗位，培养懂技术、会操作、能运维的高技能人才。</p>\n<p>深度联动区域煤炭、化工、资源利用龙头企业，围绕智能开采、安全管控、化工生产、资源循环、精准测绘核心技能，构建 “岗课赛证” 融合育人体系，助力煤炭产业低碳转型、资源高效利用与智慧矿山建设，为区域绿色智慧能源产业高质量发展提供人才支撑。</p>\n<p>综掘实训室掘进机 / 综采实训中心</p>\n<p>煤矿智能开采技术专业</p>\n<p>培养目标：本专业坚持立德树人，面向煤炭开采和洗选行业的发展需求。培养理想信念坚定与德智体美劳全面发展，具备良好职业道德、人文素养、科学素养和数字素养，掌握煤矿智能开采相关理论知识与技术技能，能够适应智能化矿山建设和生产一线岗位要求的高技能人才。毕业生应具有较强的岗位实践能力、技术应用能力、就业创业能力和持续发展能力，能够胜任智能化工作面采掘施工、采掘生产组织、通风技术管理及智能开采安全管理等工作。</p>\n<p>核心课程:《智能化采煤方法》、《采掘机械使用与维护》、《巷道智能掘进技术》、《矿井智能通风技术》、《智能采掘电气》、《煤矿安全技术》、《矿山压力观测与控制》、《智能监测监控技术》等。</p>\n<p>专业特色：煤矿智能开采技术专业是贵州省第二批高水平专业群核心专业，办学历史悠久，深度融合贵州省区域经济发展。先后获得国家、省、市多个项目支持，建成了目前省内职业院校规模最大、设备最为齐全的模拟矿井和综采实训中心。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img01.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img02.webp\" alt=\"\"></figure>\n<p>综采工作面“三机”配套设备 液压支架操作实训</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img03.webp\" alt=\"综采工作面“三机”配套设备 液压支架操作实训\"><figcaption>综采工作面“三机”配套设备 液压支架操作实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img04.webp\" alt=\"综采工作面“三机”配套设备 液压支架操作实训\"><figcaption>综采工作面“三机”配套设备 液压支架操作实训</figcaption></figure>\n<p>模拟矿井主平硐地面瓦斯抽放泵房</p>\n<p>就业去向：毕业生主要面向煤矿企业智能化综采、智能化掘进、矿井通风、安全技术管理、机电运输和生产调度等岗位就业和自主创业，从事采掘生产组织、设备运行维护、通风安全管理、现场技术管理及智能化系统应用等业务工作。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img05.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img06.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img07.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img08.webp\" alt=\"\"></figure>\n<p>应用化工技术专业</p>\n<p>培养目标：本专业旨在培养自觉践行社会主义核心价值观，具备扎实科学文化基础、良好人文科学素养、职业道德、创新意识、爱岗敬业职业精神和精益求精工匠精神，拥有较强的创新创业能力和可持续发展素养的高素质技术技能人才。学生将掌握基础化学、化学反应器、典型产品生产工艺、化工过程模拟、个人防护、HSE与清洁生产等专业理论知识；熟练掌握化工单元现场操作、中控操作技能等专业技能，具备化工装置高效运维、生产工艺流程优化、工艺方案评估的能力，可处理一般生产性突发事故，能够胜任班组生产管理工作。同时具有适应化工行业数字化和智能化发展需求，能综合运用专业知识解决生产实际问题，毕业后可从事化工生产操作与控制、生产管理和工艺技术优化等岗位工作。</p>\n<p>核心课程：化工传热与控制技术、化工分离与控制技术、化学反应过程及设备、化工生产技术、化工生产DCS操作、化工安全技术、磷系新型储能材。</p>\n<p>就业方向：主要面向化学原料和化学制品制造业，针对以基础化学原料、精细化工、新材料产业、医药化工、化工产品质量检测等为主营业务的国有或民营化工企业、专用化学品企业、技术服务机构等类型单位的就业和自主创业。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img09.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img10.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img11.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img12.webp\" alt=\"\"></figure>\n<p>安全技术与管理专业</p>\n<p>培养目标：本专业培养理想信念坚定，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、职业道德和创新意识，德技并修、精益求精的工匠精神，较强的就业创新创业能力和可持续发展能力，掌握安全技术与管理的专业知识和技术技能，面向相关行业领域企事业单位、专业技术服务行业以及应急管理部门的技术人员、管理人员、行政执法人员等职业群，能够从事安全检查与管理、安全评价、安全技术咨询等工作的高素质技术技能人才。</p>\n<p>主要课程：《安全管理》、《安全评价技术》、《防火与防爆技术》、《电气安全技术》、《智能安全监测与监控技术》、《安全生产事故调查与案例分析》、《工业通风与除尘》、《安全系统工程》、《安全人机工程》、《电工技术》、《安全法律法规》。</p>\n<p>实训条件：安全技术与管理专业校内实践教学基地设备总价值1800余万元，每个实训基地（实训室）均能同时满足30～40人开展实习实训，优越的实习实训基地为学生的生产实习实训奠定了坚实基础。</p>\n<p>就业去向：职业服务领域面向安全生产领域相关企事业单位，可在煤矿安全监察部门、矿山设计研究院、矿产企业等从事安全生产项目设计、施工、生产、组织、管理及检测等技术技能工作。</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(16,29,30,'BP-TOPIC-SMART_ENERGY-TRAINING','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-TRAINING", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "实训基地", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>煤矿智能开采技术专业群群内专业协同互补，聚焦智能开采、化工生产、安全保障三大领域，建有总投资1.2亿元的智能矿山产教融合实训基地、省级安全培训基地，实训条件省内一流。</p>\n<p>综掘实训室掘进机 / 综采实训中心</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img13.webp\" alt=\"综掘实训室掘进机 / 综采实训中心\"><figcaption>综掘实训室掘进机 / 综采实训中心</figcaption></figure>\n<p>煤矿智能开采技术专业学生在综采工作面操作液压支架</p>\n<p>智能矿山产教融合实训基地 ？</p>\n<p>智能综采实训中心</p>\n<p>主要功能：一是开展采煤机结构认识、液压支架结构认识，综采工作面“三机”配套设备组成认识实训；二是开展液压支架、刮板输送机、胶带输送机操作实训。</p>\n<p>承担的教学任务：可开展《智能开采机械使用与维护》课程中液压支架操作、刮板输送机操作、胶带输送机操作等实训。</p>\n<p>模拟矿井实训基地</p>\n<p>主要功能：一是开展矿井生产系统认识实训；二是开展局部通风机操作实训（含反风）；三是开展掘进工作面风筒安装实训；四是开展矿井巷道布置实训；五是开展采掘工作面传感器布置实训；六是开展机电设备结构认识实训。</p>\n<p>承担的教学任务：可开展《采掘电气》《巷道施工与智能掘进技术》等课程实训。</p>\n<p>1楼 智能综采实训中心：布置煤矿采煤工作面三机配套技术，能满足采煤机司机、液压支架工、皮带机司机等工种技能培训。智能综掘实训中心：布置煤矿掘进工作面及配套技术，满足掘进机司机、瓦斯抽放工、瓦斯检查工等工种技能培训。AR-VR实训中心：布置井下模拟生产场景和各主要核心技能体验，实现井下多个工种模拟考核及培训。综合管控平台（地面调度中心）：布置综合管控平台和煤矿井下调度中心，引入煤矿实际生产场景数据，并实现与智能综采实训中心和智能综掘实训中心设备远程控制。</p>\n<p>2楼 技能大赛训练中心：布置无人机救援系统、事故坍塌救援系统、电力恢复系统和防灭火装置系统等，能完成安全生产事故应急救援方面的技能训练。瓦斯治理实训室：布置瓦斯抽采、瓦斯突出等实训设备，能完成瓦斯抽采钻孔布置、瓦斯抽采和瓦斯突出等实训。机电实训室：布置煤矿井下各种馈电开关和机电监测控制系统，可满足学生从模拟训练、安全电压下操作到井下一致设备操作的培训。矿井通风实训室：布置井下矿井通风系统，能实现井下风流控制、反风等功能。</p>\n<p>3楼 安全巡检实训室：布置巡检机器人及煤矿相关检测设备，能实现煤矿安全巡检、机器设备探伤及井下相关设备维护保养的日常训练。矿山压力观测实训室：布置了矿山压力控制装置及测量设备，能开展煤矿井下测量、矿山压力显现及控制等实训。PLC控制实训室：能开展煤矿井下智能化控制技术训练和智能化技术培训。</p>\n<p>4楼 无人机应用技术实训室：能开展无人机操作培训和实训。</p>\n<p>5楼 应用化工技术单元操作实训室：能开展应用化工技术液体传热、蒸馏、萃取等实训和培训。应用化工技术基础实训室：能开展化学基础实验实训和培训。矿山生态修复实训室：能开展矿山环境治理研究、生态修复研究等实训以及社会培训。</p>\n<p>安全技术与管理校内实践教学基地</p>\n<p>安全技术与管理专业校内实践教学基地设备总价值1800余万元，每个实训基地（实训室）均能同时满足30～40人开展实习实训，优越的实习实训基地为学生的生产实习实训奠定了坚实基础。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img14.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img15.webp\" alt=\"\"></figure>\n<p>煤与瓦斯突出防治操作演示 生产事故应急救援实训</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img16.webp\" alt=\"煤与瓦斯突出防治操作演示 生产事故应急救援实训\"><figcaption>煤与瓦斯突出防治操作演示 生产事故应急救援实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img17.webp\" alt=\"煤与瓦斯突出防治操作演示 生产事故应急救援实训\"><figcaption>煤与瓦斯突出防治操作演示 生产事故应急救援实训</figcaption></figure>\n<p>采煤工作面 采煤工作面回风巷</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img18.webp\" alt=\"采煤工作面 采煤工作面回风巷\"><figcaption>采煤工作面 采煤工作面回风巷</figcaption></figure>\n<p>煤矿安全培训基地</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img19.webp\" alt=\"煤矿安全培训基地\"><figcaption>煤矿安全培训基地</figcaption></figure>\n<p>矿山机器人巡检</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img20.webp\" alt=\"矿山机器人巡检\"><figcaption>矿山机器人巡检</figcaption></figure>\n<p>突发事故应急救援（cpr）</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img21.webp\" alt=\"突发事故应急救援（cpr）\"><figcaption>突发事故应急救援（cpr）</figcaption></figure>\n<p>智能监测监控实训室</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img22.webp\" alt=\"智能监测监控实训室\"><figcaption>智能监测监控实训室</figcaption></figure>\n<p>综采工作面安全操作实训</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img13.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(17,30,30,'BP-TOPIC-SMART_ENERGY-COOPERATION','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "产教融合", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>对接产业</p>\n<p>产教融合成果</p>\n<p>产教融合实。依托统一战线帮扶，与东部广州港集团、广汽集团、奇瑞控股集团等龙头企业开展深度合作，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img23.webp\" alt=\"\"></figure>\n<p>牵头成立西南地区新型综合能源行业产教融合共同体 毕节市智能矿山市域产教联合体</p>\n<p>校企合作订单班/产业学院</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img23.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(18,31,30,'BP-TOPIC-SMART_ENERGY-MASTERS','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-MASTERS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "名师名匠", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img24.webp\" alt=\"高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人\"><figcaption>高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人</figcaption></figure>\n<p>2006年毕业于辽宁工程技术大学采矿工程专业，获工学硕士学位，2006年4月参加工作，从事煤矿瓦斯灾害防治研究与教学工作19年。</p>\n<p>主要研究方向为煤矿瓦斯灾害防治、浆体管道输送竖直段管路阻力损失研究。主持市级及以上科研项目4项，主持或参与国家重大专项子课题1项、省部级项目1项、中煤科工集团二级企业技术创新项目1项，横向重点项目40余项；授权国家发明专利4项，撰写科研、咨询报告50余篇。获省部级奖励13项，其中个人证书3项、集体奖10项。发表学术论文20篇，其中中文核心期刊独著5篇、第一作者5篇，中文科技期刊独著4篇、第二作者2篇，EI检索国际会议独著2篇，参编教材1部。牵头申报煤炭行业井工煤矿智能化实训（实习）基地、煤炭行业教育培训贵州基地，培养青年教师5名，在安全工程专业建设、煤矿安全科研与人才培养方面成果显著。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img25.webp\" alt=\"\"></figure>\n<p>王锦 教授 一级建造师，工矿建筑系建筑工程技术专业带头人</p>\n<p>2007年毕业于重庆交通大学工程管理专业，获工学学士学位，2007年7月参加工作，从事建筑工程施工管理与教学工作18年。主要研究方向为建筑施工安全管理、建筑材料研究。主持市级及以上科研项目2项，主持或参与省部级质量工程项目和技能贵州项目2项；授权国家发明专利1项。发表学术论文15余篇。牵头申报住房和城乡建设领域现场人员培训（实习）基地、贵州省建设质量检测培训基地，在建筑工程技术专业建设与人才培养方面成果显著。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img26.webp\" alt=\"\"></figure>\n<p>罗根华 工学博士 副教授 工矿建筑系专任教师</p>\n<p>深耕环境污染控制技术、矿山环境生态修复等领域科研与教学工作二十余年，主持及参与市级及以上教科研项目7项，其中国家自然科学基金项目2项；承接企业委托横向项目近30项。科研成果先后荣获1项辽宁省科技进步奖二等奖、市厅级科技进步奖一等奖3项；累计发表北大核心及以上级别期刊论文18篇，获授权发明专利3项，主编高职教材1部。从教以来获评校优秀教师、优秀班导师，荣获毕业生“我最喜爱的老师”等多项荣誉称号。</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img24.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(19,32,30,'BP-TOPIC-SMART_ENERGY-ALUMNI','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-ALUMNI", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀校友", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>谢佳丽 毕节职业技术学院工矿建筑系2018级工业机器人专业班学生</p>\n<p>2021年就职于广汽乘用车有限公司，担任文化活动专员职务。2021年12月荣获祺盛动力“传祺岗位小能手”称号，2022年7月荣获祺盛动力企业文化宣传系列“优秀宣传个人”称号，2022年12月荣获广汽集团支援疫情防控党员突击队“先进个人”称号。</p>\n<p>2024年4月获评广州市团干部讲党团课优秀讲师；2024年5月荣获广州市国资系统宣讲赛特等奖；2024年8月荣获广州市“十佳宣讲员”称号；2025年8月荣获广汽集团优秀团干部称号；2025年9月荣获广州市总工会乡村振兴（“百千万工程”）羊城女能手入围奖。2024年5月被聘请为国资委系统宣讲队员，其事迹被学习强国、《工人日报》等央媒及省市媒体累计报道超18次。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img27.webp\" alt=\"\"></figure>\n<p>王 祥，毕节职业技术学院工矿建筑系2017级广州港班学生</p>\n<p>2020年就职于广州港集团股份有限公司南沙集装箱码头分公司，担任龙门吊机械司机。2021年11月在央视《新闻联播》推出系列报道《弘扬伟大建党精神 开创历史新伟业》第一集《百年大党引领中华民族伟大复兴》，栏目接受采访，自2022年起任其作业大队带训师傅一职，2022年至2023年带出任职以来首批职工，2023年至2025年年初带训出第二批职工，2024年12月被评为公司“安全先进个人”。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img28.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img29.webp\" alt=\"\"></figure>\n<p>韩 赟，贵州金沙人，中共党员，毕节职业技术学院2013级煤矿开采技术专业毕业生后就读西南大学法学专业取得本科学历，2024年12月入职毕节市七星关区纪委监委，现任区纪委监委工作员。2013.9—2016.7在校期间曾任系学生会主席、院学生会副主席；2016年8月起以西部计划志愿者身份扎根赫章基层，先后在白果镇政府、金银山街道办事处、松林坡安监站、赫章县委办任职，历任党群办负责人、县委办秘书二股负责人，深耕基层服务近8年。</p>\n<p>扎根基层期间全程参与脱贫攻坚、常态化疫情防控重点工作，牵头落地“党建＋积分”“团建＋积分”基层治理创新项目。2017年获评赫章县优秀志愿者；2018年获评毕节市优秀志愿者；2019年获评贵州省优秀志愿者；第十二届中国青年志愿者优秀个人，2020年获评最美赫章人，2022年获评第十九届贵州青年五四奖章（集体），贵州省最美劳动者。转入纪检岗位后，2025年获评七星关区纪委监委优秀共产党员。扎根基层志愿服务与实干履职事迹多次被省、市主流媒体宣传报道，是贵州基层青年党员、青年志愿者先进典型代表。</p>\n<p>秦鹏，毕节职业技术学院工矿建筑系，2017级港口机械操作与维护</p>\n<p>2020年就职于广州港股份有限公司南沙集装箱码头分公司，担任岸桥司机职务。2024年7月，获得公司龙门吊比武第一名，2025年2月当选广东省工会第十五次代表大会代表。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img30.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img31.webp\" alt=\"\"></figure>\n<p>张启浪，男，汉族，中共党员</p>\n<p>在校期间思想积极上进，政治立场坚定，始终以优秀共产党员和优秀大学生的标准严格要求自己，学习、竞赛、工作与实践表现优异，综合成绩突出。</p>\n<p>他持之以恒，刻苦钻研，不断夯实专业基础、拓宽知识视野。2015年至2021年，他先后在我校完成工艺美术（中职）、建筑工程技术（高职）专业的学习，2021年7月保送到凯里学院攻读土木工程本科，逐步构建起跨学科、复合型的建筑工程知识体系。在校期间学习态度端正，成绩稳居前列，曾多次获得学院一等奖学金，被评为优秀学生干部，获得国家励志奖学金、国家奖学金等。因综合素质突出，2021年，他获得校级和贵州省优秀毕业生荣誉称号。</p>\n<p>他以赛促学，以练促长，积极参加省级、国家级技能竞赛，斩获多项荣誉。2019年4月获贵州省职业院校技能大赛一等奖，同年5月获全国职业院校技能大赛高职组建筑装饰技术应用三等奖，2022年7月获贵州省大学生结构设计竞赛三等奖，专业技能与创新能力获得充分认可。</p>\n<p>毕业后他不忘初心、勇于创业，于2023年自主创办贵州青雲工程设计有限公司，将专业知识与竞赛经验运用于实践，脚踏实地，精益求精。未来，他将继续深耕工程设计领域，积极奉献社会，展现新时代优秀毕业生的良好风貌。</p>\n<p>欧安进，中共党员，毕节职业技术学院工矿建筑系2019级汽车检测与维修技术专业汽车检测与维修班学生</p>\n<p>2022年3月至2023年5月就职于施秉县中等职业技术学校担任汽修专业教师，2023年7月至今就职于贵州永华技工学校担任新能源汽车检测与维修专业组组长。2021年9月至2022年7月，他在校期间担任班级班长，荣获以下奖项：2020年，获得国家励志奖学金，获得学院“三好学生”称号；2021年，获得国家励志奖学金，获得学院“三好学生”称号，获得工矿建筑系汽车检测与维修技能大赛一等奖；2022年，获得院级优秀毕业生称号，获得贵州省三好学生称号。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img32.webp\" alt=\"\"></figure>\n<p>陈胜利，男，年龄：37</p>\n<p>一、教育经历</p>\n<p>2010年9月--2013年7月毕业于毕节职业技术学院，专业：煤矿开采技术。</p>\n<p>二、工作经历</p>\n<p>2013年7月毕业后，2013年9月进入贵州众一金彩黔矿业有限公司瑞丰煤矿任技术员，2015年在瑞丰煤矿任技术科长，2018年在瑞丰煤矿任技术副总，2019年在瑞丰煤矿任技术负责人；2020年5月调贵州众一金彩黔矿业有限公司织金县志成煤矿任总工程师；2025年7月调贵州众一金彩黔矿业有限公司岩脚煤矿任总工程师。2020年以来一直负责贵州众一金彩黔矿业有限公司国家安全改造项目，2021年参与贵州省科技重大项目：薄煤层无人/少人采掘系统研究与应用。</p>\n<p>三、荣誉奖项</p>\n<p>2017年获得众一控股优秀员工，2021年获得众一金彩黔矿业有限公司优秀管理员，2025年获得众一控股有限公司卓越精英奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img33.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img27.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(20,33,30,'BP-TOPIC-SMART_ENERGY-STUDENTS','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-STUDENTS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀学生", "subtitle": "绿色能源、智能开采与化工安全", "body": "<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img34.webp\" alt=\"\"></figure>\n<p>徐俊，毕节职业技术学院2025级建筑工程技术专业学生</p>\n<p>2022年入校就读中职建筑工程施工专业；2025年9月，升入本校高职建筑工程技术专业。中职三年，连续两年获得校级一等奖学金，获评毕节职业技术学院“三好学生”“优秀毕业生”等荣誉。</p>\n<p>专业技能方面，在校期间，积极参加各类技能竞赛并斩获多项荣誉：2022年获毕节市教育局举办的职业院校技能大赛工程测量赛项二等奖，2023年获毕节市教育局举办的水利工程制图赛项一等奖，2025年获贵州省职业院校技能大赛水利工程制图赛项一等奖，并代表学校参加世界职业院校技能大赛，获得土木施工赛道铜奖。</p>\n<p>专业实践方面，2025年暑假，他曾在贵州青雲工程设计有限公司担任装饰设计师助理，独立完成8户业主的室内施工图绘制与三维建模，协助现场技术交底，掌握了BIM核心建模流程。</p>\n<p>成长前景回顾，2025年9月，他升入本校高职层次继续深造；入学后，保持拼搏劲头：2025年10月获教育厅、团省委举办的第四届贵州省大学生创新方法大赛二等奖；2026年，他先后获得教育厅举办的贵州省大学生职业规划大赛铜奖、贵州省职业院校技能大赛水利赛道三等奖。此外，他以专业知识登记1项软件著作权和3项作品版权，并参与老师科研项目。</p>\n<p>从中职到高职，从赛场到实习再到科研，他用踏实证明自己：学好技术、做好小事，就能为家乡建设出力。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img35.webp\" alt=\"\"></figure>\n<p>吴鹏，毕节职业技术学院2025级建筑工程技术专业学生</p>\n<p>共青团员。现任班级学习委员以及学院数字素养与技能协会会长。他以踏实的学习态度和扎实过硬的技能应用能力，赢得了师生的一致认可。</p>\n<p>2022年，吴鹏进入我校建筑工程施工专业中技班就读。自入学以来，始终保持着专业成绩与综合排名双第一的优异表现。中职三年，他连续位列专业第一，先后荣获多项省市级技能大赛奖项，包括贵州省职业院校技能大赛一等奖、全市中等职业学校师生技能大赛一等奖等，并在2025年8月代表贵州省参加世界职业院校技能大赛总决赛，斩获争夺赛铜奖。此外，他还被评为毕节职业技术学院“优秀班干”和“优秀毕业生”。</p>\n<p>升入高职后，吴鹏继续在本校建筑工程技术专业深造。他迅速转变角色，积极投身各类专业竞赛，持续展现出色的学习能力与进取精神。在短短一学期内，他便斩获以下荣誉：获得第四届贵州省大学生创新方法大赛二等奖、第十七届全国高等院校学生斯维尔杯数字城市创新技术与应用大赛三等奖、第三届贵州省大学生职业规划大赛职教组铜奖和贵州省职业院校技能大赛三等奖。与此同时，他依然保持专业与综合排名双第一的优异成绩，充分体现了其进入高职阶段后快速成长、敢于挑战、全面发展的优秀素质。</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img34.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(21,34,30,'BP-TOPIC-SMART_ENERGY-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "教学成果", "subtitle": "绿色能源、智能开采与化工安全", "body": "<p>教科研成果、课题项目...</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(22,35,30,'BP-TOPIC-SMART_ENERGY-COMPETITIONS','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-COMPETITIONS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "技能大赛", "subtitle": "绿色能源、智能开采与化工安全", "body": "<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img36.webp\" alt=\"\"></figure>\n<p>承办2026年贵州省职业院校技能大赛暨世界职业院校技能大赛贵州省选拔赛高职组“岩矿鉴定与综合地质编录技术”特色赛项</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img37.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img38.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img39.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img40.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img41.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img42.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img43.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img44.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img45.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img46.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img47.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img36.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(23,36,30,'BP-TOPIC-SMART_ENERGY-HONORS','upsert','approved','{"code": "BP-TOPIC-SMART_ENERGY-HONORS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "荣誉资质", "subtitle": "绿色能源、智能开采与化工安全", "body": "<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img48.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img49.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img50.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img51.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img52.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img53.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img54.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img55.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img56.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img57.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img58.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img59.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-energy/images/img60.webp\" alt=\"\"></figure>\n<p>视频资料（专业特色，可于所在区域屏幕循环播放）</p>", "imageUrl": "/uploads/blueprint/topics/smart-energy/images/img48.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(24,37,31,'BP-TOPIC-SMART_MANUFACTURING-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>系部简介：工矿建筑系</p>\n<p>工矿建筑系2008年成立，下设矿业、机电、建筑三个教研室，设建筑工程技术、煤矿智能开采技术、智能机电技术、安全技术与管理、测绘工程技术、应用化工技术、新能源汽车检测与维修技术、资源综合利用技术等8个高职专业和煤矿开采中技专业，与贵州工程应用技术学院开展联合培养土木工程、工程管理、采矿工程3个本科专业。建筑工程技术、煤矿智能开采技术获批两个省级高水平专业群。</p>\n<p>办学基础好。系部现有教职工82人，博士、教授、副教授等高层次人才齐备，双师型教师49人。先后获批国家高技能人才培训基地、毕节市智能矿山产教融合实训基地、贵州省开放性实训基地等多个项目支持，建成模拟矿井、智能综采实训中心、智能综掘进实训中心、建筑等比例模型、智能机电实训中心、应用化工专业实训室等30余个实训室，总投入资金近1.4亿元。</p>\n<p>产教融合实。依托统一战线帮扶，与东部广州港集团、广汽集团、奇瑞控股集团等龙头企业开展深度合作，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>\n<p>办学质量高。累计培养学生2万余名。获国家教学成果二等奖1项、省级教学成果一等奖2项。近三年学生在各类大赛中获奖120余项。系部获“贵州省脱贫攻坚先进集体”等优秀称号。</p>\n<p>科研能力强。教师主持省市级科研项目 50 余项，一年来开展横向课题经费到账80余万元。</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(25,38,31,'BP-TOPIC-SMART_MANUFACTURING-MAJORS','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "专业设置", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>智能制造专业群（校级重点 新兴打造）</p>\n<p>智能制造专业群立足省级高水平建设定位，以智能机电技术为核心，整合新能源汽车检测与维修技术、无人机应用技术等专业，聚焦智能装备运维、新能源汽车服务、无人机智能应用等领域，服务贵州省高端装备制造、新能源汽车、低空经济产业集群。</p>\n<p>专业群对接智能装备运维、新能源汽车、无人机应用、智能制造产线管控等关键环节，面向智能机电运维工程师、新能源汽车制造维修、无人机应用、智能制造产线技术员等岗位，培养懂技术、会操作、能运维的高技能人才。</p>\n<p>深度联动区域智能制造、新能源汽车、无人机应用龙头企业，围绕智能机电控制、新能源汽车检修、无人机飞控与作业、智能产线运维核心技能，构建“岗课赛证”融合育人体系，助力区域装备制造业数字化转型、新能源产业提质升级与低空经济规范发展，为区域智能制造产业高质量发展提供人才支撑。</p>\n<p>智能机电实训区 / 数控装调实训区</p>\n<p>无人机应用技术专业</p>\n<p>专业建设背景与发展机遇：当前我国无人机市场规模年均增速超20%，农业植保、地理测绘、应急救援等10余个应用领域持续拓展，2025年行业人才缺口超100万，相关岗位薪资年均涨幅达25%，人才需求向“技术 + 管理”复合型升级。贵州省作为西南低空经济发展核心区域，2024年无人机产业相关企业达5.2万家（较2020年增长3倍），2030年全省产业人才需求预计达12万；毕节市“十五五”规划聚焦低空经济布局，谋划无人机物流节点、低空运行航线，2027年本地需新增无人机技术技能人才 950余人，农业植保、矿山救援、能源巡检等领域人才需求迫切，专业建设具备极强的产业支撑与市场需求。同时，国家工信部、贵州省发改委、毕节市政府相继出台多项政策，明确支持无人机产业发展、培育低空经济专业技能人才，为专业建设提供了坚实的政策保障。</p>\n<p>课程体系与核心能力：专业构建 “两平台两模块” 课程体系，兼具 “模块化、跨学科、强应用”</p>\n<p>特色：1.公共基础平台：筑牢思想政治、人文素养及文化基础，培养学生综合职业素养；2.专业基础平台：开设电工电子技术、单片机与嵌入式系统、空气动力学与飞行原理等课程，奠定机械、电子、编程等理论与技能基础；3.专业核心模块：围绕核心岗位设置无人机导论与飞行法规、无人机操控技术、无人机结构与系统、无人机维护技术、航测影像数据处理等课程，培养飞行控制、组装调试、系统维护等核心能力；4.专业拓展模块：结合区域需求开设无人机行业应用技术、矿山救援无人机实操、山地农业植保技术等课程，拓展航拍、巡检、大数据应用等特色技能。学生可考取无人机驾驶员执照、无人机装调检修工等职业资格证书，实现“课岗证赛”深度融通。</p>\n<p>专业特色与培养模式：</p>\n<p>1.区域特色鲜明：聚焦毕节喀斯特地貌应用场景，适配山地农业作业需求，突出生态监测、矿山救援、能源巡检专业方向，与省内同类院校形成差异化定位，精准服务黔西北低空经济发展；</p>\n<p>2.培养模式创新：实施“五三三”人才培养模式，坚持“专业设置与产业需求、课程内容与职业标准”等五个对接，将素质、知识、能力培养贯穿全程，构建“初始岗位-发展岗位-目标岗位”三层次递进的职业能力培养体系；</p>\n<p>3.教学方法多元：采用混合式教学、项目驱动、竞赛育人相结合的教学方法，推行“教师+工程师+名匠大师”三师教学模式，强化实训实操，基础实训“一对一”指导、专项实训“任务工单”载体、综合实训“小组协作+岗位分工”；</p>\n<p>4.产教协同育人：与区域龙头企业共建课程标准、实训基地与产业学院，以真实项目为教学载体，让学生参与无人机航测、巡检、植保等实际工作，实现 “工学结合、岗课融通”；</p>\n<p>5.课程内容前沿：融入无人机大数据、飞控开发、AIGC 等前沿内容，强化航拍、巡检、编队等实战技能，培养学生适应产业发展的创新能力。</p>\n<p>就业方向与发展前景：</p>\n<p>（一）核心就业岗位</p>\n<p>无人机驾驶员、无人机装调检修工、无人机维保员、无人机航测员、无人机航拍员、无人机植保员等；</p>\n<p>（二）主要就业领域</p>\n<p>1.农业领域：无人机植保、农作物病虫害监测、农业资源勘查；2. 能源领域：电力、光伏等设施的无人机巡检与维护；3. 测绘与建筑领域：城乡测绘、实景三维构建、灾害勘测；4. 应急救援领域：矿山救援、应急物资配送、灾害现场勘查；5.文旅与环保领域：风景航拍、文旅宣传、生态环境动态监测；6.物流领域：无人机城际运输、末端配送（契合毕节低空物流发展规划）。</p>\n<p>（三）发展前景</p>\n<p>无人机产业为国家低空经济核心赛道，西南地区2030年无人机技术人才需求预计超30万，贵州省2027年无人机产业产值将突破50亿元，专业毕业生就业缺口大、薪资涨幅高。学校制定三年发展规划，确保毕业生年终就业率≥95%、专业对口率≥80%，用人单位满意度稳定在 90% 以上，学生毕业后可直接入职无人机应用企业、测绘院、农业科技公司、电力企业等，也可自主创业开展无人机技术服务。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img01.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img02.webp\" alt=\"\"></figure>\n<p>农业方面（无人机植保） 能源方面（电力巡检）</p>\n<p>新能源汽车检测与维修技术专业</p>\n<p>专业介绍：本专业旨在培养适应新能源汽车行业需要，具备新能源汽车检测与维修的基础理论、专门知识和基本技能的高素质劳动者和技术技能人才。这些人才将面向新能源汽车关键部件制造、整车制造及维修服务、充电设施运行与维护等企业，从事新能源汽车的检测、维修、保养、管理等工作。本专业与广汽集团深度合作，联合开展“订单班”。</p>\n<p>实训室条件：本教研室新能源汽车专业拥有国家级高技能人才培训基地、汽车综合实训室、发动机电控检修实训室、汽车底盘电控检修实训室、发动机变速器拆装实训室、汽车电气设备检修实训室及焊接实训室等，占地约6000平方米，设备总价值约700万。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img03.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img04.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img05.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img06.webp\" alt=\"\"></figure>\n<p>办学特色：为培养学生掌握扎实的科学机械基础、机械操作技能，在新能源汽车检测与维修技术和智能机电技术专业的教学环节中，安排有特色金工实习，开展普车、数控车、电工、电子工、钳工、焊接技术等各类工种实训任务。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img07.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img18.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img09.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img10.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img11.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img12.webp\" alt=\"\"></figure>\n<p>办学成效：教研室师生技能大赛获市赛一等奖6项，三等奖18项，获省赛二等奖2项，三等奖20余项；创新创业大赛校级铜奖3项，省级铜奖3项。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img13.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img14.webp\" alt=\"\"></figure>\n<p>智能机电技术专业</p>\n<p>专业介绍：本专专业面向装备制造、机械工业等企事业单位，致力于培养能够从事机电一体化设备设计、安装、调试与管理，数控机床维护与使用，以及具备创新、实践精神等综合职业能力的高素质技术人才。本专业融合了机械、电子、控制、计算机及人工智能等多学科知识，为智能制造领域输送紧缺的专业人才。</p>\n<p>实训室条件：智能机电技术专业拥有一个智能制造实训基地，占地约4000平方米，其拥有自动控制技术实训平台、机器人技术实训平台、气动应用与控制技术实训平台、机电一体化技术实训平台、数控车床、普通车床、3D打印机、钳工台等设备，能完成工科类专业操作技能培养。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img15.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img16.webp\" alt=\"\"></figure>\n<p>办学特色：为培养学生掌握扎实的科学机械基础、机械操作技能，在智能机电技术专业的教学环节中，安排有特色金工实习，开展普车、数控车、电工、电子工、钳工、焊接技术等各类工种实训任务。</p>\n<p>专业紧扣智能制造发展需求，以“东西部协作、产教深度融合”为核心特色，聚焦智能设备运维、工业机器人应用等核心能力培养，构建理实一体化课程体系，实训设备覆盖 PLC 控制、智能产线调试等关键领域。</p>\n<p>与广州港集团共建的“广港班”订单班，采用成熟的“2+1”培养模式，前两年在校夯实理论与基础技能，第三年赴企业顶岗实习。企业派技术骨干授课，融入港口机械智能运维等特色内容，还设立专项资助。该模式实现 “招生即招工”，已有上百名学生留在广州港就业。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img17.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img18.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img19.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img20.webp\" alt=\"\"></figure>\n<p>办学成效：教研室师生技能大赛获市赛一等奖4项，三等奖8项，获省赛二等奖1项，三等奖10余项；创新创业大赛校级铜奖2项，省级铜奖1项。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img21.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img22.webp\" alt=\"\"></figure>\n<p>建筑工程技术专业群</p>\n<p>建筑工程技术专业群以建筑工程技术为核心，协同工程造价、市政工程技术两大专业组建而成。核心专业建筑工程技术为省级骨干专业、国家高技能人才培训基地专业，市政工程技术为杭州科技职业技术学院“1+1+1”跨省联办专业，工程造价专业紧扣产业数字化转型需求，形成特色鲜明、优势互补的专业集群。专业群现有在校学生1135人，累计向社会输送土建类毕业生2000余人，办学基础扎实、综合实力省内领先，发展势头强劲。</p>\n<p>本专业群聚焦现代建筑产业转型升级，面向房屋建筑、土木工程建筑业高端领域，精准对接智能施工管理、智慧造价管理、智能检测、数字化运维、城市更新等新兴技术岗位需求。致力于培养理想信念坚定、德智体美劳全面发展，恪守职业道德、秉持工匠精神，具备国际视野与创新意识，掌握建筑工程技术、工程造价、市政工程技术专业核心知识，拥有智能检测、智慧造价、智能施工、数字化运维与更新综合能力，兼具“一技之长+综合素质”，适配产业创新发展需求的“会改造、通造价、能管理、精施工”高素质复合型技术技能人才。</p>\n<p>建筑工程等比例模型 / 智能建造现代产业学院</p>\n<p>建筑工程技术专业</p>\n<p>专业简介：建筑工程技术专业是我院第一批两个省级“双高”专业群之一建筑工程技术“双高”专业群的核心专业。</p>\n<p>培养目标：本专业培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握建筑工程技术专业知识和技术技能、建筑信息模型（BIM）应用、智能施工、智能造价和智慧运维等相关知识和技术技能，能够从事智能建筑设计校核、智能测绘、智能建造施工（智慧工地管理）、建筑智慧维护等相关工作的复合型、创新型高素质技术技能人才。面向房屋建筑行业的建筑工程技术人员、管理工程技术人员等职业，能够从事建筑施工技术与建筑施工管理等工作的高技能人才。立足毕节，服务“黔川滇”。</p>\n<p>就业方向：代表职位有施工员、资料员、质量员、监理员、造价员、建筑工程师、结构工程师、技术经理、项目经理等。代表行业有建筑施工企业、房地产开发企业、路桥施工企业等。</p>\n<p>就业前景：土木建筑行业对工程技术人才的需求不断增长， 需求量已经跃居第一位。随着经济发展和路网改造、城市基础设施建设工作的不断深入，土建工程技术人员在当前和今后一段时期内需求量还将不断上升。再加上路桥和城市基础设施的更新换代，只要人才市场上没有出现过度饱和的状况，可以说建筑工程技术人员一直有着不错的就业前景。典型职业通路：施工员/技术员－工程师/工长、标段负责人－技术经理－项目经理/总工程师。</p>\n<p>随着我国执业资格认证制度的不断完善，土建行业工程技术人员不但需要精通专业知识和技术，还需要取得必要的执业资格证书。工程技术人员的相关执业资格认证主要有全国一、二级注册建筑师、全国注册土木工程师、全国一、二级注册结构工程师、注册建造师、注册造价工程师等。需要注意的是，这些执业资格认证均需要一定年限的相关工作经验才能报考，因此土木工程专业的毕业生即使走上工作岗位后也要注意知识结构的更新，尽早报考以取得相关的执业资格。想要从事工程技术工作的大学生，在实习中可选择建筑工地上的测量、建材、土工及路桥标段的路基、路面、小桥涵的施工、测量工作。</p>\n<p>专业面向岗位：建筑工程技术专业实习岗位可分为三大类：第一类是现场施工管理人员；第二类是各层次的技术管理人员；第三类是后勤技术支持人员等。</p>\n<p>序号 / 岗位群 / 初始岗位 / 发展岗位 / 目标岗位\n1 / 施工现场管理 / 施工员 / 二级建造师、监理工程师、技术负责人、建筑工程师（智能设计校核、智慧造价） / 一级建造师、项目经理、总监理工程师\n2 / 施工现场管理 / 质量员 / 监理工程师、技术负责人、建筑工程师（智能设计校核） / 一级建造师、项目经理、总监理工程师\n3 / 资料管理 / 材料员 / 造价工程师、监理工程师、建筑工程师（智慧造价） / 注册造价师\n4 / 安全控制、质量检验 / 安全员 / 二级建造师、监理工程师、技术负责人、建筑工程师（智能设计校核） / 一级建造师、项目经理、总监理工程师\n5 / 造价控制 / 预算员 / 造价工程师 / 注册造价师\n6 / 施工测量 / 测量员 / 监理工程师、技术负责人 / 一级建造师、项目经理、总监理工程师\n7 / 装配式建筑施工 / 施工员 / 二级建造师、监理工程师、技术负责人 / 一级建造师、项目经理、总监理工程师\n8 / 建筑信息模型技术 / 施工员、安全员、质量员、测量员、预算员 / BIM工程师、二级建造师、造价工程师、监理工程师、技术负责人、建筑工程师（设计校核） / 项目经理、一级建造师、项目负责人、总监理工程师、注册造价师</p>\n<p>专业特色：本专业从2009年9月开始招生，2014年获批“院级重点专业建设”并验收通过，2014年获批国家人社部“国家级高技能人才培训基地”项目并于2018年4月验收通过，2018年获批贵州省质量提升工程建筑工程技术骨干专业项目、建筑工程开放实训基地项目建设并于2020年12月验收通过，其中开放实训基地项目获得优秀。2019年首次获得“1+X”建筑工程识图职业技能等级证书（中级）试点并开展培训考证工作，2021年我院立项建设“双高”校，“建筑工程技术（智能建造）专业群”作为省立项建设的两个“双高专业群”之一，并获得贵州省脱贫攻坚先进集体，2021年“兴黔富民计划”立项建设“智慧建造产教融合实训基地”项目，2022年“技能贵州行动计划”立项建设“建筑工程技术教师教学创新团队”项目、示范性人才培养方案项目，这些项目截止2024年12月已全部验收合格。并再次申报成功“1+X”建设工程质量检测、“1+X”工程造价数字化应用、“1+X”智能建造设计与集成应用、“1+X”路桥工程无损检测四个职业技能等级证书试点，并开展了培训和考证。学生在校可考工程测量员高级工等职业技能等级证书。众多项目的建设立项建设为专业的良好发展打下了雄厚的发展基础，也为人才培养提供了优质的条件。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img23.webp\" alt=\"\"></figure>\n<p>部分学生获证情况：近年来，校内承办1+X路桥无损检测、建筑工程识图、BIM建筑信息模型、建设工程质量检测、工程造价数字化应用等多个职业技能等级证书考核站点，考核通过率80%以上。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img24.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img25.webp\" alt=\"\"></figure>\n<p>工程造价专业</p>\n<p>专业介绍：工程造价专业是教育部根据国民经济和社会发展的需要而增设的热门专业之一，是以工程学、经济学、管理学为理论基础，以工程项目管理理论和方法为主导的社会科学与自然科学相交叉的学科。</p>\n<p>培养目标：本专业立足”川滇黔”结合部，面向建筑工程、安装工程、市政工程等建设行业，培养德、智、体、美、劳全面发展，掌握扎实的工程造价基础理论、专业知识和BIM等数字化技术，具备工程识图、算量、组价、招投标、成本控制等核心技能，具有良好职业道德、工匠精神、创新意识和可持续发展能力的“懂技术、精造价、会管理、善沟通”高素质技术技能人才。</p>\n<p>专业特色：“岗课赛证”综合育人：将岗位标准、课程内容、技能竞赛（如全国大学生工程造价技能大赛）、职业证书（如“1+X”建筑工程识图、工程造价数字化应用证书）深度融合，确保教学内容与行业需求无缝对接。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img26.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img27.webp\" alt=\"\"></figure>\n<p>学生取得省技能大赛 学生取得省技能大赛</p>\n<p>“理实一体”教学模式：工程造价专业构建总面积2100㎡“五位一体”的校内外产教融合实践教学基地。获批为建成国家高技能人才培训基地、省级开放性实训基地，省级智慧产教融合实训中心。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img28.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img29.webp\" alt=\"\"></figure>\n<p>工法楼 智慧工地</p>\n<p>“双师型”教学团队：工程造价专业共有11名专任（兼职）教师，教师责任心强、热爱职业教育，专业知识扎实，所有专任教师均具有信息化教学能力，双师素质教师占专业教师比例为90%，教师中级以上职称7人，占比87.5%，正高2人，研究生6人，一级建造师2名，二级造价工程师1名，建筑师1名。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img30.webp\" alt=\"\"></figure>\n<p>校企合作，就业无忧：与本地多家知名建筑企业、工程造价咨询公司建立了深度校企合作关系，共同制定培养方案，开设“订单班”，为学生提供稳定的实习和就业渠道。</p>\n<p>毕业展望：本专业就业面广，需求量大，毕业生深受用人单位欢迎。主要就业方向包括：施工单位、造价咨询公司、建设单位、政府审计部门/事业单位、工程审计、基建处造价管理、设计院所。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img31.webp\" alt=\"\"></figure>\n<p>随着新型城镇化、城市更新、新基建等国家战略的推进，建筑行业对精细化管理人才的需求日益迫切，掌握BIM等数字化技术的造价工程师职业发展前景极为广阔。</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(26,39,31,'BP-TOPIC-SMART_MANUFACTURING-TRAINING','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-TRAINING", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "实训基地", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>“广东·技工”广汽班/广港班实训基地</p>\n<p>主要功能：培养高素质技术技能人才，助力毕节市人力资源开发，为粤港澳大湾区发展培养新型技工人才。开创东西部智力帮扶全新模式，打造招生即招工，毕业即就业的新型现代学徒制培养模式。</p>\n<p>承担的教学任务：承担新能源汽车检测与维修、智能机电专业钳工、电工、汽车检修等相应专业课程实训，相应工种技能认定，省市技能大赛相应项目技能比赛，毕节市劳动教育基地。</p>\n<p>新能源汽车国家级高技能人才培训基地</p>\n<p>新能源汽车专业拥有国家级高技能人才培训基地、汽车综合实训室、发动机电控检修实训室、汽车底盘电控检修实训室、发动机变速器拆装实训室、汽车电气设备检修实训室及焊接实训室等，占地约6000平方米，设备总价值约700万。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img32.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img33.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img34.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img35.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img36.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img37.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img38.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img39.webp\" alt=\"\"></figure>\n<p>智能制造实训基地</p>\n<p>智能机电技术专业拥有一个智能制造实训基地，占地约4000平方米，其拥有自动控制技术实训平台、机器人技术实训平台、气动应用与控制技术实训平台、机电一体化技术实训平台、数控车床、普通车床、3D打印机、钳工台等设备，能完成工科类专业操作技能培养。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img40.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img41.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img42.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img43.webp\" alt=\"\"></figure>\n<p>智能机电实训区 数控装调实训区</p>\n<p>贵州省质量提升工程项目建筑工程开放实训基地</p>\n<p>贵州省“兴黔富民”计划智能建造产教融合实训基地</p>\n<p>建筑工程技术专业实训基地包括贵州省质量提升工程项目建筑工程开放实训基地、贵州省“兴黔富民”计划智能建造产教融合实训基地两大实训基地，包括建筑工程智能实体比例节点模型实训室、建筑检验检测实训室、装配式建筑实训室、工种实训室、建筑工程制图实训室、建筑工程识图实训室、BIM建模实训室、工程造价实训室、建筑工程测量实训室、工程招投标与管理实训室等。建筑工程技术专业的职业技能细分为基础技能、专业操作技能及综合运用技能三大类。每一大类技能又可分解为数种技能或基本能力要求。学生可在学校的组织下，根据自身的特点及毕业后的就业方向，选择一种或几种专业技能参加实训及鉴定。目前可开展鉴定工种：测量工、钢筋工、砌筑工、混凝土工、架子工，还可开展“1+X”BIM 中级证书，“1+X”建筑工程识图中级证书，“1+X”建设工程质量检测证书的培训和鉴定。</p>\n<p>建筑工程智能实体比例节点构造模型实训室</p>\n<p>主要功能：建筑工程智能实体比例节点构造模型实训室，该实训室是省级质量提升工程项目建筑工程开放实训基地的子项目之一，项目于2020年7月公开招标中标后，2020年9月开始建设，并于2021年3月建成并验收通过，为开放实训基地验收通过并获得优秀等次奠定了基础。实训室现有等比例节点构造模型271个节点，并配套200个节点的软件资源，总投资174万元。模型楼占地面积约250平方米，总面积580平方米，可以为建筑识图与构造、平法识图、主体结构施工、地基与基础、建筑结构等课程提供很好的实训条件，并结合工匠精神打造了丰富的实训室文化。</p>\n<p>该教学模型共两层半，一层节点包括地基与基础节点构造、砖墙、楼梯、墙体、脚手架、外墙装饰装修等模型，二层节点包括装配式节点构造、建筑装饰节点构造、玻璃幕墙、门窗等模型，三层节点包括屋顶防水构造、屋面构造、木屋和坡屋顶构造、钢结构模型等。</p>\n<p>承担的教学任务：满足建筑工程技术、工程造价等专业学生实训教学需要</p>\n<p>智能建造现代产业学院</p>\n<p>主要功能：虚拟仿真（VR），施工升降机，无人塔吊，智慧监控，虚拟灭火，安全体验，BIM实训，贴砖机器人，物料系统，智慧指挥等</p>\n<p>承担的教学任务：智慧建造相关课程，装配式建造相关课程。满足建筑工程技术、工程造价等专业学生实训教学需要</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img44.webp\" alt=\"\"></figure>\n<p>开放实训基地“建筑工程智能实体比例节点模型”实训</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img45.webp\" alt=\"开放实训基地“建筑工程智能实体比例节点模型”实训\"><figcaption>开放实训基地“建筑工程智能实体比例节点模型”实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img46.webp\" alt=\"开放实训基地“建筑工程智能实体比例节点模型”实训\"><figcaption>开放实训基地“建筑工程智能实体比例节点模型”实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img47.webp\" alt=\"开放实训基地“建筑工程智能实体比例节点模型”实训\"><figcaption>开放实训基地“建筑工程智能实体比例节点模型”实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img48.webp\" alt=\"开放实训基地“建筑工程智能实体比例节点模型”实训\"><figcaption>开放实训基地“建筑工程智能实体比例节点模型”实训</figcaption></figure>\n<p>智能建造产教融合实训基地“智慧工地”实训</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img49.webp\" alt=\"智能建造产教融合实训基地“智慧工地”实训\"><figcaption>智能建造产教融合实训基地“智慧工地”实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img50.webp\" alt=\"智能建造产教融合实训基地“智慧工地”实训\"><figcaption>智能建造产教融合实训基地“智慧工地”实训</figcaption></figure>\n<p>智能建造产教融合实训基地“工地安全”实训</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img51.webp\" alt=\"智能建造产教融合实训基地“工地安全”实训\"><figcaption>智能建造产教融合实训基地“工地安全”实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img52.webp\" alt=\"智能建造产教融合实训基地“工地安全”实训\"><figcaption>智能建造产教融合实训基地“工地安全”实训</figcaption></figure>\n<p>智能建造产教融合实训基地“智能建造”实训</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img53.webp\" alt=\"智能建造产教融合实训基地“智能建造”实训\"><figcaption>智能建造产教融合实训基地“智能建造”实训</figcaption></figure>\n<p>“测量工”实训</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img32.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(27,40,31,'BP-TOPIC-SMART_MANUFACTURING-COOPERATION','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "产教融合", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>对接产业</p>\n<p>产教融合成果</p>\n<p>依托统一战线帮扶，与东部广州港集团、广汽集团、奇瑞控股集团等龙头企业开展深度合作，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img54.webp\" alt=\"\"></figure>\n<p>2024级奇瑞订单班学生转段奇瑞控股集团开展岗前实践安全教育培训</p>\n<p>校企合作订单班</p>\n<p>依托统一战线帮扶与东西部协作的契机，系部深化产教融合、校企合作，与广州港集团、广汽集团等多家知名企业共建订单班、冠名班，企业年均提供实习就业岗位3500余个。</p>\n<p>广汽集团企业导师赴学校为学生 开展实训教学 / 校企合作“广州港班”风采</p>\n<p>智能机电技术专业紧扣智能制造发展需求，以“东西部协作、产教深度融合”为核心特色，聚焦智能设备运维、工业机器人应用等核心能力培养，构建理实一体化课程体系，实训设备覆盖 PLC 控制、智能产线调试等关键领域。</p>\n<p>与广州港集团共建的“广港班”订单班，采用成熟的“2+1”培养模式，前两年在校夯实理论与基础技能，第三年赴企业顶岗实习。企业派技术骨干授课，融入港口机械智能运维等特色内容，还设立专项资助。该模式实现 “招生即招工”，已有上百名学生留在广州港就业。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img55.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img56.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img57.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img58.webp\" alt=\"\"></figure>\n<p>工程造价专业与本地多家知名建筑企业、工程造价咨询公司建立了深度校企合作关系，共同制定培养方案，开设“订单班”，为学生提供稳定的实习和就业渠道。建筑工程技术专业校企如下表：</p>\n<p>序号 / 名称 / 地点 / 功能\n1 / 贵州东冶建设工程有限公司 / 贵州省毕节市毕节经济开发区内 / 实习实训\n2 / 耀华建设管理有限公司 / 浙江省杭州市临平区运河街道东明路1号 / 实习实训\n3 / 贵州城乡建设集团有限公司 / 贵州毕节七星关区碧阳街道碧阳大道1号光大银行11楼 / 实习实训\n4 / 贵州省鑫盛建设集团有限公司 / 贵州省毕节市七星关区环东路（原学院路）东城印象3层2号 / 实习实训\n5 / 贵州省森越建设工程有限公司 / 毕节市七星关区学院路振华商贸大厦 / 实习实训\n6 / 毕节市永筑监理有限公司 / 毕节市七星关区麻园路东园小区E-4幢 / 实习实训</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img54.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(28,41,31,'BP-TOPIC-SMART_MANUFACTURING-MASTERS','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-MASTERS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "名师名匠", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img59.webp\" alt=\"高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人\"><figcaption>高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人</figcaption></figure>\n<p>2006年毕业于辽宁工程技术大学采矿工程专业，获工学硕士学位，2006年4月参加工作，从事煤矿瓦斯灾害防治研究与教学工作19年。</p>\n<p>主要研究方向为煤矿瓦斯灾害防治、浆体管道输送竖直段管路阻力损失研究。主持市级及以上科研项目4项，主持或参与国家重大专项子课题1项、省部级项目1项、中煤科工集团二级企业技术创新项目1项，横向重点项目40余项；授权国家发明专利4项，撰写科研、咨询报告50余篇。获省部级奖励13项，其中个人证书3项、集体奖10项。发表学术论文20篇，其中中文核心期刊独著5篇、第一作者5篇，中文科技期刊独著4篇、第二作者2篇，EI检索国际会议独著2篇，参编教材1部。牵头申报煤炭行业井工煤矿智能化实训（实习）基地、煤炭行业教育培训贵州基地，培养青年教师5名，在安全工程专业建设、煤矿安全科研与人才培养方面成果显著。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img60.webp\" alt=\"\"></figure>\n<p>王锦 教授 一级建造师，工矿建筑系建筑工程技术专业带头人</p>\n<p>2007年毕业于重庆交通大学工程管理专业，获工学学士学位，2007年7月参加工作，从事建筑工程施工管理与教学工作18年。主要研究方向为建筑施工安全管理、建筑材料研究。主持市级及以上科研项目2项，主持或参与省部级质量工程项目和技能贵州项目2项；授权国家发明专利1项。发表学术论文15余篇。牵头申报住房和城乡建设领域现场人员培训（实习）基地、贵州省建设质量检测培训基地，在建筑工程技术专业建设与人才培养方面成果显著。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img61.webp\" alt=\"\"></figure>\n<p>罗根华 工学博士 副教授 工矿建筑系专任教师</p>\n<p>深耕环境污染控制技术、矿山环境生态修复等领域科研与教学工作二十余年，主持及参与市级及以上教科研项目7项，其中国家自然科学基金项目2项；承接企业委托横向项目近30项。科研成果先后荣获1项辽宁省科技进步奖二等奖、市厅级科技进步奖一等奖3项；累计发表北大核心及以上级别期刊论文18篇，获授权发明专利3项，主编高职教材1部。从教以来获评校优秀教师、优秀班导师，荣获毕业生“我最喜爱的老师”等多项荣誉称号。</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img59.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(29,42,31,'BP-TOPIC-SMART_MANUFACTURING-ALUMNI','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-ALUMNI", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀校友", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>谢佳丽 毕节职业技术学院工矿建筑系2018级工业机器人专业班学生</p>\n<p>2021年就职于广汽乘用车有限公司，担任文化活动专员职务。2021年12月荣获祺盛动力“传祺岗位小能手”称号，2022年7月荣获祺盛动力企业文化宣传系列“优秀宣传个人”称号，2022年12月荣获广汽集团支援疫情防控党员突击队“先进个人”称号。</p>\n<p>2024年4月获评广州市团干部讲党团课优秀讲师；2024年5月荣获广州市国资系统宣讲赛特等奖；2024年8月荣获广州市“十佳宣讲员”称号；2025年8月荣获广汽集团优秀团干部称号；2025年9月荣获广州市总工会乡村振兴（“百千万工程”）羊城女能手入围奖。2024年5月被聘请为国资委系统宣讲队员，其事迹被学习强国、《工人日报》等央媒及省市媒体累计报道超18次。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img62.webp\" alt=\"\"></figure>\n<p>王 祥 毕节职业技术学院工矿建筑系2017级广州港班学生</p>\n<p>2020年就职于广州港集团股份有限公司南沙集装箱码头分公司，担任龙门吊机械司机。2021年11月在央视《新闻联播》推出系列报道《弘扬伟大建党精神 开创历史新伟业》第一集《百年大党引领中华民族伟大复兴》，栏目接受采访，自2022年起任其作业大队带训师傅一职，2022年至2023年带出任职以来首批职工，2023年至2025年年初带训出第二批职工，2024年12月被评为公司“安全先进个人”。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img63.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img64.webp\" alt=\"\"></figure>\n<p>韩 赟，贵州金沙人，中共党员，毕节职业技术学院2013级煤矿开采技术专业毕业生后就读西南大学法学专业取得本科学历，2024年12月入职毕节市七星关区纪委监委，现任区纪委监委工作员。2013.9—2016.7在校期间曾任系学生会主席、院学生会副主席；2016年8月起以西部计划志愿者身份扎根赫章基层，先后在白果镇政府、金银山街道办事处、松林坡安监站、赫章县委办任职，历任党群办负责人、县委办秘书二股负责人，深耕基层服务近8年。</p>\n<p>扎根基层期间全程参与脱贫攻坚、常态化疫情防控重点工作，牵头落地“党建＋积分”“团建＋积分”基层治理创新项目。2017年获评赫章县优秀志愿者；2018年获评毕节市优秀志愿者；2019年获评贵州省优秀志愿者；第十二届中国青年志愿者优秀个人，2020年获评最美赫章人，2022年获评第十九届贵州青年五四奖章（集体），贵州省最美劳动者。转入纪检岗位后，2025年获评七星关区纪委监委优秀共产党员。扎根基层志愿服务与实干履职事迹多次被省、市主流媒体宣传报道，是贵州基层青年党员、青年志愿者先进典型代表。</p>\n<p>秦鹏，毕节职业技术学院工矿建筑系，2017级港口机械操作与维护</p>\n<p>2020年就职于广州港股份有限公司南沙集装箱码头分公司，担任岸桥司机职务。2024年7月，获得公司龙门吊比武第一名，2025年2月当选广东省工会第十五次代表大会代表。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img65.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img66.webp\" alt=\"\"></figure>\n<p>张启浪，男，汉族，中共党员</p>\n<p>在校期间思想积极上进，政治立场坚定，始终以优秀共产党员和优秀大学生的标准严格要求自己，学习、竞赛、工作与实践表现优异，综合成绩突出。</p>\n<p>他持之以恒，刻苦钻研，不断夯实专业基础、拓宽知识视野。2015年至2021年，他先后在我校完成工艺美术（中职）、建筑工程技术（高职）专业的学习，2021年7月保送到凯里学院攻读土木工程本科，逐步构建起跨学科、复合型的建筑工程知识体系。在校期间学习态度端正，成绩稳居前列，曾多次获得学院一等奖学金，被评为优秀学生干部，获得国家励志奖学金、国家奖学金等。因综合素质突出，2021年，他获得校级和贵州省优秀毕业生荣誉称号。</p>\n<p>他以赛促学，以练促长，积极参加省级、国家级技能竞赛，斩获多项荣誉。2019年4月获贵州省职业院校技能大赛一等奖，同年5月获全国职业院校技能大赛高职组建筑装饰技术应用三等奖，2022年7月获贵州省大学生结构设计竞赛三等奖，专业技能与创新能力获得充分认可。</p>\n<p>毕业后他不忘初心、勇于创业，于2023年自主创办贵州青雲工程设计有限公司，将专业知识与竞赛经验运用于实践，脚踏实地，精益求精。未来，他将继续深耕工程设计领域，积极奉献社会，展现新时代优秀毕业生的良好风貌。</p>\n<p>欧安进，中共党员，毕节职业技术学院工矿建筑系2019级汽车检测与维修技术专业汽车检测与维修班学生</p>\n<p>2022年3月至2023年5月就职于施秉县中等职业技术学校担任汽修专业教师，2023年7月至今就职于贵州永华技工学校担任新能源汽车检测与维修专业组组长。2021年9月至2022年7月，他在校期间担任班级班长，荣获以下奖项：2020年，获得国家励志奖学金，获得学院“三好学生”称号；2021年，获得国家励志奖学金，获得学院“三好学生”称号，获得工矿建筑系汽车检测与维修技能大赛一等奖；2022年，获得院级优秀毕业生称号，获得贵州省三好学生称号。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img67.webp\" alt=\"\"></figure>\n<p>陈胜利，男，年龄：37</p>\n<p>一、教育经历</p>\n<p>2010年9月--2013年7月毕业于毕节职业技术学院，专业：煤矿开采技术。</p>\n<p>二、工作经历</p>\n<p>2013年7月毕业后，2013年9月进入贵州众一金彩黔矿业有限公司瑞丰煤矿任技术员，2015年在瑞丰煤矿任技术科长，2018年在瑞丰煤矿任技术副总，2019年在瑞丰煤矿任技术负责人；2020年5月调贵州众一金彩黔矿业有限公司织金县志成煤矿任总工程师；2025年7月调贵州众一金彩黔矿业有限公司岩脚煤矿任总工程师。2020年以来一直负责贵州众一金彩黔矿业有限公司国家安全改造项目，2021年参与贵州省科技重大项目：薄煤层无人/少人采掘系统研究与应用。</p>\n<p>三、荣誉奖项</p>\n<p>2017年获得众一控股优秀员工，2021年获得众一金彩黔矿业有限公司优秀管理员，2025年获得众一控股有限公司卓越精英奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img68.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img62.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(30,43,31,'BP-TOPIC-SMART_MANUFACTURING-STUDENTS','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-STUDENTS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀学生", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img69.webp\" alt=\"\"></figure>\n<p>徐俊，毕节职业技术学院2025级建筑工程技术专业学生</p>\n<p>2022年入校就读中职建筑工程施工专业；2025年9月，升入本校高职建筑工程技术专业。中职三年，连续两年获得校级一等奖学金，获评毕节职业技术学院“三好学生”“优秀毕业生”等荣誉。</p>\n<p>专业技能方面，在校期间，积极参加各类技能竞赛并斩获多项荣誉：2022年获毕节市教育局举办的职业院校技能大赛工程测量赛项二等奖，2023年获毕节市教育局举办的水利工程制图赛项一等奖，2025年获贵州省职业院校技能大赛水利工程制图赛项一等奖，并代表学校参加世界职业院校技能大赛，获得土木施工赛道铜奖。</p>\n<p>专业实践方面，2025年暑假，他曾在贵州青雲工程设计有限公司担任装饰设计师助理，独立完成8户业主的室内施工图绘制与三维建模，协助现场技术交底，掌握了BIM核心建模流程。</p>\n<p>成长前景回顾，2025年9月，他升入本校高职层次继续深造；入学后，保持拼搏劲头：2025年10月获教育厅、团省委举办的第四届贵州省大学生创新方法大赛二等奖；2026年，他先后获得教育厅举办的贵州省大学生职业规划大赛铜奖、贵州省职业院校技能大赛水利赛道三等奖。此外，他以专业知识登记1项软件著作权和3项作品版权，并参与老师科研项目。</p>\n<p>从中职到高职，从赛场到实习再到科研，他用踏实证明自己：学好技术、做好小事，就能为家乡建设出力。</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img70.webp\" alt=\"\"></figure>\n<p>吴鹏，毕节职业技术学院2025级建筑工程技术专业学生</p>\n<p>共青团员。现任班级学习委员以及学院数字素养与技能协会会长。他以踏实的学习态度和扎实过硬的技能应用能力，赢得了师生的一致认可。</p>\n<p>2022年，吴鹏进入我校建筑工程施工专业中技班就读。自入学以来，始终保持着专业成绩与综合排名双第一的优异表现。中职三年，他连续位列专业第一，先后荣获多项省市级技能大赛奖项，包括贵州省职业院校技能大赛一等奖、全市中等职业学校师生技能大赛一等奖等，并在2025年8月代表贵州省参加世界职业院校技能大赛总决赛，斩获争夺赛铜奖。此外，他还被评为毕节职业技术学院“优秀班干”和“优秀毕业生”。</p>\n<p>升入高职后，吴鹏继续在本校建筑工程技术专业深造。他迅速转变角色，积极投身各类专业竞赛，持续展现出色的学习能力与进取精神。在短短一学期内，他便斩获以下荣誉：获得第四届贵州省大学生创新方法大赛二等奖、第十七届全国高等院校学生斯维尔杯数字城市创新技术与应用大赛三等奖、第三届贵州省大学生职业规划大赛职教组铜奖和贵州省职业院校技能大赛三等奖。与此同时，他依然保持专业与综合排名双第一的优异成绩，充分体现了其进入高职阶段后快速成长、敢于挑战、全面发展的优秀素质。</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img69.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(31,44,31,'BP-TOPIC-SMART_MANUFACTURING-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "教学成果", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<p>教科研成果、课题项目...</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(32,45,31,'BP-TOPIC-SMART_MANUFACTURING-COMPETITIONS','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-COMPETITIONS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "技能大赛", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img71.webp\" alt=\"\"></figure>\n<p>承办2026年贵州省职业院校技能大赛暨世界职业院校技能大赛贵州省选拔赛高职组“岩矿鉴定与综合地质编录技术”特色赛项</p>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img72.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img73.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img74.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img75.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img76.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img77.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img78.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img79.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img80.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img81.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img82.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img71.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(33,46,31,'BP-TOPIC-SMART_MANUFACTURING-HONORS','upsert','approved','{"code": "BP-TOPIC-SMART_MANUFACTURING-HONORS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "荣誉资质", "subtitle": "智能装备、新能源汽车与无人机应用", "body": "<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img83.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img84.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img85.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img86.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img87.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img88.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img89.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img90.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img91.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img92.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img93.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img94.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/smart-manufacturing/images/img95.webp\" alt=\"\"></figure>\n<p>视频资料（专业特色，可于所在区域屏幕循环播放）</p>", "imageUrl": "/uploads/blueprint/topics/smart-manufacturing/images/img83.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(34,47,32,'BP-TOPIC-FINANCE_COMMERCE-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>系部简介：财政经济系</p>\n<p>财政经济系于 2008 年组建，开设大数据与会计、现代物流管理、电子商务三大专业，年均在校生约 1600 人。2022 年起与贵州工程应用技术学院联合培养财务管理本科班。</p>\n<p>电子商务专业为毕节市人民政府授牌 \"毕节电子商务学院\"，专业群获评贵州省职业教育特色骨干专业群（优秀等次）；大数据与会计专业为省级骨干专业。加入全国直播电商职业教育集团等 5 个国家级产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体（成员单位 120 余家）。拥有贵州省农业电商产业扶贫协同创新中心、高水平乡村电商产教融合实训基地等省级项目 11 项，获批市级数商兴农人才团队、省级教学创新人才团队。先后荣获省级五好基层党组织、市级样板院系、全国五四红旗团支部、全国活力团支部等荣誉。</p>\n<p>学生专升本上线率 93%、录取率 89%。2025年荣获贵州省教学成果特等奖；技能大赛斩获国家级铜奖5项、省级一等奖12项，各级各类奖项累计400余项，为区域经济社会发展作出积极贡献。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img01.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img02.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img03.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img04.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(35,48,32,'BP-TOPIC-FINANCE_COMMERCE-MAJORS','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "专业设置", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>财经商贸电子商务专业群（省级特色骨干专业群 特色打造）</p>\n<p>以电子商务专业群（省级专业群验收优秀等次）为核心，整合大数据与会计（省级质量提升工程骨干专业）、现代物流管理（两年内完成数字化升级为智能物流技术专业），构建“电商引流+物流支撑+会计赋能”三位一体乡村振兴服务体系，精准对接贵州省数字经济、现代服务业及毕节市新型综合能源、山地特色农业、资源精深加工产业集群需求。</p>\n<p>专业群深耕区域特色打造差异化优势：大数据与会计聚焦能源财税、农产加工成本核算，嵌入 RPA 税务机器人等前沿工具；电子商务主攻乡村电商、民族文创电商、跨境电商，助力“黔货出山”；智能物流技术专业聚焦农村共配、服务毕节“1区8中心”快递物流体系建设，同步推进与京东深度合作，升级改造现有物流实训室为生产性智能物流配送中心，新建1-2个京东订单班，为专业数字化升级筑牢基础。</p>\n<p>进一步深化产教融合，推进订单培养模式，整合现有省级实训基地，开发活页式教材。构建“岗课赛证”融通课程体系，培养兼具“传统财经技能+数字技术应用+本土产业认知”的复合型人才，专业群将打造毕节中小企业财经服务、乡村振兴电商赋能、区域物流体系优化核心平台，为西部陆海新通道建设和毕节区域经济高质量发展提供坚实人才支撑。</p>\n<p>电子商务专业</p>\n<p>培养目标：本专业培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向互联网和相关服务、批发业、零售业的运营主管、全渠道营销主管、O2O 销售主管、智能客服主管、视觉营销设计师等岗位（群），能够从事数据化运营、网店运营、社群运营、行业运营、营销活动策划与执行、销售方案执行与优化、客户服务管理、视觉设计工作的高技能人才。</p>\n<p>核心课程：网店运营、数据化运营、社群运营、互联网销售、视觉营销设计、网络营销、零售门店O2O运营、农产品电商运营、跨境电子商务运营、短视频拍摄与直播运营。</p>\n<p>就业方向：本专业毕业生主要面向面向电子商务师、互联网营销师、营销员、市场营销专业人员、商务策划专业人员、品牌开发与运营专业人员、客户服务管理员等职业，运营主管、全渠道营销主管、O2O销售主管、智能客服主管、视觉营销设计师、互联网产品开发主管等岗位（群）就业和自主创业，从事相关工作。</p>\n<p>专业成果：学生获全国职业院校技能大赛、挑战杯、“互联网+ ”双创赛奖项5 项、省赛 100 余项；与京东、贵州卡妈等 15 家企业开展订单培养 350余人，就业率提升至98%以上；面向退伍军人、新农人及返乡创业就业人员，开展乡村电商技能培训和职业体验2000 人次，开展互联网营销师等职业技能鉴定，考证通过率94%以上；获教育部产教融合校企合作典型案例；牵头成立东西部协作乡村电商行业产教融合共同体；教师打造了《黔西北农业职业经理人》省级优质课，培养高级农业经理人7人、贵州省技术能手3人、甲秀之光访问学者3人，团队获批毕节市数商兴农人才团队，贵州省教师教学创新团队。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img05.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img06.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img07.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img08.webp\" alt=\"\"></figure>\n<p>现代物流管理专业</p>\n<p>培养目标：培养践行社会主义核心价值观，具备良好人文素养、数字素养与职业道德，掌握现代物流管理核心知识与技术技能的高技能人才。学生需熟练运用仓储管理系统、数据分析工具及智能物流技术，具备智慧仓配运营、物流运输调度、供应链协同管理等能力，能从事物流项目运营、数据分析、国际货运代理等工作，兼具可持续发展能力与创新创业意识。</p>\n<p>核心课程：构建“基础+核心+拓展”三层课程体系，核心课程包括智慧仓配运营、智慧运输运营、物流成本与绩效管理、采购与供应管理、物流营销与客户关系、国际货运代理实务、物流项目运营、物流系统规划与设计。课程融入大数据、人工智能等新技术，结合农产品电商运营仿真实训、物流数据采集与分析等实践内容，对接物流管理、供应链运营等职业技能等级证书考核要求。</p>\n<p>办学特色：产教融合深厚：与10余家企业共建校外实习基地，引入真实物流项目开展生产性实训，“数商兴农”人才团队助力区域产业发展。</p>\n<p>赛教融合突出：承办贵州省第二届职业技能大赛“物流与货运代理”赛项并获省赛金奖1项，学生在世界职业院校技能大赛全国决赛物流与供应链赛道中获铜奖1项、并先后获省赛一等奖2项，2025第八届一带一路暨金砖国家技能发展与技术创新大赛供应链管理赛项全国总决赛中获一等奖1项，专业教师指导学生获技能大赛奖项50余项。</p>\n<p>师资力量雄厚：拥有“双师型”教师占比91%的教学团队，含全国商贸服务业青年专家1人、市级高技能骨干人才1人、商贸物流专家3人及企业行业导师，主持立项30余项省级、市厅级教研科研课题。</p>\n<p>证书体系完善：推行职业技能等级证书制度，学生可考取贵州省人力资源与社会保障厅认可的三级物流服务师（高级）、供应链管理师等证书。</p>\n<p>就业方向：毕业生主要面向智慧仓配运营、智慧运输运营、生产物流管理等领域，可从事物流项目运营主管、物流数据分析员、国际货运主管、供应链管理师等岗位。就业单位涵盖京东、顺丰速运等知名企业及区域重点物流企业，可通过岗位实习实现就业衔接，也可自主创业开展物流相关服务业务。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img09.webp\" alt=\"\"></figure>\n<p>大数据与会计专业</p>\n<p>培养目标：大数据与会计专业紧跟会计行业数字化、智能化转型要求，立足毕节、服务贵州经济和社会发展为目标，培养德、智、体、美、劳全面发展，践行社会主义核心价值观，具备一定文化水平、良好职业道德和人文素养，掌握本专业知识和技术技能，具备职业综合素质和行动能力，主要面向中小型企业及会计师事务所等中介服务机构，能够胜任出纳、会计核算、税务管理、成本管理、财务数据分析等工作，既精通传统财务功底，又能驾驭财务大数据分析工具，具有创新精神的高素质技术技能型人才。</p>\n<p>核心课程：企业财务会计、智能化成本核算与管理、智能化税费申报与管理、会计信息系统应用、管理会计实务、财务大数据分析、Python开发与财务应用、企业内部控制。</p>\n<p>就业方向：毕业生可选择专升本或到行政事业单位、各类中小微企业、会计师事务所等单位，从事出纳、会计核算、纳税申报、成本管理、财务管理、大数据分析、财务机器应用与开发等岗位相关工作。</p>\n<p>办学特色：大数据与会计专业（原名会计电算化）专业于2008年开始招生，2014年被学校评为重点专业，2017年被贵州省教育厅评为省级骨干专业，2024年大数据与会计专业人才培养方案被贵州省教育厅评为省级示范性人才培养方案。经过10年积淀，办学成果显著。学生参加国家级、省级技能大赛获奖44个，其中获国家三等奖 4个， 获省级一等奖 12 个，二等奖4个，三等奖24个；教师参加金砖国家职业技能竞赛获二等奖2个，三等奖2 个，教师参加贵州省教学成果奖申报获一等奖1个，主持省级、校级科研项目16项，发表科研论文30多篇，开展财税知识培训1000多人次，专业实力雄厚，办学成果显著。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img10.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img11.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img12.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img05.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(36,49,32,'BP-TOPIC-FINANCE_COMMERCE-TRAINING','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-TRAINING", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "实训基地", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>贵州省兴黔富民行动计划项目——高水平乡村电商产教融合实训基地</p>\n<p>围绕毕节建设贯彻新发展理念示范区历史使命，聚焦乡村振兴和人力资源开发，学院瞄准区域农业全产业链数字化转型新机遇，围绕新经济、新商业、新电商，融入人工智能、物联网、大数据、虚拟现实等新技术，构筑线上线下有机融合的“毕货网行”双轨系统，拟建“高水平乡村电商产教融合实训基地”(以下简称基地)，按照“深化产教融合新模式、对接产业发展新定位、融合“云物大智”新技术、共创协同发展新标杆”的总体建设思路，建立“1 基地+4 内容+6 功能+X 中心”的产教融合服务体系，构建一个集教学科研、职业培训、技能竞赛和社会服务为一体的人才培养、技术创新、实务对接、精准扶贫与创新服务高水平专业化产教融合实训基地。探索建立发展股份制、混合所有制产权制度，形成产教深度融合的校企命运共同体。服务我校电子商务省级特色骨干专业群，重点是培养“懂财会、会技术、明市场、精电商、能运营、善管理、可创业”的复合型本土化高素质“新农商”人才。</p>\n<p>本项目建成六中心一平台，其中 1+X 考培中心辐射全校所有 1+X 证书制度试点（15 个），同时兼顾校内外培训，目前在中心已开展社会培训 500 人次，考证合计 300 人次，针对四类人员培训（退伍军人、农民工、下岗职工、普通高中毕业生）500 人次；京东校园实训中心目前组织开展真实订单业务，截止目前已完成订单 3582752 单，2022 年产生社会效益 42.6 万元，2023 年至今产生社会效益 26.6 万元；乡村电商网络营销与直播实训中心连续开展四届网络直播大赛（2020 年——2023 年），主要直播品类为家乡农特产品及其他类目引流品，用实际行动服务乡村振兴，产生总经济效益 36481 元；与重庆诺维奇进出口贸易有限公司开展真实外贸业务，产生订单国家10余个，产生外贸订单销售额2679.65美金；职教扶贫农村电商，助力乡村振兴，辐射带动区域产</p>\n<p>业高质量发展。</p>\n<p>贵州省技能贵州建设项目——乡村电商物流生产性产教融合实训基地</p>\n<p>基地立足服务贵州省“乡村振兴、大数据、大生态”三大战略目标，围绕“四新”主攻“四化”，以服务区域现代农业全产业链“种植、养殖、加工、检测、销售、物流、客服”中农产品上行及工业品下乡为出发点，持续引入京东、顺丰等头部电商物流企业真实工作任务和生产性实训业务，打造创新型教师团队、推进“岗课赛证”综合育人，建立产学研用技术创新高地，助力毕节乡村电商及配套物流体系的发展完善，将基地打造成为“五大标杆”。</p>\n<p>打通农产品上行与工业品下乡流通链路，降低物流成本，带动涉农主体增收。依托“岗课赛证”定向培育电商物流技能人才，同步开展社会化培训，培育本土创业带头人。打造双师团队，开发特色实训课程，产出课题、论文、软著等科研成果。建成全链条生产性实训平台，实现多功能融合，为乡村涉农主体提供技术服务。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img13.webp\" alt=\"\"></figure>\n<p>互联网+财务云实践基地</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img14.webp\" alt=\"互联网+财务云实践基地\"><figcaption>互联网+财务云实践基地</figcaption></figure>\n<p>乡村电商物流生产性产教融合实训基地</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img15.webp\" alt=\"乡村电商物流生产性产教融合实训基地\"><figcaption>乡村电商物流生产性产教融合实训基地</figcaption></figure>\n<p>电子商务课程培训</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img13.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(37,50,32,'BP-TOPIC-FINANCE_COMMERCE-COOPERATION','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "产教融合", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>数商兴农：产教协同，构建特色发展格局</p>\n<p>紧扣“数商兴农”战略与“黔货出山”需求，系部深化专业建设与产教融合，走出特色发展之路。优化专业布局，暂停同质化专业，打造电子商务特色骨干专业群，建成贵州省农业电商扶贫协同创新中心、高水平乡村电商产教融合实训基地等 11 项省级项目，组建毕节市数商兴农人才团队、贵州省电子商务教师教学创新团队。搭建高能级产教平台，受邀加入5个全国性产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟等协作载体，与京东实现 “课堂即岗位” 深度合作，与顺丰联合推进直播助农项目，将数字商务技能培养与乡村振兴需求精准对接，相关成果荣获贵州省教学成果特等奖。</p>\n<p>服商赋能：扎根地方，扛起区域发展责任</p>\n<p>立足毕节区域发展需求，系部以“服商赋能”为导向，全面强化社会服务能力。10名教师入选毕节市商贸流通领域专家库（全市共 29人），4 人入选市文化旅游培训师资库，拥有科技特派员、毕节市拔尖人才、高级农业职业经理人等一批行业骨干。聚焦商贸流通、乡村电商等领域，开展技能培训与技术服务，助力地方产业升级；组建学生助农团队两年来，帮助毕节农特产品实现销售转化 30 余万元，成功破解织金县竹荪电商运营技术难点，获织金县商务局感谢函；协助推广毕节市航空航天展，获主办单位四川商会致谢，相关事迹被毕节日报等多家媒体大版面报道。通过东西部协作、校地联动，将商科人才培养、技术服务与区域电子商务、现代物流产业发展深度绑定，在数商兴农、商贸人才培育等领域持续贡献力量，赢得广泛社会赞誉。</p>\n<p>对接产业</p>\n<p>系部深度锚定贵州省及毕节市现代商贸、数字经济、现代物流、财税服务、农特产品产销等重点产业链，精准对接产业岗位需求，深化校企协同育人，构建全链条、全覆盖的产业对接体系，实现专业与产业、教学与岗位、育人与就业精准适配。</p>\n<p>（一）核心对接产业领域</p>\n<p>重点对接数字电商产业、现代供应链物流产业、智能财税服务产业、乡村农特产品商贸产业、进出口贸易产业、智慧供应链科技产业六大核心产业，贴合数字经济发展浪潮与粤黔东西部协作发展布局，聚焦地方数商兴农、乡村振兴、商贸流通升级核心需求。</p>\n<p>（二）重点合作企业单位</p>\n<p>深耕行业龙头企业与地方重点国企、优质本土企业合作，合作单位涵盖全国头部电商物流企业、行业科技龙头、地方国资商贸企业、农业龙头企业及专业财税服务机构，核心合作主体包括：京东集团、阿里巴巴（中国）教育科技、贵州顺丰速运、江苏京东信息技术、贵州京邦达供应链、珍岛信息技术、广州大洋教育、中联集团教育科技、重庆诺维奇进出口贸易；毕节市商贸物流发展集团、毕节农投实业、毕节十八农产品物流园、贵州电子商务云、贵州卡妈农特产品开发、毕节珍好农特产品开发、毕节家乡美农业综合开发、毕节山宝农业、毕节绿色畜牧科技；贵州嘉禾华政税务师事务所、毕节水务、厦门网中网软件、贵州誉佳朗商贸等，全方位保障实习实训、岗位就业、项目研发、师资共建等产教融合落地。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img16.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img17.webp\" alt=\"\"></figure>\n<p>产教融合平台</p>\n<p>平台建设层级高、数量多，累计建成贵州省电子商务协同创新中心、物流生产性产教融合实训基地等省级平台项目11项；获批毕节市数商兴农人才团队、省级教学创新人才团队。行业影响力持续攀升，2024年成功加入全国直播电商、现代物流与供应链、财税服务等5个国家级行业产教融合共同体；牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体，共同体汇聚120余家成员单位，由全国电商教指委、毕节市教育局、商务局、粤黔协作工作组权威指导，成为区域产教融合标杆平台。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img18.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img19.webp\" alt=\"\"></figure>\n<p>校企合作订单班</p>\n<p>京东订单班</p>\n<p>为深化校企合作，充分发挥学校和企业双方的优势，推进电子商务专业建设和教学改革，完善实践实验教学体系，使学生在顶岗实训中内化专业知识，发挥高校为社会服务的功能，为企业培养更多高素质、高技能的应用型人才，同时学生在实训过程中能够获取一定的经济收入，院校与京东充分沟通，《客服实战跟岗实训》由学校教师和京东教师联合授课，把京东企业真实客服业务引入课堂，充分利用京东校企合作实训室建设基础设施和学院师资和教学资源，与企业行业共同培养客户服务相关人才。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img20.webp\" alt=\"\"></figure>\n<p>京东订单班授课</p>\n<p>顺丰订单班</p>\n<p>为深化校企协同育人机制，提升电商专业学生实践应用能力与岗位适配素养，毕节职业技术学院财经经济系联合顺丰企业打造顺丰班赋能电商专业体系。通过明确实践方向、优化团队架构、强化资源保障，为系列实践项目规范化推进奠定坚实基础。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img21.webp\" alt=\"\"></figure>\n<p>顺丰订单班授课</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img16.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(38,51,32,'BP-TOPIC-FINANCE_COMMERCE-MASTERS','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-MASTERS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "名师名匠", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>张进华，男，41岁，汉族，中共党员，副教授。先后担任财政经济系团总支书记、副主任、系主任等职务，现任毕节职业技术学院教务处长，贵州省高等职业学校办学能力评价专家、贵州省职教学会职业教育教学专家、市管专家、市拔尖人才、毕节市“数商兴农”人才团队负责人、贵州省电子商务教师教学创新团队负责人、贵州省电子商务特色骨干专业群负责人（优秀等次）、贵州省农业电商产业扶贫协同创新中心负责人;获全国商贸服务业青年专家、中国商业会计学会慧心育人奖、贵州省“甲秀之光”访问学者、毕节市商贸服务重点领域专家库专家等荣誉称号;担任“畅享杯”全国财经商贸类专业教师数字技术技能大赛-直播营销竞赛裁判、贵州省职业院校技能大赛教学能力比赛裁判、广东省等省级职业院校技能大赛（世界职业院校技能大赛选拔赛）裁判。</p>\n<p>主持成果荣获2024年贵州省职业教育教学成果奖特等奖;主持成果《育训并举 多方协同 平台赋能：西部山区乡村振兴人才培养模式创新实践》荣获2025年教育赋能乡村振兴典型案例、《乡村振兴背景下本土化复合型乡村电商人才培养研究与创新实践》荣获2025年贵州省职业教育典型案例；荣获省级以上奖项10项；主持市厅级以上科研项目5项；发表论文8篇。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img22.webp\" alt=\"\"></figure>\n<p>一、案例基本信息</p>\n<p>人物：李洁，毕节职业技术学院财政经济系电子商务专业专任教师</p>\n<p>赛事：贵州省第二届职业技能大赛（主办：贵州省人民政府；承办：贵州省人社厅、毕节市人民政府）</p>\n<p>参赛项目：直播带岗（省级特色赛项）</p>\n<p>荣誉：赛项金牌、贵州省技术能手</p>\n<p>配套配图：图 1：颁奖现场留影（省技能大赛主舞台个人获奖实拍） 图 2：大赛金奖获奖证书 图 3：贵州省人力资源和社会保障厅颁发 “贵州省技术能手” 荣誉证书</p>\n<p>二、案例背景</p>\n<p>职业教育强调 “岗课赛证” 深度融合，直播电商、数字人力资源服务是电子商务专业核心发展方向，“直播带岗” 作为贴合地方就业帮扶、乡村人才输送的新兴技能赛道，高度契合毕节本地产业招工、劳务输出、乡村振兴就业服务需求。 为紧跟全省职业技能提升行动，打磨专业实操教学能力，提升课堂教学与真实职场岗位的匹配度，本人主动报名参加 2025 年贵州省第二届职业技能大赛直播带岗特色赛项，以行业竞赛标准倒逼自身专业技能迭代，探索 “竞赛内容转化课程资源” 的育人路径。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img23.webp\" alt=\"\"></figure>\n<p>扎根地方产业，夯实竞赛核心能力 赛前深入毕节市农投实业、山宝农业本地涉农企业走访调研，熟悉企业用工需求、高校毕业生、易地搬迁群众求职痛点，将本地特色农产品企业、基层服务岗位作为直播带岗脚本核心素材，把电商直播话术、镜头表达、流量运营、就业政策解读、求职者心理疏导五大模块作为训练重点。</p>\n<p>以教学经验打磨竞赛综合素养 依托多年电子商务直播运营课程授课经验，搭建完整竞赛训练体系：模拟直播间实景带岗宣讲、线上连麦求职者答疑、企业 HR 连线互动、短视频引流招工全流程演练；同步打磨就业政策宣讲、岗位价值塑造、舆情应急处置等拓展能力，兼顾电商传播能力与公共就业服务专业素养。</p>\n<p>省级大赛同台竞技，斩获最高奖项 2025 年 5 月，在毕节主赛场与全省各市州、院校、企业百余名选手同台比拼，竞赛考核涵盖直播脚本策划、实景带岗直播、短视频招工内容创作、就业服务综合答辩四大模块。凭借贴合毕节本地就业场景的创作内容、成熟流畅的直播表达、兼具电商传播与民生服务的综合能力，最终拿下直播带岗项目全省金牌。</p>\n<p>四、赛事成果与官方荣誉</p>\n<p>获得《贵州省第二届职业技能大赛直播带岗金牌》，证书由大赛组委会、省人社厅代章颁发；</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img24.webp\" alt=\"\"></figure>\n<p>依据省级技能大赛获奖表彰政策，经贵州省人力资源和社会保障厅评定，于 2026 年 2 月授予 “贵州省技术能手”省级行业权威荣誉，颁发专属荣誉证书，编号 N2026GZS0124。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img25.webp\" alt=\"\"></figure>\n<p>（一）树立师生技能榜样，营造技能成才校园氛围</p>\n<p>作为专业教师斩获省级赛事金牌、获评省级技术能手，在系部、校内形成示范效应，带动全系电商专业师生主动参与各级职业技能竞赛，推动 “人人练技能、人人闯赛场” 的实训育人氛围落地，践行职业教育 “技能黔行・创造未来” 大赛主题精神。</p>\n<p>（二）岗课赛证融合创新，构建特色育人模式</p>\n<p>依托直播带岗赛项经验，探索 “电商直播技能 + 公共就业服务” 复合型人才培养方向，对接人社相关职业技能证书考核内容，打造适配毕节乡村振兴劳务输出、县域企业数字招工的特色电商人才培养路径，提升学生就业竞争力与社会服务能力。</p>\n<p>本次参赛不仅是个人专业技能的全面提升，更是一次职业教育服务地方产业、民生就业的实践探索。今后将持续把省级大赛积累的实操经验、行业标准、本地产业素材融入日常教学，持续深耕直播电商、数字就业服务教学方向，带领学生以数字技能助力毕节乡村就业振兴，充分发挥 “贵州省技术能手” 的示范引领作用，落实职业教育技能育人、服务地方的根本使命。</p>\n<p>何园园，中共党员，毕节职业技术学院副教授、物流专业负责人、一级物流师（高级技师），2017年入职我校，深耕职业教育与物流技能领域多年，是毕节市的高技能骨干人才，以高尚师德、扎实学识与精湛技艺，成为我校教师队伍中的优秀标杆。</p>\n<p>作为物流领域高级技师，何园园将前沿技术融入日常教学。她深耕技能竞赛赛场，先后斩获贵州省职业院校教学能力大赛三等奖、“智慧物流”教师赛二等奖，京津冀沪交通职业教育集团联盟教师赛全国一等奖，还参与斩获贵州省职业教育教学成果奖特等奖。</p>\n<p>在育人之路上，她倾力指导学生逐梦赛场，十余年间带领学生斩获各级奖项数十项，囊括一带一路金砖供应链管理赛项全国总决赛一等奖、全国物流仿真设计大赛一等奖、贵州省第二届职业技能大赛物流与货运代理赛项省赛金奖等荣誉。同时，她身兼数职，担任全国职业技能大赛、省级技能大赛等多项赛事裁判与技术专家。</p>\n<p>教研方面，她主持省级技能贵州项目生产性产教融合实训基地、贵州省教育厅教育科学规划课题、贵州省教育厅职业教育课题、市委重大课题、市社科课题等十余项科研与教改项目，聚焦毕节农产品物流、电商物流发展等本土课题，发表国家级、省级论文10余篇，助力地方物流产业与职业教育融合发展。</p>\n<p>师德立身，初心不改。她先后获评校级“优秀教师”“优秀辅导员”“教学名师”“优秀党务工作者”毕节市“师德标兵”等荣誉。立足黔西北职教沃土，何园园以技能赋能育人，以实干担当使命，充分展现了新时代高技能人才的风采，为学校专业建设、地方技能人才培养贡献力量。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img26.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img27.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img22.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(39,52,32,'BP-TOPIC-FINANCE_COMMERCE-ALUMNI','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-ALUMNI", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀校友", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>1.行业技术能手2020级优秀毕业生 孟小蛟</p>\n<p>工作单位及职务：中国人寿保险股份有限公司 业务员</p>\n<p>在校期间表现：毕节职业技术学院财政经济系2020级会计专业学生，贵州省毕节市人。在校期间担任系部团总支学生会权益委员会主席兼团总支副书记及2020级会计1班团支部副书记一职，多次荣获国家励志奖学金、优秀学生干部及三好学生等表彰，2023年荣获贵州省优秀学生干部、优秀毕业生称号。</p>\n<p>工作业绩：2023年9月以来，从事中国人寿保险股份有限公司业务员工作，在此期间积极参与公司策划培训，在保险工作总会遇到复杂的情况和困难，需要耐心地处理和时刻保持积极的心态，用良好心态对待问题和挑战，不断给予客户足够的耐心和帮助。在工作单位团结同事、吃苦耐劳，不断持续学习新的经济法规政策，作为保险从业者，在工作中不断提升自己的知识和技能，目前在工作中得到了很大的提升，时刻铭记，成己为人，成人达己，今后将不断提升自我，不负党和国家对我的培养教育，更好地服务于人民。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img28.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img29.webp\" alt=\"\"></figure>\n<p>（孟小蛟参加大学生创业计划竞赛） （孟小蛟参加优秀教职生进校园分享会）</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img30.webp\" alt=\"（孟小蛟参加大学生创业计划竞赛） （孟小蛟参加优秀教职生进校园分享会）\"><figcaption>（孟小蛟参加大学生创业计划竞赛） （孟小蛟参加优秀教职生进校园分享会）</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img31.webp\" alt=\"（孟小蛟参加大学生创业计划竞赛） （孟小蛟参加优秀教职生进校园分享会）\"><figcaption>（孟小蛟参加大学生创业计划竞赛） （孟小蛟参加优秀教职生进校园分享会）</figcaption></figure>\n<p>（孟小蛟参加财政经济系优秀学生干部颁奖典礼）</p>\n<p>（孟小蛟参加财政经济系党支部七星关区生机镇“绝壁天渠”主题党日活动）</p>\n<p>座右铭：胸有凌云志，无高不可攀。</p>\n<p>2.行业技术能手2020级优秀毕业生 查佳丽</p>\n<p>工作单位及职务：毕节丰业置业有限公司 会计助理</p>\n<p>在校期间表现为：毕节职业技术学院财政经济系2020级会计专业学生，贵州省毕节人。在校期间踏实肯干、努力学习，担任2020级会计一班的学习委员、连续两年获得国家励志奖学金、三好学生等表彰、积极参加贵州省会计技能大赛并获得三等奖，2023年获得贵州省优秀毕业生称号。</p>\n<p>工作业绩：2023年01月以来，从事毕节丰业置业有限公司会计助理工作，并成功转正为正式员工，期间多次获得奖金，在工作单位团结同事、吃苦耐劳，得到同事和领导的一致好评。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img32.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img33.webp\" alt=\"\"></figure>\n<p>（荣获国家励志奖学金） （获得初级会计证书）</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img34.webp\" alt=\"（荣获国家励志奖学金） （获得初级会计证书）\"><figcaption>（荣获国家励志奖学金） （获得初级会计证书）</figcaption></figure>\n<p>（公司组织项目培训）</p>\n<p>座右铭：纵有疾风起，人生不言弃！</p>\n<p>3.行业技术能手2020级优秀毕业生 权佑红</p>\n<p>工作单位及职务：北京春苇建文咨询服务有限公司 会计助理</p>\n<p>在校期间表现：毕节职业技术学院财政经济系2020级会计专业学生。在校期间担任2020级会计1班班长兼团支部书记一职，积极参加课外活动，工作认真负责、积极主动；能吃苦耐劳，喜欢思考，虚心与人交流，拥有良好的沟通协调能力，善于应变，能够快速适应新环境，具有较强的团队组织能力与协作能力，能够熟练掌握办公软件。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img35.webp\" alt=\"\"></figure>\n<p>工作业绩：2023年5月以来，从事北京春苇建文咨询服务有限公司会计助理工作，工作期间负责公司财务报表的准确性和完整性，及时地编制财务报表，并确保其真实、合法、完整，主要对企业的经济业务进行监督和控制，确保企业的财务活动符合法律法规和企业的规章制度。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img36.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img37.webp\" alt=\"\"></figure>\n<p>（开展田径协会第一届换届大会暨第二届成立大会）（参加公司会计报账工作）</p>\n<p>座右铭：天行健子 君子以自强不息 地势坤 君子以厚德载物。</p>\n<p>4.行业技术能手2020级优秀毕业生 王国来</p>\n<p>工作单位及职务：贵阳市南明区中华南路街道办事处</p>\n<p>在校期间表现：为毕节职业技术学院财政经济系2020级电子商务专业学生，贵州省毕节市威宁人。在校期间担任电子商务二班学习委员，2021年荣获校级学生优秀干部、农村电商创新创业大赛三等奖及职教赛道优秀奖，2022年荣获校级一等奖学金和国家励志奖学金，2023年荣获学院优秀毕业生称号。</p>\n<p>随着对实习岗位的深入了解，我为自己未来感到迷茫，感到无助、感到害怕，作为低学历的我们能干嘛呢？这时想起老师曾经对我说过关于大学生西部计划的事：“到西部去、到基层去、到祖国需要的地方去报效祖国是一件很有意义的事，能提升锻炼自我的同时，政府还给予一定的政策扶持”。老师还说有这个想法的话，就要好好备考，因为考西部计划的竞争很大。听师一席话胜读十年书，接下来得好好准备了。而且刚好自己一直向往的是：既能服务人民，服务国家、服务社会还能让自己得到充分锻炼和提升自我，何乐而不为呢？</p>\n<p>今后的日子里，我搜集了有关西部计划题库和历年的试卷，正如，好记性不如烂笔头，我进行全部抄下来，理解性地进行背诵。5月15这一天我收到学校西部计划报名通知，此时内心无比激动想着离自己的梦想又更近一步。但压力也随之大了许多，于是我更加全身心投入当中，开启了“狂”刷试题模式，经过一个多月战斗终于迎来上战场那天，笔试考试前一天就来学校附近酒店住下准备明天的考试，第二天当我踏进考场那一刻感觉如百米赛跑， 每个人都随时准备好冲在第一个。走出考场那一刻如释重负很多题目都是自己刷到过的，接下来就是准备面试。</p>\n<p>四天之后收到通知面试，面试有一分钟的自我介绍，我就提前写了稿子，稿子虽然简简短短的几句话，但是我经过了反复地修改，还找了我觉得文采不错的朋友看了，给我意见。当面试到我时由于我之前参加学校各种赛事和我自己的精心准备，自我介绍在意料之中地顺利完成，面对老师提问时不慌不忙回答流畅思路清晰。走出考场悬着的心终于落下，等待一个星期后全校成绩出了，当我看到自己综合成绩那一刻，内心彻底狂热因为我考了全校第一名。此时此刻明白了这句话机会永远都是留给有准备的人。随着体检的通过我被分配到贵阳南明区中南街道办事处。</p>\n<p>8月1日，来街道办事处报到，领导就给我分配了任务，办公上：主要负责“拷文件、青年之家平台活动录入、智慧团建主题录入和团员转接关系审批、收取团费等，并安排和督促11个社区开展智慧团建的相关工作，还有筑红云平台的维护、写简报、制作表格和汇总表格、收集相关活动图片、打印资料、刊播LED并将刊播内容发放各辖区督促刊播和进行宣传”等。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img38.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img39.webp\" alt=\"\"></figure>\n<p>（青年之家活动录入） （LED屏刊播拍照反馈工作群）</p>\n<p>自我提升上：街道也会不定时地安排到不同的地方进行一些自我能力提升的培训，如“在贵阳广播电视台培训微型相机拍摄技巧、南明区文化馆和贵州省图书馆培训普法学习、南明区区政府培训舆情信息”等等。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img40.webp\" alt=\"\"></figure>\n<p>外环境上：协助领导开展巩文工作，对三星级以上酒店周边环境卫生、车辆乱停乱放，非抽烟区对抽烟人员进行劝阻，以及酒店点位进行检查。酒店点位检查的内容有：“是否有制作刊播展示公益广告、反对浪费的温馨提示、餐厅餐桌上提供公勺或公筷、无露天烧烤、乱排烟现象、有消毒设配、消毒措施和记录”等等。经过一段时间的排查后，环境卫生、车辆乱停乱放、非抽烟区不能抽烟，以及酒店点位都有很大的整改。在工作期间勤奋努力，恪尽职守，不耻下问，赢得了领导和同事们的一致好评。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img41.webp\" alt=\"\"></figure>\n<p>（酒店附近进行环境维护）</p>\n<p>座右铭： 流星之所以美丽在于燃烧的过程，人生之所以美丽在于奋斗的过程。</p>\n<p>5.行业技术能手2020级优秀毕业生 李朝娥</p>\n<p>工作单位及职务：贵州凌悦大酒店有限公司 财务</p>\n<p>在校期间表现：为毕节职业技术学院财政经济系财务管理专业学生，贵州省安顺市镇宁布依族苗族自治县人，在校期间成绩较优异，担任2020级财务管理（1）班学习委员，2021年6月荣获学院“互联网＋”大学生创新创业大赛三等奖、2021年11月荣获学院一等奖、多次荣获国家励志奖学金、2022年7月荣获初级会计职称、同年荣获优秀学生干部、2023年荣获优秀毕业生称号。</p>\n<p>工作业绩：出校之后就选择这家公司实习，在她上班的第一天去税务局遇到了一个专管员，专管员知道她是刚出来实习的，就跟她说了一句话，你刚出来做财务一定不能做假账，一定要本本分分地做好自己的本职工作，千万不能触碰法律，当然这也是在校期间老师们所教诲的，她也会铭记终生的，公司给的实习期是三个月，在上了一个半月的时候财务经理就直接给她转正，成为公司的正式员工，在这里她学到了更多书本上写但不仅限于书本上的知识，更加了解财务这个行业，运用所学的知识跟实际相结合，工作期间也不断地丰富自己的财务知识，随时关注税务政策上的更新，她会更加努力地学习更多税务知识，使自己的业务能力跟综合素质各方面得到提升。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img42.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img43.webp\" alt=\"\"></figure>\n<p>（国家励志奖学金） （初级会计职称证书）</p>\n<p>座右铭：不要着急，最好的总会在最不经意地时候出现。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img44.webp\" alt=\"座右铭：不要着急，最好的总会在最不经意地时候出现。\"><figcaption>座右铭：不要着急，最好的总会在最不经意地时候出现。</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img45.webp\" alt=\"座右铭：不要着急，最好的总会在最不经意地时候出现。\"><figcaption>座右铭：不要着急，最好的总会在最不经意地时候出现。</figcaption></figure>\n<p>（在工作中获得公司颁发的证书） （公司团建时照片）</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img46.webp\" alt=\"（在工作中获得公司颁发的证书） （公司团建时照片）\"><figcaption>（在工作中获得公司颁发的证书） （公司团建时照片）</figcaption></figure>\n<p>（公司举行员工大会颁奖）</p>\n<p>6.行业技术能手2020级优秀毕业生 邓云云</p>\n<p>工作单位及职务：毕节市彝姑娘特色食品开发有限公司主播。</p>\n<p>在校期间表现：为毕节职业技术学院财政经济系2020级电子商务专业学生，贵州省毕节市七星关区人。在校期间担任第八届ERP商战协会会长一职及2020级电子商务一班副班长兼团支部副书记，2021至2022连续两年荣获国家励志奖学金及优秀学生干部称号，2022年1月荣获毕节市首届电商直播大赛人气奖，2021年7月荣获毕节职业技术学院第七届互联网+创新创业大赛三等奖，2021年6月荣获毕节职业技术学院农村电商互联网+创新创业大赛优秀奖，2021年6月，荣获毕节职业技术学院学生社团联合会第六届ERP沙盘模拟企业经营二等奖，2022年5月，荣获毕节职业技术学院ERP商战协会第八届沙盘模拟企业经营一等奖，2021年10月荣获毕节职业技术学院财政经济系团总支优秀成员称号，2023年荣获学院优秀毕业生称号。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img47.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img48.webp\" alt=\"\"></figure>\n<p>工作业绩：2022年8月1日参加了工学结合就到毕节市彝姑娘特色食品开发有限公司做主播，直播间主要推出的是我们贵州的特色产品。来到公司的第二天我就开始尝试直播，第一次直播卖了35单销售额到达1439元直播人数达到2000多，第一次以工作形式去播心里还是很紧张很害怕的。来公司的第二个月就成功转正了，现在每天至少要播两小时，流量好的时候播到了晚上十二点左右，销售额最高一次达到1.2万，直播间在线人数最高一次达到1262人。除了直播带货，我还负责了一些贵州特产的拍摄，从2023年3月1日就开始养了小号，小号每天主要负责拍作品、剪作品和发作品，每天早上上班我就会以不同的方式去拍摄不同的视频，每天中午一点到两点之间发布视频。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img49.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img50.webp\" alt=\"\"></figure>\n<p>（第一次直播销售数据） （直播间最高在线人数）</p>\n<p>2022年9月底因疫情严重、物资紧缺，10月3日协同彝姑娘公司捐赠了抗疫物资。在工作期间勤奋好学、团结同事、吃苦耐劳得到同事以及领导们的一致好评。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img51.webp\" alt=\"\"></figure>\n<p>（协同彝姑娘特色食品开发有限公司捐赠抗疫物资）</p>\n<p>座右铭： 越努力就越幸运，要相信付出永远都是有收获的。</p>\n<p>7.升学励志进取优秀毕业生 李貌</p>\n<p>学习单位及职务：2020级高职财务管理（2）班，担任学习委员</p>\n<p>在校期间表现：为毕节职业技术学院财政经济系 2020 级高职财务管理专业学生，贵州省七星关区人。在校期间总是积极进取，担任2020级高职财务管理（2）班学习委员，三年学习成绩都是班级第一，财务管理专业第一。2023年荣获省级“优秀毕业生”称号、2020-2021年度荣获“国家励志奖学金”、2021-2022年度荣获“国家励志奖学金”2021年荣获校级“三好学生”称号、2021年度荣获“优秀共青团员”称号、2022年荣获校级“三好学生”称号等等。</p>\n<p>升学历程：自2020年以来，一直努力学习专升本的课程，始终坚持了三年的学习，一心想着无论如何都要考上，每天都坚持背单词，背语文。大学是一个展示自我、认识自我的地方，从中收获颇多。努力了三年终于有了结果，以文化+专业301分的成绩成功录取贵州工程应用技术学院的财务管理专业。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img52.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img53.webp\" alt=\"\"></figure>\n<p>（李貌毕业生代表讲话现场） （李貌为学弟学妹讲解专升本现场）</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img54.webp\" alt=\"（李貌毕业生代表讲话现场） （李貌为学弟学妹讲解专升本现场）\"><figcaption>（李貌毕业生代表讲话现场） （李貌为学弟学妹讲解专升本现场）</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img55.webp\" alt=\"（李貌毕业生代表讲话现场） （李貌为学弟学妹讲解专升本现场）\"><figcaption>（李貌毕业生代表讲话现场） （李貌为学弟学妹讲解专升本现场）</figcaption></figure>\n<p>（李貌荣获省级毕业生） （李貌专升本录取）</p>\n<p>座右铭：我相信努力了一定有收获，皇天不负有心人，星光不问赶路人。</p>\n<p>8.升学励志进取优秀毕业生 杨乾敏</p>\n<p>学习单位及职务：2020级高职会计2班，资助委员</p>\n<p>在校期间表现：为毕节职业技术学院财政经济系2020级会计专业学生，在校期间品学兼优，尽职尽责。曾担任财政经济系副主席、班级资助委员一职。2021年荣获学院“优秀共青团干部”荣誉称号，2022年5月份积极参与学院组织的第十五期青年马克思主义培训工程，并荣获“优秀学员”称号。在2021至2022学年连续两次荣获国家励志奖学金，2021年度学院一等奖学金，2022年度学院“优秀学生干部”以及贵州省2023年度“优秀毕业生”等荣誉称号。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img56.webp\" alt=\"\"></figure>\n<p>（2023年荣获贵州省优秀毕业生荣誉称号）</p>\n<p>升学历程： 2020年当她得知自己将就读于高职时，她凭借着一颗不安于现状的决心在专科学院里努力学习着，于2023年7月份她终于成功上岸啦，录取于贵阳信息科技学院的会计学专业。但她的脚步并不会止步于此，在今后的道路中她将会坚定不移地向着自己的目标前行。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img57.webp\" alt=\"\"></figure>\n<p>杨乾敏就读于贵阳信息科技学院（原贵州大学明德学院））</p>\n<p>座右铭：成功不是凭理想和希望，而是凭努力和实践。</p>\n<p>9.升学励志进取优秀毕业生 夏飞飞</p>\n<p>学习单位：贵州省安顺市安顺学院经济与管理学院，专业：农村区域发展学生。</p>\n<p>在校期间表现：曾就读于毕节职业学校财政经济系，贵州省习水人，在校期间曾参与并创办了田径协会，并担任副会长一职。</p>\n<p>工作业绩：于2023年参加国家统一专升本考试，并上岸安顺学院。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img58.webp\" alt=\"工作业绩：于2023年参加国家统一专升本考试，并上岸安顺学院。\"><figcaption>工作业绩：于2023年参加国家统一专升本考试，并上岸安顺学院。</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img59.webp\" alt=\"工作业绩：于2023年参加国家统一专升本考试，并上岸安顺学院。\"><figcaption>工作业绩：于2023年参加国家统一专升本考试，并上岸安顺学院。</figcaption></figure>\n<p>专升本录取通知书</p>\n<p>座右铭：知识改变命运，勤奋创造未来。</p>\n<p>10.升学励志进取优秀毕业生 杨飞</p>\n<p>贵州省贵州商学院2021级工商管理3班</p>\n<p>系毕节职业技术学院财政经济系2020级高职市场营销专业学生，贵州省安顺市人。在校期间，担任班级文体委员一职，担任学校社团春晖社担任第七届春晖社社长，荣获国家励志奖学金、优秀个人等表彰。</p>\n<p>2020年以来，思想上积极进取、遵纪守法、遵守校纪校规，坚持理论学习，一心向党。在学习上，认真学习，认真踏实，成绩优异。在生活上，乐于助人，积极配合老师工作完成工作，与同学建立良好关系，互帮互助，攻克难关，营造了良好的班级氛围。 现在在本科院校也积极努力学习，提升自己的学习能力和实践能力，坚持就会有回报 ，努力就会有奇迹，一切都会越来越好！ 座右铭；关关难过关关过，前路漫漫亦灿灿</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img60.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img61.webp\" alt=\"\"></figure>\n<p>11.升学励志进取优秀毕业生 曾祥梅</p>\n<p>工作单位及职务：第八届ERP商战协会副会长</p>\n<p>在校期间表现：为毕节职业技术学院财政经济系2020级会计专业学生，贵州毕节人。在校期间加入中国共青团，曾担任ERP商战协会副会长一职。2020年—2021学年荣获“国家励志奖学金”，2020年—2021年荣获“三好学生”称号等荣誉，2021年6月获得第十七届全国职业院校数智化企业经营沙盘大赛贵州省省赛“一等奖”、第六届ERP沙盘模拟企业经营项目“一等奖”，2022年8月考取初级会计师资格证。</p>\n<p>升学历程：2023年5月份，她在2023年专升本工作中，成功上岸，录取贵阳信息科技学院，感谢毕节职业技术学院生活让她在思想境界、知识水平、工作潜力等方面都迈上了一个新台阶。作为当代大学生她一定会力所能及为社会奉献出自己的一份力，将自己投身到“中华民族的伟大复兴梦”当中，在新征程新启航中燃烧、奉献自己，在新的形势下勇挑重担，扎实有效地推进乡村振兴战略，不辜负党和人民的期盼。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img62.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img63.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img64.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img65.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img66.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img67.webp\" alt=\"\"></figure>\n<p>（荣获“三好学生”称号）（荣获国家励志奖学金）（获企业经营沙盘省赛“一等奖”）（获沙盘模拟“一等奖”）</p>\n<p>座右铭：前路浩浩荡荡，万物皆可期待。</p>\n<p>（一）李虎</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img68.webp\" alt=\"（一）李虎\"><figcaption>（一）李虎</figcaption></figure>\n<p>李虎，男，1998年11月，贵州毕节人，共青团员，在校期间曾担任系团总支副书记、学生会主席、青年志愿者协会会长等职务，2020年毕业于2015级五年制会计班。</p>\n<p>一、毕业前的简介</p>\n<p>平时我认真学习习近平总书记系列重要讲话精神和社会主义核心价值观来不断提高自身的政治修养，争做新时代下的新青年。在2018年5月经系部推荐，参加了“青年马克思主义者培养工程”培训班学习，在培训中，我认真学习理论知识，不断用思想政治理论知识来武装自己，并积极参加培训班各项社会实践活动，在毕节市敬老院关爱空巢老人、幼儿园关爱留守儿童，以及在学校田径场参加素质拓展活动我都认真对待，充分体现了新时代下大学生应该具有的尊老爱幼和团结同学的责任与义务，最终获得“青年马克思主义者培养工程”班的结业证书及院优秀志愿者荣誉称号。在此同时还积极的向党组织靠拢，时刻以党员的标准来严格的要求自己。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img69.webp\" alt=\"\"></figure>\n<p>对于学习我也是做到了认真踏实、勤学苦练，严格的要求自己学好各科专业知识做到课前认真预习，课中认真做好笔记，课后认真复习和整理笔记。同时不断提高自身动手能力，做到全面发展，在2019-2020年度中荣获院奖学金，雪松班奖学金，国家奖学金等奖励，并带领同学跨专业参加了贵州省智慧物流技能大赛取得二等奖好成绩。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img70.webp\" alt=\"\"></figure>\n<p>作为财政经济学生会主席，我积极服务同学、服务学校发展，在老师与学生之间起到桥梁纽带作用，热心帮助同学们解决困难，不管在学习方面还是工作方面，都表现良好。因此得到了老师和同学们得肯定。我在校园内并带领学生会成员，遵守学院和系的各项规章制度，以身作则，率先垂范，虚心听取各方面的意见和建议，勇于开拓创新。并在2019年10月荣获校三好学生，校优秀学生干部，贵州省优秀学干部等称号。当然过去的成绩只能证明过去，现在还是站在一个新的起点，学院学习和工作将是我一辈子受用的宝贵财富，在当今这个科技发展迅猛、竞争激烈的时代，我清楚的知道，自己的努力还远远不够，只有把自己打造成为新时代下标准的大学生，才能在今后竞争日趋激烈的社会中立于不败之地。为此，在以后的工作中我仍会以一名新时代青年高标准要求自己，一如既往的以高度的责任心投入到为社会服务中去。“读万卷书,不如行千里路”。只有将课本知识与实践只有将课本知识与实践结合才能真正锻炼自己,提升自己。合理安排好规划课程之余，结合自己所学专业知识帮助需要帮助的人。在2019年7月与院团委老师参加暑期三下乡社会实践活动过程中，才明白自己身为一名大学生身上的责任与担当，为社会，为国家，能贡献自己的一份力量是多么的自豪。</p>\n<p>二、毕业后简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img71.webp\" alt=\"二、毕业后简介\"><figcaption>二、毕业后简介</figcaption></figure>\n<p>毕业后曾在贵州顺丰速运有限公司就职，在就职的这半年里面，自己也从一个学生的身份转变成一个社会青年，但是始终没有忘记自己最初的信念，身为新时代的新青年，一定要树立崇高的理想信念，做一个有理想有担当有本领的青年，所以我于2020年6月报名应征入伍，完成自己儿时的梦想，很多人聊天曾问过我，为什么去当兵，而我的回答是因为我爱我的祖国，把我最宝贵的青春用去做最有意义的事情我觉得很值得，我知道军人意味着牺牲的奉献。当官发财，请走别路；贪生怕死，莫入此门。当听到南使馆被炸，我们怎么能不义愤填膺呢？当看到天安门阅兵时，我们怎能不激情澎湃呢？从军便成为必然的选择。运筹帷幄，决胜千里，携笔从戎，报效祖国，是机遇更是挑战，是荣耀更是责任，是权利更是义务。我相信这一定是我做过最好的决定。加油年轻人。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img72.webp\" alt=\"\"></figure>\n<p>（二）孙文英</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img73.webp\" alt=\"（二）孙文英\"><figcaption>（二）孙文英</figcaption></figure>\n<p>孙文英，共青团员，汉族，女，出生于1997年07月，在校期间担任辅导员助理及班长一职。毕业于毕节职业技术学院财政经济系2017级财务管理一班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img74.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>在思想方面，向党组织靠拢，不忘党训，积极向上，热爱祖国，热爱中国共产党，拥护中国共产党的领导，积极响应中国共产主义青年的号召，认真地学习“三个代表”、“科学发展观”等重要思想和理论，并以这些理论知识武装着自己。在2017年积极参加“青马工程”的培训，认真学习十九大精神、团队合作，从中锻炼了我的团队意识，及提高了我的管理能力，通过一个月的学习顺利结业，并在2018年5月荣获优秀“共青团员”的称号；让思想与实践相结合，在2019年与同学参加学院思政部举办的“大学生思政讲课”，比赛前我们进行选题取材，并进行分工配合，经过几轮比赛，我们团队在这次比赛中荣获“一等奖”，这次比赛让我学习到了团队的力量。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img75.webp\" alt=\"\"></figure>\n<p>对于入学前在幼教行业有过两年工作的我，选择继续学习，自考大专进入学校，使我不再有遗憾，在新生大会上代表新生发言，就是我大学生活的开始。学习上，我态度端正，勤奋、刻苦、好问，有较强的钻研精神思维较严密，具有一定的自学能力和综合分析、解决问题的能力，从入学以来我不旷课迟到早退。上课认真听讲，课后及时完成作业，做到认真预习、复习两个方面一起抓，学习成绩名列第一，荣获学院“三好学生”及连续两年荣获“国家励志奖学金”。</p>\n<p>在工作方面，在班级里担任辅导员助理及班长一职，有较高的组织协调能力。本着认真负责的态度积极完成各项工作，很好的起到沟通老师和同学的桥梁作用。是老师们给了我许多锻炼的机会，让我懂得如何做好班干部，如何为同学们服务，在日常的工作中同学们的积极配合让我在工作中得心应手，使得自己的个人综合素质全面提高。在这个过程中我不断地挑战自我，充实自我，为我的未来打下了坚实的基础。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img76.webp\" alt=\"\"></figure>\n<p>作为财务管理一班的班长，两年多以来，我工作认真负责，能替同学排忧解难。有较强的集体荣誉感，能努力完成集体交给的任务。为此，我被评为学院“优秀学生干部”。</p>\n<p>在系部里，认真对待系部分布的工作，2017年10月份策划“文明在身边”活动方案，2017年12月负责班级关于“十九大学习”的板报策划与布置。2017年10月参加财政经济系团体操比赛；2017年10月参加敬老院志愿服务；2017年12月参加“铸梦乌蒙 绽放青春”第三届艺术节合唱团比赛；2018年5月参加毕节职业技术学院第二届“寝室文化节”荣获“创意寝室奖”；2019年6月参加“互联网+创新创业项目计划书大赛”，在参与这些活动中锻炼自己，提高自己，全面的发展自己。</p>\n<p>二、毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img77.webp\" alt=\"二、毕业后的简介\"><figcaption>二、毕业后的简介</figcaption></figure>\n<p>时间飞逝，我的大学生活已经结束，踏入社会，有幸的进入到世界500强的雪松企业实习人事行政，实习是一个锻炼的平台，是展示自己能力的舞台。通过实习，我感悟到不少。“在大学里学的不是知识，而是一种叫做自学的能力”。实习时更深刻地体会了这句话的含义。在这个信息爆炸的时代，知识更新太快，靠原有的一点知识肯定是不行的。我们必须在工作中勤于动手，而且认真观察学习。任何工作任何岗位都应该认真细致，尤其是工作单位的人事部更需要有严谨的工作态度。</p>\n<p>这次实习告诉我，在社会这个大学堂里我还是一个小学生，还有很长的路要走。要抱着谦虚谨慎的态度，无论大小认真踏实的完成每一件事，走好每一步。参加实习的六个月时间里，我收获得不仅仅是工作经验，还有许多的朋友和更多宝贵的人生财富。</p>\n<p>实习结束后，我来到广州冠申事业有限公司工作，开始我毕业后的第一份工作，在公司当行政部的行政文员，虽然和我的专业有些不同，不过我相信，在坚持不懈的努力下，任何困难都会迎刃而解。</p>\n<p>大学三年，演绎了我人生的许多第一次，而大学的珍贵，并不仅仅是这许多的第一次，更重要的是涵盖着许多的最后一次：一生中最后一次有机会系统性地接受教育；最后一次可以拥有较高的可塑性、可以不断修正自我的成长历程；最后一次能在相对宽容、纯洁，可以置身其中学习为人处世之道的理想环境。</p>\n<p>所幸的是，我认真把握住了每一个“第一次”，让它们成为我未来人生道路的基石；我也珍惜每一个“最后一次”，没有让现在的自己追悔莫及。</p>\n<p>既有前程可奔赴，也有岁月可回首，感谢美丽的校园，给予了我飞翔的翅膀；感谢亲爱的老师和同学，给予了我展翅翱翔的信心和勇气。</p>\n<p>（三）吴丹</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img78.webp\" alt=\"（三）吴丹\"><figcaption>（三）吴丹</figcaption></figure>\n<p>吴丹，女，汉族，1995年12月生，共青团员，毕节职业技术学院财政经济系2017电子商务2班学生，在校期间曾担任财政经济系第十届团总支副书记、2017电子商务2班团支部书记。毕业于毕节职业技术学院2017级电子商务2班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img79.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>思想上，热爱祖国，拥护中国共产党的领导，积极向先进人物学习，树立勤奋学习报效祖国的远大志向，不断提升自己的思想觉悟，认真体会并践行社会主义核心价值观，努力提高自身思想觉悟，认真学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想和科学发展观，不断学习习近平总书记的重要讲话精神，认真贯彻落实学习十九大、十八大、十八届三中、四中、五中、六中全会精神，学习习近平总书记在高校思想政治工作会议上的讲话精神和团中央高校共青团改革实施方案、十七届六中全会精神和学院相关文件精神，坚决拥护中国共产党，积极靠近党组织，关心国家大事，让自己的思想紧紧跟上改革开放的步伐，时刻听从党的召唤，始终拥护党的纲领，认真学习党的文件，学习“三个代表”重要思想，以团员的标准严格要求自己，争取早日入党。</p>\n<p>学习上，在校期间就一直非常刻苦努力，因为我知道吃得苦中苦，方为人上人，在不断的努力下每科学习成绩都取得了不错的成绩，因此曾被评为省“三好学生”、省“优秀毕业生”、校“优秀学生干部”、校“三好学生”、也曾获得“国家奖学金、国家励志奖学金”等一些列奖项。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img80.webp\" alt=\"\"></figure>\n<p>工作上，2017年9月入校后担任17高职电商2班团支部书记一职，自接任团支部书记一职以来，我认真履行班干职责，配合辅导员及系部领导对班级的相关管理工作，并积极参与及积极鼓励班上同学参与系部、学院组织的各项活动；2017年10月加入系部学生会团总支，后于17年11月换届后担任系部团总之宣传部副部长一职，2018年财政经济系第十届团总支学生会换届后担任财政经济系第十届团总支副书记一职，按照院团委和系部团总支要求，及时开展各种主题团日活动，做好系部各班级团支部组织建设相关管理工作，履行好团总之副书记职责，积极配合团总支负责人及系部领导完成院团委安排的各项工作，积极参与系部各项学生活动，帮助老师整理资料等。学习知识技能的同时，积累工作本领、塑造创新思维，为以后的工作和生活打下坚实基础。</p>\n<p>二、毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img81.webp\" alt=\"二、毕业后的简介\"><figcaption>二、毕业后的简介</figcaption></figure>\n<p>转眼，已经离校半年多了，实习期间很幸运进入贵州顺丰速运有限公司营运部工作，来到了顺丰之后，我才真正明白顺丰做成快递行业的龙头老大不是没有道理的，从营运部、财务部、人力资源部再到客服部、综合部、公共事务部、工会，他都秉承着“成就客户、推动经济、发展民族速度业”的经营理念，帮助客户更快、更好地对市场作出反应：推出新的产品和调整策略，缩短贸易周期，降低经营成本，促进客户竞争力的提高。同时，顺丰不仅为国家发展贡献了税收，也解决了社会就业压力，和各大高校促成了校企合作模式，有效解决高校毕业生就业难的问题，为国民经济的持续健康发展做出了很大的贡献。</p>\n<p>为了我未完成的大学梦，2020年8月我选择离开顺丰，为专升本做着最后的冲刺。从2019年12月18日进入贵州顺丰有限责任公司到2020年8月10日离职，我深深感受到顺丰这个大家庭给予我的不仅是一份工作，一份薪资，还是一段不一样的人生旅途，上到领导，下到一线小哥，每个人都在尽职尽责的做着自己的工作，没有抱怨，没有消极的状态，有的只是心里的那一股拼劲。如今如果不出意外的话，我会顺利进入本科院校继续我未完成的梦。</p>\n<p>祝愿正在为梦想努力拼搏的你能够梦想成真，因为机会是留给有准备的人的！</p>\n<p>（四）杨小拱</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img82.webp\" alt=\"（四）杨小拱\"><figcaption>（四）杨小拱</figcaption></figure>\n<p>杨小拱，群众，布依族，男，出生于1998年5月，在校担任口才与交流协会常务副会长一职，毕业于毕节职业技术学院财政经济系2017级电子商务专业，</p>\n<p>毕业前简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img83.webp\" alt=\"毕业前简介\"><figcaption>毕业前简介</figcaption></figure>\n<p>学习方面，在学习方面我较较为平凡，给所有任课老师的印象并不是好学的学生，但是我给社团指导老师的印象却一个好干部，我热爱社团给我带来的气氛，我不断去策划和组织各种活动，不断的去学习去锻炼自己，在我的想法中学习并不是只有课本上的学习综合实践上的学习同样重要，</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img84.webp\" alt=\"\"></figure>\n<p>在工作方面，我尽职尽责是指导老师和同学们眼中的好干部，很多时候因为协会工作可以忙到六亲不认，也是老师跟同学眼中的工作逛，我认真努力的组织策划好协会的每一场活动，每一次组织活动都会让我成长让我进步，每一次活动都带领大家克服困难去保证活动的顺利完成。</p>\n<p>在组织活动过程中让我受益匪浅，这也让我在进入社会以后能够快速的成长适应社会打下了基础，也许我不是所有毕业生当中最优秀的，但是我也不是最差的，我始终相信只要自己努力再差的人也会变的优秀，相信相信的力量明天一定会更好。</p>\n<p>毕业后简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img85.webp\" alt=\"毕业后简介\"><figcaption>毕业后简介</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img86.webp\" alt=\"毕业后简介\"><figcaption>毕业后简介</figcaption></figure>\n<p>转眼自己已经毕业了，已经不再是一个学生的身份，在离开学校的时间。经历了很多也让自己成长了很多，从一个小小什么都不懂的小白到现在的自己成立团队创业，在这过程中经历心酸和汗水，我们这一届的毕业生是极为的尴尬，因学历太低就业困难，能够找到的工作要么是销售要么就进厂，找到合适的工作了工资又太低根本无法养活自己，老板各种的压榨员工，最终我选择了自己创业，2020年3月我从公司辞职，在辞职后的一个月我在贵阳自己租的房子里准备创业的各种材料，那时候的我不断的去联系身边的人找投资希望能够有人能够投资我的项目，但是总是被无情的拒绝，我并没有因此放弃，我带着行李来到毕节找到跟我关系要好的小伙伴，我跟他说完我的项目以后表示愿意加入跟我一起，2020年6月我们正式成立了毕节市兴创电子商务有限公司，公司成立后我们团队加入的新伙伴越来越多，从最初的两个人发展现在的八个人，团队的发展壮大让我看到了希望，当然压力也是越来越大，每一个加入的新成员我们都会一对一的去指导去带领他去学习，对于我来说我们团队的每一个人都不是为谁打工我也不会拿任何人当员工，在我这他们都是我都合伙人，我们每天不断的努力工作，努力学习，不断去提升自己，只有会学习的团队才是能够发展壮大的团队。</p>\n<p>（五）冯绍泉</p>\n<p>冯绍泉，男，共青团员，白族，1998年10月出生于贵州省盘县。2016年就读于毕节职业技术学院财政经济系电子商务班。在学院就读以来先后担任了院团委联合秘书处常务副秘书长、财政经济系第九届学生会主席。</p>\n<p>一、思想积极要求上进，不断提高政治素养</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img87.webp\" alt=\"一、思想积极要求上进，不断提高政治素养\"><figcaption>一、思想积极要求上进，不断提高政治素养</figcaption></figure>\n<p>本人平时认真学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想和社会主义核心价值观来不断提高自身的政治修养，争做新时代下的新青年，因而练就了较高的政治觉悟。在2017年5月经系部精心组织推荐，参加了院团委组织的“青年马克思主义者培养工程”班学习，在为期1个多月的培训中，我认真学习理论知识，不断用思想政治理论知识来武装自己，并积极参加培训班各项社会实践活动，在毕节市敬老院关爱空巢老人、幼儿园关爱留守儿童，以及在学校田径场参加素质拓展活动我都认真对待，充分体现了新时代下大学生应该具有的尊老爱幼和团结同学的责任与义务，最终获得“青年马克思主义者培养工程”班的结业证书。同时积极的向党组织靠拢，并向党组织递交了入党申请书，时刻以党员的标准来严格的要求自己。</p>\n<p>二、新时代青年要有新作为</p>\n<p>作为本班班长，积极的为同学服务，配合好老师开展各项工作，在老师与学生之间起到纽带的作用，热心帮助同学们解决困难，不管在学习方面还是工作方面，都表现良好。因此得到了老师和同学们得肯定。</p>\n<p>在我不懈努力下，德、智、体、美等综合素质整体提高，擅长演讲朗诵的我在2016年度全省大学生“中华民族一家亲，同心共筑中国梦”暨“五个认同”主题教育征文演讲比赛荣获优秀奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img88.webp\" alt=\"\"></figure>\n<p>2017年8月我加入网络团支部并负责播送栏目，在此过程中我累积了足够的工作经验，并在院团委老师的悉心指导下，我对新媒体的制作和运营技术得到了充分的提高，2017年9月我被推荐到新媒体制作运营团队参加了全省“大学生‘三下乡’社会实践活动新媒体创意展示大赛”，经过一个月的努力，分别获得了大赛运营策划组“二等奖”、运营实践组“三等奖”的佳绩。其中我们团队为七星关区海子街量身设计的微信公众平台，现已投入当地党政的使用，并为当地乡村旅游的发展进一步扩大了外宣影响力，获当地政府的一致好评。</p>\n<p>在校园内并带领学生会成员，模范遵守学院和系的各项规章制度，以身作则，率先垂范。虚心听取各方面的意见和建议，勇于开拓创新，全心全意为全校师生服务。所有的付出都是有收获的，2017年荣获了贵州省“优秀学生干部”称号；2018年荣获贵州省“三好学生”称号；2019年荣获贵州“优秀毕业生”称号。</p>\n<p>三、不断攀登 挑战自我</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img89.webp\" alt=\"三、不断攀登 挑战自我\"><figcaption>三、不断攀登 挑战自我</figcaption></figure>\n<p>2018年市场营销技能大赛以贵州省第一名的成绩出线，随后代表贵州省参加了全国职业技能大赛市场营销组的比赛，并获全国第三的好成绩，这样也为自己争取到了一个保送本科的名额，并被凯里学院录取，成为凯里学院大数据工程学院的学子。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img90.webp\" alt=\"\"></figure>\n<p>以往的成绩只能证明过去，现在还是站在一个新的起点，学院学习和工作将是我一辈子受用的宝贵财富，在当今这个科技发展迅猛、竞争激烈的时代，我清楚的知道，自己的努力还远远不够，只有把自己打造成为新时代下标准的大学生，才能在今后竞争日趋激烈的社会中立于不败之地。为此，我仍以团员的标准严格要求自己，一如既往的以高度的责任心投入到学习和为班级服务之中。</p>\n<p>（六）郝玲燕</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img91.webp\" alt=\"（六）郝玲燕\"><figcaption>（六）郝玲燕</figcaption></figure>\n<p>郝玲燕，共青团员，汉族，女，出生于1999年06月，毕业于毕节职业技术学院财政经济系2017级电子商务1班。</p>\n<p>思想方面：我是一名共青团员，首先，端正思想，提高思想觉悟水平，树立起作为共青团员就应起到带头和模范作用；其次，用心参与学校组织的各项团员活动，在活动中学习理论，在活动中实践理论，这样做到学以致用，按时缴纳团费，不拖后腿，争取为团的事业贡献自我的微薄之力；此外，努力提高自身思想素质，弘扬社会主义道德风尚，严于律己，扬善抑恶、求实创造、与时俱进，将优秀的中华民族传统美德发扬光大。认真学习《团的章程》，自觉履行团员的义务，执行团的决议，遵守党的纪律，完成团组织交给的任务，发挥团员的模范作用也是一个团员应尽的职责。热爱祖国，拥护中国共产党的领导，积极向先进人物学习，树立勤奋学习报效祖国的远大志向，不断提升自己的思想觉悟。有机会就参与学习马列主义，认真学习毛泽东思想、邓小平理论、“三个代表”重要思想和科学发展观，不断学习习近平总书记的重要讲话精神，认真贯彻落实学习十八大、十八届三中、四中、五中、六中全会精神，学习习近平总书记在高校思想政治工作会议上的讲话精神和团中央高校共青团改革实施方案、十七届六中全会精神和学院相关文件精神，以团员的标准严格要求自己，争取早日入党。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img92.webp\" alt=\"\"></figure>\n<p>学习方面，在校期间，我刻苦努力的学习，孔明曾说：“非学无以广才，非志无以成学”我通过自己的努力，在老师的帮助下每个学年都获得优异的成绩，在刚刚进入大学的时候，有一段时间是迷茫的，不清楚自己的目标是什么，不清楚自己到底该做些什么。调整状态过来之后，就一直非常刻苦努力，每门学科学习成绩都争取班级和年级前列，抓紧各种学习时间和机会，弥补高中自己的不足，我深知以前的时间都用来读书，自己很多社会知识，与人交流，并不是很出色，所以，来到这里在，就要学会取长补短，利用自己优势，做一个合格的，先进的，有用的学生，参加各种社团，给自己最大信心，用自己的行动来证明。我知道“融入社会，加强实践，锻炼自我”是青年志愿者的宗旨，“服务群众，服务社会”是青年志愿者的任务。我尽自己最大的努力坚持与追求着自己的每一个目标，并立志于达到期望中的成功。而我虽然不是一个青年志愿者，但我却有着这样的心，想要更加努力实现。赠人玫瑰，手有余香，是一种高尚的品德。在校期间获得国家励志奖学金，学院二等奖学金，学院优秀毕业生，省级优秀毕业生等一系列的奖项。</p>\n<p>转眼，实习已经结束了，在这期间经历了很多以前不曾有过的体验，有汗水，有付出，有辛酸也有泪水；在学习中成长，在各种人才竞争中脱颖而出，我坚信越努力越幸运。</p>\n<p>毕业之后选择了大学生西部计划志愿者的活动，分配在盘州市两河街道办事处。刚刚来到服务地点感受到了在工作中的前辈的热心辅导，并对我们的生活住宿，吃饭问题安排很细心。还有来自上一届学姐学长们的关心与帮助，这让我在新的环境里充满信心，努力工作。一是实现了我想体验体验志愿者的生活，二是在服务期的这两年里，不放弃学习，提升自己的能力不论是学历还是综合素质水平。所以我坚信未来的生活是充满希望，并丰富多彩的。</p>\n<p>（七）张丽媛</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img93.webp\" alt=\"（七）张丽媛\"><figcaption>（七）张丽媛</figcaption></figure>\n<p>张丽媛，共青团员，汉族，女，出生于1998年05月，在校期间担任资助委员一职，在系部担任团支部组织部成员，市场营销协会副会长。毕业于毕节职业技术学院财政经济系2017级财务管理班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img94.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>思想方面，热爱祖国，拥护中国共产党的领导，积极参加党团组织的各项活动，并在同学中不断的宣传，让大家也积极的参与其中。并要求自己进步，树立良好的人生观和道德观。保持与时俱进，认真学习党的工作路线，正确贯彻党的方针政策，积极参加有关活动，作为学习和班级精神力量的积极分子。向团组织组织靠拢。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img95.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img96.webp\" alt=\"\"></figure>\n<p>学习方面，在校期间，我学习刻苦努力，我知道只有不断的努力才能走得更远，才能看到更加美丽的风景。从进校的第一天开始，老师在入学典礼中送给我们新生三句话，这三句话也成为人生中不断努力何前进的动力。他说：只有更努力才能去更遥远的地方，只有更努力才能看到更美丽的风景，只有更努力，才能成为优秀的人。那时候，我甚至不知道这段话的意思是什么，年幼迷茫的我，一直对自己没有信心，心里总是非常的自卑，也不知道自己到底要干嘛，一次偶然的机会，让我加入了市场营销，在这让我改变了很多，而且也使我重新振作起来，找到自己的闪光点。我通过自己的努力，在老师和同学的帮助和指导下，代表学校出去比赛，并且在第一年的比赛中就获得了省第一名的好成绩，就这第一名让我们成功的拿到了免试升本的“门票”，当然，这使我更加的对自己有信心，在校期间多次代表省代表学校出去学习和比赛，我坚信世上无难事，只要肯登攀。所以我也会谦虚的帮助那些在学习中有困难的同学一起进步，在他们身上我能学到很多我自己不会也不能做好的事情。做到相互的取长补短。在校期间获得国家励志奖学金，三好学生，学院奖学金等一系列的奖项。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img97.webp\" alt=\"\"></figure>\n<p>工作方面，在担任班级资助委员期间，我认真的配合老师完成班级的各项工作，尽自己最大的能力帮助同学们完成生活和学习中的困难。在市场营销，带领大家完成协会的各项大大小小的活动，在每一次的活动中，我们的会付出很大的心思去做好各项准备工作，做好协会培训工作，在这过程中，我也学到了很多的东西，这使我在生活中受益匪浅。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img98.webp\" alt=\"\"></figure>\n<p>二、毕业后的简介</p>\n<p>转眼，已经毕业半年了，在这期间，经历了很多的东西，从找工作，到进入职场，然后在职场中稳定下来，这过程中，经历了很多的心酸和汗水。毕业之后，面对就业的困难，面对学历的打击，面对太多优秀人才在就业过程中的各种洗礼，面对上一级领导对工作的苛刻，最终，我还是觉得自己懂得不太多，选择了升学，幸运的是，我不像其他升本的同学一样，去准备升学考试，只需与他们同时提交资料审核就可以了。当然这给我留出了大把的时间和精力，在即将开学的最后一个月的时间里，我选择辞职，我记得在校的时候辅导员对我说过一句话，我应该多去外面走走，所以开启我的旅游行程，到自己想去的城市，看不同的风景，了解不同的风土人情。</p>\n<p>作为可以免试升本的幸运儿，成功提交了贵州工程应用技术学院的财务管理专业。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img99.webp\" alt=\"作为可以免试升本的幸运儿，成功提交了贵州工程应用技术学院的财务管理专业。\"><figcaption>作为可以免试升本的幸运儿，成功提交了贵州工程应用技术学院的财务管理专业。</figcaption></figure>\n<p>对新的学校充满了期待，也做好了一切规划，对自己的要求更加的严格。在新的校区身边也会多更多优秀的人，即使内心压力再大。但是，唯有这样才能努力使一个人继续向前走。在新的学校里，我应该会很快就融入到了新的环境中去，在学习中，我会不断的向优秀的同学看齐，学习更多的知识，只有压力才能使一个人变的更加优秀。新的学校有新的要求，我会严格遵循新校区的规章制度。怀着对新学校的期望等待开学。</p>\n<p>（八）马召</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img100.webp\" alt=\"（八）马召\"><figcaption>（八）马召</figcaption></figure>\n<p>马召，共青团员，回族，男，出生于1996年08月，在校期间担任班上组织委员一职，在系部担任学生会副主席。毕业于毕节职业技术学院财政经济系2017级会计班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img101.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>学习方面，在校期间，我学习刻苦努力，我知道只有不断的努力才能走得更远，才能看到更加美丽的风景。从进校的第一天开始，老师在入学典礼中送给我们新生三句话，这三句话也成为人生中不断努力何前进的动力。他说：只有更努力才能去更遥远的地方，只有更努力才能看到更美丽的风景，只有更努力，才能成为优秀的人。那时候，我甚至不知道这段话的意思是什么，年幼迷茫的我，一直对自己没有信心，心里总是非常的自卑。来到这个学校不仅改变了我的很多观点，而且也使我重新振作起来，找到自己的闪光点。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img102.webp\" alt=\"\"></figure>\n<p>我通过自己的努力，在老师的帮助和指导下。每学年获得班级名列前茅的好成绩，当然，这使我更加对自己有信心。我坚信世上无难事，只要肯登攀。所以我也会谦虚的帮助那些在学习中有困难的同学一起进步，在他们身上我能学到很多我自己不会也不能做好的事情。做到相互取长补短。在校期间获得国家励志奖学金，省关务技能大赛团体三等奖，省级三好学生，省级优秀毕业生，学院优秀毕业生、优秀学生干部、三等奖学金、系优秀学生干部、优秀志愿者等一系列奖项。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img103.webp\" alt=\"\"></figure>\n<p>工作方面，担任班级组织委员期间，我认真的配合老师完成班级的各项工作，尽自己最大的能力帮助同学们完成生活和学习中的困难。在学生会，带领大家完成系部各项大大小小的活动，在每一次活动中，我们都会付出很大的心思去做好各项准备工作，在活动开展过程中，我也学到了很多东西，这使我在生活中受益匪浅。</p>\n<p>二、毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img104.webp\" alt=\"二、毕业后的简介\"><figcaption>二、毕业后的简介</figcaption></figure>\n<p>转眼，已经毕业几个月的时间，在这期间，经历了很多的东西，从工作到辞职，从备考到面试成功等，这过程中，经历了很多心酸和汗水。我成功的考上了西部计划，到基层，到祖国和人民需要我的地方去，以身作则，严于律己，为祖国和人民贡献自己的绵薄之力。</p>\n<p>在西部计划服役期间，我被相关领导分配在党政办公室汇总相关资料，我不怕艰苦、不怕困难，积极配合领导开展各项工作，定期和相关领导下村走访，了解村民生活情况，住房情况等。</p>\n<p>（九）张玲玲</p>\n<p>张玲玲，共青团员，土家族，女，出生于1997年04月，在校期间担任班长一职，在系部担任学生会副主席。毕业于毕节职业技术学院财政经济系2017级电子商务班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img105.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>热爱祖国，拥护中国共产党的领导，积极向先进人物学习，树立勤奋学习报效祖国的远大志向，不断提升自己的思想觉悟。2018年4月份，在系部老师的推选下，参加团委第七期青马工程培训。培训期间一直按时到达指定培训地点，认真完成每一次培训，在培训过程中团结互助同学积极的参与培训中开展的活动。已顺利结业。学习方面，自2017年9月入校以来，就一直非常刻苦努力，每科学习成绩都争取班级和年级前列，抓紧各种学习的时间和机会。学习成绩优秀，其在班级和系部的学习带头之用明显，得到系部领导和老师的表扬。当然，这使我更加的对自己有信息。我坚信世上无难事，只要肯登攀。在校期间获得国家励志奖学金，省级三好学生，省级优秀学生干部，省级优秀毕业生一系列的奖项。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img106.webp\" alt=\"\"></figure>\n<p>工作方面，在担任班级团支部副书记期间，我认真的配合老师做好班级团支部组织建设，尽自己最大的能力帮助同学们完成生活和学习中的困难。在担任学生会副主席，积极配合团总支书记完成学生处、团委、保卫处等部门的工作，组织系部各项学生活动。学习知识技能的同时，积累工作本领、塑造创新思维，为以后的工作和生活打下坚实基础。</p>\n<p>二、毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img107.webp\" alt=\"二、毕业后的简介\"><figcaption>二、毕业后的简介</figcaption></figure>\n<p>在为期半年的实习中，我明白了要扬长避短，不断完善自己。要正确的认识自己，在工作中不但要发扬自己的优点，还要客观地面对自己的不足之处要扬长避短，不断完善自己。要正确的认识自己，在工作中不但要发扬自己的优点，还要客观地面对自己的不足之处！人力资源管理工作事无巨细，事事重要，事事都是责任。随时提醒自己“对明天最好的准备就是今天做到最好”！总之，在不断提高自己综合能力和组织的同时，在以后的学习和生活中将会不断总结经验，锻炼更强的能力，加倍努力，以更好的状态感恩和回馈社会。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img108.webp\" alt=\"\"></figure>\n<p>（十）刘娇</p>\n<p>刘娇，共青团员，汉族，女，出生于1998年12月，在校期间担任班级团支部书记一职，在系部担任团总支组织部一员。毕业于毕节职业技术学院财政经济系2017级高职会计（一）班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img109.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>在思想方面，我作为一名共青团员，有着先进的思想觉悟，时刻以一名优秀的共青团员身份严格要求自己，发扬先锋模范作用；深入贯彻和落实团的各项方针政策，服从团的领导，执行团支部的决议，遵守纪律、履行义务。完成各项任务，牢固树立为人民服务，为广大同学服务的坚定理想。在活动中学习理论，在活动中实践理论。此外，认真遵守学院各项规章制度，努力提高自身思想素质，严于律己、扬善抑恶、求实创造、与时俱进。 在学习方面，始终坚持一句格言“天行健，君子以自强不息”。进入大学以来学习一直从未松懈，勇攀知识高峰，有科学的生涯规划，有明确的学习目标，认真学习专业知识，具备了较强的专业知识水平。与其他同学互帮互助，取长补短，达到共同进步的目的。上课时认真听讲、做好笔记，积极思考并回答老师提出的问题，课后及时完成作业，做到认真复习。每学期期末，各学科都取得了优异的成绩。此外，大学期间还注重提升自己的课外学术探究能力，积极参加学校组织各项活动，培养自己的社会实践能力，为将来步入社会打下良好的基础。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img110.webp\" alt=\"\"></figure>\n<p>在工作方面，担任班级团支部书记期间，我认真的配合老师完成班级的各项工作，尽自己最大的能力帮助同学们完成生活和学习中的困难。同时，作为团总支组织部的一员，服从组织安排，参与部门日常值班、团籍管理、学院迎新生等工作，不断锻炼与学习，增强了自身各个方面的综合潜力，在工作中学到了许多在书本和课堂上学不到的东西；促使我养成了坦诚，守时守约守信用，做事讲原则，敢于承担职责的良好习惯，无论是为人处事还是交流谈吐，都得到了很大提升。在工作期间，我始终以“奉献学院，服务同学，锻炼自我”为宗旨，真正做到为同学服务，尽心尽力，用心奉献。</p>\n<p>在生活方面，我团结同学，热爱集体，保持优良正派的生活作风，发扬艰苦朴素的精神。有着积极乐观的生活态度。与室友，同班同学以及其他专业的同学打成一片。作为一名当代大学生，始终牢记时代精神，历史使命。紧跟时代步伐，不断扩充知识储备，以提高自身修养。努力学习、认真工作、团结同学、互帮互助。</p>\n<p>二、毕业后的简介</p>\n<p>转眼，已经毕业到了毕业踏入社会的时间，在这之前，我有幸</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img111.webp\" alt=\"转眼，已经毕业到了毕业踏入社会的时间，在这之前，我有幸\"><figcaption>转眼，已经毕业到了毕业踏入社会的时间，在这之前，我有幸</figcaption></figure>\n<p>到雪松控股集团进行为期6个月的实习，在这里成长，经历了很多的东西，从初出社会到上手工作，这过程中，经历了很多的心酸和汗水，最终实习结束时顺利转正留下来继续工作。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img112.webp\" alt=\"\"></figure>\n<p>为此，我要特地感谢公司的领导和同事，给了我学习和成长的机会，同时，还有对我的入职指引和帮忙，感谢大家对我工作中出现的失误给予提醒和指正，我感到无比荣幸。在今后的工作中，我会进一步严格要求自我，虚心学习，努力提高自我的综合素质，争取在各方面取得更大的进步。还有在这里融洽而和睦的相处关系让我更深刻的意识到，一个完美优秀的团队要靠大家每个人去努力。</p>\n<p>我很喜欢这份工作，六个月的实习时间我学到了很多，感悟了很多。自己在这样的工作环境中从懵懵懂懂到顺心顺利，我深深地感到骄傲和自豪，也更加迫切的希望以一名正式员工的身份在这里稳定的工作，实现自己的奋斗目标，体现自己的人生价值。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img113.webp\" alt=\"\"></figure>\n<p>（十一）彭琴琴</p>\n<p>彭琴琴，共青团员，汉族，女，出生于1998年09月，在校期间担任班长兼辅导员助理，在系部曾担任网络信息部副部长。毕业于毕节职业技术学院财政经济系2017级高职会计2班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img114.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>思想方面：我具有坚定地政治信念,坚决拥护中国共产党的纲领,认真学习马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想,学习文化知识之余,关心时事政治,努力提升个人修养,我更加明确了自我肩负的历史重任，坚定了此刻认真为老师同学服务，将来投身社会主义事业，全心全意为人民服务的信念和理想。</p>\n<p>学习方面：我不忘自己的初心，学好知识，学会做人；在学校的指导、老师的教诲、同学的帮助下，通过不断地学习理论知识和参与社会实践，自己的综合素质在很大程度上得到了提升，努力将自己塑造成为一个专业功底扎实、知识结构完善、适应能力强、具有团体协作精神的青年。我始终坚信“宝剑锋从磨砺出,梅花香自苦寒来”，一丝不苟、认真务实，在校期间获得国家奖学金、院级三好学生、院级优秀学生干部、院级奖学金、先进个人称号的奖项。相信以后的道路我能够更加的顺畅，对于未来的生活会充满更多的信心；</p>\n<p>工作方面：做到一丝不苟，认真踏实，一直都是以“今日事，今日毕”的原则去做每一件事，作为班干，在班级和学习之间难免会引起一些矛盾冲突，我能很好的解决这些问题，做到学习、班级工作两不误。如今,我更加明确自己的目标,也一直在为自己的目标付出行动和努力。</p>\n<p>生活方面：我的性格开朗、朴素节俭、品德端正。俗话说:“读万卷书,不如行千里路”。</p>\n<p>二、毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img115.webp\" alt=\"二、毕业后的简介\"><figcaption>二、毕业后的简介</figcaption></figure>\n<p>离开学校的生活似弹指一挥间，从刚踏出学校大门时的失落与迷茫，到现在走上工作岗位的从容，坦然。我知道，这又是我人生中的一大挑战，角色的转换。实习生活，给我仅是初步的经验积累，对于迈向社会是远远不够的，但我一直在坚持“吃的苦中苦，方为人上人”，我要恪守吃苦精神。因此，在今后，我会继续努力拼搏，抓住每一个机遇，迎接每一个挑战，相信自己一定会演绎出精彩的一幕。</p>\n<p>来到雪松控股集团湖南区域工作，我对自己的要求更加的严格，雪松控股集团前身创立于1997年，是一家覆盖大宗商品供应链、化工新材料、文化旅游康养、社区智联服务和社会公益服务五大产业板块的民营企业；2018年，以2210亿元营收上榜《财富》世界500强。经过自己的努力，我也成为了唯一留在湖南总部的实习生，并且在总部运营管理部任职。在公司里多了更多优秀的人，即使内心压力再大，也要努力才能使一个人继续向前走，严格要求自己，自律者出众，懒散者出局。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img116.webp\" alt=\"\"></figure>\n<p>王杰</p>\n<p>王杰，共青团员，汉族，女，出生于1993年04月，2016年09月就读于毕节职业技术学院财政经济系财务管理专业，2019年07月毕业于毕节职业技术学院财政经济系财务管理专业。</p>\n<p>在校期间简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img117.webp\" alt=\"在校期间简介\"><figcaption>在校期间简介</figcaption></figure>\n<p>思想方面，热爱祖国，热爱母校，热爱班集体，尊敬老师，团结同学；树立正确的人生观、价值观。积极拥护参加团组织的各项活动，积极向团组织靠拢，努力成为一名团组织培养关心下的合格青年，做好各项本职工作，团结友爱，热心乐于助人，积极加入学校的志愿者协会、会计协会、读书协会，为学院开展校运动会等大型活动提供力所能及的服务。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img118.webp\" alt=\"\"></figure>\n<p>学习方面，勤奋好学，踏实认真，不负韶华，珍惜人生青年时期的美好校园生活，始终牢记勤能补拙的良训。丝毫不敢放松、怠慢学永无止境的步伐，课堂上认真听取专业知识，利用课外之余阅读有益于自己未来成长的相关书籍，并通过努力取得非专业的教师资格证等相关证书。</p>\n<p>毕业后简介</p>\n<p>西部的女儿，还梦西部：2019年7月，作为刚刚迈出大学校门还在为找工作迷茫奔波的我，看到母校学校团委发出招聘大学生西部计划志愿者的好消息，我毅然地选择报名参加了同年的大学生西部计划志愿服务的大部队。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img119.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img120.webp\" alt=\"\"></figure>\n<p>伴随时代强音为积极响应祖国的号召：“到西部去、到基层去、到祖国和人民最需要的地方去！”为践行当代大学生“到基层去、到西部去、到祖国和人民最需要的地点去”的庄严承诺。2019年8月，我带着这个光荣且庄严的承诺成为了一名大学生西部计划志愿者。踏上西行的列车，带着几分好奇新鲜感来到了现今服务的关寨镇人民政府。并担任关寨镇志愿者小队长一职，服务期间我很感激项目办各级领导、镇领导镇、同事们给予我的关怀。我不善言辞，没有华丽的语言去表达这份感恩，却能用实际行动去回报这份恩情。在这里我们同基层人员过着相对艰苦的生活，这里没有城市的浮华喧嚣，没有城市的繁华大道，更没有城市彻夜不眠的夜景，也没有我们之前想象的那样糟糕。有一种生活叫做没有经历过就不知道其中的艰辛；有一种艰辛叫做没有体会过就不知道其中的滋味。所以说踏上西部计划志愿服务这条路所经历的一切，是我毕业后收获的第一笔人生财富，这笔财富的价值足以让我终身受益。虽然我不是特别的优秀与出众，但是我愿意把我有限的青春默默地献给基层、献给西部、献给祖国和人民最需要的地方，只要青春在，只要祖国和人民需要，这句话就永远不会过期。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img121.webp\" alt=\"\"></figure>\n<p>选择无悔，倾心服务：平凡的我工作在平凡的岗位上，平凡的岗位上，我仍在不断地努力争取把每一件事都做到最好。我从未忘记过自己是一名志愿者的身份，认真践行“奉献、友爱、互助、进步”的志愿服务精神。好像这种身份与生俱来就肩负着一种神圣的责任--那就是这辈子都有学不完东西。自踏入关寨以来，我们志愿者充分发挥党联系青年的桥梁和纽带作用，积极协助政府管理青年事务，在维护国家和人民利益的同时代表和维护青年的具体利益，围绕党的中心任务，开展适合青年特点的独立活动。主要有青年夜校、易扶搬迁点的四点半课堂、新市民.追梦桥。工作成果深受领导同事们的一致认可。党旗所指就是团旗所向，党有号召，团有行动。2019年10月19日曾被推荐为关寨镇团干部代表前去市委党校培训“青马工程”。学习致力培养中国特色社会主义事业合格建设中和可靠接班人，用党的理论和路线方针政策，用社会主义核心价值观来引领青年思想，帮助青年坚定信念，坚定传承红色基因和中华优秀传统文化，成长为担当名族复兴大任的时代新人。团干部要深入基层、深入实际、深入青年、到脱贫攻坚第一线，最前沿，了解青年所想所思，了解青年的困难需求。坚持党建带团建、团建促党建的工作思路。2019-2020年度被省项目办授予“优秀志愿者”称号。</p>\n<p>青春由磨砺而出彩，人生因奋斗而升华：习主席说过：“人的一生只有一次青春。现在，青春是用来的奋斗的；将来青春是用来回忆的。”青春是一本仓促的书，等待着我们去书写属于自己的精彩，我们含着泪，一读再读。新时代是奋斗者的时代，它将激荡着每一个梦想。奋斗更是艰巨的，有志者奋斗无悔，今天的奋斗铸就明天的路基，需要我义无反顾地往前走。在接下来的时光里，我会加倍珍惜在这里服务的每一天。不忘初心，端正心态，在自我加压中实现人生价值。以一颗真诚的心、满腔的热情，为他人服务，雷锋精神一向都激励着我们向目标前进，不负这个伟大的时代赋予我们的青春使命，再接再厉用心站好每一班岗，吃苦在先，享受在后，以实际行动去诠释青春的足迹。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img122.webp\" alt=\"\"></figure>\n<p>（十三）刘欢</p>\n<p>刘欢：女，汉族，出生于1997年05月，是一名中国共产主义青年团团员，在校期间担任本班班长及班级团支部书记。2019年07月毕业于毕节职业技术学院16级财务管理(2)班，</p>\n<p>坚决拥护中国共产党的领导， 坚持党的教育方针，严格要求自己，努力提高自己，解剖自己，分析自己，正视自己，认真学习新的教育理论，及时更新教育理念。</p>\n<p>毕业前在校简介：</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img123.webp\" alt=\"毕业前在校简介：\"><figcaption>毕业前在校简介：</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img124.webp\" alt=\"毕业前在校简介：\"><figcaption>毕业前在校简介：</figcaption></figure>\n<p>严格遵守学校的各种规章制度，不迟到、不早退、在平时对于老师所安排的事物中，能够团结同学，互相帮助，能正确处理与同学、老师之间的关系，真诚待人，积极参加党团组织的各项活动并鼓舞其他同学一同积极的参与每一项活动，锻炼自己，提升自己的技能。</p>\n<p>在学习方面：在校期间，努力奋斗，积极上进，对于老师所讲的课程牢记在心，虚心向他人学习，不管是在学习方面还是为人处事方面。大学期间的我很迷茫，对未来充满了许多的问号，但是我始终相信，唯有努力才会改变生活，唯有努力奋斗才是现在我们应该做的，态度决定一切！慢慢地，在这个学校我似乎找到了一点自信，找到了自己身上的亮点。在老师的指导帮助下，我获得过系部优秀学生干部、优秀团员、国家助学金，参加竞答赛获奖等荣誉证书。</p>\n<p>在工作方面：在担任本班班长及班级团支部书记期间，认真配合辅导员以及团委所安排的工作，帮助辅导员管理好班级的事物。带领大家完成各种各样的活动，在每一次管理以及活动中，我都会学到不一样的东西。使我的生活多姿多彩，也为我以后踏出社会多一份经验。非常感谢我的辅导员以及其他的老师，谢谢你们在我大学期间对我的鼓励、对我的教诲、对我的帮助。</p>\n<p>毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img125.webp\" alt=\"毕业后的简介\"><figcaption>毕业后的简介</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img126.webp\" alt=\"毕业后的简介\"><figcaption>毕业后的简介</figcaption></figure>\n<p>毕业后的我们，经历了很多的事物，在毕业的这一年里，从实习到考试再到工作，这过程中，有许多的无奈和心酸，毕业后到两个月，我面对着就业的压力，不知下一步该怎么办，我不知道自己该做什么。再经过两个月的浑浑噩噩的时光里，我对自己的人生方向似乎有了一点想法。我想工作，于是我到了金海湖社会事务管理局开始了我上班的旅程。</p>\n<p>我到了一个新的工作环境，有一点压抑，因为身边的人都非常优秀，所以我对自己的要求变得更严厉了，同时也给自己造成了很大的负担，但是，我觉得一个人只要有了方向又有了压力的时候才会有动力去朝着那个方向前行，我身边这些优秀而可爱的人就是我的压力，我要向他们学习，努力跟上他们的步伐，使自己和他们一样。</p>\n<p>（十四）杨龙萍</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img127.webp\" alt=\"（十四）杨龙萍\"><figcaption>（十四）杨龙萍</figcaption></figure>\n<p>杨龙萍，共青团员（入党积极分子），汉族，女，出生于2000年10月，在校期间担任班级团副书记一职，在系部担任学生会学习部部长。毕业于毕节职业技术学院财政经济系2015级五年制会计班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img128.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img129.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>思想上，努力提高自身素质，热心服务同学增强组织的创造力、凝聚力、战斗力。在思想道德上，认真学习各种理论知识如“马克思主义哲学”“毛泽东思想”“邓小平理论”和“三个代表”的重要思想，并将八荣八耻定为自己的行为标准，认真学习贯彻胡锦涛总书记提出的“八荣八耻”重要论述，把社会主义荣辱观教育与学习党章结合起来，引导广大的团员同学自觉对照“八荣八耻”要求，自觉树立社会主义荣辱观，持续增强学习贯彻社会主义荣辱观的自觉性和职责感、紧迫感，坚持从我做起，从点滴做起，切实把“八荣八耻”转化为自觉行动，努力做社会主义荣辱观的模范实践者和用心推动者。这些东西让我的大学乃至今后的生活奠定一个很好的人生理想。同时，我时刻关注着党和国家的发展形势，以及国内外的局势变化。</p>\n<p>学习上，坚定信念，勇往直前在专业知识学习上，她一向以用心认真的态度对待，脚踏实地，走好每一步，上课认真听讲，课后用心复习，不仅仅满足课本知识，更注重拓宽专业视野，学习和了解专业前沿知识和研究领域。</p>\n<p>我热爱自己的专业，并想在所选专业的方向进一步深造。在课堂上始终持续端正、谦虚的学习态度，用心配合老师教学，努力提高自己的专业知识水平;课下虚心向同学请教，认真预习及完成老师所留的作业。与此同时自觉扩展自己各方面的知识，课外长期坚持自学，在空余时间里经常在图书馆或通过上网的方式查阅资料来充实自己，及时补充课堂知识的不足，透过这些拓宽了我的视野，丰富了我的知识。</p>\n<p>大学期间虽然取得了很大的进步，但是大学的学习和生活所能给我的并且我所能够理解的毕竟是有限的，应对社会这所没有围墙的大学，我要不断地更新自己，不断地给自己充电，丰富自己的知识面，努力务实，抓紧每一分每一秒。</p>\n<p>工作上，用心参加实践活动，不断提高创新精神，用心向同学们带给帮忙，始终以他人的利益至上，用心参加学院专业及班级的各项活动。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img130.webp\" alt=\"\"></figure>\n<p>在生活上；学校的各项规章制度；积极乐观；以饱满的热情迎接生活中每一天的挑战；尊敬师长，见到老师主动问好;孝敬父母，为父母做力所能及的事情，我回家及时完成家庭作业，不让他们为我操心；团结同学；努力用自己积极向上的心态去影响周围的同学；我总是怀着热心、耐心、责任心竭尽全力的帮助同学解决一些在学习和生活方面的问题，面对同学在学习方面所遇到的难题总是能不厌其烦的讲解。乐于助人；积极帮助同学们做一些力所能及的事；朋友是我最宝贵的财富；并且我们班是一个不甘落后、积极向上的班级。因此生活在这样的大集体里；怎么能不积极向上。</p>\n<p>二、毕业后的简介</p>\n<p>转眼，已经毕业差不多一月多的时间了，在这期间，经历了很多的东西，从工作到辞职，又立马投入找工作中到重新找到一份专业对口的工作，这过程中，经历了很多的心酸和汗水。毕业之后，面对就业的困难，面对学历的打击，面对太多优秀人才在就业过程中的各种洗礼。最终还是坚定了走投入工作这条路，虽然升学很重要，但是最后结合自身条件还是放弃了专升本这条路，但是也有报名参加了成人自考本科，学习这条路是不能放弃，不管怎么样只要还有一点机会都还是要抓住的。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img131.webp\" alt=\"\"></figure>\n<p>来到新的公司，我对自己的要求更加的严格。在工作中没有人会无条件的包容你，只有自己更加努力，付出更多才能站住脚，即使内心压力再大，都必须告诉自己要坚持下去。因为唯有努力才能使一个人继续向前走。在新公司，我很快就融入到了新的环境中去，即使每天都在加班，有好几天甚至加班到两三点钟，但是第二天还是会强迫自己起来继续上班，因为人只有不断的突破自己才能更上一层楼，要想在这个残酷的社会生存下去，就必须要求自己更加优秀。</p>\n<p>（十五）周尧算</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img132.webp\" alt=\"（十五）周尧算\"><figcaption>（十五）周尧算</figcaption></figure>\n<p>周尧算，共青团员，汉族，女，出生于1998年05月，在校期间担任班级权益委员一职和雪松班学习委员一职，在系部担任学生会学习部副部长一职。毕业于毕节职业技术学院财政经济系2017级财务管理二班。</p>\n<p>一、毕业前的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img133.webp\" alt=\"一、毕业前的简介\"><figcaption>一、毕业前的简介</figcaption></figure>\n<p>我在思想意识中有积极向上、要求进步的动机，能主动、自觉地向党组织靠拢。坚决拥护党的路线、方针、政策，热爱发展中的社会主义祖国，热爱所从事的学生工作，积极参加社会和学校组织的各种有益的活动。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img134.webp\" alt=\"\"></figure>\n<p>学习方面， 一直以来，在学习中我刻苦努力，不松懈，努力思考，取得了不错的回报，学习成绩名列前茅。我抓紧各种学习时间和机会，在学习知识这段时间里，我更与老师们建立了浓厚的师生友谊，也取得了一定的成就。连续两年荣获“国家励志奖学金”和学院“一等奖学金”2019年荣获学院“优秀共青团员”“三好学生”等荣誉。2020年荣获“优秀毕业生”在今后的每一天我要更加积极学习努力进步，团结同学，尊敬师长，努力工作，为我系的美好明天添砖加瓦。</p>\n<p>工作方面， 我在学生会现担任学习部副部长兼值班管理员、自接任学生会学习部副部长一职以来，我认真履行学生职责，配合上级领导及我系老师对学生的相关管理工作，积极参与、组织、鼓励同学参与系部、学院的各项活动。于2017年10月加入学生会，后于2018年11月换届后担任系学生会学习部副部长一职，根据院团委和我系团总支的要求，及时开展各种组织活动，做好学生会学习部组织建设相关管理工作，履行好学生会学习部副部长职责，积极配合团总支及相关老师安排的各项工作，积极参与我系组织的各项学生活动，帮助老师整理资料，减轻老师的工作负担。在学习知识技能的同时，积累工作本领、塑造创新思维，为以后的工作和生活打下坚实基础。</p>\n<p>二、毕业后的简介</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img135.webp\" alt=\"二、毕业后的简介\"><figcaption>二、毕业后的简介</figcaption></figure>\n<p>转眼，已经毕业，在这期间，经历了很多的东西，从工作到辞职再到备考专升本，这过程中，经历了很多的心酸和汗水。毕业之后，面对就业的困难，面对学历的打击，面对太多优秀人才在就业过程中的各种洗礼。我最初我来到“贵州三人行财务咨询有限公司”实习，刚开始对财务工作流程不清楚，在学校期间也没有实践，所以需要学习好多内容，离开学校我才知道自己的会计知识没有学好，幸运的是我遇到了一个好师傅，从上班的第一天他就慢慢的教我，让我熟悉财务的流程，从最简单的开始了解公司做账报税的系统，和我说每个月我们的工作是什么重心放在检查账务上面，会计这个行业就是要细心，还要时不时去更新自己大脑里的税务知识，比如每一年的税率都会改，在工作的同时还要去不断的学习，公司的营业离不开会计的协助，慢慢的我熟悉了工作的流程，也能熟练的完成每一家报税工作，突然我发现会计这个工作真的好枯燥无味，每个月都在做同样的事情做账报税订账本。最终，我选择了升学，在最后一个月的时间里，通过我和父母的沟通，我辞职了，全心全意备考专升本，我坚信，努力的人最幸运，所以就坚持了一个月。专业成绩考了127分，文化成绩考了147分，虽然我的分数在理科中不是很高，对于我来说已经很幸运，现在离录取通知下来只有两天的时间。我并不知道自己是否已经录取，但我相信努力的人运气都不会差，我依然相信自己是最幸运的哪一个。</p>\n<p>常言道:书山有路勤为径，学海无涯苦作舟。我期待着两天后录取的结果，人生就是越努力越幸运！付出了一定就会有收获！</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img136.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img137.webp\" alt=\"\"></figure>\n<p>（十六）蒋菲</p>\n<p>蒋菲，共青团员，汉族，女，出生于1998年02月，在</p>\n<p>校期间担任资助委员一职，在院部担任资助中心助理。毕业于毕节职业技术学院财政经济系2017级电子商务2班。</p>\n<p>一、毕业前的简介</p>\n<p>在校期间获奖情况：</p>\n<p>2017-2018学年获得学院一等奖学金;</p>\n<p>2017-2018学年获得国家励志奖学金；</p>\n<p>2017-2018学年获得学院“电商协会优秀会员”荣誉称号;</p>\n<p>2018-2019学年获得学院“三好学生”荣誉称号;</p>\n<p>2018-2019学年获得国家励志奖学金;</p>\n<p>人生的道路，有起有落，无须执着得失，无须顾虑太多，只要你坚定的前进，成功其实近在咫尺。正如一叶刚刚扬起风帆的小舟，载着自己的理想，乘风破浪，前面等待的是激烈的波涛，拦路的礁石，寂静的考验，还有海燕的陪伴，让我在狂风暴雨中奋起搏击，一路航行!</p>\n<p>思想方面，注重学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想和科学发展观等重要思想。具有坚定正确的政治立场，在思想和行动上严格要求自身，在不断加强学习的同时，做好各项工作，全心全意为同学服务，并用心向党组织，团组织靠拢，但是仍然时刻提醒自己，努力做好模范带头作用，行动上更是就应向党组织和团组织靠拢，时刻心系人民心系党，踏踏实实的为党和人民奉献。十分注重加强个人品德修养，自觉践行社会主义荣辱观，始终持续创新，与时俱进的思想和理念，尊敬师长，团结同学，用心参加社会主义精神礼貌建设，具有良好的社会公德和职业道德，以实际行动发挥着模范带头的作用。不断加强自身世界观、人生观和价值观的改造，提高自身的政治理论水平和工作能力。通过扎实的思想政治理论学习，为他开展各项工作提供了强大的思想武器，在日常工作中注重学以致用，取得了明显效果。在加强理论学习的同时，注重更新知识结构，重点加强业务和政策法规知识的学习，努力做到在工作中学习，在学习中工作，精益求精，不断探索，使自己更加胜任本职工作。</p>\n<p>学习方面，在校期间，我学习刻苦努力，我知道只有不断的努力才能走得更远，才能看到更加美丽的风景。从进校的第一天开始，老师在入学典礼中送给我们新生三句话，这三句话也成为人生中不断努力何前进的动力。他说：只有更努力才能去更遥远的地方，只有更努力才能看到更美丽的风景，只有更努力，才能成为优秀的人。那时候，我甚至不知道这段话的意思是什么，年幼迷茫的我，一直对自己没有信息，心里总是非常的自卑。来到这个学校不仅改变了我的很多观点，而且也使我重新振作起来，找到自己的闪光点。我通过自己的努力，在老师的帮助何指导下。每学年获得班级第一的好成绩，当然，这使我更加的对自己有信息。我坚信世上无难事，只要肯登攀。所以我也会谦虚的帮助那些在学习中有困难的同学一起进步，在他们身上我能学到很多我自己不会也不能做好的事情。做到相互的取长补短。在校期间获得国家励志奖学金，省级三好学生，学院奖学金等一系列的奖项。</p>\n<p>工作方面，在担任班级资助委员期间，我认真的配合老师完成资助中心的各项工作，尽自己最大的能力帮助同学们完成生活和学习中的困难。在资助中心，帮助资助中心完成各系部的各项大大小小的资助工作，在每一次的工作中，我会付出很大的心思去做好各项准备工作，在整个过程中，我也学到了很多的东西，这使我在生活中受益匪浅。</p>\n<p>二、毕业后的简介</p>\n<p>转眼，已经毕业几个月了，在这期间，经历了很多的东西，从工作到辞职，从备考到升学成功等，这过程中，经历了很多的心酸和汗水。毕业之后，面对就业的困难，面对学历的打击，面对太多优秀人才在就业过程中的各种洗礼。最终，我选择了升学，在最后一个月的时间里，我选择辞职，回到家中备考专升本，那时候的我对自己只有30%的信心，从未相信过自己，但是，我坚信，努力的人最幸运，所以就坚持了一个月。最后，幸运的我升学成功。</p>\n<p>进入新的学校，我将更加严格的要求自己。身边多了更多优秀的人，即使内心压力再大。但是，唯有努力才能使一个人继续向前走!</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img28.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(40,53,32,'BP-TOPIC-FINANCE_COMMERCE-STUDENTS','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-STUDENTS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀学生", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>座右铭：不负韶华砥砺前行 心怀热爱奔赴万里</p>\n<p>白金妹，毕节职业技术学院财政经济系现代物流管理专业2024级高职学生，布依族，共青团员。曾获国家奖学金，荣获2025年度毕节职业技术学院“优秀学生干部”称号、2025年度毕节职业技术学院“三好学生”称号，始终秉持勤学笃行、技能成才的理念，深耕专业学识，锤炼职业技能，全面提升综合素养，学业成绩优异，荣获国家奖学金；认真履行学生工作职责，服务师生、务实担当，先锋模范作用突出。深耕物流专业技能领域，潜心备战各级高水平专业赛事，勇于拼搏、精益求精，在各类职业技能竞赛中屡获佳绩：荣获2025年世界职业院校技能大赛总决赛争夺赛物流与供应链赛道铜奖、2025年贵州省职业院校技能大赛智慧物流（高职组）一等奖、2024年“百蝶杯”第十届全国大学生物流仿真设计大赛（高职组）物流系统规划设计赛道二等奖。立足高职学子初心，以实干践行使命，以奋进诠释担当，充分展现新时代技术技能人才勤学上进、技能过硬、昂扬向上的精神风貌，用实际行动彰显新时代高职学子的责任与担当。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img138.webp\" alt=\"\"></figure>\n<p>座右铭：道理在书上，践行在心中，知行合一，可为君子</p>\n<p>卢義，毕节职业技术学院财政经济系现代物流管理专业 2023 级高职学生，穿青人，共青团员。曾获国家奖学金；2025 年度毕节职业技术学院 “优秀学生干部” 称号；第十九届 “挑战杯” 贵州省大学生课外学术科技作品竞赛三等奖、2025 年世界职业院校技能大赛总决赛争夺赛物流与供应链赛道铜奖。作为2023级现代物流管理一班学习委员，他深刻认识专业知识的重要性，在校期间获得过专业第一的成绩。赛场之上，他多次担任竞赛队长，统筹协调、凝心聚力，带领队员并肩钻研、互帮共进，充分彰显出色的组织能力与团队担当；课余之余，他热爱体育锻炼，入选系部篮球队，在竞技拼搏中深刻感悟团结协作、凝心聚力的意义。身为班级学习委员，深刻认识专业知识的重要性，在校期间获得过专业第一的成绩。他立足专业、奋勇争先，以扎实的学识功底、过硬的职业技能践行新时代职业教育使命，充分展现新时代高职青年朝气蓬勃、奋发向上的良好精神风貌。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img139.webp\" alt=\"\"></figure>\n<p>座右铭：以赛促学，以行践知</p>\n<p>游盈盈，女，汉族，共青团员，毕节职业技术学院财政经济系 2023 级电子商务专业高职生，现任校学生会主席、班级学习委员兼副团支部书记。</p>\n<p>学业成绩稳居班级第一，综合考评、第二课堂均位列专业第一，25门必修课平均分93分。曾荣获国家奖学金、校级三好学生称号。专业技能扎实，先后斩获贵州省职业院校技能大赛电子商务赛项一等奖、毕节市电商直播大赛一等奖、贵州省乡村旅游创客大赛创意设计组一等奖、贵州省高校团支部“微团课”竞赛二等奖等多项省市级荣誉。</p>\n<p>牵头策划校园电商文化节，搭建班级学习互助平台，统筹学生会与团务工作，服务同学、实绩突出，是全面发展、品学兼优的优秀学生代表。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img140.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img138.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(41,54,32,'BP-TOPIC-FINANCE_COMMERCE-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "教学成果", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>教学改革成果：</p>\n<p>财政经济系教学改革成效显著，2025年斩获贵州省教学成果特等奖，登顶省级教学改革最高荣誉。贵州地处我国西南腹地，曾是全国脱贫攻坚的主战场，毕节贫困人口最多、贫困面最广、贫困程度最深，是贵州脱贫攻坚的主阵地。攻坚克难，关键在人才。毕节职业技术学院是毕节市唯一的综合性高职院校，肩负为西部山区发展培养高素质技术技能人才的使命，从2015年开始，针对西部山区技能人才培养中存在的思政教育价值引领不够、实践教学资源供给不足、专业交叉融合培养不实等问题，以毕节市人民政府为学校授牌毕节电子商务学院、贵州省农业电商产业扶贫协同创新中心建设为契机，依托“毕节试验区职业教育助推农村电商融合发展的探索与实践”等课题研究，联合东部对口帮扶院校、行业企业与联建村，系统调研、分析、研判、设计、试点、总结，于2018年制定《毕节职业技术学院数字新农人培养行动方案》并付诸实施。历经8年实践，逐步形成具有“黔地铸魂、平台锻技、实战赋能”特色的西部山区数字新农人培养范式。</p>\n<p>构建\"思政教育+课程思政+日常思政\"立体化思政育人体系，夯实\"黔地铸魂\"根基。将毕节试验区脱贫攻坚精神、绝壁天渠精神、本土新农人奋斗故事融入思政课堂，把乌蒙非遗、民族团结等元素融入《农业经理人经营管理实务》等专业课程，常态化组织学生走进乡村产业一线，厚植\"知家乡、爱家乡、建家乡\"情怀，纠正择业认知偏差；打造\"多方联通、项目贯通、学做融通\"平台矩阵，做实\"平台锻技\"支撑。牵头成立联合培养共同体，联动东部协作院校、政府部门、京东等头部企业与联建村，共建实训、产业、实习、实践等各类平台；开发专业基础、订单实战、乡村服务、赛证提升等递进式项目，贯穿实践教学全过程，层层锤炼专业技能；构建\"师资协同、课程融通、场景转换\"跨专业育人机制，做强\"实战赋能\"成效。整合电商、物流、会计等专业组建跨专业教学团队，重构模块化融合课程，联动田间种养、地头直播、乡村服务等多场景，让学生在场景切换中锤炼综合能力。</p>\n<p>学校先后培养了近万名本土技术技能人才，学生获全国职业院校技能大赛（世界职业院校技能大赛总决赛争夺赛）等奖项30余项，毕业生陈燕创办农产品电商企业带动51户农民致富并当选纳雍县人大代表，育人成效入选2025年教育赋能乡村振兴典型案例、教育厅职业教育典型案例，全国人大常委会副委员长、民革中央主席郑建邦对学校学生培养成效给予高度评价；建成省级乡村电商特色骨干专业群、生产性产教融合实训基地、电子商务教师教学创新团队等省部级项目8项，牵头开发的《农业经理人职业技能标准》被菲律宾采用为国家标准；获全国五四红旗团支部、贵州省脱贫攻坚先进集体等荣誉称号；开展各类非遗、新农人培训超3500人次，推动毕节农产品销售800多万元，助力卡妈集团等15家本土企业营收增长超3.5亿元；成果获50多所院校借鉴、中央电视台新闻联播等30余家媒体报道；成果荣获2024年贵州省职业教育教学成果奖特等奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img141.webp\" alt=\"\"></figure>\n<p>贵州省职业教育质量提升计划项目——骨干专业（大数据与会计）</p>\n<p>大数据与会计创新构建了 “课岗证赛融通、三步实训、三个一体化”的人才培养模式，形成了课、证、岗、赛深度融合的课程体系，打造了一支业务强、技能精的专兼职教师队伍，科研与社会服务能力逐步提高。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img142.webp\" alt=\"\"></figure>\n<p>贵州省职业教育质量提升计划项目-骨干专业</p>\n<p>兴黔富民行动计划建设项目——《基础会计》精品在线开放课程</p>\n<p>《基础会计》是省级“兴黔富民行动计划”立项建设的精品在线开放课程，目前已经验收完成并投入使用，作为会计、财务管理专业的核心基础课，同时也是省级电子商务专业群共享平台课程，为后续专业学习筑牢理论与技能根基，助力培养高素质财会技能型人才。</p>\n<p>课程紧扣职业教育改革要求与行业发展需求，以“任务引领、资源核心、学用融合、思政铸魂”为建设理念，构建了多元化教学资源体系。现已建成50个微课视频、12个技能点动画、473道习题及491道考核试题，配套教学PPT、108页活页式电子教材和虚拟仿真实训平台，通过“筑梦财经 APP ”、学习通等实现资源共享，支持碎片化学习与沉浸式实训。真正实现 “教学相长、产教融合、服务地方”的建设目标，是财会入门学习者与行业从业者的优质学习资源。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img143.webp\" alt=\"\"></figure>\n<p>兴黔富民行动计划建设项目--《基础会计》精品开放课程</p>\n<p>贵州省技能贵州建设项目——《农业职业经理人经营管理实务》省级优质课</p>\n<p>该课程是电子商务省级特色骨干专业群平台共享课。课程立足贵州乡村振兴，搭建一门基于“岗课赛证+数字赋能”模块化的课程资源建设平台，以“课程教学团队、课程资源、实践条件、课程实施、课程评价、数字应用”为课程开发建设抓手，始终坚持立德树人，推进“三教改革”的课堂革命改革，力争建设一门对接贵州山地乡村振兴省内一流《农业职业经理人经营管理实务》特色品牌课程，发挥示范带动作用，促进人才质量培养的提高，提升服务乡村振兴人才培养培训能力水平。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img144.webp\" alt=\"\"></figure>\n<p>贵州省技能贵州建设项目—《农业职业经理人经营管理实务》省级优质课</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img141.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(42,55,32,'BP-TOPIC-FINANCE_COMMERCE-COMPETITIONS','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-COMPETITIONS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "技能大赛", "subtitle": "数字商贸、电商物流与产教融合", "body": "<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img145.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img146.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img147.webp\" alt=\"\"></figure>\n<p>——赛商砺能：以赛促学，彰显育人实效</p>\n<p>坚持“以赛促学、以赛砺能”，将技能竞赛作为提升人才实战能力的重要抓手。组建会计协会、直播运营协会等6个专业型技能社团，完善内训机制，强化实战训练。近五年来，学子在各类赛事中捷报频传，斩获国家级职业院校技能大赛奖项3项、国家级行业赛20余项，省级技能大赛一等奖13项（含6项代表贵州省参赛项目）及其他省级奖项百余项；教师在教学能力大赛、青教赛等赛事中收获校级一等奖5次、省级奖项8次。系部多次圆满承办省级重要赛事，包括3次贵州省职业院校技能大赛-市场营销赛项、4项贵州省第二届职业技能大赛赛项，4名教师获评该赛事“表现突出场地经理”，1人获评“表现突出工作人员”，输出菲律宾《农业经理人》职业技能标准等标志性成果。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img148.webp\" alt=\"\"></figure>\n<p>2025年毕节职业技术学院直播大赛</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img149.webp\" alt=\"2025年毕节职业技术学院直播大赛\"><figcaption>2025年毕节职业技术学院直播大赛</figcaption></figure>\n<p>毕节市第四届电商直播大赛</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img150.webp\" alt=\"毕节市第四届电商直播大赛\"><figcaption>毕节市第四届电商直播大赛</figcaption></figure>\n<p>2025年贵州省职业院校师生技能大赛</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img151.webp\" alt=\"2025年贵州省职业院校师生技能大赛\"><figcaption>2025年贵州省职业院校师生技能大赛</figcaption></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img145.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(43,56,32,'BP-TOPIC-FINANCE_COMMERCE-HONORS','upsert','approved','{"code": "BP-TOPIC-FINANCE_COMMERCE-HONORS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "荣誉资质", "subtitle": "数字商贸、电商物流与产教融合", "body": "<p>1.毕节市数商兴农人才团队</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img152.webp\" alt=\"1.毕节市数商兴农人才团队\"><figcaption>1.毕节市数商兴农人才团队</figcaption></figure>\n<p>毕节市数商兴农人才团队</p>\n<p>2.东西部协作乡村电商行业产教融合共同体、全国智慧物流与供应链行业产教融合共同体副理事长单位、贵州数智财税行业产教融合共同体副理事长单位</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img153.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img154.webp\" alt=\"\"></figure>\n<p>3.获2024年贵州省职业教育教学教学成果奖</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img155.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\"><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img156.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\"><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img157.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\"><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img158.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\"><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img159.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\"><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img160.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\"><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<p>视频资料（专业特色，可于所在区域屏幕循环播放）</p>\n<p>通过网盘分享的文件：毕节职院成果奖成品8.mp4</p>\n<p>链接: https://pan.baidu.com/s/1DItiFZTOyGxOXj73rISivw 提取码: 9fk7</p>\n<p>--来自百度网盘超级会员v1的分享</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img152.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(44,57,33,'BP-TOPIC-DIGITAL_TOURISM-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "基本情况", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>系部简介：旅游管理系</p>\n<p>旅游管理系从2010年9月建系以来，始终以扎根服务毕节试验区文旅产业发展为主责主业主方向，主动融入“乌蒙深处·清凉毕节”产业布局，发挥地方人力资源优势，推动优势转化，提升旅游高技能人才培养，助推毕节服务业扩容提质。</p>\n<p>现开设有旅游管理、酒店管理与数字化运营、烹饪工艺与营养3个高职专业及高星级饭店运营与管理1个中技专业。共有毕业生2400人。共计专兼职教师34人，其中硕士研究生15人；副教授3人，讲师11人。农业农村部“名课名师”1名，贵州省技术能手3名，毕节工匠3名。师资入选贵州省乡村旅游标准化质量等级评定专家委员会、毕节旅游产业化咨询委员会专家库、毕节市旅游产业化咨询委员会。</p>\n<p>现建有贵州乡村旅游虚拟仿真实训基地、毕节数字文旅开放型产教融合实践中心2个省级产教融合基地。建成《乡村旅游导览实务》1门省级精品课，烹饪工艺与营养黔匠工坊1个省级工坊。成立“全国乡村生态旅游行业产教融合共同体”“毕节市乡村生态旅游市域产教联合体”。2024年立项贵州省高校班主任工作室；立项毕节市首批“标杆院系”项目；2025年成功立项技能贵州行动计划5项，分别是“校旅结合示范校”“省级职教教师教学创新团队”“省级特色专业：旅游管理”“省级示范性人培：烹饪工艺与营养”，以及“省级一流课程：模拟导游”；此外，还成功立项毕节市第七批人才团队：毕节市乡村振兴文旅发展智库团队。</p>\n<p>“地域+领域”政策背景下，发挥毕节人力资源优势，立足毕节、面向贵州乃至全国旅游行业，开展深度校企合作，构建“一主体三延伸全拓展”政行校企合作矩阵，覆盖全国43家稳定合作主体，不断迎来职业教育高质量发展新局面。与广州地铁、越秀集团、广州酒家等优质企业达成校企合作开设“粤黔协作”岭南集团订单班、“粤黔协作”广州地铁订单班、“粤黔协作”广州酒家订单班等12个订单班，与越秀万豪万枫酒店联合建成贵州第一个国际化产教融合实训基地。立足地方，与贵州省中国青年旅行社有限公司、毕节市文化旅游集团有限公司、百里杜鹃旅游投资有限公司等龙头企业、15个景区达成校企合作，连续14年服务百里杜鹃盛花期。成立洞天花海文旅产业学院、乡村旅游学院、段大华技能大师工作室、雷远(黔菜多厨)大师工作室、蔡群国家级非物质文化遗产代表性传承人工作室等。连续9年承办毕节市旅游服务类技能大赛，学生先后在省、市各级各类技能大赛中获奖百余次，其中省级表彰61项，市级表彰50项。2025年5月，我系承办贵州省第二届职业技能大赛酒店接待、中式面点、导游服务、茶艺、民宿管家、黔菜制作6个赛项，参赛师生荣获2金2银1铜3的优异成绩。2026年，在贵州省职业院校技能大赛暨世界职业院校技能大赛贵州选拔赛旅游赛道获得一等奖；贵州省省特色赛项黔菜制作获得三等奖；贵州文旅融合推广特色赛项获二等奖。</p>\n<p>近年来教师团队获得市级以上奖项108项，其中国家级奖项3个，省级奖项58个，市级奖项46个。2021年贵州省第五届教育科学研究优秀成果二等奖、2021年获贵州省职业院校教师教学能力一等奖、全国职业院校教师教学能力大赛三等奖、2022年贵州省职业教育教学成果奖一等奖，2023年国家级职业教育教学成果奖二等奖，2024年贵州省职业教育教学成果奖二等奖，2025年获贵州省职业教育教学成果奖二等奖等，“四元融合、六岗递进、四维联动：乡村旅游课程数智资源建设改革与毕节实践”案例入选文化和旅游部2025年旅游职业教育“五金”数智化建设典型金课程案例，是贵州唯一入选典型案例的学校。</p>\n<p>未来，旅游管理系将深耕乌蒙大地，不断推进教育教学改革，提升人才培养质量，讲好洞天花海的故事，传颂多彩贵州的赞歌，为文旅产业高质量发展添砖加瓦!</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img01.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(45,58,33,'BP-TOPIC-DIGITAL_TOURISM-MAJORS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "专业设置", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>文旅康养服务专业群（校级重点 特色打造）</p>\n<p>以旅游管理（省级重点专业）为核心，整合护理、烹饪工艺与营养、老年保健与管理、智慧健康养老服务与管理，构建“旅游+康养+餐饮+文创”协同服务体系。对接贵州全域全季旅居产业布局，推进文旅体、医康养深度融合，以毕节市“5+2+N”现代服务业体系为根本导向。该专业群对接旅居康养产业链上中下游关键环节：上游对接文旅资源开发规划，面向景区规划师、文旅策划师、旅游产品设计师等岗位；中游对接康养服务运营与餐饮配套，面向康养管家、旅居管家、民宿管家、营养配餐师等岗位；下游对接老年康养服务与智慧养老平台运维，面向老年照护师、健康管理师、智慧养老平台运维员等岗位。围绕毕节市文化旅游有限公司、贵州百里杜鹃旅游集团有限公司，百里杜鹃管理区、织金洞景区、乌江源百里画廊、阿西里西等重点景区及中高端旅居康养项目核心岗位能力要求，以跨专业技能融合为特色，培养既懂旅游服务又会康养管理、既通餐饮营养又精老年照护的高素质复合型技术技能人才，为贵州、毕节建成知名康养避暑旅居目的地提供技能人才支持。</p>\n<p>旅游管理专业</p>\n<p>培养目标：培养德、智、体、美、劳全面发展，具有良好的人文素养、专业知识和创新意识；具有较强的导游（领队）服务技能、旅行社经营和景区管理能力，具备计调、导游、销售、接待咨询等岗位服务与管理等专业能力和职业可持续发展能力，适应产业转型升级和企业技术创新需要的高素质劳动者和技术技能人才。</p>\n<p>核心课程：《旅游学概论》《旅游政策法规》《导游业务》《导游基础》《模拟导游》《旅行社运行管理》《景区服务与管理》《旅游地理》《旅游酒店会计》《旅游英语》。</p>\n<p>就业方向：旅游行政事业单位、文化旅游公司、旅行社、宾馆饭店、旅游景区、度假村、会展企业等部门，从事导游、咨询、讲解、营销策划、开发、规划和人力资源培训等管理工作。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img02.webp\" alt=\"\"></figure>\n<p>旅游管理专业（酒店管理与数字化运营方向）</p>\n<p>培养目标：本专业培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识， 爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备数字化思维和技术应用能力，具备职业综合素质和行动能力，面向住宿业、餐饮业行业的旅店服务员、茶艺师、宴会定制服务师、其他住宿和餐饮服务人员等岗位群，能够从事酒店、餐饮民宿、邮轮以及其他住宿新业态和高端接待业的服务、数字化运营与管理工作的高技能人才。</p>\n<p>核心课程：《餐饮服务与数字化运营》、《前厅客房服务与数字化运营》、《酒店人力资源管理》、《酒店数字化营销》、《酒店财务管理》、《民宿管家服务》、《康养旅游服务与管理。</p>\n<p>就业方向：主要从事酒店、餐饮、民宿、邮轮等其他住宿新业态和高端接待业的数字化运营、服务、管理工作，也可从事其他企事业单位的人力资源培训、咨询、会展服务、行政管理等工作。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img03.webp\" alt=\"\"></figure>\n<p>广州越秀订单班企业导师进校园</p>\n<p>烹饪工艺与营养专业</p>\n<p>培养目标：本专业培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向餐饮行业的中式烹调师、中式面点师、营养配餐员等职业，能够从事中式菜点烹饪、营养配餐、宴会设计、厨房管理等工作的高技能人才。</p>\n<p>核心课程：《中式烹调工艺》《餐饮食品安全与控制》《中式面点工艺》《饮食营养与配餐》《餐饮企业管理》《厨政管理》《菜品设计与创新》《宴会设计实务》。</p>\n<p>就业方向：面向星级酒店、各大宾馆、度假村、连锁餐饮业、食品生产等企事业单位，从事烹调、餐饮管理、餐饮创业等工作，可晋升担任大厨、行政总厨、餐饮部经理等职务。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img04.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img02.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(46,59,33,'BP-TOPIC-DIGITAL_TOURISM-TRAINING','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-TRAINING", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "实训基地", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>为保证实践教学需要，建立了粤菜师傅（毕节）培训基地、乡村旅游虚拟仿真实训基地等“一体化”综合实训大楼。与越秀万豪万枫酒店联建贵州第一个酒店国际化产教融合实训基地。</p>\n<p>“粤菜师傅”(毕节)培训基地</p>\n<p>“粤菜师傅”(毕节)培训基地由共青团广州市委员会牵头，联合共青团毕节市委员会、广州岭南国际企业集团、广州酒家集团、广州市轻工技师学院与毕节职业技术学院合作共建。现有“粤菜文化展示室”“粤菜烹饪实训室”“广式点心实训室”“粤菜师傅模拟餐厅”“粤菜师傅大师工作室(粤菜师傅青年孵化基地)”五大工作室，依托“粤黔协作”岭南集团订单班、“粤黔协作”广州酒家订单班，通过校校合作、校企合作、定向培养，探索建立“校一企一团”三方联动、优势互补的“一条龙”合作模式，实现招生即就业，全流程培养，其中学校负责招生动员和理论教学，企业负责实训实习和就业安排，共青团负责发动企业、宣传推广、思想引导和成长关爱，共同建立“粤菜师傅”青年人才库，促进技能就业、乡村振兴。</p>\n<p>其工作目标是：</p>\n<p>一、将服务青年成长发展与巩固脱贫攻坚成果、助力乡村振兴结合起来，每年培养一批青年“粤菜师傅”“黔粤菜融合黔菜师傅”，拓宽粤菜烹饪技能青年人才就业创业渠道和职业发展路径，促进技能提升，绘就出彩人生。</p>\n<p>二、将扩大共青团的组织覆盖和工作覆盖与推动“粤菜师傅”创新创业结合起来，凝聚维系一批致力于推动餐饮行业发展的烹饪行业协会、培训机构、院校、企业，每年培育孵化一批青年烹饪青年双创项目，不断提升共青团对青年烹饪专业的吸引力凝聚力影响力。</p>\n<p>三、将组织青年服务中心大局与弘扬岭南文化和毕节试验区精神结合起来，深化粤黔文化交流，不断提高粤菜、黔菜品牌知名度和影响力。</p>\n<p>贵州省乡村旅游虚拟仿真实训基地</p>\n<p>毕节数字文旅开放型产教融合实践中心</p>\n<p>围绕贵州省“四新四化”主战略和毕节建设“两区一典范一基地”（绿色发展样板区，体制机制创新先行区，乡村振兴新典范，人力资源开发培育基地）主定位，聚焦“多彩贵州”产业布局，以“产学研用创”系统打造理念，建设集“情景逼真、课程丰富、团队卓越、育训双优”于一体的“贵州乡村旅游虚拟仿真实训基地”“毕节数字文旅开放型产教融合实践中心”， 分别隶属于贵州省职业教育“1+9”开放型区域产教融合实践中心建设子项目和贵州省“技能贵州”行动计划虚拟仿真实训基地建设项目，旨在培养具备数字文旅的高技能人才，助力毕节及贵州乡村振兴与智慧文旅产业的高质量发展。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img05.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img06.webp\" alt=\"\"></figure>\n<p>基地功能布局</p>\n<p>围绕产业布局、文化旅游专业群人才培养目标，重点建设“2展厅+1回廊+9实训室”，覆盖旅游管理、酒店管理与数字化运营、文化创意与策划、服装设计与工艺、非遗文化传承等领域专项与综合技能实训。</p>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img05.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(47,60,33,'BP-TOPIC-DIGITAL_TOURISM-COOPERATION','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "产教融合", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>旅游管理系立足地方，与区域大方县政府、百里杜鹃管理区管理委员会，毕节市旅游开发集团有限公司、贵州百里杜鹃旅游集团有限公司、蔡群苗族蜡染刺绣有限公司、贵州省研学旅行协会等23家政府、企业、协会达成政行校企合作矩阵，连续7年承办毕节市旅游服务类技能大赛，承办贵州省第二届职业技能大赛黔菜制作、酒店接待、民宿服务等6个赛项。</p>\n<p>东西部协作，在毕节市委市政府的牵头下，在广州团市委、广州总工会的牵引下，与广州地铁、越秀集团、广州酒家等优质企业达成校企合作开设“粤菜师傅”“广铁订单班”“越秀订单班”“洞天花海”4个订单班，与越秀万豪万枫酒店联建贵州第一个酒店国际化产教融合实训基地。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img07.webp\" alt=\"\"></figure>\n<p>2025年8月与百里杜鹃管理区管理委、毕节市旅游开发集团有限公司，贵州民族大学、贵州省中国青年旅行社有限公司等分别牵头成立“全国乡村生态旅游行业产教融合共同体”“毕节市乡村生态旅游市域产教联合体”。</p>\n<p>全国乡村生态旅游行业产教融合共同体成立大会</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img08.webp\" alt=\"全国乡村生态旅游行业产教融合共同体成立大会\"><figcaption>全国乡村生态旅游行业产教融合共同体成立大会</figcaption></figure>\n<p>全国乡村生态旅游行业产教融合共同体签约仪式</p>\n<p>对接产业</p>\n<p>本专业群围绕我省文旅康养、乡村旅游重点产业链布局，紧扣产业数字化转型与高质量发展需求，精准对接乡村旅游开发、景区运营管理、酒店数字化运营、康养休闲服务、文旅文创产品开发等核心岗位群，聚焦产业发展中的人才缺口与技术需求，打通教育链与产业链、创新链的衔接通道，为地方文旅产业发展持续输出高素质技术技能型人才。</p>\n<p>校企合作订单班</p>\n<p>“地域+领域”政策背景下，发挥毕节人力资源优势，立足毕节、面向贵州乃至全国旅游行业，开展深度校企合作，构建“一主体三延伸全拓展”政行校企合作矩阵，覆盖全国43家稳定合作主体，不断迎来职业教育高质量发展新局面。与广州地铁、越秀集团、广州酒家等优质企业达成校企合作开设“粤黔协作”岭南集团订单班、“粤黔协作”广州地铁订单班、“粤黔协作”广州酒家订单班等12个订单班，与越秀万豪万枫酒店联合建成贵州第一个国际化产教融合实训基地。立足地方，与贵州省中国青年旅行社有限公司、毕节市文化旅游集团有限公司、百里杜鹃旅游投资有限公司等龙头企业、15个景区达成校企合作，连续14年服务百里杜鹃盛花期。成立洞天花海文旅产业学院、乡村旅游学院、段大华技能大师工作室、雷远(黔菜多厨)大师工作室、蔡群国家级非物质文化遗产代表性传承人工作室等。校企合作、产教融合成效显著，为毕业生就业奠定了良好的基础和发展平台，有效推动专业内涵提升、专业集群发展和提高人才培养质量，实现毕业生素质高、有能力、就业好。</p>\n<p>班级 / 合作专业 / 合作企业 / 合作时间\n岭南集团订单班 / 烹调工艺与营养 / 广州岭南商旅集团 / 2020年起\n广州酒家订单班 / 烹调工艺与营养 / 广州酒家集团 / 2020年起\n广州地铁订单班 / 空中乘务、高铁服务 / 广州地铁集团有限公司 / 2019年起\n广州地铁订单班 / 旅游（旅游、酒店方向） / 广州地铁集团有限公司 / 2022年起\n越秀万豪万枫班 / 酒店（酒店方向） / 越秀万豪万枫有限公司 / 2022年起</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img09.webp\" alt=\"\"></figure>\n<p>广州岭南集团订单班粤菜大师进课堂授课</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img10.webp\" alt=\"广州岭南集团订单班粤菜大师进课堂授课\"><figcaption>广州岭南集团订单班粤菜大师进课堂授课</figcaption></figure>\n<p>“粤黔协作”广州地铁订单班开班仪式</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img11.webp\" alt=\"“粤黔协作”广州地铁订单班开班仪式\"><figcaption>“粤黔协作”广州地铁订单班开班仪式</figcaption></figure>\n<p>2025年第六期“粤菜师傅”毕节班结业仪式</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img12.webp\" alt=\"2025年第六期“粤菜师傅”毕节班结业仪式\"><figcaption>2025年第六期“粤菜师傅”毕节班结业仪式</figcaption></figure>\n<p>越秀订单班酒店职业体验研学实践营</p>\n<p>学与创新成果</p>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img07.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(48,61,33,'BP-TOPIC-DIGITAL_TOURISM-MASTERS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-MASTERS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "名师名匠", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>谭佳 副教授</p>\n<p>文旅部“万名旅游英才”、农业农村部首批“名课名师”、省级职教教师教学创新团队负责人，毕节市人民政府授予“优秀教师”称号</p>\n<p>聚焦旅游技能人才培养、数智赋能课程建设等教学教改方向，先后主持省部级、市厅级项目10余项。开发毕节市首门旅游技能培训课程《乡村旅游导览实务》，并立项省教育厅“兴黔富民计划”精品开放课程，覆盖从业人员10000余人，先后获全国教师教学能力大赛三等奖、省赛一等奖，贵州省第五届教育科学优秀成果奖三等奖，2024年贵州省职业教育教学成果二等奖。牵头成立毕节市首个旅游管理专业“双师型”工作营，实践成果入选文旅部优秀成果在全国推广。2023年承接毕节市首门“洞天花海·金牌研学”喀斯特主题研学课程开发，同年在中国—东盟教育交流周论坛、大国博士论坛中进行主旨发言。2025年8月，教学案例入选文旅部旅游职业教育“五金”数智化建设典型案例，贵州仅此一个。作为省级职教教师教学创新团队、市级第七批人才团队负责人，带领团队围绕生态旅游、乡村旅游点、红色讲解、研学旅游开发等开展课题30余项，近三年成员先后摘取省级技能大赛金奖6项。通过老带新、师带徒，优化人才结构，赋能贵州文旅产业高质量发展。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img13.webp\" alt=\"\"></figure>\n<p>孟田</p>\n<p>毕节市优秀共产党员、毕节市“四好”党员、毕节市文化与旅游局专家库成员、</p>\n<p>中式烹调二级技师、贵州名厨</p>\n<p>她围绕旅游专业人才培养，先后主持各级科研课题4项，主要参与10余项。2021年主要参与申报立项省教育厅“兴黔富民计划”烹饪与工艺营养黔匠工坊并以优秀等次验收；2023年主要参与承接毕节市首门“洞天花海·金牌研学”喀斯特主题研学课程开发，服务地方研学旅游5000余人；2025年主要参与申报并立项技能贵州项目3项；同时也是毕节市第七批人才团队主要成员。指导学生荣获省市级各类技能大赛获奖10余项，共计100余人次。其中在2024年贵州省第六届乡村旅游创客大赛中获得一等奖第一名、国际大学生创新创业大赛省级银奖、2025贵州省第二届职业技能大赛中获得铜奖等、第三届贵州省大学生职业规划大赛铜奖、2026年获得贵州省职业院校技能大赛暨世界职业院校技能大师贵州选拔赛旅游赛道一等奖。获得毕节市第二届职业技能大赛中荣获黔菜制作（毕节乡厨）竞赛项目二等奖、贵州省2025年生态黔菜职业技能大赛“新派黔菜”赛项三等奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img14.webp\" alt=\"\"></figure>\n<p>杨梅</p>\n<p>贵州省技术能手 中式烹调师技师</p>\n<p>聚焦烹饪技艺传承与职业教育改革创新，参与省教育厅“兴黔富民计划”烹饪工艺与营养黔匠工坊建设，开发《中式热菜制作》校级精品课程，构建“岗课赛证”融通育人模式，为烹饪工艺与营养专业学生搭建了学习平台。深耕技能竞赛指导，助力学生高质量就业。自2016年起，连续多年指导学生参加各级各类技能大赛，累计斩获省级一等奖1项、三等奖5项，市级一等奖1项、二等奖1项，并多次获评省级“优秀指导教师”称号。个人荣获2022年烘焙项目个人三等奖，2023年毕节市第二届职业技能大赛荣获黔菜制作(毕节乡厨)竞赛项目三等奖，2025年贵州省第二届职业技能大赛中黔菜制作赛项铜奖。参与中国名厨段大华技能大师工作室成立，研发地方特色菜品，推动黔菜产业与地方文旅融合，为贵州餐饮行业培养高素质技术技能人才，赋能贵州餐饮产业高质量发展。荣获省三星级黔菜师傅、贵州名厨等称号。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img15.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img13.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(49,62,33,'BP-TOPIC-DIGITAL_TOURISM-ALUMNI','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-ALUMNI", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀校友", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>行业典范——龚玉</p>\n<p>华住集团贵州省区营销经理</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img16.webp\" alt=\"华住集团贵州省区营销经理\"><figcaption>华住集团贵州省区营销经理</figcaption></figure>\n<p>龚玉是毕节职业技术学院2011级酒店管理班学生，在校期间，曾荣获国家励志奖学金、学院一等奖学金、毕节市优秀青年志愿者、毕节职业技术学院优秀毕业生。现就职于华住集团贵州省区，任省区营销一职，目前贵州省区在营酒店112家。</p>\n<p>学业代表——王芳</p>\n<p>贵州师范大学职业教育（旅游管理）硕士研究生</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img17.webp\" alt=\"贵州师范大学职业教育（旅游管理）硕士研究生\"><figcaption>贵州师范大学职业教育（旅游管理）硕士研究生</figcaption></figure>\n<p>王芳于2017年毕业于毕节职业技术学院旅游管理专业。高职期间，她以专业排名年级第一的优异成绩脱颖而出，并主动担任系部团总支副书记、班级团支部书记等职务，积极组织参与校内外各项活动。凭借出色的学业表现和综合能力，她先后荣获“国家奖学金”、贵州省“优秀毕业生”、校级“三好学生”等多项荣誉。三年的高职学习不仅为她奠定了扎实的专业基础，也锤炼了坚韧务实的品格。</p>\n<p>毕业后她并未停下求索的脚步，于2020年顺利考入贵州师范大学旅游管理专业攻读本科。在本科阶段，她继续保持刻苦钻研的态度，并于2023年成功考取本校职业技术教育专业（旅游管理方向）硕士研究生，目前仍在读，预计2026年7月毕业。从高职到本科再到研究生，每一步都凝结着她对旅游教育事业的执着追求，也体现了东西部协作背景下职教学子不断向上生长的可能性。</p>\n<p>研究生期间，她在学术领域展现出突出的潜力，目前已发表学术论文4篇，其中以第一作者身份发表SCI（中科院三区）论文1篇、普刊2篇、学术论文集1篇。同时，她屡获校级荣誉：贵州师范大学研究生学业一等奖学金、旅游线路设计一等奖、教学技能大赛优秀奖等。从一名高职生成长为具备科研能力与教学素养的研究生，她用行动证明：起点并非终点，奋斗终能闪光。未来，她将继续深耕旅游职业教育领域，立志为行业培养更多优秀人才2017年毕业于毕节职业技术学院旅游管理班，2020年进入贵州师范大学旅游管理专业就读本科，2026年7月贵州师范大学职业技术教育专业（旅游管理方向）在读硕士研究生。</p>\n<p>订单学子——段春亚</p>\n<p>广州地铁值班员</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img18.webp\" alt=\"广州地铁值班员\"><figcaption>广州地铁值班员</figcaption></figure>\n<p>段春亚1999年生于云南宣威，2018年考入毕节职业技术学院高速铁路客运乘务专业。在校期间，她勤学笃行，揽获贵州省优秀毕业生、国家奖学金、国家励志奖学金、三好学生等多项荣誉，三年大学生活不仅夯实了专业基础，也积累了丰富的社会实践经验。 大三时，她辗转面试南航等多家航空公司却屡屡碰壁。正值迷茫之际，东西部扶贫协作项目带来曙光——她成功进入广州地铁订单班。实习期间表现优异，考取资格证的同时还拿到贵州民族大学本科录取资格。面对深造与就业的抉择，她选择签约广州地铁，留在这座包容的一线城市，扎根于热爱的站务员岗位。 2021年8月正式入职后，她多次获评“服务之星”，2022年考取值班员资格证，2024年晋升为值班员。在职期间连续两年荣获集团优秀团员，并摘得“票务之星”等荣誉；积极投身新媒体宣传，参与新线开通及重大活动，2024年更作为订单班代表在广州市东西部“三项工程”研讨会上发言。从三四线城市的普通学生到一线城市地铁专业骨干，她的故事如星火般照亮自己，也点亮他人。</p>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img16.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(50,63,33,'BP-TOPIC-DIGITAL_TOURISM-STUDENTS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-STUDENTS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "优秀学生", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>文旅筑梦，技耀黔程——韦媛</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img19.webp\" alt=\"文旅筑梦，技耀黔程——韦媛\"><figcaption>文旅筑梦，技耀黔程——韦媛</figcaption></figure>\n<p>韦媛，女，毕节职业技术学院旅游管理系2024级旅游管理专业学生。现任班级班长、系学生会主席，始终以“服务者”自勉，躬身力行带动集体向上。</p>\n<p>专业上深耕不辍，竞逐锋芒：获2026年贵州省职业院校技能大赛旅游赛道一等奖、2026第三届贵州省大学生职业规划大赛职教组就业赛道铜奖、2025年导游服务赛项三等奖，荣膺国家励志奖学金、三好学生、优秀学生干部，考取茶艺师资格证。从课堂到赛场，她以“勤学笃行”为尺，在旅游领域深耕细作——备赛时反复打磨讲解词至深夜，实训中钻研茶艺礼仪细节，将“工匠精神”融入每一次实践。</p>\n<p>“成为一名有温度、有本领的文旅人”是她的初心。未来，她将继续以党员标准严格要求自己，在服务与奋斗中锤炼综合素质，争做新时代知行合一的青年表率。</p>\n<p>笃学砺行，领航班旅——李堂菲</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img20.webp\" alt=\"笃学砺行，领航班旅——李堂菲\"><figcaption>笃学砺行，领航班旅——李堂菲</figcaption></figure>\n<p>李堂菲，女，毕节职业技术学院旅游管理系2024级酒店管理与数字化运营二班学生，现任班级班长。入学以来，她始终秉持“笃学砺行、崇德向善”的初心，以严谨务实的态度深耕学业与学生工作，在服务同学、锤炼技能中逐光成长，生动诠释新时代高职学子的青春担当。</p>\n<p>作为班长，她履职尽责，带领班级凝聚奋进力量；作为学子，她勤学善思，成绩优异，先后获2025年校体育节团体操一等奖、第十九届“挑战杯”校级科技作品竞赛三等奖；在专业领域，她精益求精，2025年获贵州省职业院校技能大赛酒店服务赛项二等奖，2026年再攀高峰，斩获贵州省职业院校技能大赛旅游赛道一等奖。因表现突出，她获评2025年度校级“优秀学生干部”，并荣获2024至2025学年度国家励志奖学金。</p>\n<p>从班级建设到省级赛场，从课堂学习到实践磨砺，李堂菲以脚步丈量成长，用实干书写青春，展现了高职学子“技能立身、德行立人”的昂扬风貌。</p>\n<p>匠心黔味，烹然新章——李浩</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img21.webp\" alt=\"匠心黔味，烹然新章——李浩\"><figcaption>匠心黔味，烹然新章——李浩</figcaption></figure>\n<p>李浩，男，毕节职业技术学院旅游管理系2024级烹饪工艺与营养专业学生。现任班级班长、系部易班站长。他怀揣对烹饪艺术的赤诚匠心，深耕黔菜研发创新，专注挖掘贵州本土食材特色，以现代技艺赋能传统风味，在灶台方寸间潜心打磨“新派黔味”。</p>\n<p>在专业竞技场上，他硕果累累。斩获2026年贵州省职业院校技能大赛三等奖与2024年毕节生态黔菜烹饪大赛三等奖，展现了扎实的实操功底与清晰的职业蓝图。凭借卓越的创新项目潜力，他于2026年荣获校级“挑战杯”创新项目二等奖。他将赛场经验转化为服务热情，曾获评贵州省职业院校师生技能大赛“优秀志愿者”，并积极投身爱慕中国服饰教育创新项目社会实践，获颁实践证书。</p>\n<p>作为学生骨干，他履职尽责，屡获殊荣：2024年获评院“易班发展中心优秀干部”；2023年荣获中国发展研究基金会“一职闪耀·共赢未来”优秀营员称号。从田间地头寻味到三尺灶台炼技，李浩正以青春之名践行工匠精神，用一道道独具匠心的黔味佳肴，烹制出新时代高职学子的“味觉名片”。</p>\n<p>成立了旅游协会、礼仪协会、舞蹈协会、青年志愿者协会、易班等学生社团组织，开展丰富的校园文化活动，为学生提供成长成才平台。近三年来，学生100余人次获国家奖学金、励志奖学金，省、市级三好学生、优秀毕业生等称号。学生参加全国导游员资格考试，平均获证率达70%以上，高于全省平均获证率；通过组织学生参加专升本、单位招考、举办专场招聘会等方式，毕业生就业率达95%以上。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img34.webp\" alt=\"\"></figure>\n<p>团体操比赛第一名</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img35.webp\" alt=\"团体操比赛第一名\"><figcaption>团体操比赛第一名</figcaption></figure>\n<p>九洞天研学活动</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img36.webp\" alt=\"九洞天研学活动\"><figcaption>九洞天研学活动</figcaption></figure>\n<p>雷锋月活动</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img37.webp\" alt=\"雷锋月活动\"><figcaption>雷锋月活动</figcaption></figure>\n<p>获第三届贵州省大学生职业规划大赛银奖、铜奖</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img38.webp\" alt=\"获第三届贵州省大学生职业规划大赛银奖、铜奖\"><figcaption>获第三届贵州省大学生职业规划大赛银奖、铜奖</figcaption></figure>\n<p>暑期三下乡</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img39.webp\" alt=\"暑期三下乡\"><figcaption>暑期三下乡</figcaption></figure>\n<p>文旅匠心系列品牌活动</p>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img19.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(51,64,33,'BP-TOPIC-DIGITAL_TOURISM-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "教学成果", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>近年来教师团队获得市级以上奖项105项，其中国家级奖项3个，省级奖项56个，市级奖项46个。其中2021年贵州省第五届教育科学研究优秀成果二等奖、2021年获贵州省职业院校教师教学能力一等奖、全国职业院校教师教学能力大赛三等奖、2022年贵州省职业教育教学成果奖一等奖，2023年国家级职业教育教学成果奖二等奖，2025年获贵州省职业教育教学成果奖二等奖等，“四元融合、六岗递进、四维联动：乡村旅游课程数智资源建设改革与毕节实践”案例入选文化和旅游部2025年旅游职业教育“五金”数智化建设典型金课程案例，是贵州唯一入选典型案例的学校。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img22.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img23.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img24.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img25.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img26.webp\" alt=\"\"></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img27.webp\" alt=\"\"></figure>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img22.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(52,65,33,'BP-TOPIC-DIGITAL_TOURISM-COMPETITIONS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-COMPETITIONS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "技能大赛", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>2013年以来，系部连续承办毕节市职业院校旅游服务类学生技能大赛，认真组织参加省市技能大赛。近五年获省级一等奖22人次、二等奖30人次、三等奖若干。2025年承办贵州省第二届职业技能大赛酒店接待、中式面点、导游服务、茶艺、民宿管家、黔菜制作6个赛项，参赛师生荣获2金1银3铜的优异成绩。2026年，在贵州省职业院校技能大赛暨世界职业院校技能大赛贵州选拔赛旅游赛道获得一等奖；贵州省省特色赛项黔菜制作获得三等奖；贵州文旅融合推广特色赛项获二等奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img29.webp\" alt=\"\"></figure>\n<p>餐厅服务项目比赛现场</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img30.webp\" alt=\"餐厅服务项目比赛现场\"><figcaption>餐厅服务项目比赛现场</figcaption></figure>\n<p>技能大赛酒店接待项目一等奖</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img31.webp\" alt=\"技能大赛酒店接待项目一等奖\"><figcaption>技能大赛酒店接待项目一等奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img33.webp\" alt=\"技能大赛酒店接待项目一等奖\"><figcaption>技能大赛酒店接待项目一等奖</figcaption></figure>\n<p>贵州省职业技能大赛餐厅服务赛项二等奖作品“舟已过重山”</p>\n<p>贵州省第六届乡村旅游创客大赛一等奖（第一名）</p>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img29.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(53,66,33,'BP-TOPIC-DIGITAL_TOURISM-HONORS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-HONORS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "荣誉资质", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<p>先后获2022年贵州省职业教育教学成果奖一等奖，2023年国家级职业教育教学成果奖二等奖，2024年贵州职业教育教学成果二等奖。团队获全国职业院校教师教学能力大赛三等奖、贵州省职业院校教师教学能力一等奖、贵州省第五届教育科学研究优秀成果三等奖、贵州省职业教育教学成果奖二等奖。近五年获省级一等奖22人次、二等奖30人次、三等奖若干。其中，2025年承办贵州省第二届职业技能大赛6个赛项，并获得2金1银3铜的好成绩。2026年获贵州省职业院校技能大赛暨世界职业院校技能大赛贵州省选拔赛高职旅游赛道一等奖，实现历史突破！</p>\n<figure><img src=\"/uploads/blueprint/topics/digital-tourism/images/img40.webp\" alt=\"\"></figure>\n<p>2025年承办贵州省第二届职业技能大赛6个赛项，获得2金1银3铜</p>\n<p>视频资料（专业特色，可于所在区域屏幕循环播放）</p>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/images/img40.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(54,67,33,'BP-TOPIC-DIGITAL_TOURISM-MEDIA','upsert','approved','{"code": "BP-TOPIC-DIGITAL_TOURISM-MEDIA", "category": "视频资源", "source": "蓝图资料同步", "publishedAt": "2026-08-03", "title": "视频资源", "subtitle": "数字文旅、粤菜师傅与产教融合", "body": "<figure><p><strong>黔菜师傅培养纪实（一）</strong></p><img src=\"/uploads/blueprint/topics/digital-tourism/videos/2d4fbf012e1d466d56cfbc45a0980f5e.jpg\" alt=\"黔菜师傅培养纪实（一）\"><figcaption><a href=\"/uploads/blueprint/topics/digital-tourism/videos/2d4fbf012e1d466d56cfbc45a0980f5e.mp4\">查看视频资源</a></figcaption></figure>\n<figure><p><strong>黔菜师傅培养纪实（二）</strong></p><img src=\"/uploads/blueprint/topics/digital-tourism/videos/3d14324e38cec6f57fbfd29439540d38.jpg\" alt=\"黔菜师傅培养纪实（二）\"><figcaption><a href=\"/uploads/blueprint/topics/digital-tourism/videos/3d14324e38cec6f57fbfd29439540d38.mp4\">查看视频资源</a></figcaption></figure>", "imageUrl": "/uploads/blueprint/topics/digital-tourism/videos/2d4fbf012e1d466d56cfbc45a0980f5e.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-03T05:35:55.398098+00:00','admin','2026-08-03T05:35:55.398098+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(55,68,37,'BP-TOPIC-MODERN_AGRICULTURE-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-MODERN_AGRICULTURE-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。", "body": "<p>现代农业专题面向山地特色农业、农产品流通、乡村建设与乡村运营需求，整合电子信息工程系、旅游管理系、工矿建筑系的技术与服务能力，形成“数字技术支撑、乡村文旅运营、工程场景保障”的展示主线。</p>\n<p>专题在学校门户中承担乡村振兴与现代职业教育结合的入口，重点展示数字化监测、农产品品牌传播、乡村服务场景、设施建设和学生实践成果。</p>\n<figure><img src=\"/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg\" alt=\"学校形象与乡村振兴服务场景\"><figcaption>学校形象与乡村振兴服务场景</figcaption></figure>", "imageUrl": "/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(56,69,37,'BP-TOPIC-MODERN_AGRICULTURE-MAJORS','upsert','approved','{"code": "BP-TOPIC-MODERN_AGRICULTURE-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专业群布局", "subtitle": "面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。", "body": "<p>关联系部：电子信息工程系提供数字化平台、数据采集与网络技术支撑；旅游管理系提供乡村文旅、品牌运营与服务接待能力；工矿建筑系提供设施建设、资源利用与工程场景实践支撑。</p>\n<p>展示内容可围绕智慧种植、农产品电商、乡村旅游线路、公共服务空间、数字化管理平台和学生实践作品组织。</p>", "imageUrl": "/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(57,70,37,'BP-TOPIC-MODERN_AGRICULTURE-COOPERATION','upsert','approved','{"code": "BP-TOPIC-MODERN_AGRICULTURE-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "产教协同", "subtitle": "面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。", "body": "<p>专题适合承接校地合作、乡村振兴服务、农产品品牌孵化、乡村旅游运营和信息化平台建设项目，以真实任务驱动课程、实训和社会服务联动。</p>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img01.webp\" alt=\"文旅服务与乡村运营能力\"><figcaption>文旅服务与乡村运营能力</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/tourism/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(58,71,37,'BP-TOPIC-MODERN_AGRICULTURE-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-MODERN_AGRICULTURE-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题成果", "subtitle": "面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。", "body": "<p>成果展示可聚焦师生服务地方案例、数字化应用成果、乡村文旅活动、农产品传播方案和跨专业实践作品，形成可持续更新的专题成果库。</p>", "imageUrl": "/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(59,72,37,'BP-TOPIC-MODERN_AGRICULTURE-GALLERY','upsert','approved','{"code": "BP-TOPIC-MODERN_AGRICULTURE-GALLERY", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "图文资料", "subtitle": "面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。", "body": "<figure><img src=\"/uploads/blueprint/departments/information/images/img01.webp\" alt=\"数字技术支撑现代农业服务\"><figcaption>数字技术支撑现代农业服务</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/departments/mining-construction/images/img01.webp\" alt=\"工程技术支撑乡村建设场景\"><figcaption>工程技术支撑乡村建设场景</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/information/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(60,73,38,'BP-TOPIC-SMART_HEALTHCARE-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-SMART_HEALTHCARE-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。", "body": "<p>智慧康养专题以医学护理系为核心，联动旅游管理系的服务接待与康养场景运营能力，以及电子信息工程系的数字化平台与智能设备支撑，展示护理教育、急救训练、康养服务和健康管理的综合育人路径。</p>\n<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img01.webp\" alt=\"护理与康养服务实训场景\"><figcaption>护理与康养服务实训场景</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/medical-nursing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(61,74,38,'BP-TOPIC-SMART_HEALTHCARE-MAJORS','upsert','approved','{"code": "BP-TOPIC-SMART_HEALTHCARE-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专业群布局", "subtitle": "围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。", "body": "<p>关联系部：医学护理系承担临床护理、急救教育和康养服务主线；旅游管理系承接康养旅游、酒店服务与接待运营；电子信息工程系支撑健康数据、智能终端和数字化互动展示。</p>\n<p>可展示护理技能、老年照护、急救科普、康养服务设计、智慧健康设备应用和学生志愿服务成果。</p>", "imageUrl": "/uploads/blueprint/departments/medical-nursing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(62,75,38,'BP-TOPIC-SMART_HEALTHCARE-COOPERATION','upsert','approved','{"code": "BP-TOPIC-SMART_HEALTHCARE-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "产教协同", "subtitle": "围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。", "body": "<p>专题适合联动医院、社区、养老机构、康养企业与旅游服务企业，共建真实服务场景，让学生在护理、健康管理、服务运营和数字工具应用中完成综合训练。</p>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img02.webp\" alt=\"服务接待与康养运营场景\"><figcaption>服务接待与康养运营场景</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/tourism/images/img02.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(63,76,38,'BP-TOPIC-SMART_HEALTHCARE-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-SMART_HEALTHCARE-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题成果", "subtitle": "围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。", "body": "<p>成果展示可包括护理技能竞赛、急救教育活动、康养服务案例、志愿服务项目、校企合作实践和智慧健康互动内容。</p>", "imageUrl": "/uploads/blueprint/departments/medical-nursing/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(64,77,38,'BP-TOPIC-SMART_HEALTHCARE-GALLERY','upsert','approved','{"code": "BP-TOPIC-SMART_HEALTHCARE-GALLERY", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "图文资料", "subtitle": "围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。", "body": "<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img02.webp\" alt=\"医学护理教学成果\"><figcaption>医学护理教学成果</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img02.webp\" alt=\"信息技术支撑智慧健康应用\"><figcaption>信息技术支撑智慧健康应用</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/medical-nursing/images/img02.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(65,78,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-DIGITAL_INTELLIGENCE-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。", "body": "<p>数智技术专题以电子信息工程系为牵引，把人工智能、网络安全、数据应用、物联网和数字媒体能力延伸到能源、制造、文旅、康养、财经商贸等专业场景，形成学校跨专业数字化能力展示入口。</p>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img01.webp\" alt=\"电子信息工程系数智技术成果\"><figcaption>电子信息工程系数智技术成果</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/information/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(66,79,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-MAJORS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_INTELLIGENCE-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专业群布局", "subtitle": "聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。", "body": "<p>关联系部：电子信息工程系承担技术底座；财政经济系承接数字商贸与财务数据应用；工矿建筑系承接智能设备与工程数字化；医学护理系承接智慧健康；旅游管理系承接数字文旅与服务管理。</p>\n<p>该专题适合展示人工智能应用、网络安全实训、数据看板、数字资源平台、交互式展示系统和跨专业项目制学习成果。</p>", "imageUrl": "/uploads/blueprint/departments/information/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(67,80,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-COOPERATION','upsert','approved','{"code": "BP-TOPIC-DIGITAL_INTELLIGENCE-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "产教协同", "subtitle": "聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。", "body": "<p>专题可对接信息技术企业、平台型企业和行业数字化项目，围绕真实需求共建课程、训练平台、认证项目和应用场景。</p>\n<figure><img src=\"/uploads/blueprint/departments/information/images/img03.webp\" alt=\"数智技术竞赛与项目实践\"><figcaption>数智技术竞赛与项目实践</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/information/images/img03.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(68,81,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-DIGITAL_INTELLIGENCE-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题成果", "subtitle": "聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。", "body": "<p>成果展示可聚合技术竞赛、校企项目、平台建设、学生作品、数字化服务地方案例和跨专业应用成果。</p>", "imageUrl": "/uploads/blueprint/departments/information/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(69,82,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-GALLERY','upsert','approved','{"code": "BP-TOPIC-DIGITAL_INTELLIGENCE-GALLERY", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "图文资料", "subtitle": "聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。", "body": "<figure><img src=\"/uploads/blueprint/departments/information/images/img02.webp\" alt=\"数字技术服务场景\"><figcaption>数字技术服务场景</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/departments/finance/images/img01.webp\" alt=\"财经商贸数据应用场景\"><figcaption>财经商贸数据应用场景</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/information/images/img02.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(70,83,40,'BP-TOPIC-SMART_CONSTRUCTION-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-SMART_CONSTRUCTION-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "面向现代建造、工程管理、测绘应用和绿色施工，承接工矿建筑系的建筑工程方向。", "body": "<p>智慧建造专题以工矿建筑系建筑工程方向为核心，联动电子信息工程系的数字技术能力和财政经济系的项目管理、成本核算与供应链能力，展示现代建造、测绘应用、工程管理和绿色施工的综合育人路径。</p>\n<figure><img src=\"/uploads/blueprint/departments/mining-construction/images/img01.webp\" alt=\"工矿建筑系工程技术展示\"><figcaption>工矿建筑系工程技术展示</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/mining-construction/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(71,84,40,'BP-TOPIC-SMART_CONSTRUCTION-MAJORS','upsert','approved','{"code": "BP-TOPIC-SMART_CONSTRUCTION-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专业群布局", "subtitle": "面向现代建造、工程管理、测绘应用和绿色施工，承接工矿建筑系的建筑工程方向。", "body": "<p>关联系部：工矿建筑系承担建筑工程、测绘、施工组织和安全管理；电子信息工程系支撑工程数字化、数据采集和可视化展示；财政经济系支撑工程成本、项目运营与供应链管理。</p>\n<p>专题可展示建筑模型、工程测绘、智慧工地、绿色施工、安全教育、项目管理和工程类学生实践成果。</p>", "imageUrl": "/uploads/blueprint/departments/mining-construction/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(72,85,40,'BP-TOPIC-SMART_CONSTRUCTION-COOPERATION','upsert','approved','{"code": "BP-TOPIC-SMART_CONSTRUCTION-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "产教协同", "subtitle": "面向现代建造、工程管理、测绘应用和绿色施工，承接工矿建筑系的建筑工程方向。", "body": "<p>专题适合对接建筑施工、城市更新、测绘服务、工程咨询和数字建造企业，通过真实工程任务组织课程、实训和成果展示。</p>", "imageUrl": "/uploads/blueprint/departments/mining-construction/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(73,86,40,'BP-TOPIC-SMART_CONSTRUCTION-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-SMART_CONSTRUCTION-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题成果", "subtitle": "面向现代建造、工程管理、测绘应用和绿色施工，承接工矿建筑系的建筑工程方向。", "body": "<p>成果展示可聚合工程实践作品、技能竞赛、校企项目、服务地方建设案例和学生岗位能力成长记录。</p>", "imageUrl": "/uploads/blueprint/departments/mining-construction/images/img01.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(74,87,40,'BP-TOPIC-SMART_CONSTRUCTION-GALLERY','upsert','approved','{"code": "BP-TOPIC-SMART_CONSTRUCTION-GALLERY", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "图文资料", "subtitle": "面向现代建造、工程管理、测绘应用和绿色施工，承接工矿建筑系的建筑工程方向。", "body": "<figure><img src=\"/uploads/blueprint/departments/information/images/img04.webp\" alt=\"数字化技术支撑智慧建造\"><figcaption>数字化技术支撑智慧建造</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/departments/finance/images/img02.webp\" alt=\"项目运营与供应链管理能力\"><figcaption>项目运营与供应链管理能力</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/information/images/img04.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(75,88,41,'BP-TOPIC-CAMPUS_CULTURE-OVERVIEW','upsert','approved','{"code": "BP-TOPIC-CAMPUS_CULTURE-OVERVIEW", "category": "专题概况", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。", "body": "<p>同心校园文化专题作为创新育人专题之外的文化入口，汇聚学校形象、校园活动、学生成长、志愿服务、优秀校友、名师名匠和各系部文化品牌，形成统一的校园精神展示空间。</p>\n<figure><img src=\"/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg\" alt=\"校园文化与学校形象\"><figcaption>校园文化与学校形象</figcaption></figure>", "imageUrl": "/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(76,89,41,'BP-TOPIC-CAMPUS_CULTURE-MAJORS','upsert','approved','{"code": "BP-TOPIC-CAMPUS_CULTURE-MAJORS", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "系部融入", "subtitle": "以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。", "body": "<p>覆盖系部：工矿建筑系、财政经济系、电子信息工程系、医学护理系、旅游管理系。各系部可在此汇聚党建思政、技能成长、志愿服务、文化活动和学生风采。</p>\n<p>该专题不替代系部门户，而是作为学校层面的文化聚合页，让参观者在进入具体专业内容之前，先看到学校共同的价值表达。</p>", "imageUrl": "/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(77,90,41,'BP-TOPIC-CAMPUS_CULTURE-COOPERATION','upsert','approved','{"code": "BP-TOPIC-CAMPUS_CULTURE-COOPERATION", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "文化协同", "subtitle": "以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。", "body": "<p>专题可承接校地合作、社会服务、民族团结进步教育、学生社团、志愿服务和大型活动影像，形成更稳定的校园文化资料库。</p>\n<figure><img src=\"/uploads/blueprint/departments/tourism/images/img03.webp\" alt=\"学生服务与校园活动场景\"><figcaption>学生服务与校园活动场景</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/tourism/images/img03.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(78,91,41,'BP-TOPIC-CAMPUS_CULTURE-ACHIEVEMENTS','upsert','approved','{"code": "BP-TOPIC-CAMPUS_CULTURE-ACHIEVEMENTS", "category": "专题成果", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "文化成果", "subtitle": "以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。", "body": "<p>成果展示可包括校园文化品牌、学生成长故事、优秀毕业生、竞赛荣誉、社会服务案例和校园活动图文影像。</p>", "imageUrl": "/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(79,92,41,'BP-TOPIC-CAMPUS_CULTURE-GALLERY','upsert','approved','{"code": "BP-TOPIC-CAMPUS_CULTURE-GALLERY", "category": "图文资料", "source": "蓝图资料同步", "publishedAt": "2026-08-04", "title": "图文资料", "subtitle": "以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。", "body": "<figure><img src=\"/uploads/blueprint/departments/medical-nursing/images/img03.webp\" alt=\"学生成长与服务活动\"><figcaption>学生成长与服务活动</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/departments/finance/images/img03.webp\" alt=\"系部文化与实践活动\"><figcaption>系部文化与实践活动</figcaption></figure>", "imageUrl": "/uploads/blueprint/departments/medical-nursing/images/img03.webp", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T03:25:50.313856+00:00','admin','2026-08-04T03:25:50.313856+00:00','','blueprint-sync');
INSERT INTO "page_versions" VALUES(80,95,32,'finance-commerce-overview','upsert','approved','{"code": "finance-commerce-overview", "category": "专题概况", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "", "body": "<p>系部简介：财政经济系</p>\n<p>财政经济系于2008年组建，紧扣现代职业教育发展方向，锚定区域产业升级与乡村振兴需求，以“德商融合、数商兴农、赛商砺能、服商赋能”为核心路径，深耕商科人才培养与社会服务，开设大数据与会计、现代物流管理、电子商务三大专业，年均在校生约1600人。2022 年起与贵州工程应用技术学院联合培养财务管理本科班。</p>\n<p>专业建设成果丰硕：电子商务专业为毕节市人民政府授牌 &quot;毕节电子商务学院&quot;，专业群获评贵州省职业教育特色骨干专业群（优秀等次）；大数据与会计专业为省级骨干专业。加入全国直播电商职业教育集团等 5 个国家级产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体（成员单位120余家）。</p>\n<p>系部拥有贵州省农业电商产业扶贫协同创新中心、高水平乡村电商产教融合实训基地等省级项目 11 项，获批市级数商兴农人才团队、省级教学创新人才团队。先后荣获省级五好基层党组织、市级样板院系、全国五四红旗团支部、全国活力团支部等荣誉。</p>\n<p>育人成效显著：学生专升本上线率 93%、录取率89%。2025年荣获贵州省教学成果特等奖；技能大赛斩获国家级铜奖5项、省级一等奖12项，各级各类奖项累计400余项，为区域经济社会发展作出积极贡献。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img01.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img02.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img03.webp\" alt=\"专题图片\" /></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img01.webp", "contentType": "article", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(81,96,32,'finance-commerce-majors','upsert','approved','{"code": "finance-commerce-majors", "category": "专业群布局", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "专业群布局", "subtitle": "", "body": "<p>财经商贸电子商务专业群（省级特色骨干专业群 特色打造）</p>\n<p>以电子商务专业群（省级专业群验收优秀等次）为核心，整合大数据与会计（省级质量提升工程骨干专业）、现代物流管理（两年内完成数字化升级为智能物流技术专业），构建“电商引流+物流支撑+会计赋能”三位一体乡村振兴服务体系，精准对接贵州省数字经济、现代服务业及毕节市新型综合能源、山地特色农业、资源精深加工产业集群需求。</p>\n<p>专业群深耕区域特色打造差异化优势：大数据与会计聚焦能源财税、农产加工成本核算，嵌入 RPA 税务机器人等前沿工具；电子商务主攻乡村电商、民族文创电商、跨境电商，助力“黔货出山”；智能物流技术专业聚焦农村共配、服务毕节“1区8中心”快递物流体系建设，同步推进与京东深度合作，升级改造现有物流实训室为生产性智能物流配送中心，新建1-2个京东订单班，为专业数字化升级筑牢基础。</p>\n<p>进一步深化产教融合，推进订单培养模式，整合现有省级实训基地，开发活页式教材。构建“岗课赛证”融通课程体系，培养兼具“传统财经技能+数字技术应用+本土产业认知”的复合型人才，专业群将打造毕节中小企业财经服务、乡村振兴电商赋能、区域物流体系优化核心平台，为西部陆海新通道建设和毕节区域经济高质量发展提供坚实人才支撑。</p>\n<p>电子商务专业</p>\n<p>培养目标：本专业培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向互联网和相关服务、批发业、零售业的运营主管、全渠道营销主管、O2O 销售主管、智能客服主管、视觉营销设计师等岗位（群），能够从事数据化运营、网店运营、社群运营、行业运营、营销活动策划与执行、销售方案执行与优化、客户服务管理、视觉设计工作的高技能人才。</p>\n<p>核心课程：网店运营、数据化运营、社群运营、互联网销售、视觉营销设计、网络营销、零售门店O2O运营、农产品电商运营、跨境电子商务运营、短视频拍摄与直播运营。</p>\n<p>就业方向：本专业毕业生主要面向面向电子商务师、互联网营销师、营销员、市场营销专业人员、商务策划专业人员、品牌开发与运营专业人员、客户服务管理员等职业，运营主管、全渠道营销主管、O2O销售主管、智能客服主管、视觉营销设计师、互联网产品开发主管等岗位（群）就业和自主创业，从事相关工作。</p>\n<p>培养特色：竞赛成果：学生获全国职业院校技能大赛、挑战杯、“互联网+ ”双创赛奖项5 项、省赛 100 余项；对口就业：与京东、贵州卡妈等 15 家企业开展订单培养 350余人，就业率提升至98%以上；考证培训：面向退伍军人、新农人及返乡创业就业人员，开展乡村电商技能培训和职业体验2000 人次，开展互联网营销师等职业技能鉴定，考证通过率94%以上；获教育部产教融合校企合作典型案例；牵头成立东西部协作乡村电商行业产教融合共同体；教师打造了《黔西北农业职业经理人》省级优质课，培养高级农业经理人7人。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img04.webp\" alt=\"现代物流管理专业\" /><figcaption>现代物流管理专业</figcaption></figure>\n<p>培养目标：培养践行社会主义核心价值观，具备良好人文素养、数字素养与职业道德，掌握现代物流管理核心知识与技术技能的高技能人才。学生需熟练运用仓储管理系统、数据分析工具及智能物流技术，具备智慧仓配运营、物流运输调度、供应链协同管理等能力，能从事物流项目运营、数据分析、国际货运代理等工作，兼具可持续发展能力与创新创业意识。</p>\n<p>核心课程：构建“基础+核心+拓展”三层课程体系，核心课程包括智慧仓配运营、智慧运输运营、物流成本与绩效管理、采购与供应管理、物流营销与客户关系、国际货运代理实务、物流项目运营、物流系统规划与设计。课程融入大数据、人工智能等新技术，结合农产品电商运营仿真实训、物流数据采集与分析等实践内容，对接物流管理、供应链运营等职业技能等级证书考核要求。</p>\n<p>办学特色：产教融合深厚：与10余家企业共建校外实习基地，引入真实物流项目开展生产性实训，“数商兴农”人才团队助力区域产业发展。</p>\n<p>赛教融合突出：承办贵州省第二届职业技能大赛“物流与货运代理”赛项并获省赛金奖1项，学生在世界职业院校技能大赛全国决赛物流与供应链赛道中获铜奖1项、并先后获省赛一等奖2项，2025第八届一带一路暨金砖国家技能发展与技术创新大赛供应链管理赛项全国总决赛中获一等奖1项，专业教师先后累计指导学生获技能大赛奖项50余项。</p>\n<p>师资力量雄厚：拥有“双师型”教师占比91%的教学团队，含全国商贸服务业青年专家1人、市级高技能骨干人才1人、商贸物流专家3人及企业行业导师，主持立项30余项省级、市厅级教研科研课题。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img05.webp\" alt=\"专题图片\" /></figure>\n<p>证书体系完善：推行职业技能等级证书制度，学生可考取贵州省人力资源与社会保障厅认可的三级物流服务师（高级）、供应链管理师等证书。</p>\n<p>部分骨干教师</p>\n<p>就业方向：毕业生主要面向智慧仓配运营、智慧运输运营、生产物流管理等领域，可从事物流项目运营主管、物流数据分析员、国际货运主管、供应链管理师等岗位。就业单位涵盖京东、顺丰速运等知名企业及区域重点物流企业，可通过岗位实习实现就业衔接，也可自主创业开展物流相关服务业务。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img06.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img07.webp\" alt=\"大数据与会计专业\" /><figcaption>大数据与会计专业</figcaption></figure>\n<p>培养目标：大数据与会计专业紧跟会计行业数字化、智能化转型要求，立足毕节、服务贵州经济和社会发展为目标，培养德、智、体、美、劳全面发展，践行社会主义核心价值观，具备一定文化水平、良好职业道德和人文素养，掌握本专业知识和技术技能，具备职业综合素质和行动能力，主要面向中小型企业及会计师事务所等中介服务机构，能够胜任出纳、会计核算、税务管理、成本管理、财务数据分析等工作，既精通传统财务功底，又能驾驭财务大数据分析工具，具有创新精神的高素质技术技能型人才。</p>\n<p>核心课程：企业财务会计、智能化成本核算与管理、智能化税费申报与管理、会计信息系统应用、管理会计实务、财务大数据分析、Python开发与财务应用、企业内部控制。</p>\n<p>就业方向：毕业生可选择专升本或到行政事业单位、各类中小微企业、会计师事务所等单位，从事出纳、会计核算、纳税申报、成本管理、财务管理、大数据分析、财务机器应用与开发等岗位相关工作。</p>\n<p>办学特色：大数据与会计专业（原名会计电算化）专业于2008年开始招生，2014年被学校评为重点专业，2017年被贵州省教育厅评为省级骨干专业，2024年大数据与会计专业人才培养方案被贵州省教育厅评为省级示范性人才培养方案。经过10年积淀，办学成果显著。学生参加国家级、省级技能大赛获奖44个，其中获国家三等奖 4个， 获省级一等奖 12 个，二等奖4个，三等奖24个；教师参加金砖国家职业技能竞赛获二等奖2个，三等奖2 个，教师参加贵州省教学成果奖申报获一等奖1个，主持省级、校级科研项目16项，发表科研论文30多篇，开展财税知识培训1000多人次，专业实力雄厚，办学成果显著。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img08.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img09.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img10.webp\" alt=\"专题图片\" /></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img04.webp", "contentType": "article", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(82,97,32,'finance-commerce-training','upsert','approved','{"code": "finance-commerce-training", "category": "实训场景", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "实训场景", "subtitle": "", "body": "<p>贵州省兴黔富民行动计划项目——高水平乡村电商产教融合实训基地</p>\n<p>围绕毕节建设贯彻新发展理念示范区历史使命，聚焦乡村振兴和人力资源开发，学院瞄准区域农业全产业链数字化转型新机遇，围绕新经济、新商业、新电商，融入人工智能、物联网、大数据、虚拟现实等新技术，构筑线上线下有机融合的“毕货网行”双轨系统，拟建“高水平乡村电商产教融合实训基地”(以下简称基地)，按照“深化产教融合新模式、对接产业发展新定位、融合“云物大智”新技术、共创协同发展新标杆”的总体建设思路，建立“1 基地+4 内容+6 功能+X 中心”的产教融合服务体系，构建一个集教学科研、职业培训、技能竞赛和社会服务为一体的人才培养、技术创新、实务对接、精准扶贫与创新服务高水平专业化产教融合实训基地。探索建立发展股份制、混合所有制产权制度，形成产教深度融合的校企命运共同体。服务我校电子商务省级特色骨干专业群，重点是培养“懂财会、会技术、明市场、精电商、能运营、善管理、可创业”的复合型本土化高素质“新农商”人才。</p>\n<p>本项目建成六中心一平台，其中 1+X 考培中心辐射全校所有 1+X 证书制度试点（15 个），同时兼顾校内外培训，目前在中心已开展社会培训 500 人次，考证合计 300 人次，针对四类人员培训（退伍军人、农民工、下岗职工、普通高中毕业生）500 人次；京东校园实训中心目前组织开展真实订单业务，截止目前已完成订单 3582752 单，2022 年产生社会效益 42.6 万元，2023 年至今产生社会效益 26.6 万元；乡村电商网络营销与直播实训中心连续开展四届网络直播大赛（2020 年——2023 年），主要直播品类为家乡农特产品及其他类目引流品，用实际行动服务乡村振兴，产生总经济效益 36481 元；与重庆诺维奇进出口贸易有限公司开展真实外贸业务，产生订单国家10余个，产生外贸订单销售额2679.65美金；职教扶贫农村电商，助力乡村振兴，辐射带动区域产</p>\n<p>业高质量发展。</p>\n<p>贵州省技能贵州建设项目——乡村电商物流生产性产教融合实训基地</p>\n<p>基地立足服务贵州省“乡村振兴、大数据、大生态”三大战略目标，围绕“四新”主攻“四化”，以服务区域现代农业全产业链“种植、养殖、加工、检测、销售、物流、客服”中农产品上行及工业品下乡为出发点，持续引入京东、顺丰等头部电商物流企业真实工作任务和生产性实训业务，打造创新型教师团队、推进“岗课赛证”综合育人，建立产学研用技术创新高地，助力毕节乡村电商及配套物流体系的发展完善，将基地打造成为“五大标杆”。</p>\n<p>打通农产品上行与工业品下乡流通链路，降低物流成本，带动涉农主体增收。依托“岗课赛证”定向培育电商物流技能人才，同步开展社会化培训，培育本土创业带头人。打造双师团队，开发特色实训课程，产出课题、论文、软著等科研成果。建成全链条生产性实训平台，实现多功能融合，为乡村涉农主体提供技术服务。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img11.webp\" alt=\"互联网+财务云实践基地\" /><figcaption>互联网+财务云实践基地</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img12.webp\" alt=\"互联网+财务云实践基地\" /><figcaption>互联网+财务云实践基地</figcaption></figure>\n<p>乡村电商物流生产性产教融合实训基地</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img13.webp\" alt=\"乡村电商物流生产性产教融合实训基地\" /><figcaption>乡村电商物流生产性产教融合实训基地</figcaption></figure>\n<p>电子商务课程培训</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img11.webp", "contentType": "scene", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(83,98,32,'finance-commerce-cooperation','upsert','approved','{"code": "finance-commerce-cooperation", "category": "产教协同", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "产教协同", "subtitle": "", "body": "<p>数商兴农：产教协同，构建特色发展格局</p>\n<p>紧扣“数商兴农”战略与“黔货出山”需求，系部深化专业建设与产教融合，走出特色发展之路。优化专业布局，暂停同质化专业，打造电子商务特色骨干专业群，建成贵州省农业电商扶贫协同创新中心、高水平乡村电商产教融合实训基地等 11 项省级项目，组建毕节市数商兴农人才团队、贵州省电子商务教师教学创新团队。搭建高能级产教平台，受邀加入5个全国性产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟等协作载体，与京东实现 “课堂即岗位” 深度合作，与顺丰联合推进直播助农项目，将数字商务技能培养与乡村振兴需求精准对接，相关成果荣获贵州省教学成果特等奖。</p>\n<p>服商赋能：扎根地方，扛起区域发展责任</p>\n<p>立足毕节区域发展需求，系部以“服商赋能”为导向，全面强化社会服务能力。10名教师入选毕节市商贸流通领域专家库（全市共 29人），4 人入选市文化旅游培训师资库，拥有科技特派员、毕节市拔尖人才、高级农业职业经理人等一批行业骨干。聚焦商贸流通、乡村电商等领域，开展技能培训与技术服务，助力地方产业升级；组建学生助农团队两年来，帮助毕节农特产品实现销售转化 30 余万元，成功破解织金县竹荪电商运营技术难点，获织金县商务局感谢函；协助推广毕节市航空航天展，获主办单位四川商会致谢，相关事迹被毕节日报等多家媒体大版面报道。通过东西部协作、校地联动，将商科人才培养、技术服务与区域电子商务、现代物流产业发展深度绑定，在数商兴农、商贸人才培育等领域持续贡献力量，赢得广泛社会赞誉。</p>\n<p>对接产业</p>\n<p>系部深度锚定贵州省及毕节市现代商贸、数字经济、现代物流、财税服务、农特产品产销等重点产业链，精准对接产业岗位需求，深化校企协同育人，构建全链条、全覆盖的产业对接体系，实现专业与产业、教学与岗位、育人与就业精准适配。</p>\n<p>（一）核心对接产业领域</p>\n<p>重点对接数字电商产业、现代供应链物流产业、智能财税服务产业、乡村农特产品商贸产业、进出口贸易产业、智慧供应链科技产业六大核心产业，贴合数字经济发展浪潮与粤黔东西部协作发展布局，聚焦地方数商兴农、乡村振兴、商贸流通升级核心需求。</p>\n<p>（二）重点合作企业单位</p>\n<p>深耕行业龙头企业与地方重点国企、优质本土企业合作，合作单位涵盖全国头部电商物流企业、行业科技龙头、地方国资商贸企业、农业龙头企业及专业财税服务机构，核心合作主体包括：京东集团、阿里巴巴（中国）教育科技、贵州顺丰速运、江苏京东信息技术、贵州京邦达供应链、珍岛信息技术、广州大洋教育、中联集团教育科技、重庆诺维奇进出口贸易；毕节市商贸物流发展集团、毕节农投实业、毕节十八农产品物流园、贵州电子商务云、贵州卡妈农特产品开发、毕节珍好农特产品开发、毕节家乡美农业综合开发、毕节山宝农业、毕节绿色畜牧科技；贵州嘉禾华政税务师事务所、毕节水务、厦门网中网软件、贵州誉佳朗商贸等，全方位保障实习实训、岗位就业、项目研发、师资共建等产教融合落地。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img14.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img15.webp\" alt=\"产教融合平台\" /><figcaption>产教融合平台</figcaption></figure>\n<p>平台建设层级高、数量多，累计建成贵州省电子商务协同创新中心、物流生产性产教融合实训基地等省级平台项目11项；获批毕节市数商兴农人才团队、省级教学创新人才团队。行业影响力持续攀升，2024年成功加入全国直播电商、现代物流与供应链、财税服务等5个国家级行业产教融合共同体；牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体，共同体汇聚120余家成员单位，由全国电商教指委、毕节市教育局、商务局、粤黔协作工作组权威指导，成为区域产教融合标杆平台。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img16.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img17.webp\" alt=\"校企合作订单班\" /><figcaption>校企合作订单班</figcaption></figure>\n<p>京东订单班</p>\n<p>为深化校企合作，充分发挥学校和企业双方的优势，推进电子商务专业建设和教学改革，完善实践实验教学体系，使学生在顶岗实训中内化专业知识，发挥高校为社会服务的功能，为企业培养更多高素质、高技能的应用型人才，同时学生在实训过程中能够获取一定的经济收入，院校与京东充分沟通，《客服实战跟岗实训》由学校教师和京东教师联合授课，把京东企业真实客服业务引入课堂，充分利用京东校企合作实训室建设基础设施和学院师资和教学资源，与企业行业共同培养客户服务相关人才。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img18.webp\" alt=\"京东订单班授课\" /><figcaption>京东订单班授课</figcaption></figure>\n<p>顺丰订单班</p>\n<p>为深化校企协同育人机制，提升电商专业学生实践应用能力与岗位适配素养，毕节职业技术学院财经经济系联合顺丰企业打造顺丰班赋能电商专业体系。通过明确实践方向、优化团队架构、强化资源保障，为系列实践项目规范化推进奠定坚实基础。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img19.webp\" alt=\"顺丰订单班授课\" /><figcaption>顺丰订单班授课</figcaption></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img14.webp", "contentType": "activity", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(84,99,32,'finance-commerce-masters','upsert','approved','{"code": "finance-commerce-masters", "category": "名师名匠", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "名师名匠", "subtitle": "", "body": "<p>张进华，男，41岁，汉族，中共党员，副教授。先后担任财政经济系团总支书记、副主任、系主任等职务，现任毕节职业技术学院教务处长，贵州省高等职业学校办学能力评价专家、贵州省职教学会职业教育教学专家、市管专家、市拔尖人才、毕节市“数商兴农”人才团队负责人、贵州省电子商务教师教学创新团队负责人、贵州省电子商务特色骨干专业群负责人（优秀等次）、贵州省农业电商产业扶贫协同创新中心负责人;获全国商贸服务业青年专家、中国商业会计学会慧心育人奖、贵州省“甲秀之光”访问学者、毕节市商贸服务重点领域专家库专家等荣誉称号;担任“畅享杯”全国财经商贸类专业教师数字技术技能大赛-直播营销竞赛裁判、贵州省职业院校技能大赛教学能力比赛裁判、广东省等省级职业院校技能大赛（世界职业院校技能大赛选拔赛）裁判。</p>\n<p>主持成果荣获2024年贵州省职业教育教学成果奖特等奖;主持成果《育训并举 多方协同 平台赋能：西部山区乡村振兴人才培养模式创新实践》荣获2025年教育赋能乡村振兴典型案例、《乡村振兴背景下本土化复合型乡村电商人才培养研究与创新实践》荣获2025年贵州省职业教育典型案例；荣获省级以上奖项10项；主持市厅级以上科研项目5项；发表论文8篇。</p>\n<p>李洁，女，33岁，汉族，硕士研究生，毕节职业技术学院财政经济系电子商务专业专任教师，主攻短视频剪辑与直播运营方向。</p>\n<p>2025年参加贵州省第二届职业技能大赛直播带岗特色赛项，获得金牌，被授予“贵州省技术能手”称号；2024年在毕节市第三届职业技能大赛中斩获电子商务师一等奖；多次担任市级直播电商大赛裁判；深耕创新创业人才培养，指导学生参与全国职业院校技能大赛选拔赛、“挑战杯”等赛事，斩获多项省、市级奖项，多次获评优秀指导教师。坚持以赛促教、教研相融，积极投身地方电商人才培养与乡村电商服务工作。</p>\n<p>先后主编教材《农产品短视频拍摄与直播运营》《电子商务法律法规》，参编《短视频拍摄与直播运营》《消费者行为分析》等多部校级教材</p>\n<p>社会服务方面，立足毕节本地乡村振兴需求，持续开展电商助农与技能培训工作。助力大屯彝族乡三观村打通柑橘线上销售渠道；赴赫章县企业开展直播技能培训；面向七星关区多个社区普及直播电商知识；配合毕节市人社局面向应届毕业生、失业青年开展创新创业课程培训，持续为地方培育电商人才，以专业能力服务地方产业发展。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img20.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img21.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img22.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img23.webp\" alt=\"专题图片\" /></figure>\n<p>何园园，女，39岁，汉族，中共党员，副教授、物流专业带头人、一级物流师（高级技师），毕节市高技能骨干人才、毕节市商贸服务重点领域专家库专家。深耕物流教学与技能竞赛领域，担任第三届全国职业技能大赛、省级技能大赛等多项赛事裁判与技术专家，先后荣获贵州省职业院校教学能力大赛三等奖、“智慧物流”教师赛省赛二等奖，“京津冀沪”交通职业教育集团联盟教师赛一等奖，指导学生获各级各类赛事奖项20余项，囊括一带一路金砖供应链管理赛项全国总决赛一等奖、全国物流仿真设计大赛一等奖、贵州省第二届职业技能大赛物流与货运代理赛项省赛金奖等多项荣誉；曾荣获校级“优秀教师”“优秀辅导员”“优秀党务工作者”、毕节市“师德标兵”等荣誉。</p>\n<p>主持省级技能贵州项目乡村电商物流生产性产教融合实训基地、贵州省教育厅教育科学规划课题、贵州省教育厅职业教育课题、市委重大课题、市社科课题等10余项市厅级科研项目，聚焦毕节农产品物流、电商物流本土产业发展方向，发表论文10余篇。</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img20.webp", "contentType": "person", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(85,100,32,'finance-commerce-alumni','upsert','approved','{"code": "finance-commerce-alumni", "category": "优秀校友", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "优秀校友", "subtitle": "", "body": "<p>基础信息栏（基层奉献类校友）</p>\n<p>姓名：穆桥林</p>\n<p>入学：2021年9月</p>\n<p>毕业年份：2024年6月</p>\n<p>专业：大数据与会计</p>\n<p>荣誉标签</p>\n<p>优秀学生干部、国家奖学金获得者、基层工作者</p>\n<p>个人简介</p>\n<p>穆桥林，贵州金沙人，2024 届大数据与会计专业毕业生，中共预备党员。求学期间身兼多项学生工作，平衡学业与服务工作，屡获国家奖学金、省优秀毕业生等荣誉。毕业后投身西部计划，在纳雍县乡镇综合治理中心开展矛盾调解、信访接待、禁毒宣传等工作，坚守基层一线，以青春力量守护地方平安稳定。</p>\n<p>四、校友寄语</p>\n<p>青年当向基层而行，把所学付诸乡土。愿学弟学妹坚守理想、脚踏实地，勇担时代使命，在祖国需要的地方扎根生长，书写属于青年的青春答卷。</p>\n<p>基础信息栏</p>\n<p>李会，2018年9月---2021年7月 财务管理专业。</p>\n<p>荣誉标签</p>\n<p>曾获：“国家励志奖学金”、省级“优秀毕业生”、“优秀学生干部”、“三好学生”、“优秀共青团干部”、“青春思辩-最佳辩手”、第六届中国“互联网+”大学生创新创业大赛职教赛道银奖等荣誉。</p>\n<p>个人简介</p>\n<p>李会，女，汉族，中共党员。于2018年9月入学毕节职院，2021年7月毕业。同年9月升学至凯里学院读本科，本科在校期间曾获：“优秀毕业生”、“三好学生”、一等奖学金等荣誉；</p>\n<p>2023年7月毕业后考入银行系统工作，2024年9月选择从银行裸辞返乡投身基层工作。从村主任助理逐步成长为村副主任，一直坚守乡村基层治理一线，党建引领扎实开展民生服务、平安建设、群众宣传等工作；扎根田间地头，奔走农户家中，坚持把一件件群众小事做实，累计服务两千余人。将财经专业素养融入乡村发展，扎根乡土奉献青春，用实际行动诠释新时代财经学子的责任与担当。</p>\n<p>校友寄语</p>\n<p>在困苦磨砺中练就不屈不挠的眼神，从头再来的魄力；在心中深耕成长的踏实、力量和智慧。愿各位校友永葆热忱初心，一如既往，乘风破浪。</p>\n<p>基础信息栏</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img24.webp\" alt=\"基础信息栏\" /><figcaption>基础信息栏</figcaption></figure>\n<p>曹静 2018-2021 财务管理</p>\n<p>荣誉标签</p>\n<p>2018-2019年获学院优秀干部</p>\n<p>2018-2019年获国家励志奖学金</p>\n<p>2019-2020年获学院优秀会长</p>\n<p>个人简介</p>\n<p>2018级财务管理1班学生，曾担任班级资助委员，院社会实践部部长、ERP商战协会会长。本人性格热情开朗，对待工作积极主动，认真负责。在校期间积极参与学校组织的各项活动，积极进取不断提升自己。</p>\n<p>校友寄语</p>\n<p>大学是充满无限可能的 “成长副本”， 只管努力珍惜、勇敢向前。我们不去想是否会成功。既然选择了，便只顾风雨兼程，我们不必强求，但不可不求。</p>\n<p>基础信息栏（基层奉献类校友）</p>\n<p>刘娇，2017年9月入学，2020年6月毕业，会计专业</p>\n<p>荣誉标签</p>\n<p>“文明礼仪”征文比赛一等奖、</p>\n<p>三等奖学金、</p>\n<p>优秀学生干部、</p>\n<p>国家励志奖学金获得者</p>\n<p>优秀毕业生。</p>\n<p>个人简介</p>\n<p>本人在校期间，与同学友好相处，尊师敬长，同时担任班内团支部书记一职，做好“纽带”工作，期间也大大提升了自身综合素质、多方面学习及发展的能力，不怕苦肯吃苦，在校积蓄成长力量，参加工作便自带较强的环境适应能力、抗压能力，工作顺利。</p>\n<p>校友寄语</p>\n<p>不管走了多远，提起母校名字，还是会心头一暖，这里是梦开始的地方，也是永远的家。</p>\n<p>祝愿母校枝繁叶茂，桃李芬芳；</p>\n<p>祝各位师长身体健康，工作顺利；</p>\n<p>祝各位校友前程似锦，万事顺意；</p>\n<p>祝学弟学妹们学业有成，不负韶华！</p>\n<p>基础信息栏（行业精英类校友）</p>\n<p>付绍翔｜2018年9月入学/2021年6月毕业｜会计</p>\n<p>荣誉标签</p>\n<p>国家奖学金获得者、贵州省“三好学生”、2021届贵州省“优秀毕业生”、2019年全省大中专学生志愿者暑期“三下乡”社会实践活动先进个人、优秀学生干部。</p>\n<p>个人简介</p>\n<p>付绍翔，中共党员，在校期间曾担任财政经济系团总支副书记、学生会主席、毕节职院ERP商战协会副会长。2023年在佛山市禅城区发展和改革局工作，2024年担任佛山市企业征信建设促进会办公室主任。</p>\n<p>校友寄语</p>\n<p>情系毕职院，根在财经系。感恩母校悉心培育，祝愿母校宏图永续，财经系薪火绵延、广育英才。</p>\n<p>基础信息（基层奉献类）</p>\n<p>郎廷，2018年9月入学，2021年7月毕业，财政经济系财务管理专业</p>\n<p>荣誉标签</p>\n<p>优秀学生干部、国家励志奖学金获得者、基层工作者</p>\n<p>三、个人简历</p>\n<p>求学期间勤奋笃学，曾多次荣获奖学金、国家励志奖学金，履职学生干部，积极参与校园服务与实践。毕业之后响应号召参军入伍，两年军旅生涯磨砺意志、锤炼作风。退伍后返乡扎根基层岗位，踏实履职尽责，以实干践行青年使命，在基层沃土锤炼成长。</p>\n<p>四、校友寄语</p>\n<p>昔日校园相伴，今朝各自扬帆。祝愿全体校友眼里有光，心中有梦，不负韶华，前路坦荡，期待他日再聚，共叙当年！</p>\n<p>一、基本信息</p>\n<p>秦大红，财政经济系2023级大数据与财务管理专业，曾担任财政经济系学生会班级联络部部长，班级副班长兼任生活委员，校级排球协会会长。曾获国家励志奖学金、校级优秀共青团员、校级优秀学生干部，毕节职业技术学院第二届职业规划大赛优秀奖。</p>\n<p>二、荣誉标签</p>\n<p>国家励志奖学金、优秀学生干部、优秀共青团员，行业骨干。</p>\n<p>三、个人简介</p>\n<p>在校期间深耕专业学习，专业排名前10%，连续两年获得国家励志奖学金。积极参与社会实践，多次获评校级荣誉。扎实掌握专业理论知识，积极参与学科竞赛与校园实践。主动参与班级、社团工作，责任心强，善于协作交流。持续提升综合能力，保持求知进取的态度，为步入社会夯实基础。</p>\n<p>四、校友寄语</p>\n<p>日复一日，那些看似冷漠的日子会像你展示坚持的意义，没有一朵花从一开始就是花，世界盛大灿烂 欢迎出发。</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img24.webp", "contentType": "person", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(86,101,32,'finance-commerce-students','upsert','approved','{"code": "finance-commerce-students", "category": "优秀学生", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "优秀学生", "subtitle": "", "body": "<p>座右铭：不负韶华砥砺前行 心怀热爱奔赴万里</p>\n<p>白金妹，毕节职业技术学院财政经济系现代物流管理专业2024级高职学生，布依族，共青团员。曾获国家奖学金，荣获2025年度毕节职业技术学院“优秀学生干部”称号、2025年度毕节职业技术学院“三好学生”称号，始终秉持勤学笃行、技能成才的理念，深耕专业学识，锤炼职业技能，全面提升综合素养，学业成绩优异，荣获国家奖学金；认真履行学生工作职责，服务师生、务实担当，先锋模范作用突出。深耕物流专业技能领域，潜心备战各级高水平专业赛事，勇于拼搏、精益求精，在各类职业技能竞赛中屡获佳绩：荣获2025年世界职业院校技能大赛总决赛争夺赛物流与供应链赛道铜奖、2025年贵州省职业院校技能大赛智慧物流（高职组）一等奖、2024年“百蝶杯”第十届全国大学生物流仿真设计大赛（高职组）物流系统规划设计赛道二等奖。立足高职学子初心，以实干践行使命，以奋进诠释担当，充分展现新时代技术技能人才勤学上进、技能过硬、昂扬向上的精神风貌，用实际行动彰显新时代高职学子的责任与担当。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img25.webp\" alt=\"专题图片\" /></figure>\n<p>座右铭：道理在书上，践行在心中，知行合一，可为君子</p>\n<p>卢義，毕节职业技术学院财政经济系现代物流管理专业 2023 级高职学生，穿青人，共青团员。曾获国家奖学金；2025 年度毕节职业技术学院 “优秀学生干部” 称号；第十九届 “挑战杯” 贵州省大学生课外学术科技作品竞赛三等奖、2025 年世界职业院校技能大赛总决赛争夺赛物流与供应链赛道铜奖。作为2023级现代物流管理一班学习委员，他深刻认识专业知识的重要性，在校期间获得过专业第一的成绩。赛场之上，他多次担任竞赛队长，统筹协调、凝心聚力，带领队员并肩钻研、互帮共进，充分彰显出色的组织能力与团队担当；课余之余，他热爱体育锻炼，入选系部篮球队，在竞技拼搏中深刻感悟团结协作、凝心聚力的意义。身为班级学习委员，深刻认识专业知识的重要性，在校期间获得过专业第一的成绩。他立足专业、奋勇争先，以扎实的学识功底、过硬的职业技能践行新时代职业教育使命，充分展现新时代高职青年朝气蓬勃、奋发向上的良好精神风貌。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img26.webp\" alt=\"专题图片\" /></figure>\n<p>座右铭：以赛促学，以行践知</p>\n<p>游盈盈，女，汉族，共青团员，毕节职业技术学院财政经济系 2023 级电子商务专业高职生，现任校学生会主席、班级学习委员兼副团支部书记。</p>\n<p>学业成绩稳居班级第一，综合考评、第二课堂均位列专业第一，25门必修课平均分93分。曾荣获国家奖学金、校级三好学生称号。专业技能扎实，先后斩获贵州省职业院校技能大赛电子商务赛项一等奖、毕节市电商直播大赛一等奖、贵州省乡村旅游创客大赛创意设计组一等奖、贵州省高校团支部“微团课”竞赛二等奖等多项省市级荣誉。</p>\n<p>牵头策划校园电商文化节，搭建班级学习互助平台，统筹学生会与团务工作，服务同学、实绩突出，是全面发展、品学兼优的优秀学生代表。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img27.webp\" alt=\"专题图片\" /></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img25.webp", "contentType": "person", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(87,102,32,'finance-commerce-achievements','upsert','approved','{"code": "finance-commerce-achievements", "category": "专题成果", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "专题成果", "subtitle": "", "body": "<p>教学改革成果：</p>\n<p>财政经济系教学改革成效显著，2025年斩获贵州省教学成果特等奖，登顶省级教学改革最高荣誉。贵州地处我国西南腹地，曾是全国脱贫攻坚的主战场，毕节贫困人口最多、贫困面最广、贫困程度最深，是贵州脱贫攻坚的主阵地。攻坚克难，关键在人才。毕节职业技术学院是毕节市唯一的综合性高职院校，肩负为西部山区发展培养高素质技术技能人才的使命，从2015年开始，针对西部山区技能人才培养中存在的思政教育价值引领不够、实践教学资源供给不足、专业交叉融合培养不实等问题，以毕节市人民政府为学校授牌毕节电子商务学院、贵州省农业电商产业扶贫协同创新中心建设为契机，依托“毕节试验区职业教育助推农村电商融合发展的探索与实践”等课题研究，联合东部对口帮扶院校、行业企业与联建村，系统调研、分析、研判、设计、试点、总结，于2018年制定《毕节职业技术学院数字新农人培养行动方案》并付诸实施。学校先后培养了近万名本土技术技能人才，学生获全国职业院校技能大赛（世界职业院校技能大赛总决赛争夺赛）等奖项30余项，毕业生陈燕创办农产品电商企业带动51户农民致富并当选纳雍县人大代表，育人成效入选2025年教育赋能乡村振兴典型案例、教育厅职业教育典型案例，全国人大常委会副委员长、民革中央主席郑建邦对学校学生培养成效给予高度评价；建成省级乡村电商特色骨干专业群、生产性产教融合实训基地、电子商务教师教学创新团队等省部级项目8项，牵头开发的《农业经理人职业技能标准》被菲律宾采用为国家标准；获全国五四红旗团支部、贵州省脱贫攻坚先进集体等荣誉称号；开展各类非遗、新农人培训超3500人次，推动毕节农产品销售800多万元，助力卡妈集团等15家本土企业营收增长超3.5亿元；成果获50多所院校借鉴、中央电视台新闻联播等30余家媒体报道；成果荣获2024年贵州省职业教育教学成果奖特等奖。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img28.webp\" alt=\"贵州省职业教育质量提升计划项目——骨干专业（大数据与会计）\" /><figcaption>贵州省职业教育质量提升计划项目——骨干专业（大数据与会计）</figcaption></figure>\n<p>大数据与会计创新构建了 “课岗证赛融通、三步实训、三个一体化”的人才培养模式，形成了课、证、岗、赛深度融合的课程体系，打造了一支业务强、技能精的专兼职教师队伍，科研与社会服务能力逐步提高。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img29.webp\" alt=\"贵州省职业教育质量提升计划项目-骨干专业\" /><figcaption>贵州省职业教育质量提升计划项目-骨干专业</figcaption></figure>\n<p>兴黔富民行动计划建设项目——《基础会计》精品在线开放课程</p>\n<p>《基础会计》是省级“兴黔富民行动计划”立项建设的精品在线开放课程，目前已经验收完成并投入使用，作为会计、财务管理专业的核心基础课，同时也是省级电子商务专业群共享平台课程，为后续专业学习筑牢理论与技能根基，助力培养高素质财会技能型人才。</p>\n<p>课程紧扣职业教育改革要求与行业发展需求，以“任务引领、资源核心、学用融合、思政铸魂”为建设理念，构建了多元化教学资源体系。现已建成50个微课视频、12个技能点动画、473道习题及491道考核试题，配套教学PPT、108页活页式电子教材和虚拟仿真实训平台，通过“筑梦财经 APP ”、学习通等实现资源共享，支持碎片化学习与沉浸式实训。真正实现 “教学相长、产教融合、服务地方”的建设目标，是财会入门学习者与行业从业者的优质学习资源。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img30.webp\" alt=\"兴黔富民行动计划建设项目--《基础会计》精品开放课程\" /><figcaption>兴黔富民行动计划建设项目--《基础会计》精品开放课程</figcaption></figure>\n<p>贵州省技能贵州建设项目——《农业职业经理人经营管理实务》省级优质课</p>\n<p>该课程是电子商务省级特色骨干专业群平台共享课。课程立足贵州乡村振兴，搭建一门基于“岗课赛证+数字赋能”模块化的课程资源建设平台，以“课程教学团队、课程资源、实践条件、课程实施、课程评价、数字应用”为课程开发建设抓手，始终坚持立德树人，推进“三教改革”的课堂革命改革，力争建设一门对接贵州山地乡村振兴省内一流《农业职业经理人经营管理实务》特色品牌课程，发挥示范带动作用，促进人才质量培养的提高，提升服务乡村振兴人才培养培训能力水平。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img31.webp\" alt=\"贵州省技能贵州建设项目—《农业职业经理人经营管理实务》省级优质课\" /><figcaption>贵州省技能贵州建设项目—《农业职业经理人经营管理实务》省级优质课</figcaption></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img28.webp", "contentType": "achievement", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(88,103,32,'finance-commerce-competitions','upsert','approved','{"code": "finance-commerce-competitions", "category": "技能大赛", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "技能大赛", "subtitle": "", "body": "<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img32.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img33.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img34.webp\" alt=\"专题图片\" /></figure>\n<p>技能大赛补充资料</p>\n<p>——赛商砺能：以赛促学，彰显育人实效</p>\n<p>坚持“以赛促学、以赛砺能”，将技能竞赛作为提升人才实战能力的重要抓手。组建会计协会、直播运营协会等6个专业型技能社团，完善内训机制，强化实战训练。近五年来，学子在各类赛事中捷报频传，斩获国家级职业院校技能大赛奖项3项、国家级行业赛20余项，省级技能大赛一等奖13项（含6项代表贵州省参赛项目）及其他省级奖项百余项；教师在教学能力大赛、青教赛等赛事中收获校级一等奖5次、省级奖项8次。系部多次圆满承办省级重要赛事，包括3次贵州省职业院校技能大赛-市场营销赛项、4项贵州省第二届职业技能大赛赛项，4名教师获评该赛事“表现突出场地经理”，1人获评“表现突出工作人员”，输出菲律宾《农业经理人》职业技能标准等标志性成果。</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img35.webp\" alt=\"2025年毕节职业技术学院直播大赛\" /><figcaption>2025年毕节职业技术学院直播大赛</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img36.webp\" alt=\"2025年毕节职业技术学院直播大赛\" /><figcaption>2025年毕节职业技术学院直播大赛</figcaption></figure>\n<p>毕节市第四届电商直播大赛</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img37.webp\" alt=\"毕节市第四届电商直播大赛\" /><figcaption>毕节市第四届电商直播大赛</figcaption></figure>\n<p>2025年贵州省职业院校师生技能大赛</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img38.webp\" alt=\"2025年贵州省职业院校师生技能大赛\" /><figcaption>2025年贵州省职业院校师生技能大赛</figcaption></figure>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img32.webp", "contentType": "activity", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(89,104,32,'finance-commerce-honors','upsert','approved','{"code": "finance-commerce-honors", "category": "荣誉资质", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "荣誉资质", "subtitle": "", "body": "<p>1.毕节市数商兴农人才团队</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img39.webp\" alt=\"1.毕节市数商兴农人才团队\" /><figcaption>1.毕节市数商兴农人才团队</figcaption></figure>\n<p>毕节市数商兴农人才团队</p>\n<p>2.东西部协作乡村电商行业产教融合共同体、全国智慧物流与供应链行业产教融合共同体副理事长单位、贵州数智财税行业产教融合共同体副理事长单位</p>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img40.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img41.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img42.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img43.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img44.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img45.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img46.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/finance-commerce/images/img47.webp\" alt=\"3.获2024年贵州省职业教育教学教学成果奖\" /><figcaption>3.获2024年贵州省职业教育教学教学成果奖</figcaption></figure>\n<p>视频资料（专业特色，可于所在区域屏幕循环播放）</p>\n<p>通过网盘分享的文件：毕节职院成果奖成品8.mp4</p>\n<p>链接: https://pan.baidu.com/s/1DItiFZTOyGxOXj73rISivw 提取码: 9fk7</p>\n<p>--来自百度网盘超级会员v1的分享</p>", "imageUrl": "/uploads/blueprint/topics/finance-commerce/images/img39.webp", "contentType": "honor", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(90,105,37,'modern-agriculture-overview','upsert','approved','{"code": "modern-agriculture-overview", "category": "专题概况", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "专题概况", "subtitle": "", "body": "<p>系部简介：农业工程系</p>\n<p>农业工程系办学历史可追溯到1956年贵州省毕节农业学校，近年来先后获批贵州省第一批、第二批高水平专业群，全省先进基层党组织。现有专业教师50人，其中，教授3人，副教授17人，讲师15人；博士研究生1人、硕士研究生27人；“双师型”教师38人，中华优秀茶教师1人，省级职教名师2人，贵州省五一劳动奖章1人，贵州省技术能手5人，毕节市管专家3人。省级技能大师工作室1个、省级劳模和创新工作室1个、省级名匠工作室1个和毕节市数字育训人才团队1个。</p>\n<p>目前开设畜牧兽医、中草药栽培与加工技术、农产品加工与质量检测、茶叶生产与加工技术和园林技术等5个高职专业，畜牧兽医1个中技专业，其中畜牧兽医专业为省级特色骨干专业。在校生1750人，学生平均就业率为98.2％，累计培养学生20000余人。近三年师生参加全国、省、市技能大赛获奖100余项。</p>\n<p>牵头成立毕节生态食品产业市域产教联合体，加入中国智慧养猪业产教融合共同体、贵州省药学行业产教融合共同体、贵药大健康行业产教融合共同体。现有贵州省山地特色农业数字化人才产教融合实训平台等实训教学设备价值达3000余万元。</p>", "imageUrl": "", "contentType": "article", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(91,106,37,'modern-agriculture-majors','upsert','approved','{"code": "modern-agriculture-majors", "category": "专业群布局", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "专业群布局", "subtitle": "", "body": "<p>专业群介绍</p>\n<p>农产品加工与质量检测专业群是省级“高水平”专业群，由畜牧兽医、中草药栽培与加工技术、农产品加工与质量检测、茶叶生产与加工技术和电子商务等5个高职专业组成，专业群紧紧围绕毕节要打造农产品加工产业集群和绿色生态食品加工基地等产业布局，贯穿毕节生态食品产业种养、加工、检测、销售全产业链，精准对接生态食品产业规范化、绿色化、数字化对高技能人才培养的要求，做到坚持需求导向、产教融合、质量为本、标准引领，全面落实立德树人根本任务，加快推进产教一体化、教学数智化、办学国际化，系统推进金专业、金课、金师、金教材、金基地等“五金”关键办学能力建设，努力成为毕节生态食品产业的关键技术集成引领者、技术标准输出者，培养适应生态食品产业链从原料生产到终端消费全产业链环节和新质生产力岗位急需的“懂工艺、会管理、善协作、能创新”“知农爱农”人才。</p>\n<p>茶叶生产与加工技术专业</p>\n<p>培养目标：茶叶生产与加工技术专业是省级重点专业群建设专业之一。坚持培养学生理想信念坚定，德、智、体、美、劳全面发展，具有一定的科学文化水平，良好的人文素养、职业道德和创新意识，精益求精的工匠精神，较强的就业能力和可持续发展的能力；掌握本专业知识和技术技能，针对区域经济发展、为巩固拓展脱贫攻坚和乡村振兴有效衔接，培养懂技术、会管理、善经营的具有“三农”情怀的新茶人，面向茶叶生产管理、茶叶加工、茶产品营销、茶叶生产技术服务等岗位（群）的高素质技术技能人才。</p>\n<p>核心课程：茶叶加工技术、茶树栽培技术、茶树病虫害防治技术、茶的综合利用、茶叶市场营销、茶叶审评与检验技术、茶艺。</p>\n<p>职业面向：本专业毕业生主要面向茶行业、茶企事业单位，主要从事茶叶生产管理、茶叶加工、茶产品营销、茶叶生产技术服务等岗位（群）工作。</p>\n<p>专业特色：茶叶生产与加工技术专业致力于培养懂种植、会加工、能品评、善营销的复合型高素质技术技能人才，服务于茶产业全链条，推动传统茶业向现代茶业转型升级。</p>\n<p>我校茶叶生产与加工技术专业拥有校内教学茶园、标准化审评室、多种类加工实训车间，每年春茶茶季还与贵州乌蒙利民农业开发有限公司、贵州乌撒烤茶茶业有限公司开展现代学徒制教学。学生实训贯穿种植、采摘、加工、审评、销售全流程，实现“从茶园到茶杯”的全产业链实践教学。</p>\n<p>茶叶生产与加工技术专业课程对接评茶员、茶艺师等职业资格证书；组织学生参与省级茶叶加工、茶艺、评茶技能大赛；课程内容直接对应茶园管理、生产品控、技术服务等岗位需求，实现“岗课赛证”综合育人。</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img01.webp\" alt=\"学生到贵州乌撒烤茶茶业有限公司开展“学徒制”实践教学\" /><figcaption>学生到贵州乌撒烤茶茶业有限公司开展“学徒制”实践教学</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img02.webp\" alt=\"学生到贵州乌撒烤茶茶业有限公司开展“学徒制”实践教学\" /><figcaption>学生到贵州乌撒烤茶茶业有限公司开展“学徒制”实践教学</figcaption></figure>\n<p>学生到贵州乌蒙利民农业开发有限公司茶园开展“学徒制”实践教学</p>\n<p>办学成效：经多年发展，茶叶生产与加工技术专业取得的办学成果如下。</p>\n<p>1.建成茶叶加工实验室1个和茶叶审评室1个；</p>\n<p>2.建成茶叶生产与加工技术教师创新团队1个；培养“甲秀之光”访问学者1名；贵州省“黔茶工匠”1名；2022年12月获得《贵州省技能大师工作室》建设。</p>\n<p>3.承担重大科研项目：毕节市联合基金项目《毕节市茶叶加工实验平台建设》，在研；与广东农科院茶叶研究所联合申报2022年毕节市“揭榜挂帅”项目《毕节市夏秋茶提质加工与品控技术及示范》，获批立项，经费100万元。</p>\n<p>4.技能大赛取得丰硕成果。近三年，师生学生参加市级、省级制茶大赛获得省级“一等奖”5个，“二等奖”5个，“三等奖”6个；市级“一等奖”3个，“二等奖”2个，“三等奖”4个，省市“优秀奖”若干。</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img03.webp\" alt=\"贵州省杨留勇茶叶技能大师工作室\" /><figcaption>贵州省杨留勇茶叶技能大师工作室</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img04.webp\" alt=\"贵州省杨留勇茶叶技能大师工作室\" /><figcaption>贵州省杨留勇茶叶技能大师工作室</figcaption></figure>\n<p>杨留勇荣获贵州省制茶大师称号</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img05.webp\" alt=\"杨留勇荣获贵州省制茶大师称号\" /><figcaption>杨留勇荣获贵州省制茶大师称号</figcaption></figure>\n<p>畜牧兽医专业</p>\n<p>培养目标：畜牧兽医专业是省级重点专业群建设专业之一。本专业培养能够践行社会主义核心价值观，传承技能技艺，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向牲畜饲养、家禽饲养、畜牧专业及辅助性活动行业的畜禽种苗繁育人员、畜禽饲养人员及其他畜牧业生产人员等职业，能够从事畜禽繁育、畜禽饲养管理、畜禽疾病防控、畜牧场废弃物资源化利用、畜牧场设备使用与维护工作的高技能人才。</p>\n<p>核心课程：养猪与猪病防治技术、养禽与禽病防治技术、养牛与牛病防治技术、养羊与羊病防治技术、兽医临床诊疗技术、畜牧场设备使用与维护、畜牧场经营与管理。</p>\n<p>就业方向：本专业毕业生主要面向养殖企业、饲料加工与销售企业、兽药生产与营销企业、动物卫生监督与疫病监测机构、动物医院、基层畜牧兽医服务机构等；可在县、乡级兽医行政部门、动物防检站、动物屠宰企业、动物疾控中心、动物/宠物医院、规模养殖企业、饲料企业和兽药企业等企事业部门或单位，从事动物疫病防治、动物检疫检验、兽医化验、执业（助理）兽医、兽药饲料营销、动物饲养管理、牧场经营管理等工作或自主创业。</p>\n<p>办学特色：畜牧兽医专业为省级特色骨干专业，紧扣毕节山地畜牧业需求。创新“五阶递进、四创融合”等育人模式，推行现代学徒制与订单班，深化“校政企行”产教融合，建有“国家高技能人才培训基地”，培养适配区域产业的高素质技术技能人才。</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img06.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img07.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img08.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img09.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img10.webp\" alt=\"专题图片\" /></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img11.webp\" alt=\"畜牧兽医专业进行解剖实训\" /><figcaption>畜牧兽医专业进行解剖实训</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img12.webp\" alt=\"畜牧兽医专业进行解剖实训\" /><figcaption>畜牧兽医专业进行解剖实训</figcaption></figure>\n<p>畜牧兽医专业进行猪的防疫实训</p>\n<p>农产品加工与质量检测专业</p>\n<p>培养目标：农产品加工与质量检测是省级重点专业群建设专业之一。本专业培养具有良好的职业素质和职业素养，掌握农产品加工与质量检测专业必要的文化基础知识、专业知识和职业技能，具备从事农产品生产加工、产品开发、品质控制、质量检测、产品营销管理等方面的基本理论知识、专业操作技能和综合应用素质，适应农产品加工与质量检测相关行业生产、建设、管理、服务等一线需要的德智体美劳全面发展的高素质复合型技术技能人才</p>\n<p>专业开设的课程：本专业开设的核心课程：生态特色农产品加工技术、果蔬加工技术、畜产品加工、特色生态食品加工、仪器分析、农产品安全与质量安全控制、农产品食品检验技术、食品微生物。专业基础课程：食品生物化学；中西式面点制作、饮料生产技术、农产品贮藏技术、农产品食品标准与法规、食品添加剂、无极与分析化学、食品化学等。</p>\n<p>专业特色：作为省级“双高计划”专业群核心专业，农产品加工与质量检测专业人才培养按照“五阶递进、五育贯通”的“双五模式，身份“学生一学徒一准员工一员工一创业者”五阶递进，并进行“岗、课、赛、证”四创融合综合育人培养模式。</p>\n<p>学生校内实训教学</p>\n<p>学生校外实习实训</p>\n<p>学生技能比赛教师社会服务</p>\n<p>老师社会服务</p>\n<p>学生实训作品</p>\n<p>专业教师走访企业</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img13.webp\" alt=\"专业教师走访企业\" /><figcaption>专业教师走访企业</figcaption></figure>\n<p>邀请企业技术能手到校上课</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img14.webp\" alt=\"邀请企业技术能手到校上课\" /><figcaption>邀请企业技术能手到校上课</figcaption></figure>\n<p>制作黔西黄粑</p>\n<p>中草药栽培技术与加工技术专业</p>\n<p>培养目标：中草药栽培与加工技术专业是省级重点专业群建设专业之一。该专业坚持培养能够践行社会主义核心价值观，传承技能文明，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、科学素养、数字素养、职业道德、创新意识，爱岗敬业的职业精神和精益求精的工匠精神，较强的就业创业能力和可持续发展的能力，掌握本专业知识和技术技能，具备职业综合素质和行动能力，面向农业的中草药良种繁育、中草药栽培管理、中草药采收与产地初加工、中草药质量检测、中草药销售等岗位（群），能够从事中草药良种繁育、中草药栽培管理、中草药采收与产地初加工、中草药质量检测、中草药销售等工作的高技能人才。</p>\n<p>核心课程：结合区域内中药材支柱产业发展需要，针对直接培养学生的中草药栽培、加工、检测分析能力，训练学生完成工作任务，获得岗位能力，设置《中草药栽培技术》《中草药病虫害防治技术》《中草药鉴别技术》《中草药繁育技术》《中草药质量检测技术》《中草药采收与产地初加工》《中草药营销》7门专业（技能）核心课程。</p>\n<p>就业方向：毕业生主要面向以满足各县（区）中药材生产种植企业、加工企业、购销企业、制药企业以及医院药房等就业和自主创业，从事中草药栽培、生产管理、加工、鉴别检测及营销等工作。适应的岗位群是：①中草药良种繁育岗位群；②中草药栽培管理岗位群；③中草药采收与产地初加工岗位群；④中草药质量检测岗位群；⑤中药材销售岗位群。</p>\n<p>专业特色：在贵州省委、省政府重点打造中药产业发展战略下，中药现代化科技产业（毕节）基地建设不断推进。中药材经营主体逐渐壮大，中草药栽培技术专业立足于服务地方中药材产业发展，培养能进行中草药栽培技术、中药炮制加工、中药材鉴别与质量检测及中药销售产业的高素质技术技能人才。</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img15.webp\" alt=\"中药专业实训室-中药前处理实训室\" /><figcaption>中药专业实训室-中药前处理实训室</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img16.webp\" alt=\"中药专业实训室-中药前处理实训室\" /><figcaption>中药专业实训室-中药前处理实训室</figcaption></figure>\n<p>中药专业实训室-中药炮制实训室</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img17.webp\" alt=\"中药专业实训室-中药炮制实训室\" /><figcaption>中药专业实训室-中药炮制实训室</figcaption></figure>\n<p>中药专业实训室-中药调剂实训室</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img18.webp\" alt=\"中药专业实训室-中药调剂实训室\" /><figcaption>中药专业实训室-中药调剂实训室</figcaption></figure>\n<p>中药调剂实训室</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img19.webp\" alt=\"中药调剂实训室\" /><figcaption>中药调剂实训室</figcaption></figure>\n<p>中药炮制实训室</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img20.webp\" alt=\"中药炮制实训室\" /><figcaption>中药炮制实训室</figcaption></figure>\n<p>中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img21.webp\" alt=\"中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观\" /><figcaption>中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观</figcaption></figure>\n<p>中草药栽培与加工技术专业学生到国药集团贵州同济堂中药饮片有限公司的中药智能煎配中心，开展岗位实习试岗活动</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img22.webp\" alt=\"中草药栽培与加工技术专业师生作为志愿者参加2024年中国农民丰收节第三届毕节天麻博览会\" /><figcaption>中草药栽培与加工技术专业师生作为志愿者参加2024年中国农民丰收节第三届毕节天麻博览会</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img23.webp\" alt=\"专题图片\" /></figure>\n<p>中草药栽培与加工技术专业学生创立黔草菁英社2024年、2025年连续两年为军训新生提供中药茶饮服务</p>\n<p>园林技术</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img24.webp\" alt=\"园林技术\" /><figcaption>园林技术</figcaption></figure>\n<p>智慧大棚</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img25.webp\" alt=\"智慧大棚\" /><figcaption>智慧大棚</figcaption></figure>\n<p>教师带领学生识别植物</p>", "imageUrl": "/uploads/blueprint/topics/modern-agriculture/images/img01.webp", "contentType": "article", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(92,107,37,'modern-agriculture-training','upsert','approved','{"code": "modern-agriculture-training", "category": "实训场景", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "实训场景", "subtitle": "", "body": "<p>依托贵州省职业教育“兴黔富民”“技能贵州”行动计划，夯实实训硬件根基，累计投入3000余万元建成贵州省职业教育山地特色农业数字化人才产教融合实训平台，配套智慧植物工厂、现代农业实训基地、农产品质量检测中心等实训场地，建成6个校内协同创新中心，实训设备总值雄厚，实现数字化、智能化、实景化实训全覆盖，彻底打破传统农业教学“重理论、轻实操”的壁垒。</p>\n<p>畜牧兽医专业高技能人才培养基地</p>\n<p>畜牧兽医专业高技能人才培养基地是国家级培训基地，聚焦山地特色畜牧业发展需求。基地配备自动微生物鉴定与药敏分析系统、离心机、VR远程牧场实训系统等先进设备，建有动物健康服务中心、宠物护理实训室等8间功能实训室，涵盖疫病检测、畜禽繁育、宠物养护等120余个实训项目。基地以“岗课赛证”融通为核心，承担“认知-跟岗-岗位实习”阶梯式实践教学，支撑《黔西北牛羊生产》等核心课程理实一体化教学。同时开展动物疫病防治员、养猪工等职业技能培训与鉴定，累计培训超800人次，职业技能大赛登记认定通过率95%以上。作为区域畜牧技术服务枢纽，基地组建科技特派员团队，为养殖户提供技术咨询、疫病防控等服务，助力乡村振兴；与正大集团等企业共建学徒制，推动产学研深度融合，为毕节山地特色畜牧业输送高素质技术技能人才。</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img26.webp\" alt=\"中药专业实训室-中药前处理实训室\" /><figcaption>中药专业实训室-中药前处理实训室</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img27.webp\" alt=\"中药专业实训室-中药前处理实训室\" /><figcaption>中药专业实训室-中药前处理实训室</figcaption></figure>\n<p>中药专业实训室-中药炮制实训室</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img28.webp\" alt=\"中药专业实训室-中药炮制实训室\" /><figcaption>中药专业实训室-中药炮制实训室</figcaption></figure>\n<p>中药专业实训室-中药调剂实训室</p>", "imageUrl": "/uploads/blueprint/topics/modern-agriculture/images/img26.webp", "contentType": "scene", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(93,108,37,'modern-agriculture-cooperation','upsert','approved','{"code": "modern-agriculture-cooperation", "category": "产教协同", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "产教协同", "subtitle": "", "body": "<p>农业工程系深耕乌蒙山区职业农业教育，紧扣毕节乡村振兴战略与山地特色农业产业布局，立足“1+3+5+N”毕节现代农业产业，坚守“以农立系、以技兴农、服务地方、赋能振兴”办学定位，深耕职教育人、产教融合、科技助农、社会服务四大核心领域，形成了专业精准对接产业、实训赋能实战、师资深耕乡土、育人贴合需求、服务扎根地方的办学特色，办学质量、育人成效、社会影响力持续提升。</p>\n<p>在产教融合方面，构建“校内实训基地+校外产业基地+科普教育基地”三位一体实训体系，校内建成中草药“百草园”实训基地，校外打造2400余亩枇杷产业科普实训基地、织金生态茶叶实训基地等一批产业实景教学点。深化校企、校地协同育人，与地方农业龙头企业、专业合作社深度合作，推行“课堂搬进田间、实训对接产业”的实景教学模式，实现教学过程与生产过程无缝衔接，让学生在真实产业场景中练技能、长本领，切实提升人才培养实操性与岗位适配度。</p>\n<p>对接产业</p>\n<p>校企合作订单班/产业学院</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img29.webp\" alt=\"校企合作订单班/产业学院\" /><figcaption>校企合作订单班/产业学院</figcaption></figure>\n<p>中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img30.webp\" alt=\"中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观\" /><figcaption>中草药栽培与加工技术专业学生到贵州两山天麻产业（集团）有限公司参观</figcaption></figure>\n<p>中草药栽培与加工技术专业学生到国药集团贵州同济堂中药饮片有限公司的中药智能煎配中心，开展岗位实习试岗活动览会</p>", "imageUrl": "/uploads/blueprint/topics/modern-agriculture/images/img29.webp", "contentType": "activity", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(94,109,37,'modern-agriculture-masters','upsert','approved','{"code": "modern-agriculture-masters", "category": "名师名匠", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "名师名匠", "subtitle": "", "body": "<p>杨留勇 中共党员 副教授</p>\n<p>茶叶生产与加工技术专业带头人，长期从事茶叶生产加工及教学科研研究工作，国家一级评茶技师、一级制茶师，管理期内市管专家，贵州省技能大师工作室、贵州省名师名匠工作室及贵州省劳模和工匠人才创新工作室等领办人，毕节市高山生态茶加工技术创新中心主任</p>\n<p>2021年以来，主持教科研项目11项，其中省级4项，市“揭榜挂帅”重大专项1项，市技术创新中心1项；完成团体标准13项（其中3项排名第一，2项排名第二），完成企业标准8项（其中1项排名第一，4项排名第二）；发表研究论文10余篇（其中2篇被中文核心期刊收录）；参编《中国茶全书·贵州毕节分卷》《贵州太极古茶》等茶专著2部；开展技术培训30余期，培训茶叶技能人才2000余人，完成“师带徒”186人，为企业创收约1.5亿元；指导学徒在省市级技能大赛获奖百余项（其中省级金牌（一等奖）8名，铜牌（二等奖）12名等）；培养省级技术能手4名，黔茶工匠3名。2023年荣获贵州省五一劳动奖章，贵州省技术能手和贵州省茶文化传播优秀工作者等荣誉称号。2024年荣获全国第三届“茶人榜样”中华优秀茶教师荣誉称号，2024年入选贵州省第八批高层次创新型“千”层次人才称号。2025年荣获“贵州十佳红茶制茶能手”荣誉称号。</p>\n<p>汪青筑 中共党员、副教授</p>\n<p>中草药栽培与加工技术专业带头人</p>\n<p>2011年7月毕业于贵州大学农学院中草药栽培与鉴定专业，同年8月进入毕节职业技术学院农业工程系担任专业教师；教学中参编的《药用植物栽培技术》（第3版）获评高等职业教育农业部“十二五”规划教材，在《中医教育》《光明中医》等期刊发表论文10篇，2019年以来荣获各级各类奖项15项，围绕中药产品开发指导学生斩获创新创业大赛奖项4项；科研层面主持毕节市科技局《毕节牡丹生长适应性调查及药材质量评价研究》、贵州省教育厅兴黔富民行动计划精品课程《中草药栽培》等7个项目，全部完成验收，同时作为主要完成人参与《三种石斛在毕节市种植适应性研究》《半夏鲜药材去皮技术及质量控制研究》等12项各级各类科研项目；社会服务方面担任贵州省科技特派员与毕节市科普专家，运用专业技术服务地方中药材产业发展、科技提升与区域经济建设。</p>\n<p>李兰芝 农业工程系专任教师</p>\n<p>2018年在中文核心期刊《动物医学进展》上以第一作者发表文章1篇，2019年以第一作者在SCI（International Journal of Molecular Sciences）期刊发表论文1篇，具有较强的科研能力。2021年至2022年，在贵州省教育厅主办的贵州省职业院校师生技能大赛中分别荣获教师组“一等奖”和“二等奖”，指导学生荣获“三等奖”。2022年在全省大中专学生志愿者暑期文化科技卫生“三下乡”社会实践活动中，所指导的团队荣获省级“优秀团队”称号。同年入选贵州省第十二届“最美劳动者”。作为主要参与人员，参与了贵州省兴黔富民项目——“畜牧兽医”特色骨干专业的建设，是校级教师教学创新团队-畜牧兽医团队成员，作为农产品加工与质量检测专业群核心专业课的教师，参与了农产品加工与质量检测省级高水平专业群建设。</p>", "imageUrl": "", "contentType": "person", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(95,110,37,'modern-agriculture-students','upsert','approved','{"code": "modern-agriculture-students", "category": "优秀学生", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "优秀学生", "subtitle": "", "body": "<p>苏兴梦</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img32.webp\" alt=\"苏兴梦\" /><figcaption>苏兴梦</figcaption></figure>\n<p>苏兴梦，女，毕节职业技术学院畜牧兽医专业毕业生，中共党员。2021年通过专升本考试进入安顺学院农学专业学习；2022年考取青海大学畜牧专业硕士研究生；2026年硕士毕业之际，已完成博士研究生入学考试，目前正在等待录取结果。</p>\n<p>杨荣</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img33.webp\" alt=\"杨荣\" /><figcaption>杨荣</figcaption></figure>\n<p>毕节职业技术学院农业工程系2020届茶叶专业优秀毕业生，现任贵州春山已知茶文化传播有限责任公司法人，国家二级茶艺技师、高级评茶员、高级制茶师。是学校依托职业教育培育成才、深耕贵州茶产业、助力乡村振兴的优秀校友。在校期间依托学校系统化专业教学与校内外实训资源夯实茶学功底，走出校园后深耕茶产业，凭借扎实专业素养从应届毕业生成长为行业骨干、创业先锋，用实干印证职业教育赋能出彩人生。</p>\n<p>从踏入校园的那一刻起，杨荣就与茶结下了不解之缘。通过不断的努力与坚持，杨荣在茶艺领域取得了一些成绩，也找到了属于自己的职业方向。</p>\n<p>缪慢</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img34.webp\" alt=\"缪慢\" /><figcaption>缪慢</figcaption></figure>\n<p>缪慢，2017级园林工程技术专业学生，从专科起点，历经专升本、考研读研，再成功申博、即将入读博士，以步步深耕、持之以恒的求学之路，书写了职院学子逆袭成长的励志答卷，生动诠释“人生没有白走的路，每一步付出皆有回响”。</p>", "imageUrl": "/uploads/blueprint/topics/modern-agriculture/images/img32.webp", "contentType": "person", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(96,111,37,'modern-agriculture-achievements','upsert','approved','{"code": "modern-agriculture-achievements", "category": "专题成果", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "专题成果", "subtitle": "", "body": "<p>教科研成果、课题项目...</p>\n<p>序号 / 项目名称 / 数量 / 备注 1 / 毕节特色中药材产业实训基地 / 1 / 2020年贵州省中药材产业实训基地（培育） 2 / 省精品在线开放课程 / 1 / 2020年兴黔富民行动计划《中草药栽培》 3 / 院级精品课程 / 4 / 分别于2022、2024年 4 / 道地中药材检测服务中心 / 1 / 产教融合技术技能创新平台 5 / 参编《药用用植物栽培技术》第三版 / 1 / 2020年高等职业教育农业部“十二五”规划教材高等职业教育“十四五”规划教材 6 / 院级教材 / 2 / 2024年 7 / 校外实训基地 / 6 / 威宁天露、大方九龙、贵州乌蒙腾等 8 / 中药炮制技能大师工作室 / 1 / 董志颖（上海中医药大学）、黎代余等 9 / “中草药栽培与加工技术教师教学创新团队” / 1 / 张士齐等 10 / 学生参与各类比赛获奖 / 20 / 省级 11 / 团队教师主持参与项目 / 20 / 省级、市级 12 / 贵州省科技特派员 / 2 / 2022年 13 / 毕节市科技特派员 / 3 / 2024年 14 / 毕节市科普专家 / 4 / 2022年</p>", "imageUrl": "", "contentType": "achievement", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
INSERT INTO "page_versions" VALUES(97,112,37,'modern-agriculture-honors','upsert','approved','{"code": "modern-agriculture-honors", "category": "荣誉资质", "source": "创新育人专题", "publishedAt": "2026-08-04", "title": "荣誉资质", "subtitle": "", "body": "<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img35.webp\" alt=\"杨留勇荣获贵州省制茶大师称号\" /><figcaption>杨留勇荣获贵州省制茶大师称号</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img36.webp\" alt=\"杨留勇荣获贵州省制茶大师称号\" /><figcaption>杨留勇荣获贵州省制茶大师称号</figcaption></figure>\n<p>技能大赛获奖证书</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img37.webp\" alt=\"技能大赛获奖证书\" /><figcaption>技能大赛获奖证书</figcaption></figure>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img38.webp\" alt=\"技能大赛获奖证书\" /><figcaption>技能大赛获奖证书</figcaption></figure>\n<p>学生技能大赛获奖证书</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img39.webp\" alt=\"学生技能大赛获奖证书\" /><figcaption>学生技能大赛获奖证书</figcaption></figure>\n<p>2025年教师获奖</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img40.webp\" alt=\"2025年教师获奖\" /><figcaption>2025年教师获奖</figcaption></figure>\n<p>2024年中药专业教师指导学生智慧农业种植大赛获奖</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img41.webp\" alt=\"2024年中药专业教师指导学生智慧农业种植大赛获奖\" /><figcaption>2024年中药专业教师指导学生智慧农业种植大赛获奖</figcaption></figure>\n<p>2025年中药专业教师指导学生中药传统技能大赛获奖</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img42.webp\" alt=\"2025年中药专业教师指导学生中药传统技能大赛获奖\" /><figcaption>2025年中药专业教师指导学生中药传统技能大赛获奖</figcaption></figure>\n<p>2025年中药专业教师指导学生中药传统技能大赛获奖</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img43.webp\" alt=\"2025年中药专业教师指导学生中药传统技能大赛获奖\" /><figcaption>2025年中药专业教师指导学生中药传统技能大赛获奖</figcaption></figure>\n<p>2025年中药专业教师指导学生创新创业大赛获奖</p>\n<figure><img src=\"/uploads/blueprint/topics/modern-agriculture/images/img44.webp\" alt=\"2025年中药专业教师指导学生创新创业大赛获奖\" /><figcaption>2025年中药专业教师指导学生创新创业大赛获奖</figcaption></figure>\n<p>视频资料（专业特色，可于所在区域屏幕循环播放）</p>", "imageUrl": "/uploads/blueprint/topics/modern-agriculture/images/img35.webp", "contentType": "honor", "accent": "#f59a13", "enabled": true}','admin','2026-08-04T10:35:09.537955+00:00','admin','2026-08-04T10:35:09.537955+00:00','','legacy import');
CREATE TABLE pages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER NOT NULL,
            code TEXT NOT NULL,
            title TEXT NOT NULL,
            subtitle TEXT NOT NULL DEFAULT '',
            body TEXT NOT NULL DEFAULT '',
            image_url TEXT NOT NULL DEFAULT '',
            accent TEXT NOT NULL DEFAULT '#0f766e',
            enabled INTEGER NOT NULL DEFAULT 1,
            updated_at TEXT NOT NULL, category TEXT NOT NULL DEFAULT '校园新闻', source TEXT NOT NULL DEFAULT '学校展示', published_at TEXT NOT NULL DEFAULT '', review_status TEXT NOT NULL DEFAULT 'approved', pending_version_id INTEGER, submitted_by TEXT NOT NULL DEFAULT 'admin', reviewed_by TEXT NOT NULL DEFAULT 'admin', review_note TEXT NOT NULL DEFAULT '', content_type TEXT NOT NULL DEFAULT 'article',
            UNIQUE(project_id, code)
        );
INSERT INTO "pages" VALUES(5,15,'BJ-SERVICE','社会服务成果','聚焦技能培训、职业认定与乡村振兴服务，测试指标卡、图文组合与引用块。','<div class="lead-card"><span>SOCIAL SERVICE</span><strong>服务地方产业与技能人才培养</strong><p>学校围绕毕节新发展理念示范区建设，聚焦现代能源、生态食品、先进装备制造、轻纺及健康医药等产业，持续开展职业技能培训、等级认定和乡村振兴服务。</p></div>
<div class="stat-grid"><div class="stat"><strong>45000+</strong><span>培训人次</span><p>联合政校企完成多类型技术技能培训。</p></div><div class="stat"><strong>15000+</strong><span>认定人次</span><p>面向学生和社会人员开展职业技能等级认定。</p></div><div class="stat"><strong>八大产业</strong><span>服务方向</span><p>对接地方工业产业和特色农业发展需求。</p></div></div>
<h2>重点服务方向</h2><ul><li>高技能人才、基层服务、煤矿安全技术、退役军人就业创业培训。</li><li>乡村振兴技能人才培养和非物质文化遗产传承人群研修研习。</li><li>职业技能等级认定与专项职业能力认定平台建设。</li></ul>
<div class="photo-strip"><figure><img src="/uploads/bijie-samples/image1.jpeg" alt="培训现场"><figcaption>毕节市财政财务基础业务培训班</figcaption></figure><figure><img src="/uploads/bijie-samples/image16.jpeg" alt="稻米示范推广培训"><figcaption>优质稻米示范推广培训进入田间地头</figcaption></figure></div>
<blockquote>以学校技术资源和师资优势服务地方产业发展，助力毕节市人力资源开发和乡村全面振兴。</blockquote>','/uploads/bijie-samples/image16.jpeg','#49c5b6',1,'2026-07-13T02:59:45.752052+00:00','社会服务成果','毕节职业技术学院','','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(6,15,'BJ-INTL','国际交流合作成果','从海外研学到职业标准输出，测试时间线、列表、图片和分隔线。','<div class="lead-card"><span>GLOBAL COOPERATION</span><strong>从“引进来”到“走出去”的国际合作</strong><p>学校主动服务“一带一路”倡议和中国-东盟、中非教育合作，在海外交流、标准输出、多边合作、技能竞赛、人文往来等方面形成阶段性成果。</p></div>
<div class="timeline"><div><span>2024</span><p>组织师生赴泰国格乐大学开展短期研学，拓宽学生国际视野，增进中泰人文交流。</p></div><div><span>2025</span><p>牵头制定菲律宾《农业经理人》国家职业技能标准，并参与中国-东盟数字资源共建共享合作。</p></div><div><span>近三年</span><p>累计接待国（境）外来访团组 4 个，举办国际文化交流活动 4 场，签订校际合作备忘录 2 份。</p></div></div>
<h2>成果看点</h2><ul><li>获批埃塞俄比亚国家职业标准开发项目认证。</li><li>课程资源被俄罗斯喀山联邦大学、埃塞俄比亚 Dire Dawa University 采用。</li><li>师生在金砖国家技能发展与技术创新大赛等国际赛事中获得多项奖项。</li></ul>
<div class="photo-strip"><figure><img src="/uploads/bijie-samples/image23.jpeg" alt="泰国研学合影"><figcaption>师生赴泰国格乐大学开展短期研学</figcaption></figure><figure><img src="/uploads/bijie-samples/image31.jpeg" alt="国际人文交流活动"><figcaption>“桥见”贵州毕节职院人文交流活动</figcaption></figure></div>
<hr><p>这一页用于测试时间线、图文组合、列表与分隔线在大屏详情页中的可读性。</p>','/uploads/bijie-samples/image23.jpeg','#f8c35a',1,'2026-07-13T03:07:46.158420+00:00','国际交流合作','毕节职业技术学院','','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(7,15,'BJ-GRAD','优秀毕业生张娅婷','以人物卡片、荣誉标签和分段叙事展示优秀毕业生成长故事。','<div class="profile-card"><img src="/uploads/bijie-samples/image38.jpeg" alt="张娅婷事迹照片"><div><span>优秀毕业生</span><h3>张娅婷</h3><p>贵州省 2024 届优秀毕业生，学前教育专业。她在校园学习、学生工作、志愿服务和西部计划实践中持续成长。</p></div></div>
<div class="badge-list"><span>中共党员</span><span>教育科学系</span><span>学前教育</span><span>国家奖学金</span><span>省级优秀毕业生</span></div>
<h2>一路追光，筑梦前行</h2><p>在校期间，她担任系学生会团总支副书记、学生会主席、班级团支部书记与班长，荣获全国乡村振兴“笃行计划优秀实践个人”、励志奖学金、省三好学生等荣誉。</p>
<h3>敢担当</h3><p>2021 年至 2023 年，她承担学生组织工作，并于 2023 年赴马来西亚英迪国际大学短期访学，按期高质量完成学业。</p>
<h3>能吃苦</h3><p>连续两年参加“三下乡”社会实践，组织关爱留守儿童、服务空巢老人和民族文化传承活动，在实践中锤炼专业能力和社会责任。</p>
<h3>有理想</h3><p>2024 年 8 月，她投身贵州省毕节市七星关区碧阳街道办事处西部计划志愿服务，参与档案整理、热线回应和志愿服务等工作。</p>
<div class="template-note"><strong>教师评语</strong><p>希望你用行动去诠释教育的真谛，展现青春的力量。</p></div>','/uploads/bijie-samples/image37.png','#ff8f5a',1,'2026-07-13T03:35:29.273403+00:00','育人成果','教育科学系','','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(8,15,'BJ-TEACHER','校内名师谭佳','用人物介绍、数据卡和成果列表展示名师名匠内容模板。','<div class="profile-card"><img src="/uploads/bijie-samples/image39.jpeg" alt="谭佳 portrait"><div><span>校内名师</span><h3>谭佳</h3><p>旅游管理系副教授，聚焦旅游技能人才培养、数智赋能课程建设等教学教改方向。</p></div></div>
<div class="stat-grid"><div class="stat"><strong>10+</strong><span>省部级、市厅级项目</span><p>主持并推进多项教学教改与社会服务项目。</p></div><div class="stat"><strong>10000+</strong><span>课程覆盖人次</span><p>开发《乡村旅游导览实务》等培训课程。</p></div><div class="stat"><strong>30+</strong><span>团队课题</span><p>围绕生态旅游、红色讲解、研学旅游开发等方向开展研究。</p></div></div>
<h2>教学与产业服务成果</h2><ul><li>获全国教师教学能力大赛三等奖、省赛一等奖。</li><li>实践成果入选文旅部优秀成果并在全国推广。</li><li>教学案例入选文旅部旅游职业教育“五金”数智化建设典型案例。</li></ul>
<div class="photo-strip"><figure><img src="/uploads/bijie-samples/image32.jpeg" alt="论坛发言"><figcaption>在论坛活动中进行主旨发言</figcaption></figure><figure><img src="/uploads/bijie-samples/image30.jpeg" alt="校园成果展示"><figcaption>职业教育成果面向行业与社会展示</figcaption></figure></div>
<blockquote>通过老带新、师带徒，优化人才结构，赋能贵州文旅产业高质量发展。</blockquote>','/uploads/bijie-samples/image32.jpeg','#8bd17c',1,'2026-07-13T03:37:17.139551+00:00','名师名匠','旅游管理系','','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(9,15,'DEMO-10100043','欢迎来到成果展示','深圳先进技术研究院展会互动展示','这里可以放项目介绍、展品亮点、团队说明和现场引导文案。后台可以随时替换这些文字和图片。','/static/sample.svg','#0f766e',1,'2026-07-16T04:00:22.063+00:00','校园新闻','学校展示','','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(22,25,'BP-DEPT-MINING_CONSTRUCTION-OVERVIEW','基本情况','智慧矿山、智能制造与现代建造','<figure><img src="/uploads/blueprint/departments/mining-construction/images/img01.webp" alt=""></figure>
<p>系部简介：</p>
<p>工矿建筑系2008年成立，开设建筑工程技术、煤矿智能开采技术、智能机电技术、安全技术与管理、测绘工程技术、应用化工技术、新能源汽车检测与维修技术、资源综合利用技术、无人机应用技术等9个高职专业和煤矿开采中技专业，与贵州工程应用技术学院联合培养土木工程、工程管理、采矿工程3个本科专业学生。建筑工程技术、煤矿智能开采技术专业群为贵州省高水平专业群。</p>
<p>现有教职工82人，博士、教授、副教授等高层次人才齐备。建有国家、省、市三级高技能人才培训基地，打造模拟矿井、智能综采中心、建筑模型等30余间实训室，实训总投入近1.4 亿元。</p>
<p>依托统战资源对接广州港、广汽、奇瑞等东部龙头企业，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>
<p>累计培养学生2万余名，斩获国家级教学成果二等奖1项、省级一等奖2项，近三年学生竞赛获奖120余项，获评贵州省脱贫攻坚先进集体；教师承担省市级科研项目50余项，年度横向经费到账80余万元，成果丰硕。</p>','/uploads/blueprint/departments/mining-construction/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','基本情况','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(23,26,'BP-DEPT-FINANCE-OVERVIEW','基本情况','数字商贸、智慧物流与财务实践','<p>改：财政经济系于 2008 年组建，开设大数据与会计、现代物流管理、电子商务三大专业，年均在校生约 1600 人。2022 年起与贵州工程应用技术学院联合培养财务管理本科班。</p>
<p>电子商务专业为毕节市人民政府授牌 "毕节电子商务学院"，专业群获评贵州省职业教育特色骨干专业群（优秀等次）；大数据与会计专业为省级骨干专业。加入全国直播电商职业教育集团等 5 个国家级产教融合共同体，牵头组建毕节市乡村电商职业教育产教联盟、东西部协作乡村电商行业产教融合共同体（成员单位 120 余家）。拥有贵州省农业电商产业扶贫协同创新中心、高水平乡村电商产教融合实训基地等省级项目 11 项，获批市级数商兴农人才团队、省级教学创新人才团队。先后荣获省级五好基层党组织、市级样板院系、全国五四红旗团支部、全国活力团支部等荣誉。</p>
<p>学生专升本上线率 93%、录取率 89%。2025年荣获贵州省教学成果特等奖；技能大赛斩获国家级铜奖5项、省级一等奖12项，各级各类奖项累计400余项，为区域经济社会发展作出积极贡献。</p>
<figure><img src="/uploads/blueprint/departments/finance/images/img01.webp" alt=""></figure>
<p>京东实战班618校内真岗实战</p>
<figure><img src="/uploads/blueprint/departments/finance/images/img02.webp" alt="京东实战班618校内真岗实战"><figcaption>京东实战班618校内真岗实战</figcaption></figure>
<p>物流专业教师开展校内专业教学</p>
<figure><img src="/uploads/blueprint/departments/finance/images/img03.webp" alt="物流专业教师开展校内专业教学"><figcaption>物流专业教师开展校内专业教学</figcaption></figure>
<p>学生到昆山亚洲一号物流园开展实践教学</p>','/uploads/blueprint/departments/finance/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','基本情况','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(24,27,'BP-DEPT-INFORMATION-OVERVIEW','基本情况','人工智能、网络安全与数字技术','<p>电子信息工程系系部介绍</p>
<p>毕节职业技术学院电子信息工程系溯源于1996年成立的毕节农业学校计算机教研室，2008年正式建系，至今已有30年办学积淀。现有教职工40余人，其中副高以上职称占比32.3%，“双师型”教师达83.3%。</p>
<p>现开设计算机应用技术（省级重点特色专业）、人工智能技术应用（省级现场工程师培训基地）、计算机网络技术三个专业，在校生1500人。学生职业证书获取率达92%，毕业生就业去向落实率长期保持在90%以上。近三年获省级以上比赛奖项46项（国家级三等奖1项、省级一等奖6项、省级二等奖10项、省级三等奖14项）；创新创业类比赛获国家级银奖1项、省级银奖2项、省级铜奖16项；“挑战杯”比赛获省级二等奖1项、省级三等奖5项、省级优秀奖1项。</p>
<p>系部建有国家级计算机应用技术高技能人才培养基地1个、国家级小米AIoT工程师能力培训中心1个、省级重点（特色）专业1个、省级人工智能现场工程师培训基地1个。入选全国新一代信息技术、全国大数据、全国人工智能、全国信息安全行业产教融合共同体理事单位。与小米、360、H3C等头部企业深度合作，共建人工智能产业学院、360数智安全产业学院、H3C网络学院，实现课堂与岗位无缝对接。</p>
<p>1.师生在2025年省第二届网络安全实战赛获奖</p>
<figure><img src="/uploads/blueprint/departments/information/images/img01.webp" alt="1.师生在2025年省第二届网络安全实战赛获奖"><figcaption>1.师生在2025年省第二届网络安全实战赛获奖</figcaption></figure>
<p>2.系部学生王恩利利用数字化技术服务乡村被中央电视台报道</p>
<figure><img src="/uploads/blueprint/departments/information/images/img02.webp" alt="2.系部学生王恩利利用数字化技术服务乡村被中央电视台报道"><figcaption>2.系部学生王恩利利用数字化技术服务乡村被中央电视台报道</figcaption></figure>
<p>3.系部学生参加2024全国职业院校技能大赛获奖</p>
<figure><img src="/uploads/blueprint/departments/information/images/img03.webp" alt="3.系部学生参加2024全国职业院校技能大赛获奖"><figcaption>3.系部学生参加2024全国职业院校技能大赛获奖</figcaption></figure>
<p>4.荣获小米优秀合作院校表彰</p>
<figure><img src="/uploads/blueprint/departments/information/images/img04.webp" alt="4.荣获小米优秀合作院校表彰"><figcaption>4.荣获小米优秀合作院校表彰</figcaption></figure>','/uploads/blueprint/departments/information/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','基本情况','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(25,28,'BP-DEPT-MEDICAL_NURSING-OVERVIEW','基本情况','临床护理、康养服务与急救教育','<p>系部简介：医学护理系</p>
<p>医学护理系始建于2011年，是毕节市内首批开设卫生健康类专业的高职院校，作为区域内医疗卫生与大健康服务领域高素质技术技能人才重点培养基地。</p>
<p>紧扣大健康产业发展需求设置专业，现开设护理、老年保健与管理、智慧健康养老服务与管理三大专业，精准对接临床护理、健康养老、基层社会服务核心岗位。师资队伍结构优良，双师型教师占比超95%。</p>
<p>现拥有国家级高技能人才培训基地（康养家政护理）、全国学校急救教育试点学校两大国家级平台；美国心脏协会心血管急救培训中心、贵州省红十字会救护员取证培训试点等省级平台。系部为全国智慧健康养老行业产教融合共同体第一届理事单位、铜仁市健康养老行业产教融合共同体副理事单位，联动省内外20余家优质单位共建校外实训基地，构建岗课训赛一体化育人体系。</p>
<p>校内建有标准化模拟医院、AHA急救培训中心等35个实训场地。办学至今累计培养优秀技能人才6000余人，学生护士执业资格考试通过率稳定在95%、专升本上线率达94%，师生累计斩获国家级、省级奖项180余项，乡村义诊服务群众超7万人次，人才质量获行业高度认可。</p>
<figure><img src="/uploads/blueprint/departments/medical-nursing/images/img01.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/departments/medical-nursing/images/img02.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/departments/medical-nursing/images/img03.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/departments/medical-nursing/images/img04.webp" alt=""></figure>','/uploads/blueprint/departments/medical-nursing/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','基本情况','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(26,29,'BP-DEPT-TOURISM-OVERVIEW','基本情况','数字文旅、酒店运营与烹饪技艺','<p>旅游管理系简介：</p>
<p>旅游管理系2010年成立，开设旅游管理、酒店管理与数字化运营、烹饪工艺与营养3个高职专业，饭店（酒店）服务、烹饪（中式烹调）2个中技专业，旅游管理专业为省级重点特色专业。</p>
<p>共计专兼职教师35人，双师型教师比例达95%以上。其中，文旅部“万名旅游英才”2名，农业农村部“名课名师”1名，贵州省技术能手3名，毕节工匠3名。</p>
<p>先后建成贵州乡村旅游虚拟仿真实训基地、毕节数字文旅开放型产教融合实践中心2个省级产教融合基地，烹饪工艺与营养黔匠工坊1个省级工坊，洞天花海产业学院、大方九驿街道乡村旅游学院2个产业学院。</p>
<p>依托东西部协作、统一战线帮扶、聚焦地方产业发展，开设广州地铁集团、广州岭南集团越秀集团、广州酒家等优质订单班，与牵头成立“全国乡村生态旅游行业产教融合共同体”“毕节市乡村生态旅游市域产教联合体”。</p>
<p>近五年，立项省级“校旅结合”示范校、省级虚拟仿真实训基地、省级黔匠工坊等18个省级建设项目。育人模式获贵州职业教育教学成果二等奖、贵州省第五届教育科学研究优秀成果三等奖；团队获全国职业院校教师教学能力大赛三等奖、贵州省职业院校教师教学能力一等奖。师生先后获省级一等奖22人次、二等奖30人次、三等奖若干。办学特色鲜明、成果显著！</p>
<figure><img src="/uploads/blueprint/departments/tourism/images/img01.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/departments/tourism/images/img02.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/departments/tourism/images/img03.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/departments/tourism/images/img04.webp" alt=""></figure>','/uploads/blueprint/departments/tourism/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','基本情况','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(27,30,'BP-TOPIC-SMART_ENERGY-OVERVIEW','基本情况','绿色能源、智能开采与化工安全','<p>系部简介：工矿建筑系</p>
<p>工矿建筑系2008年成立，下设矿业、机电、建筑三个教研室，设建筑工程技术、煤矿智能开采技术、智能机电技术、安全技术与管理、测绘工程技术、应用化工技术、新能源汽车检测与维修技术、资源综合利用技术等8个高职专业和煤矿开采中技专业，与贵州工程应用技术学院开展联合培养土木工程、工程管理、采矿工程3个本科专业。建筑工程技术、煤矿智能开采技术获批两个省级高水平专业群。</p>
<p>办学基础好。系部现有教职工82人，博士、教授、副教授等高层次人才齐备，双师型教师49人。先后获批国家高技能人才培训基地、毕节市智能矿山产教融合实训基地、贵州省开放性实训基地等多个项目支持，建成模拟矿井、智能综采实训中心、智能综掘进实训中心、建筑等比例模型、智能机电实训中心、应用化工专业实训室等30余个实训室，总投入资金近1.4亿元。</p>
<p>产教融合实。依托统一战线帮扶，与东部广州港集团、广汽集团、奇瑞控股集团等龙头企业开展深度合作，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>
<p>办学质量高。累计培养学生2万余名。获国家教学成果二等奖1项、省级教学成果一等奖2项。近三年学生在各类大赛中获奖120余项。系部获“贵州省脱贫攻坚先进集体”等优秀称号。</p>
<p>科研能力强。教师主持省市级科研项目 50 余项，一年来开展横向课题经费到账80余万元。</p>','/uploads/blueprint/topics/smart-energy/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','专题概况','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(28,30,'BP-TOPIC-SMART_ENERGY-MAJORS','专业设置','绿色能源、智能开采与化工安全','<p>绿色智慧能源专业群（省级高水平专业群）</p>
<p>绿色智慧能源专业群立足省级高水平建设定位，以煤矿智能开采技术为核心，整合安全技术与管理、应用化工技术、资源综合利用技术、测绘工程技术五大专业，聚焦煤炭绿色开发、磷煤化工、资源循环利用、智慧测绘等领域，服务贵州省基础能源、毕节市精细磷煤化工及资源综合利用产业集群。</p>
<p>专业群对接智能矿山建设、煤炭安全高效生产、化工工艺管控、固废资源化利用、矿山测绘与地理信息等关键环节，面向智能采掘工程师、安全监测监控师、化工工艺技术员、资源综合利用工程师、测绘与地理信息技术员等岗位，培养懂技术、会操作、能运维的高技能人才。</p>
<p>深度联动区域煤炭、化工、资源利用龙头企业，围绕智能开采、安全管控、化工生产、资源循环、精准测绘核心技能，构建 “岗课赛证” 融合育人体系，助力煤炭产业低碳转型、资源高效利用与智慧矿山建设，为区域绿色智慧能源产业高质量发展提供人才支撑。</p>
<p>综掘实训室掘进机 / 综采实训中心</p>
<p>煤矿智能开采技术专业</p>
<p>培养目标：本专业坚持立德树人，面向煤炭开采和洗选行业的发展需求。培养理想信念坚定与德智体美劳全面发展，具备良好职业道德、人文素养、科学素养和数字素养，掌握煤矿智能开采相关理论知识与技术技能，能够适应智能化矿山建设和生产一线岗位要求的高技能人才。毕业生应具有较强的岗位实践能力、技术应用能力、就业创业能力和持续发展能力，能够胜任智能化工作面采掘施工、采掘生产组织、通风技术管理及智能开采安全管理等工作。</p>
<p>核心课程:《智能化采煤方法》、《采掘机械使用与维护》、《巷道智能掘进技术》、《矿井智能通风技术》、《智能采掘电气》、《煤矿安全技术》、《矿山压力观测与控制》、《智能监测监控技术》等。</p>
<p>专业特色：煤矿智能开采技术专业是贵州省第二批高水平专业群核心专业，办学历史悠久，深度融合贵州省区域经济发展。先后获得国家、省、市多个项目支持，建成了目前省内职业院校规模最大、设备最为齐全的模拟矿井和综采实训中心。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img01.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img02.webp" alt=""></figure>
<p>综采工作面“三机”配套设备 液压支架操作实训</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img03.webp" alt="综采工作面“三机”配套设备 液压支架操作实训"><figcaption>综采工作面“三机”配套设备 液压支架操作实训</figcaption></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img04.webp" alt="综采工作面“三机”配套设备 液压支架操作实训"><figcaption>综采工作面“三机”配套设备 液压支架操作实训</figcaption></figure>
<p>模拟矿井主平硐地面瓦斯抽放泵房</p>
<p>就业去向：毕业生主要面向煤矿企业智能化综采、智能化掘进、矿井通风、安全技术管理、机电运输和生产调度等岗位就业和自主创业，从事采掘生产组织、设备运行维护、通风安全管理、现场技术管理及智能化系统应用等业务工作。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img05.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img06.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img07.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img08.webp" alt=""></figure>
<p>应用化工技术专业</p>
<p>培养目标：本专业旨在培养自觉践行社会主义核心价值观，具备扎实科学文化基础、良好人文科学素养、职业道德、创新意识、爱岗敬业职业精神和精益求精工匠精神，拥有较强的创新创业能力和可持续发展素养的高素质技术技能人才。学生将掌握基础化学、化学反应器、典型产品生产工艺、化工过程模拟、个人防护、HSE与清洁生产等专业理论知识；熟练掌握化工单元现场操作、中控操作技能等专业技能，具备化工装置高效运维、生产工艺流程优化、工艺方案评估的能力，可处理一般生产性突发事故，能够胜任班组生产管理工作。同时具有适应化工行业数字化和智能化发展需求，能综合运用专业知识解决生产实际问题，毕业后可从事化工生产操作与控制、生产管理和工艺技术优化等岗位工作。</p>
<p>核心课程：化工传热与控制技术、化工分离与控制技术、化学反应过程及设备、化工生产技术、化工生产DCS操作、化工安全技术、磷系新型储能材。</p>
<p>就业方向：主要面向化学原料和化学制品制造业，针对以基础化学原料、精细化工、新材料产业、医药化工、化工产品质量检测等为主营业务的国有或民营化工企业、专用化学品企业、技术服务机构等类型单位的就业和自主创业。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img09.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img10.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img11.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img12.webp" alt=""></figure>
<p>安全技术与管理专业</p>
<p>培养目标：本专业培养理想信念坚定，德智体美劳全面发展，具有一定的科学文化水平，良好的人文素养、职业道德和创新意识，德技并修、精益求精的工匠精神，较强的就业创新创业能力和可持续发展能力，掌握安全技术与管理的专业知识和技术技能，面向相关行业领域企事业单位、专业技术服务行业以及应急管理部门的技术人员、管理人员、行政执法人员等职业群，能够从事安全检查与管理、安全评价、安全技术咨询等工作的高素质技术技能人才。</p>
<p>主要课程：《安全管理》、《安全评价技术》、《防火与防爆技术》、《电气安全技术》、《智能安全监测与监控技术》、《安全生产事故调查与案例分析》、《工业通风与除尘》、《安全系统工程》、《安全人机工程》、《电工技术》、《安全法律法规》。</p>
<p>实训条件：安全技术与管理专业校内实践教学基地设备总价值1800余万元，每个实训基地（实训室）均能同时满足30～40人开展实习实训，优越的实习实训基地为学生的生产实习实训奠定了坚实基础。</p>
<p>就业去向：职业服务领域面向安全生产领域相关企事业单位，可在煤矿安全监察部门、矿山设计研究院、矿产企业等从事安全生产项目设计、施工、生产、组织、管理及检测等技术技能工作。</p>','/uploads/blueprint/topics/smart-energy/images/img01.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','图文资料','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(29,30,'BP-TOPIC-SMART_ENERGY-TRAINING','实训基地','绿色能源、智能开采与化工安全','<p>煤矿智能开采技术专业群群内专业协同互补，聚焦智能开采、化工生产、安全保障三大领域，建有总投资1.2亿元的智能矿山产教融合实训基地、省级安全培训基地，实训条件省内一流。</p>
<p>综掘实训室掘进机 / 综采实训中心</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img13.webp" alt="综掘实训室掘进机 / 综采实训中心"><figcaption>综掘实训室掘进机 / 综采实训中心</figcaption></figure>
<p>煤矿智能开采技术专业学生在综采工作面操作液压支架</p>
<p>智能矿山产教融合实训基地 ？</p>
<p>智能综采实训中心</p>
<p>主要功能：一是开展采煤机结构认识、液压支架结构认识，综采工作面“三机”配套设备组成认识实训；二是开展液压支架、刮板输送机、胶带输送机操作实训。</p>
<p>承担的教学任务：可开展《智能开采机械使用与维护》课程中液压支架操作、刮板输送机操作、胶带输送机操作等实训。</p>
<p>模拟矿井实训基地</p>
<p>主要功能：一是开展矿井生产系统认识实训；二是开展局部通风机操作实训（含反风）；三是开展掘进工作面风筒安装实训；四是开展矿井巷道布置实训；五是开展采掘工作面传感器布置实训；六是开展机电设备结构认识实训。</p>
<p>承担的教学任务：可开展《采掘电气》《巷道施工与智能掘进技术》等课程实训。</p>
<p>1楼 智能综采实训中心：布置煤矿采煤工作面三机配套技术，能满足采煤机司机、液压支架工、皮带机司机等工种技能培训。智能综掘实训中心：布置煤矿掘进工作面及配套技术，满足掘进机司机、瓦斯抽放工、瓦斯检查工等工种技能培训。AR-VR实训中心：布置井下模拟生产场景和各主要核心技能体验，实现井下多个工种模拟考核及培训。综合管控平台（地面调度中心）：布置综合管控平台和煤矿井下调度中心，引入煤矿实际生产场景数据，并实现与智能综采实训中心和智能综掘实训中心设备远程控制。</p>
<p>2楼 技能大赛训练中心：布置无人机救援系统、事故坍塌救援系统、电力恢复系统和防灭火装置系统等，能完成安全生产事故应急救援方面的技能训练。瓦斯治理实训室：布置瓦斯抽采、瓦斯突出等实训设备，能完成瓦斯抽采钻孔布置、瓦斯抽采和瓦斯突出等实训。机电实训室：布置煤矿井下各种馈电开关和机电监测控制系统，可满足学生从模拟训练、安全电压下操作到井下一致设备操作的培训。矿井通风实训室：布置井下矿井通风系统，能实现井下风流控制、反风等功能。</p>
<p>3楼 安全巡检实训室：布置巡检机器人及煤矿相关检测设备，能实现煤矿安全巡检、机器设备探伤及井下相关设备维护保养的日常训练。矿山压力观测实训室：布置了矿山压力控制装置及测量设备，能开展煤矿井下测量、矿山压力显现及控制等实训。PLC控制实训室：能开展煤矿井下智能化控制技术训练和智能化技术培训。</p>
<p>4楼 无人机应用技术实训室：能开展无人机操作培训和实训。</p>
<p>5楼 应用化工技术单元操作实训室：能开展应用化工技术液体传热、蒸馏、萃取等实训和培训。应用化工技术基础实训室：能开展化学基础实验实训和培训。矿山生态修复实训室：能开展矿山环境治理研究、生态修复研究等实训以及社会培训。</p>
<p>安全技术与管理校内实践教学基地</p>
<p>安全技术与管理专业校内实践教学基地设备总价值1800余万元，每个实训基地（实训室）均能同时满足30～40人开展实习实训，优越的实习实训基地为学生的生产实习实训奠定了坚实基础。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img14.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img15.webp" alt=""></figure>
<p>煤与瓦斯突出防治操作演示 生产事故应急救援实训</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img16.webp" alt="煤与瓦斯突出防治操作演示 生产事故应急救援实训"><figcaption>煤与瓦斯突出防治操作演示 生产事故应急救援实训</figcaption></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img17.webp" alt="煤与瓦斯突出防治操作演示 生产事故应急救援实训"><figcaption>煤与瓦斯突出防治操作演示 生产事故应急救援实训</figcaption></figure>
<p>采煤工作面 采煤工作面回风巷</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img18.webp" alt="采煤工作面 采煤工作面回风巷"><figcaption>采煤工作面 采煤工作面回风巷</figcaption></figure>
<p>煤矿安全培训基地</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img19.webp" alt="煤矿安全培训基地"><figcaption>煤矿安全培训基地</figcaption></figure>
<p>矿山机器人巡检</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img20.webp" alt="矿山机器人巡检"><figcaption>矿山机器人巡检</figcaption></figure>
<p>突发事故应急救援（cpr）</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img21.webp" alt="突发事故应急救援（cpr）"><figcaption>突发事故应急救援（cpr）</figcaption></figure>
<p>智能监测监控实训室</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img22.webp" alt="智能监测监控实训室"><figcaption>智能监测监控实训室</figcaption></figure>
<p>综采工作面安全操作实训</p>','/uploads/blueprint/topics/smart-energy/images/img13.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','图文资料','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(30,30,'BP-TOPIC-SMART_ENERGY-COOPERATION','产教融合','绿色能源、智能开采与化工安全','<p>对接产业</p>
<p>产教融合成果</p>
<p>产教融合实。依托统一战线帮扶，与东部广州港集团、广汽集团、奇瑞控股集团等龙头企业开展深度合作，年均提供实习就业岗位2000余个。牵头成立西南地区新型综合能源行业产教融合共同体、毕节市智能矿山市域产教联合体，加入全国城市更新、全国核能建设等10余个共同体和联合体。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img23.webp" alt=""></figure>
<p>牵头成立西南地区新型综合能源行业产教融合共同体 毕节市智能矿山市域产教联合体</p>
<p>校企合作订单班/产业学院</p>','/uploads/blueprint/topics/smart-energy/images/img23.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','图文资料','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(31,30,'BP-TOPIC-SMART_ENERGY-MASTERS','名师名匠','绿色能源、智能开采与化工安全','<p>高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img24.webp" alt="高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人"><figcaption>高振勇 研究员、咨询（投资）工程师 工矿建筑系安全技术与管理专业带头人</figcaption></figure>
<p>2006年毕业于辽宁工程技术大学采矿工程专业，获工学硕士学位，2006年4月参加工作，从事煤矿瓦斯灾害防治研究与教学工作19年。</p>
<p>主要研究方向为煤矿瓦斯灾害防治、浆体管道输送竖直段管路阻力损失研究。主持市级及以上科研项目4项，主持或参与国家重大专项子课题1项、省部级项目1项、中煤科工集团二级企业技术创新项目1项，横向重点项目40余项；授权国家发明专利4项，撰写科研、咨询报告50余篇。获省部级奖励13项，其中个人证书3项、集体奖10项。发表学术论文20篇，其中中文核心期刊独著5篇、第一作者5篇，中文科技期刊独著4篇、第二作者2篇，EI检索国际会议独著2篇，参编教材1部。牵头申报煤炭行业井工煤矿智能化实训（实习）基地、煤炭行业教育培训贵州基地，培养青年教师5名，在安全工程专业建设、煤矿安全科研与人才培养方面成果显著。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img25.webp" alt=""></figure>
<p>王锦 教授 一级建造师，工矿建筑系建筑工程技术专业带头人</p>
<p>2007年毕业于重庆交通大学工程管理专业，获工学学士学位，2007年7月参加工作，从事建筑工程施工管理与教学工作18年。主要研究方向为建筑施工安全管理、建筑材料研究。主持市级及以上科研项目2项，主持或参与省部级质量工程项目和技能贵州项目2项；授权国家发明专利1项。发表学术论文15余篇。牵头申报住房和城乡建设领域现场人员培训（实习）基地、贵州省建设质量检测培训基地，在建筑工程技术专业建设与人才培养方面成果显著。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img26.webp" alt=""></figure>
<p>罗根华 工学博士 副教授 工矿建筑系专任教师</p>
<p>深耕环境污染控制技术、矿山环境生态修复等领域科研与教学工作二十余年，主持及参与市级及以上教科研项目7项，其中国家自然科学基金项目2项；承接企业委托横向项目近30项。科研成果先后荣获1项辽宁省科技进步奖二等奖、市厅级科技进步奖一等奖3项；累计发表北大核心及以上级别期刊论文18篇，获授权发明专利3项，主编高职教材1部。从教以来获评校优秀教师、优秀班导师，荣获毕业生“我最喜爱的老师”等多项荣誉称号。</p>','/uploads/blueprint/topics/smart-energy/images/img24.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','图文资料','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(32,30,'BP-TOPIC-SMART_ENERGY-ALUMNI','优秀校友','绿色能源、智能开采与化工安全','<p>谢佳丽 毕节职业技术学院工矿建筑系2018级工业机器人专业班学生</p>
<p>2021年就职于广汽乘用车有限公司，担任文化活动专员职务。2021年12月荣获祺盛动力“传祺岗位小能手”称号，2022年7月荣获祺盛动力企业文化宣传系列“优秀宣传个人”称号，2022年12月荣获广汽集团支援疫情防控党员突击队“先进个人”称号。</p>
<p>2024年4月获评广州市团干部讲党团课优秀讲师；2024年5月荣获广州市国资系统宣讲赛特等奖；2024年8月荣获广州市“十佳宣讲员”称号；2025年8月荣获广汽集团优秀团干部称号；2025年9月荣获广州市总工会乡村振兴（“百千万工程”）羊城女能手入围奖。2024年5月被聘请为国资委系统宣讲队员，其事迹被学习强国、《工人日报》等央媒及省市媒体累计报道超18次。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img27.webp" alt=""></figure>
<p>王 祥，毕节职业技术学院工矿建筑系2017级广州港班学生</p>
<p>2020年就职于广州港集团股份有限公司南沙集装箱码头分公司，担任龙门吊机械司机。2021年11月在央视《新闻联播》推出系列报道《弘扬伟大建党精神 开创历史新伟业》第一集《百年大党引领中华民族伟大复兴》，栏目接受采访，自2022年起任其作业大队带训师傅一职，2022年至2023年带出任职以来首批职工，2023年至2025年年初带训出第二批职工，2024年12月被评为公司“安全先进个人”。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img28.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img29.webp" alt=""></figure>
<p>韩 赟，贵州金沙人，中共党员，毕节职业技术学院2013级煤矿开采技术专业毕业生后就读西南大学法学专业取得本科学历，2024年12月入职毕节市七星关区纪委监委，现任区纪委监委工作员。2013.9—2016.7在校期间曾任系学生会主席、院学生会副主席；2016年8月起以西部计划志愿者身份扎根赫章基层，先后在白果镇政府、金银山街道办事处、松林坡安监站、赫章县委办任职，历任党群办负责人、县委办秘书二股负责人，深耕基层服务近8年。</p>
<p>扎根基层期间全程参与脱贫攻坚、常态化疫情防控重点工作，牵头落地“党建＋积分”“团建＋积分”基层治理创新项目。2017年获评赫章县优秀志愿者；2018年获评毕节市优秀志愿者；2019年获评贵州省优秀志愿者；第十二届中国青年志愿者优秀个人，2020年获评最美赫章人，2022年获评第十九届贵州青年五四奖章（集体），贵州省最美劳动者。转入纪检岗位后，2025年获评七星关区纪委监委优秀共产党员。扎根基层志愿服务与实干履职事迹多次被省、市主流媒体宣传报道，是贵州基层青年党员、青年志愿者先进典型代表。</p>
<p>秦鹏，毕节职业技术学院工矿建筑系，2017级港口机械操作与维护</p>
<p>2020年就职于广州港股份有限公司南沙集装箱码头分公司，担任岸桥司机职务。2024年7月，获得公司龙门吊比武第一名，2025年2月当选广东省工会第十五次代表大会代表。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img30.webp" alt=""></figure>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img31.webp" alt=""></figure>
<p>张启浪，男，汉族，中共党员</p>
<p>在校期间思想积极上进，政治立场坚定，始终以优秀共产党员和优秀大学生的标准严格要求自己，学习、竞赛、工作与实践表现优异，综合成绩突出。</p>
<p>他持之以恒，刻苦钻研，不断夯实专业基础、拓宽知识视野。2015年至2021年，他先后在我校完成工艺美术（中职）、建筑工程技术（高职）专业的学习，2021年7月保送到凯里学院攻读土木工程本科，逐步构建起跨学科、复合型的建筑工程知识体系。在校期间学习态度端正，成绩稳居前列，曾多次获得学院一等奖学金，被评为优秀学生干部，获得国家励志奖学金、国家奖学金等。因综合素质突出，2021年，他获得校级和贵州省优秀毕业生荣誉称号。</p>
<p>他以赛促学，以练促长，积极参加省级、国家级技能竞赛，斩获多项荣誉。2019年4月获贵州省职业院校技能大赛一等奖，同年5月获全国职业院校技能大赛高职组建筑装饰技术应用三等奖，2022年7月获贵州省大学生结构设计竞赛三等奖，专业技能与创新能力获得充分认可。</p>
<p>毕业后他不忘初心、勇于创业，于2023年自主创办贵州青雲工程设计有限公司，将专业知识与竞赛经验运用于实践，脚踏实地，精益求精。未来，他将继续深耕工程设计领域，积极奉献社会，展现新时代优秀毕业生的良好风貌。</p>
<p>欧安进，中共党员，毕节职业技术学院工矿建筑系2019级汽车检测与维修技术专业汽车检测与维修班学生</p>
<p>2022年3月至2023年5月就职于施秉县中等职业技术学校担任汽修专业教师，2023年7月至今就职于贵州永华技工学校担任新能源汽车检测与维修专业组组长。2021年9月至2022年7月，他在校期间担任班级班长，荣获以下奖项：2020年，获得国家励志奖学金，获得学院“三好学生”称号；2021年，获得国家励志奖学金，获得学院“三好学生”称号，获得工矿建筑系汽车检测与维修技能大赛一等奖；2022年，获得院级优秀毕业生称号，获得贵州省三好学生称号。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img32.webp" alt=""></figure>
<p>陈胜利，男，年龄：37</p>
<p>一、教育经历</p>
<p>2010年9月--2013年7月毕业于毕节职业技术学院，专业：煤矿开采技术。</p>
<p>二、工作经历</p>
<p>2013年7月毕业后，2013年9月进入贵州众一金彩黔矿业有限公司瑞丰煤矿任技术员，2015年在瑞丰煤矿任技术科长，2018年在瑞丰煤矿任技术副总，2019年在瑞丰煤矿任技术负责人；2020年5月调贵州众一金彩黔矿业有限公司织金县志成煤矿任总工程师；2025年7月调贵州众一金彩黔矿业有限公司岩脚煤矿任总工程师。2020年以来一直负责贵州众一金彩黔矿业有限公司国家安全改造项目，2021年参与贵州省科技重大项目：薄煤层无人/少人采掘系统研究与应用。</p>
<p>三、荣誉奖项</p>
<p>2017年获得众一控股优秀员工，2021年获得众一金彩黔矿业有限公司优秀管理员，2025年获得众一控股有限公司卓越精英奖。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img33.webp" alt=""></figure>','/uploads/blueprint/topics/smart-energy/images/img27.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','图文资料','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(33,30,'BP-TOPIC-SMART_ENERGY-STUDENTS','优秀学生','绿色能源、智能开采与化工安全','<figure><img src="/uploads/blueprint/topics/smart-energy/images/img34.webp" alt=""></figure>
<p>徐俊，毕节职业技术学院2025级建筑工程技术专业学生</p>
<p>2022年入校就读中职建筑工程施工专业；2025年9月，升入本校高职建筑工程技术专业。中职三年，连续两年获得校级一等奖学金，获评毕节职业技术学院“三好学生”“优秀毕业生”等荣誉。</p>
<p>专业技能方面，在校期间，积极参加各类技能竞赛并斩获多项荣誉：2022年获毕节市教育局举办的职业院校技能大赛工程测量赛项二等奖，2023年获毕节市教育局举办的水利工程制图赛项一等奖，2025年获贵州省职业院校技能大赛水利工程制图赛项一等奖，并代表学校参加世界职业院校技能大赛，获得土木施工赛道铜奖。</p>
<p>专业实践方面，2025年暑假，他曾在贵州青雲工程设计有限公司担任装饰设计师助理，独立完成8户业主的室内施工图绘制与三维建模，协助现场技术交底，掌握了BIM核心建模流程。</p>
<p>成长前景回顾，2025年9月，他升入本校高职层次继续深造；入学后，保持拼搏劲头：2025年10月获教育厅、团省委举办的第四届贵州省大学生创新方法大赛二等奖；2026年，他先后获得教育厅举办的贵州省大学生职业规划大赛铜奖、贵州省职业院校技能大赛水利赛道三等奖。此外，他以专业知识登记1项软件著作权和3项作品版权，并参与老师科研项目。</p>
<p>从中职到高职，从赛场到实习再到科研，他用踏实证明自己：学好技术、做好小事，就能为家乡建设出力。</p>
<figure><img src="/uploads/blueprint/topics/smart-energy/images/img35.webp" alt=""></figure>
<p>吴鹏，毕节职业技术学院2025级建筑工程技术专业学生</p>
<p>共青团员。现任班级学习委员以及学院数字素养与技能协会会长。他以踏实的学习态度和扎实过硬的技能应用能力，赢得了师生的一致认可。</p>
<p>2022年，吴鹏进入我校建筑工程施工专业中技班就读。自入学以来，始终保持着专业成绩与综合排名双第一的优异表现。中职三年，他连续位列专业第一，先后荣获多项省市级技能大赛奖项，包括贵州省职业院校技能大赛一等奖、全市中等职业学校师生技能大赛一等奖等，并在2025年8月代表贵州省参加世界职业院校技能大赛总决赛，斩获争夺赛铜奖。此外，他还被评为毕节职业技术学院“优秀班干”和“优秀毕业生”。</p>
<p>升入高职后，吴鹏继续在本校建筑工程技术专业深造。他迅速转变角色，积极投身各类专业竞赛，持续展现出色的学习能力与进取精神。在短短一学期内，他便斩获以下荣誉：获得第四届贵州省大学生创新方法大赛二等奖、第十七届全国高等院校学生斯维尔杯数字城市创新技术与应用大赛三等奖、第三届贵州省大学生职业规划大赛职教组铜奖和贵州省职业院校技能大赛三等奖。与此同时，他依然保持专业与综合排名双第一的优异成绩，充分体现了其进入高职阶段后快速成长、敢于挑战、全面发展的优秀素质。</p>','/uploads/blueprint/topics/smart-energy/images/img34.webp','#f59a13',1,'2026-08-03T05:35:55.398098+00:00','图文资料','蓝图资料同步','2026-08-03','approved',NULL,'admin','admin','','article');
