INSERT INTO "pages" VALUES(68,37,'BP-TOPIC-MODERN_AGRICULTURE-OVERVIEW','专题概况','面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。','<p>现代农业专题面向山地特色农业、农产品流通、乡村建设与乡村运营需求，整合电子信息工程系、旅游管理系、工矿建筑系的技术与服务能力，形成“数字技术支撑、乡村文旅运营、工程场景保障”的展示主线。</p>
<p>专题在学校门户中承担乡村振兴与现代职业教育结合的入口，重点展示数字化监测、农产品品牌传播、乡村服务场景、设施建设和学生实践成果。</p>
<figure><img src="/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg" alt="学校形象与乡村振兴服务场景"><figcaption>学校形象与乡村振兴服务场景</figcaption></figure>','/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg','#f59a13',0,'2026-08-04T09:41:45.959916+00:00','专题概况','蓝图资料同步','2026-08-04','deleted',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(69,37,'BP-TOPIC-MODERN_AGRICULTURE-MAJORS','专业群布局','面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。','<p>关联系部：电子信息工程系提供数字化平台、数据采集与网络技术支撑；旅游管理系提供乡村文旅、品牌运营与服务接待能力；工矿建筑系提供设施建设、资源利用与工程场景实践支撑。</p>
<p>展示内容可围绕智慧种植、农产品电商、乡村旅游线路、公共服务空间、数字化管理平台和学生实践作品组织。</p>','/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg','#f59a13',0,'2026-08-04T09:41:45.959916+00:00','图文资料','蓝图资料同步','2026-08-04','deleted',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(70,37,'BP-TOPIC-MODERN_AGRICULTURE-COOPERATION','产教协同','面向山地特色农业、乡村振兴与数字化生产服务，整合信息技术、文旅运营与工程支撑能力。','<p>专题适合承接校地合作、乡村振兴服务、农产品品牌孵化、乡村旅游运营和信息化平台建设项目，以真实任务驱动课程、实训和社会服务联动。</p>
<figure><img src="/uploads/blueprint/departments/tourism/images/img01.webp" alt="文旅服务与乡村运营能力"><figcaption>文旅服务与乡村运营能力</figcaption></figure>','/uploads/blueprint/departments/tourism/images/img01.webp','#f59a13',0,'2026-08-04T09:41:45.959916+00:00','图文资料','蓝图资料同步','2026-08-04','deleted',NULL,'admin','admin','','article');
