INSERT INTO "pages" VALUES(73,38,'BP-TOPIC-SMART_HEALTHCARE-OVERVIEW','专题概况','围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。','<p>智慧康养专题以医学护理系为核心，联动旅游管理系的服务接待与康养场景运营能力，以及电子信息工程系的数字化平台与智能设备支撑，展示护理教育、急救训练、康养服务和健康管理的综合育人路径。</p>
<figure><img src="/uploads/blueprint/departments/medical-nursing/images/img01.webp" alt="护理与康养服务实训场景"><figcaption>护理与康养服务实训场景</figcaption></figure>','/uploads/blueprint/departments/medical-nursing/images/img01.webp','#f59a13',1,'2026-08-04T03:25:50.313856+00:00','专题概况','蓝图资料同步','2026-08-04','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(74,38,'BP-TOPIC-SMART_HEALTHCARE-MAJORS','专业群布局','围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。','<p>关联系部：医学护理系承担临床护理、急救教育和康养服务主线；旅游管理系承接康养旅游、酒店服务与接待运营；电子信息工程系支撑健康数据、智能终端和数字化互动展示。</p>
<p>可展示护理技能、老年照护、急救科普、康养服务设计、智慧健康设备应用和学生志愿服务成果。</p>','/uploads/blueprint/departments/medical-nursing/images/img01.webp','#f59a13',1,'2026-08-04T03:25:50.313856+00:00','图文资料','蓝图资料同步','2026-08-04','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(75,38,'BP-TOPIC-SMART_HEALTHCARE-COOPERATION','产教协同','围绕护理、康养服务、急救教育和智慧健康管理，整合医学护理、旅游服务与信息技术资源。','<p>专题适合联动医院、社区、养老机构、康养企业与旅游服务企业，共建真实服务场景，让学生在护理、健康管理、服务运营和数字工具应用中完成综合训练。</p>
<figure><img src="/uploads/blueprint/departments/tourism/images/img02.webp" alt="服务接待与康养运营场景"><figcaption>服务接待与康养运营场景</figcaption></figure>','/uploads/blueprint/departments/tourism/images/img02.webp','#f59a13',1,'2026-08-04T03:25:50.313856+00:00','图文资料','蓝图资料同步','2026-08-04','approved',NULL,'admin','admin','','article');
