INSERT INTO "pages" VALUES(78,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-OVERVIEW','专题概况','聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。','<p>数智技术专题以电子信息工程系为牵引，把人工智能、网络安全、数据应用、物联网和数字媒体能力延伸到能源、制造、文旅、康养、财经商贸等专业场景，形成学校跨专业数字化能力展示入口。</p>
<figure><img src="/uploads/blueprint/departments/information/images/img01.webp" alt="电子信息工程系数智技术成果"><figcaption>电子信息工程系数智技术成果</figcaption></figure>','/uploads/blueprint/departments/information/images/img01.webp','#f59a13',1,'2026-08-04T03:25:50.313856+00:00','专题概况','蓝图资料同步','2026-08-04','approved',NULL,'admin','admin','','article');
INSERT INTO "pages" VALUES(79,39,'BP-TOPIC-DIGITAL_INTELLIGENCE-MAJORS','专业群布局','聚焦人工智能、网络安全、数据应用与跨专业数字化改造，作为各系部数字能力的公共底座。','<p>关联系部：电子信息工程系承担技术底座；财政经济系承接数字商贸与财务数据应用；工矿建筑系承接智能设备与工程数字化；医学护理系承接智慧健康；旅游管理系承接数字文旅与服务管理。</p>
<p>该专题适合展示人工智能应用、网络安全实训、数据看板、数字资源平台、交互式展示系统和跨专业项目制学习成果。</p>','/uploads/blueprint/departments/information/images/img01.webp','#f59a13',1,'2026-08-04T03:25:50.313856+00:00','图文资料','蓝图资料同步','2026-08-04','approved',NULL,'admin','admin','','article');
