INSERT INTO "pages" VALUES(88,41,'BP-TOPIC-CAMPUS_CULTURE-OVERVIEW','专题概况','以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。','<p>同心校园文化专题作为创新育人专题之外的文化入口，汇聚学校形象、校园活动、学生成长、志愿服务、优秀校友、名师名匠和各系部文化品牌，形成统一的校园精神展示空间。</p>
