INSERT INTO "pages" VALUES(89,41,'BP-TOPIC-CAMPUS_CULTURE-MAJORS','系部融入','以同心育人、校园文化、学生成长和服务地方为主线，汇聚学校与各系部共同的精神气质。','<p>覆盖系部：工矿建筑系、财政经济系、电子信息工程系、医学护理系、旅游管理系。各系部可在此汇聚党建思政、技能成长、志愿服务、文化活动和学生风采。</p>
<p>该专题不替代系部门户，而是作为学校层面的文化聚合页，让参观者在进入具体专业内容之前，先看到学校共同的价值表达。</p>','/uploads/4fcaa6e34b5f40c7a7e2b58947b9de1c.jpg','#f59a13',1,'2026-08-04T03:25:50.313856+00:00','图文资料','蓝图资料同步','2026-08-04','approved',NULL,'admin','admin','','article');
